#[derive(Debug, Parser)]
#[command(name = "mayhem")]
#[command(about = "Mayhem network CLI")]
#[command(arg_required_else_help = true)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Debug, Subcommand)]
enum Commands {
    /// Choose a role, create or import a wallet, and sign current router rules.
    Setup(SetupArgs),
    /// Inspect, back up, import, and re-encrypt the local Mayhem wallet.
    Wallet {
        #[command(subcommand)]
        command: WalletCommands,
    },
    /// Add Mayhem credit through TNK, Stripe, or TAP and inspect confirmation state.
    Deposit {
        #[command(subcommand)]
        command: DepositCommands,
    },
    /// Cash out claimable TAP distribution entries without giving Mayhem custody.
    #[command(visible_alias = "claim")]
    Withdraw(WithdrawArgs),
    /// Open a paid participant dispute over a session.
    Dispute(DisputeArgs),
    /// Submit fraud evidence against an epoch commit.
    FraudProof {
        #[command(subcommand)]
        command: FraudProofCommands,
    },
    /// Probe local hardware and print enclave backend feasibility.
    Doctor(DoctorArgs),
    /// Inspect and verify the admin-signed model catalog.
    Catalog {
        #[command(subcommand)]
        command: CatalogCommands,
    },
    /// Provider serving lifecycle commands.
    Provider {
        #[command(subcommand)]
        command: Box<ProviderCommands>,
    },
    /// Admin-only canonical contract control-plane commands.
    Admin {
        #[command(subcommand)]
        command: Box<AdminCommands>,
    },
    /// Start the local OpenAI-compatible user gateway.
    Use(UseArgs),
    /// List models from the ledger-anchored admin catalog release.
    Models(ModelsArgs),
    /// Buy Mayhem credits through fiat/crypto rails.
    Pay {
        #[command(subcommand)]
        command: PayCommands,
    },
    /// Show a canonical contract credit balance.
    Balance(BalanceArgs),
    /// Show one-shot node, gateway, peer, session, and wallet health.
    Status(StatusArgs),
    /// Show recent local gateway receipts without needing an epoch number.
    History(SessionHistoryArgs),
    /// Show recent local gateway sessions without needing an epoch number.
    Sessions(SessionHistoryArgs),
    /// Show provider payout evidence and treasury fee sweeps.
    Payouts(PayoutsArgs),
    /// Show provider earnings, holdback, paid, released, and claimable balances.
    Earnings(EarningsArgs),
    /// Show provider reputation plus earning/holdback state.
    Reputation(ReputationArgs),
    /// Inspect and persist local Mayhem CLI configuration.
    Config {
        #[command(subcommand)]
        command: ConfigCommands,
    },
    /// Remove local Mayhem state under --home after confirmation.
    Reset(ResetArgs),
    /// Remove local Mayhem state under --home after confirmation.
    Uninstall(ResetArgs),
    /// Wire or repair opencode for the local Mayhem gateway.
    Opencode(OpencodeArgs),
    /// Auditor probe commands.
    Auditor {
        #[command(subcommand)]
        command: AuditorCommands,
    },
    /// Receipt audit commands.
    Receipts {
        #[command(subcommand)]
        command: ReceiptsCommands,
    },
    /// Inspect, hash, and re-consent to router rules.
    Rules {
        #[command(subcommand)]
        command: RulesCommands,
    },
    /// Run a gateway, peer, opencode, and receipt smoke test.
    Test(TestArgs),
    /// Check for a signed release, verify it, and stage the Mayhem binary.
    Update(UpdateArgs),
    /// Sign a release manifest with the operator release key.
    #[command(hide = true)]
    ReleaseSign(ReleaseSignArgs),
}

#[derive(Debug, Subcommand)]
enum ProviderCommands {
    /// List this provider wallet's active canonical enclaves and rooms.
    List(ProviderListArgs),
    /// Show provider serving state and local gateway route visibility.
    Health(ProviderHealthArgs),
    /// Inspect or set the payment rails this provider accepts for serving.
    Rails {
        #[command(subcommand)]
        command: ProviderRailsCommands,
    },
    /// Pick an admin-created enclave, seal its artifact, join canonical rooms, and send heartbeats.
    Start(Box<ProviderStartArgs>),
    /// Register if needed, then join an existing admin-created enclave and canonical rooms.
    Join(ProviderJoinArgs),
    /// Leave canonical rooms, then leave an existing admin-created enclave.
    Leave(ProviderLeaveArgs),
    /// Leave every active canonical room and enclave for this provider wallet.
    Stop(ProviderStopArgs),
    /// Join or leave canonical admin-created rooms for a served enclave.
    Rooms {
        #[command(subcommand)]
        command: ProviderRoomsCommands,
    },
}

#[derive(Debug, Subcommand)]
enum ProviderRoomsCommands {
    /// Join one canonical room with an already-served enclave.
    Join(ProviderRoomJoinArgs),
    /// Leave one canonical room.
    Leave(ProviderRoomLeaveArgs),
}

#[derive(Debug, Subcommand)]
enum ProviderRailsCommands {
    /// Read the provider's canonical accepted rails from contract state.
    Get(ProviderRailsGetArgs),
    /// Set the provider's accepted serving rails.
    Set(ProviderRailsSetArgs),
}

#[derive(Debug, Subcommand)]
enum FraudProofCommands {
    /// Submit an over-credit fraud proof against an epoch commit.
    Submit(FraudProofSubmitArgs),
    /// Scan receipts and provisional epoch commits, then challenge inflated commits.
    Challenge(FraudProofChallengeArgs),
}

#[derive(Debug, Subcommand)]
enum ConfigCommands {
    /// Print the whole config or one key.
    Get(ConfigGetArgs),
    /// Persist one config key.
    Set(ConfigSetArgs),
}

#[derive(Debug, Subcommand)]
enum AdminCommands {
    /// Set the active rules version and hash.
    SetRules(AdminSetRulesArgs),
    /// Schedule admin-owned contract parameters.
    SetParams(AdminSetParamsArgs),
    /// Set the admin model reference price used to bound enclave prices.
    SetModelRef(AdminSetModelRefArgs),
    /// Publish the latest signed catalog release anchor for network discovery.
    PublishCatalog(AdminPublishCatalogArgs),
    /// Register an admin-created and attested canonical enclave.
    RegisterEnclave(AdminRegisterEnclaveArgs),
    /// Retire an admin-created enclave.
    RetireEnclave(AdminRetireEnclaveArgs),
    /// Open a canonical admin room for a model.
    OpenRoom(AdminOpenRoomArgs),
    /// Close a canonical admin room.
    CloseRoom(AdminCloseRoomArgs),
    /// Set a forward-facing admin price schedule for an enclave.
    SetPrice(AdminSetPriceArgs),
    /// Set an admin-approved provider payout target.
    SetProviderPayout(AdminSetProviderPayoutArgs),
    /// Verify a provider business identity for Tier 4 accountability.
    SetProviderKyb(AdminSetProviderKybArgs),
    /// Revoke a provider business identity verification.
    RevokeProviderKyb(AdminRevokeProviderKybArgs),
    /// Ban a provider and tombstone its active serving rows.
    BanProvider(AdminBanProviderArgs),
    /// Accredit an auditor key for probe submission.
    AuditorRegister(AdminAuditorRegisterArgs),
    /// Post a fresh TNK/USD oracle rate for payment and payout conversions.
    RateOracle(AdminRateOracleArgs),
    /// Post a fresh TAP/USD policy rate for TAP deposit conversion.
    TapRateOracle(AdminTapRateOracleArgs),
    /// Record one real treasury-signed MSB batch settlement for TNK earnings.
    TnkSettlement(AdminTnkSettlementArgs),
    /// Confirm a memo-bound TNK deposit into the canonical credit ledger.
    TnkDeposit(AdminTnkDepositArgs),
    /// Confirm a finalized TAP escrow Deposit event into the canonical credit ledger.
    TapDeposit(AdminTapDepositArgs),
    /// Confirm a fiat checkout deposit into the canonical credit ledger.
    FiatDeposit(AdminFiatDepositArgs),
    /// Record a fiat chargeback clawback and account freeze.
    FiatChargeback(AdminFiatChargebackArgs),
    /// Retired: use rail-specific epoch settlement and claim flows.
    PayoutConfirm(AdminPayoutConfirmArgs),
    /// Anchor recomputed epoch roots permissionlessly.
    EpochCommit(AdminEpochCommitArgs),
    /// Apply admin-verified epoch debits/earnings and ev/* roots.
    EpochApply(AdminEpochApplyArgs),
}

#[derive(Debug, Subcommand)]
enum PayCommands {
    /// Prepare a memo-bound TNK treasury deposit.
    Tnk(PayTnkArgs),
    /// Buy credits via Stripe hosted checkout.
    Stripe(PayRailArgs),
}

#[derive(Debug, Subcommand)]
enum DepositCommands {
    /// Prepare a memo-bound TNK treasury deposit.
    Tnk(PayTnkArgs),
    /// Buy credits via Stripe hosted checkout.
    Stripe(PayRailArgs),
    /// Build unsigned TAP approve+deposit calldata for an external wallet.
    Tap(DepositTapArgs),
    /// Show pending/confirmed deposit state from the contract ledger.
    Status(DepositStatusArgs),
}

#[derive(Debug, Subcommand)]
enum WalletCommands {
    /// Show the local wallet public key, Trac address, and keypair path.
    Show(WalletShowArgs),
    /// Reveal the restorable mnemonic after explicit confirmation.
    Backup(WalletBackupArgs),
    /// Reveal the restorable mnemonic after explicit confirmation.
    #[command(name = "export-mnemonic", alias = "export")]
    ExportMnemonic(WalletBackupArgs),
    /// Import a wallet from a BIP-39 mnemonic.
    Import(WalletImportArgs),
    /// Re-encrypt the wallet with a new password.
    Passwd(WalletPasswdArgs),
}

#[derive(Debug, Args, Clone)]
struct WalletLocatorArgs {
    /// Mayhem home directory. Defaults to MAYHEM_HOME or ~/.mayhem.
    #[arg(long, value_name = "PATH")]
    home: Option<PathBuf>,

    /// Exact keypair.json path. Overrides config.toml and --peer-store-name.
    #[arg(long, value_name = "PATH")]
    keypair: Option<PathBuf>,

    /// Intercom peer store name under <home>/stores when config.toml is absent.
    #[arg(long, default_value = "main")]
    peer_store_name: String,

    /// Password for the encrypted keypair.json. Empty by default.
    #[arg(long)]
    wallet_password: Option<String>,
}

#[derive(Debug, Parser)]
struct WalletShowArgs {
    #[command(flatten)]
    wallet: WalletLocatorArgs,

    /// Print a machine-readable wallet report.
    #[arg(long)]
    json: bool,
}

#[derive(Debug, Parser)]
struct WalletBackupArgs {
    #[command(flatten)]
    wallet: WalletLocatorArgs,

    /// Confirm that the mnemonic should be printed to this terminal.
    #[arg(long)]
    yes: bool,

    /// Print a machine-readable wallet backup report.
    #[arg(long)]
    json: bool,
}

#[derive(Debug, Parser)]
struct WalletImportArgs {
    #[command(flatten)]
    wallet: WalletLocatorArgs,

    /// BIP-39 mnemonic to import.
    #[arg(long)]
    mnemonic: String,

    /// Overwrite an existing keypair.json.
    #[arg(long)]
    force: bool,

    /// Print a machine-readable wallet import report.
    #[arg(long)]
    json: bool,
}

#[derive(Debug, Parser)]
struct WalletPasswdArgs {
    #[command(flatten)]
    wallet: WalletLocatorArgs,

    /// New password for the encrypted keypair.json. Empty string removes the password.
    #[arg(long)]
    new_wallet_password: Option<String>,

    /// Print a machine-readable password-rotation report.
    #[arg(long)]
    json: bool,
}

#[derive(Debug, Subcommand)]
enum RulesCommands {
    /// Print the BLAKE3 hash of RULES.md.
    Hash(RulesHashArgs),
    /// Review current rules and sign fresh consent when needed.
    Review(RulesReviewArgs),
}

#[derive(Debug, Subcommand)]
enum ReceiptsCommands {
    /// Export an epoch audit bundle and verify it against ev/* roots.
    Export(ReceiptsExportArgs),
    /// Publish gateway receipts onto the canonical epoch sidechannel.
    Publish(ReceiptsPublishArgs),
    /// Collect epoch sidechannel receipts into a receipts-file compatible JSON bundle.
    Collect(ReceiptsCollectArgs),
}

#[derive(Debug, Subcommand)]
enum AuditorCommands {
    /// Run a canary probe through the normal gateway chat path and emit/submit probe_result evidence.
    Canary(AuditorCanaryArgs),
}

#[derive(Debug, Subcommand)]
enum CatalogCommands {
    /// List admin-approved catalog models and downloadable artifacts.
    List(CatalogListArgs),
    /// Verify catalog structure, maintainer signature, canary refs, and optional dev downloads.
    Verify(CatalogVerifyArgs),
    /// Sign an admin-reviewed catalog draft with an operator-held Ed25519 seed file.
    Sign(CatalogSignArgs),
    /// Compute launch catalog metadata for a local admin artifact without loading model weights.
    ArtifactMetadata(CatalogArtifactMetadataArgs),
    /// Apply bound artifact metadata reports into a catalog draft.
    ApplyArtifactMetadata(CatalogApplyArtifactMetadataArgs),
    /// Print copy/paste artifact metadata/apply/sign/verify commands for the launch matrix.
    ArtifactPlan(CatalogArtifactPlanArgs),
    /// Print copy/paste source download/build commands that stage launch artifacts for upload.
    ArtifactStagePlan(CatalogArtifactStagePlanArgs),
    /// Print copy/paste Hugging Face upload plus artifact finalization commands.
    ArtifactPublishPlan(CatalogArtifactPublishPlanArgs),
    /// Run catalog canaries against a local admin artifact and print catalog-ready fingerprints.
    CalibrateCanary(CatalogCalibrateCanaryArgs),
    /// Verify calibration report files cover the catalog canary matrix.
    CanaryEvidence(CatalogCanaryEvidenceArgs),
    /// Apply bound calibration report fingerprints into a catalog draft.
    ApplyCanaryReports(CatalogApplyCanaryReportsArgs),
    /// Audit per-backend canary fingerprint coverage for launch artifacts.
    CanaryMatrix(CatalogCanaryMatrixArgs),
    /// Print copy/paste calibration commands for the catalog canary matrix.
    CanaryPlan(CatalogCanaryPlanArgs),
}

