#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    match cli.command {
        Commands::Setup(args) => setup(args).await,
        Commands::Wallet { command } => wallet_command(command).await,
        Commands::Deposit { command } => deposit_command(command).await,
        Commands::Withdraw(args) => withdraw(args).await,
        Commands::Dispute(args) => dispute(args).await,
        Commands::FraudProof { command } => match command {
            FraudProofCommands::Submit(args) => fraud_proof_submit(args).await,
            FraudProofCommands::Challenge(args) => fraud_proof_challenge(args).await,
        },
        Commands::Doctor(args) => doctor(args),
        Commands::Catalog { command } => match command {
            CatalogCommands::List(args) => catalog_list(args),
            CatalogCommands::Verify(args) => catalog_verify(args),
            CatalogCommands::Sign(args) => catalog_sign(args),
            CatalogCommands::ArtifactMetadata(args) => catalog_artifact_metadata(args),
            CatalogCommands::ApplyArtifactMetadata(args) => catalog_apply_artifact_metadata(args),
            CatalogCommands::ArtifactPlan(args) => catalog_artifact_plan(args),
            CatalogCommands::ArtifactStagePlan(args) => catalog_artifact_stage_plan(args),
            CatalogCommands::ArtifactPublishPlan(args) => catalog_artifact_publish_plan(args),
            CatalogCommands::CalibrateCanary(args) => catalog_calibrate_canary(args),
            CatalogCommands::CanaryEvidence(args) => catalog_canary_evidence(args),
            CatalogCommands::ApplyCanaryReports(args) => catalog_apply_canary_reports(args),
            CatalogCommands::CanaryMatrix(args) => catalog_canary_matrix(args),
            CatalogCommands::CanaryPlan(args) => catalog_canary_plan(args),
        },
        Commands::Provider { command } => match *command {
            ProviderCommands::List(args) => provider_list(args).await,
            ProviderCommands::Health(args) => provider_health(args).await,
            ProviderCommands::Rails { command } => match command {
                ProviderRailsCommands::Get(args) => provider_rails_get(args).await,
                ProviderRailsCommands::Set(args) => provider_rails_set(args).await,
            },
            ProviderCommands::Start(args) => provider_start(*args).await,
            ProviderCommands::Join(args) => provider_join(args).await,
            ProviderCommands::Leave(args) => provider_leave(args).await,
            ProviderCommands::Stop(args) => provider_stop(args).await,
            ProviderCommands::Rooms { command } => match command {
                ProviderRoomsCommands::Join(args) => provider_room_join(args).await,
                ProviderRoomsCommands::Leave(args) => provider_room_leave(args).await,
            },
        },
        Commands::Admin { command } => admin(*command).await,
        Commands::Use(args) => use_gateway(args).await,
        Commands::Models(args) => models(args).await,
        Commands::Pay { command } => match command {
            PayCommands::Tnk(args) => pay_tnk(args).await,
            PayCommands::Stripe(args) => pay(PayRail::Stripe, args).await,
        },
        Commands::Balance(args) => balance(args).await,
        Commands::Status(args) => status(args).await,
        Commands::History(args) => session_history(args, false).await,
        Commands::Sessions(args) => session_history(args, true).await,
        Commands::Payouts(args) => payouts(args).await,
        Commands::Earnings(args) => earnings(args).await,
        Commands::Reputation(args) => reputation(args).await,
        Commands::Config { command } => match command {
            ConfigCommands::Get(args) => config_get(args),
            ConfigCommands::Set(args) => config_set(args),
        },
        Commands::Reset(args) => reset(args, "reset"),
        Commands::Uninstall(args) => reset(args, "uninstall"),
        Commands::Opencode(args) => opencode(args).await,
        Commands::Auditor { command } => match command {
            AuditorCommands::Canary(args) => auditor_canary(args).await,
        },
        Commands::Receipts { command } => match command {
            ReceiptsCommands::Export(args) => receipts_export(args).await,
            ReceiptsCommands::Publish(args) => receipts_publish(args).await,
            ReceiptsCommands::Collect(args) => receipts_collect(args).await,
        },
        Commands::Rules { command } => match command {
            RulesCommands::Hash(args) => rules_hash(args),
            RulesCommands::Review(args) => rules_review(args).await,
        },
        Commands::Test(args) => mayhem_test(args).await,
        Commands::Update(args) => update(args).await,
        Commands::ReleaseSign(args) => release_sign(args),
    }
}

async fn setup(args: SetupArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let role = select_role(args.role)?;
    let rpc_url = args
        .rpc_url
        .clone()
        .unwrap_or_else(|| DEFAULT_RPC_URL.to_owned());
    let store_path = home.join("stores").join(&args.peer_store_name);
    let keypair_path = store_path.join("db").join("keypair.json");
    let password = args.wallet_password.clone().unwrap_or_default();

    fs::create_dir_all(&home).with_context(|| format!("creating {}", home.display()))?;
    fs::create_dir_all(keypair_path.parent().expect("keypair has parent"))
        .with_context(|| format!("creating {}", keypair_path.display()))?;

    let wallet = materialize_wallet(&args, &keypair_path, &password).await?;
    let config_path = write_config(
        &home,
        &store_path,
        &wallet,
        role,
        &args.peer_store_name,
        &rpc_url,
    )?;
    let opencode_config = merge_mayhem_opencode_config(
        &default_opencode_config_path()?,
        DEFAULT_GATEWAY_URL,
        None,
        false,
    )?;

    let consent = if args.no_consent {
        ConsentReport {
            skipped: true,
            simulated: args.sim,
            rules: None,
            tx: None,
            command_hash: None,
            feature: None,
            result: None,
            state: None,
        }
    } else {
        let rpc = PeerRpcClient::new(&rpc_url)?;
        let rules_doc = read_rules_doc(args.rules_path.as_deref())?;
        let rules = resolve_rules(
            args.rules_ver,
            args.rules_hash.as_deref(),
            &rpc,
            Some(&rules_doc),
        )
        .await?;
        if !args.print_json {
            print_rules_review(&home, &rules_doc, &rules, None, None)?;
        }
        confirm_rules_acceptance(args.yes)?;
        let consent = submit_consent(
            &rpc,
            &keypair_path,
            &password,
            &wallet,
            rules.clone(),
            args.sim,
        )
        .await?;
        if !args.sim {
            persist_rules_acceptance(&home, &rules_doc, &rules)?;
        }
        consent
    };

    let report = json!({
        "home": home,
        "role": role.as_str(),
        "config_path": config_path,
        "wallet": wallet,
        "network": {
            "rpc_url": rpc_url,
            "gateway_url": DEFAULT_GATEWAY_URL,
        },
        "opencode": opencode_config,
        "consent": consent,
    });

    if args.print_json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_human_report(&report)?;
    }

    Ok(())
}

async fn wallet_command(command: WalletCommands) -> Result<()> {
    match command {
        WalletCommands::Show(args) => wallet_show(args).await,
        WalletCommands::Backup(args) | WalletCommands::ExportMnemonic(args) => {
            wallet_backup(args).await
        }
        WalletCommands::Import(args) => wallet_import(args).await,
        WalletCommands::Passwd(args) => wallet_passwd(args).await,
    }
}

async fn wallet_show(args: WalletShowArgs) -> Result<()> {
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    let password = args.wallet.wallet_password.clone().unwrap_or_default();
    let wallet = inspect_wallet(&keypair_path, &password)
        .await
        .with_context(|| format!("reading wallet {}", keypair_path.display()))?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&wallet)?);
    } else {
        print_wallet_show(&wallet);
    }
    Ok(())
}

async fn wallet_backup(args: WalletBackupArgs) -> Result<()> {
    confirm_wallet_backup_reveal(args.yes)?;
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    let password = args.wallet.wallet_password.clone().unwrap_or_default();
    let wallet = backup_wallet(&keypair_path, &password)
        .await
        .with_context(|| format!("backing up wallet {}", keypair_path.display()))?;
    if wallet.mnemonic.as_deref().unwrap_or_default().is_empty() {
        bail!(
            "wallet {} did not contain a restorable mnemonic",
            keypair_path.display()
        );
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&wallet)?);
    } else {
        print_wallet_backup(&wallet);
    }
    Ok(())
}

async fn wallet_import(args: WalletImportArgs) -> Result<()> {
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    if keypair_path.exists() && !args.force {
        bail!(
            "{} already exists; pass --force to overwrite it.",
            keypair_path.display()
        );
    }
    if let Some(parent) = keypair_path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    let password = args.wallet.wallet_password.clone().unwrap_or_default();
    let wallet = create_wallet(&keypair_path, &password, Some(&args.mnemonic), true)
        .await
        .with_context(|| format!("importing wallet {}", keypair_path.display()))?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&wallet)?);
    } else {
        println!("Wallet imported.");
        print_wallet_show(&wallet);
    }
    Ok(())
}

async fn wallet_passwd(args: WalletPasswdArgs) -> Result<()> {
    let keypair_path = resolve_wallet_keypair_path(&args.wallet)?;
    let old_password = args.wallet.wallet_password.clone().unwrap_or_default();
    let new_password = args
        .new_wallet_password
        .clone()
        .or_else(|| env::var("MAYHEM_NEW_WALLET_PASSWORD").ok())
        .context(
            "missing --new-wallet-password (or MAYHEM_NEW_WALLET_PASSWORD); pass an empty string to remove the password",
        )?;
    let wallet = rotate_wallet_password(&keypair_path, &old_password, &new_password)
        .await
        .with_context(|| format!("re-encrypting wallet {}", keypair_path.display()))?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&wallet)?);
    } else {
        println!("Wallet password updated.");
        print_wallet_show(&wallet);
    }
    Ok(())
}

fn resolve_wallet_keypair_path(args: &WalletLocatorArgs) -> Result<PathBuf> {
    if let Some(keypair) = &args.keypair {
        return Ok(keypair.clone());
    }

    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let store_name = config
        .as_ref()
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.store_name.as_deref())
        .unwrap_or(&args.peer_store_name);
    Ok(config
        .as_ref()
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.keypair_path.as_deref())
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            home.join("stores")
                .join(store_name)
                .join("db")
                .join("keypair.json")
        }))
}

fn confirm_wallet_backup_reveal(yes: bool) -> Result<()> {
    if yes {
        return Ok(());
    }
    if !io::stdin().is_terminal() {
        bail!("refusing to reveal a mnemonic without --yes in a non-interactive shell");
    }

    println!("This will print the wallet mnemonic. Anyone who sees it can restore this wallet.");
    print!("Type REVEAL to continue: ");
    io::stdout().flush()?;
    let mut answer = String::new();
    io::stdin().read_line(&mut answer)?;
    if answer.trim() != "REVEAL" {
        bail!("wallet backup cancelled");
    }
    Ok(())
}

fn print_wallet_show(wallet: &WalletInfo) {
    println!("Public key: {}", wallet.public_key);
    if let Some(address) = wallet.address.as_deref() {
        println!("Address: {address}");
    }
    if let Some(derivation_path) = wallet.derivation_path.as_deref() {
        println!("Derivation path: {derivation_path}");
    }
    println!("Keypair: {}", wallet.keypair_path);
}

fn print_wallet_backup(wallet: &WalletInfo) {
    print_wallet_show(wallet);
    if let Some(mnemonic) = wallet.mnemonic.as_deref() {
        println!("Mnemonic: {mnemonic}");
        println!(
            "Restore command: mayhem wallet import --keypair {} --mnemonic '<mnemonic>'",
            wallet.keypair_path
        );
    }
}

fn rules_hash(args: RulesHashArgs) -> Result<()> {
    let rules_doc = read_rules_doc(args.rules_path.as_deref())?;
    if args.print_json {
        println!(
            "{}",
            serde_json::to_string_pretty(&json!({
                "rules_path": rules_doc.path,
                "hash": rules_doc.hash,
                "bytes": rules_doc.bytes,
            }))?
        );
    } else {
        println!("{}", rules_doc.hash);
    }
    Ok(())
}

async fn rules_review(args: RulesReviewArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let rpc_url = args
        .rpc_url
        .clone()
        .or_else(|| {
            config
                .as_ref()
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.rpc_url.clone())
        })
        .unwrap_or_else(|| DEFAULT_RPC_URL.to_owned());
    let store_name = config
        .as_ref()
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.store_name.clone())
        .unwrap_or_else(|| args.peer_store_name.clone());
    let keypair_path = config
        .as_ref()
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.keypair_path.as_ref())
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            home.join("stores")
                .join(&store_name)
                .join("db")
                .join("keypair.json")
        });
    let password = args.wallet_password.clone().unwrap_or_default();
    let wallet = inspect_wallet(&keypair_path, &password).await?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let rules_doc = read_rules_doc(args.rules_path.as_deref())?;
    let rules = resolve_rules(None, None, &rpc, Some(&rules_doc)).await?;
    let prior_consent = read_consent_state(&rpc, &wallet.public_key).await?;
    let already_consented = consent_matches(prior_consent.as_ref(), &rules);
    let previous_rules = read_current_accepted_rules(&home)?;

    if !args.print_json {
        print_rules_review(
            &home,
            &rules_doc,
            &rules,
            previous_rules.as_deref(),
            prior_consent.as_ref(),
        )?;
    }

    let consent = if already_consented && !args.sim {
        if previous_rules.as_deref() != Some(rules_doc.text.as_str()) {
            confirm_rules_acceptance(args.yes)?;
            persist_rules_acceptance(&home, &rules_doc, &rules)?;
        }
        ConsentReport {
            skipped: true,
            simulated: false,
            rules: Some(rules.clone()),
            tx: None,
            command_hash: None,
            feature: None,
            result: None,
            state: prior_consent.clone(),
        }
    } else {
        confirm_rules_acceptance(args.yes)?;
        let consent = submit_consent(
            &rpc,
            &keypair_path,
            &password,
            &wallet,
            rules.clone(),
            args.sim,
        )
        .await?;
        if !args.sim {
            persist_rules_acceptance(&home, &rules_doc, &rules)?;
        }
        consent
    };
    let consent_skipped = consent.skipped;
    let consent_simulated = consent.simulated;
    let rules_ver = rules.ver;

    let report = json!({
        "home": home,
        "wallet": {
            "public_key": wallet.public_key,
            "address": wallet.address,
            "keypair_path": wallet.keypair_path,
        },
        "network": {
            "rpc_url": rpc_url,
        },
        "rules": {
            "ver": rules.ver,
            "hash": rules.hash,
            "local_hash": rules_doc.hash,
            "path": rules_doc.path,
            "bytes": rules_doc.bytes,
        },
        "prior_consent": prior_consent,
        "already_consented": already_consented,
        "consent": consent,
    });

    if args.print_json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if consent_skipped {
        println!("Consent: already current for rules v{rules_ver}");
    } else if consent_simulated {
        println!("Consent: simulated for rules v{rules_ver}");
    } else {
        println!("Consent: submitted and observed for rules v{rules_ver}");
    }

    Ok(())
}

fn doctor(args: DoctorArgs) -> Result<()> {
    let fixture = args
        .fixture
        .as_deref()
        .map(|value| {
            FixtureProfile::parse(value).with_context(|| {
                format!(
                    "unknown fixture {value}; expected apple-silicon, linux-nvidia, or cpu-only"
                )
            })
        })
        .transpose()?;

    let mut options = ProbeOptions::default();
    if let Some(path) = args.disk_path {
        options.disk_path = absolutize(path)?;
    }
    options.run_disk_bench = !args.skip_disk_bench;
    options.disk_bench_mib = args.disk_bench_mib;
    options.fixture = fixture;

    let report = probe(options);
    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print!("{}", human_report(&report));
    }
    Ok(())
}

#[derive(Debug, Serialize)]
struct CatalogListReport {
    ok: bool,
    catalog_path: PathBuf,
    signature_path: PathBuf,
    catalog_hash: String,
    key_id: String,
    tier_filter: String,
    local_hardware: Option<CatalogListHardware>,
    authority: String,
    model_count: usize,
    artifact_count: usize,
    models: Vec<CatalogListModel>,
}

#[derive(Debug, Serialize)]
struct CatalogListModel {
    model_id: String,
    model_class: String,
    family: String,
    params_b: f64,
    tier: String,
    min_app_version: Option<String>,
    license: String,
    price_ref_mu: CatalogListPrice,
    caps: CatalogListCaps,
    requirements: CatalogListRequirements,
    adapter: catalog::CatalogAdapter,
    canary_set: String,
    canary_match_min: f64,
    canary_verification_method: String,
    canary_verification_tolerance_bps: Option<u32>,
    artifacts: Vec<CatalogListArtifact>,
}

#[derive(Debug, Serialize)]
struct CatalogListPrice {
    denom: String,
    rate_map: Vec<RateMapEntry>,
}

#[derive(Debug, Serialize)]
struct CatalogListCaps {
    tools: bool,
    json: bool,
    ctx_max: u64,
    vision: bool,
    image: bool,
    video: bool,
    audio: bool,
    output_modality: Option<String>,
    output_modalities: Vec<String>,
}

#[derive(Debug, Serialize)]
struct CatalogListRequirements {
    min_ram_gb: u64,
    min_vram_gb_full_offload: u64,
    backends: Vec<String>,
}

#[derive(Debug, Serialize)]
struct CatalogListArtifact {
    artifact: String,
    engine: String,
    compatibility: Option<CatalogArtifactCompatibility>,
    artifact_root: String,
    artifact_root_kind: String,
    weights_bytes: u64,
    weights_human: String,
    source_kind: String,
    source_repo: String,
    source_revision: String,
    source_path: String,
    source_url: Option<String>,
    source_sha256: Option<String>,
    canary_fingerprint: Option<String>,
    notes: Option<String>,
}

#[derive(Debug, Serialize)]
struct CatalogListHardware {
    source: String,
    fixture: Option<String>,
    host: String,
    selected_backend: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
struct CatalogArtifactCompatibility {
    compatible: bool,
    status: String,
    reason: String,
    suggestion: Option<String>,
}

fn catalog_list(args: CatalogListArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let signature_path = args
        .signature_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
    let signature_path = absolutize(signature_path)?;
    let keys_dir = args
        .keys_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let keys_dir = absolutize(keys_dir)?;
    let canaries_dir = args
        .canaries_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let canaries_dir = absolutize(canaries_dir)?;

    let verification = catalog::verify(catalog::VerifyOptions {
        catalog_path: catalog_path.clone(),
        signature_path: signature_path.clone(),
        keys_dir,
        canaries_dir,
        check_dev_downloads: false,
        check_launch_sources: false,
        hf_token_file: None,
    })?;
    if !verification.ok {
        if args.json {
            println!("{}", serde_json::to_string_pretty(&verification)?);
        } else {
            for error in &verification.errors {
                eprintln!("Catalog error: {error}");
            }
        }
        bail!("catalog verification failed");
    }

    let catalog_doc = catalog::load_document(&catalog_path)?;
    let report = catalog_list_report(
        &catalog_doc,
        catalog_path,
        signature_path,
        verification.catalog_hash,
        verification.key_id,
        args.tier,
        None,
    );
    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_catalog_list_report(&report);
    }
    Ok(())
}

fn catalog_list_report(
    catalog_doc: &catalog::CatalogDocument,
    catalog_path: PathBuf,
    signature_path: PathBuf,
    catalog_hash: String,
    key_id: String,
    tier: CatalogListTier,
    hardware: Option<&HardwareReport>,
) -> CatalogListReport {
    let models = catalog_doc
        .models
        .iter()
        .filter(|model| catalog_list_tier_matches(model.tier.as_str(), tier))
        .map(|model| catalog_list_model(model, hardware))
        .collect::<Vec<_>>();
    let artifact_count = models.iter().map(|model| model.artifacts.len()).sum();
    CatalogListReport {
        ok: true,
        catalog_path,
        signature_path,
        catalog_hash,
        key_id,
        tier_filter: catalog_list_tier_name(tier).to_owned(),
        local_hardware: hardware.map(catalog_list_hardware),
        authority: "admin-signed catalog; live routability still requires active contract ledger enclave, room, admin price, and provider join".to_owned(),
        model_count: models.len(),
        artifact_count,
        models,
    }
}

fn catalog_list_tier_matches(model_tier: &str, filter: CatalogListTier) -> bool {
    match filter {
        CatalogListTier::Launch => model_tier == "launch",
        CatalogListTier::Dev => model_tier == "dev",
        CatalogListTier::All => true,
    }
}

fn catalog_list_tier_name(tier: CatalogListTier) -> &'static str {
    match tier {
        CatalogListTier::Launch => "launch",
        CatalogListTier::Dev => "dev",
        CatalogListTier::All => "all",
    }
}

fn catalog_list_hardware(hardware: &HardwareReport) -> CatalogListHardware {
    CatalogListHardware {
        source: hardware.source.kind.clone(),
        fixture: hardware.source.fixture.clone(),
        host: format!("{}/{}", hardware.host.os, hardware.host.arch),
        selected_backend: hardware.selected_backend.clone(),
    }
}

fn catalog_list_model(
    model: &catalog::CatalogModel,
    hardware: Option<&HardwareReport>,
) -> CatalogListModel {
    let artifacts = model
        .artifacts
        .iter()
        .map(|(artifact_name, artifact)| CatalogListArtifact {
            artifact: artifact_name.clone(),
            engine: artifact.engine.clone(),
            compatibility: hardware.map(|hardware| {
                artifact_hardware_compatibility(model, artifact_name, artifact, hardware)
            }),
            artifact_root: artifact.artifact_root.clone(),
            artifact_root_kind: artifact.artifact_root_kind.clone(),
            weights_bytes: artifact.weights_bytes,
            weights_human: human_bytes(artifact.weights_bytes),
            source_kind: artifact.source.kind.clone(),
            source_repo: artifact.source.repo.clone(),
            source_revision: artifact.source.revision.clone(),
            source_path: artifact.path.clone(),
            source_url: catalog::huggingface_resolve_url(&artifact.source, &artifact.path).ok(),
            source_sha256: artifact.source_sha256.clone(),
            canary_fingerprint: model.canary.fingerprints.get(artifact_name).cloned(),
            notes: artifact.notes.clone(),
        })
        .collect();
    CatalogListModel {
        model_id: model.model_id.clone(),
        model_class: model.model_class.clone(),
        family: model.family.clone(),
        params_b: model.params_b,
        tier: model.tier.clone(),
        min_app_version: model.min_app_version.clone(),
        license: model.provenance.license.clone(),
        price_ref_mu: CatalogListPrice {
            denom: model.price_ref_mu.denom.clone(),
            rate_map: text_generation_rate_map(
                model.price_ref_mu.in_per_1k,
                model.price_ref_mu.out_per_1k,
            ),
        },
        caps: CatalogListCaps {
            tools: model.caps.tools,
            json: model.caps.json,
            ctx_max: model.caps.ctx_max,
            vision: model.caps.vision,
            image: model.caps.image,
            video: model.caps.video,
            audio: model.caps.audio,
            output_modality: model.caps.output_modality.clone(),
            output_modalities: model.caps.output_modalities.clone(),
        },
        requirements: CatalogListRequirements {
            min_ram_gb: model.requirements.min_ram_gb,
            min_vram_gb_full_offload: model.requirements.min_vram_gb_full_offload,
            backends: model.requirements.backends.clone(),
        },
        adapter: model.adapter.clone(),
        canary_set: model.canary.set_id.clone(),
        canary_match_min: model.canary.match_min,
        canary_verification_method: model.canary.verification_method.clone(),
        canary_verification_tolerance_bps: model.canary.verification_tolerance_bps,
        artifacts,
    }
}

fn artifact_hardware_compatibility(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    hardware: &HardwareReport,
) -> CatalogArtifactCompatibility {
    let mut compatibility =
        artifact_hardware_compatibility_base(model, artifact_name, artifact, hardware);
    if !compatibility.compatible {
        compatibility.suggestion =
            compatible_catalog_artifact_suggestion(model, hardware, Some(artifact_name));
    }
    compatibility
}

fn artifact_hardware_compatibility_base(
    model: &catalog::CatalogModel,
    artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
    hardware: &HardwareReport,
) -> CatalogArtifactCompatibility {
    if !model
        .requirements
        .backends
        .iter()
        .any(|backend| backend == &artifact.engine)
    {
        return incompatible_artifact(format!(
            "artifact backend {} is not listed in model requirements",
            artifact.engine
        ));
    }
    let min_ram_bytes = gib_u64(model.requirements.min_ram_gb);
    if hardware.memory.total_bytes < min_ram_bytes {
        return incompatible_artifact(format!(
            "needs at least {} GiB RAM; local host has {}",
            model.requirements.min_ram_gb,
            human_bytes(hardware.memory.total_bytes)
        ));
    }
    if let Some(requirement) =
        unsatisfied_cpu_flag_requirement(&model.requirements.cpu_flags, hardware)
    {
        return incompatible_artifact(format!(
            "missing required CPU feature expression {requirement}"
        ));
    }
    let Some(verdict) = hardware
        .backend_verdicts
        .iter()
        .find(|verdict| verdict.backend == artifact.engine)
    else {
        return incompatible_artifact(format!(
            "backend {} is not reported by hwprobe on this host",
            artifact.engine
        ));
    };
    if verdict.status == VerdictStatus::Insufficient {
        return incompatible_artifact(format!(
            "{}; {}",
            backend_requirement_hint(&artifact.engine),
            verdict
                .reason
                .as_deref()
                .unwrap_or("hwprobe marked this backend insufficient")
        ));
    }
    if let Some(min_compute_cap) = artifact.min_compute_cap.as_deref() {
        if !hardware_supports_compute_cap(hardware, min_compute_cap) {
            return incompatible_artifact(format!(
                "artifact {artifact_name} requires NVIDIA compute capability >= {min_compute_cap}; local best is {}",
                best_compute_capability_label(hardware)
            ));
        }
    }
    if artifact.engine == "trt-llm" || artifact.engine == "vllm" {
        let min_vram_bytes = gib_u64(model.requirements.min_vram_gb_full_offload);
        if min_vram_bytes > 0 && total_dedicated_vram_bytes(hardware) < min_vram_bytes {
            return incompatible_artifact(format!(
                "needs at least {} GiB dedicated VRAM for {}; local dedicated VRAM is {}",
                model.requirements.min_vram_gb_full_offload,
                artifact.engine,
                human_bytes(total_dedicated_vram_bytes(hardware))
            ));
        }
    }
    compatible_artifact(format!("{:?}", verdict.status))
}

fn compatible_artifact(status: String) -> CatalogArtifactCompatibility {
    CatalogArtifactCompatibility {
        compatible: true,
        status,
        reason: "local hardware can run this artifact".to_owned(),
        suggestion: None,
    }
}

fn incompatible_artifact(reason: String) -> CatalogArtifactCompatibility {
    CatalogArtifactCompatibility {
        compatible: false,
        status: "incompatible".to_owned(),
        reason,
        suggestion: None,
    }
}

fn compatible_catalog_artifact_suggestion(
    model: &catalog::CatalogModel,
    hardware: &HardwareReport,
    exclude_artifact: Option<&str>,
) -> Option<String> {
    model
        .artifacts
        .iter()
        .filter(|(name, _)| exclude_artifact != Some(name.as_str()))
        .filter_map(|(name, artifact)| {
            let compatibility =
                artifact_hardware_compatibility_base(model, name, artifact, hardware);
            compatibility
                .compatible
                .then_some((name, artifact, backend_rank(&artifact.engine)))
        })
        .max_by_key(|(_, _, rank)| *rank)
        .map(|(name, artifact, _)| {
            format!(
                "use catalog artifact {name} via {} for model {}",
                artifact.engine, model.model_id
            )
        })
}

fn backend_requirement_hint(backend: &str) -> &'static str {
    match backend {
        "mlx" => "MLX requires Apple Silicon with a Metal unified-memory GPU",
        "trt-llm" => {
            "TensorRT-LLM requires a compatible NVIDIA GPU; NVFP4 artifacts require Blackwell-class compute capability"
        }
        "vllm" => "vLLM launch artifacts require a compatible NVIDIA GPU",
        "llama.cpp" => "llama.cpp requires enough RAM and a compatible CPU/GPU runtime",
        "stable-diffusion.cpp" => {
            "stable-diffusion.cpp requires enough local RAM and preferably a local accelerator"
        }
        "whisper.cpp" => "whisper.cpp requires enough local RAM and CPU SIMD support",
        "piper" => "Piper requires enough local RAM for the voice artifact",
        _ => "backend is not compatible with this host",
    }
}

fn unsatisfied_cpu_flag_requirement(
    requirements: &[String],
    hardware: &HardwareReport,
) -> Option<String> {
    requirements
        .iter()
        .find(|requirement| !cpu_flag_expression_satisfied(requirement, hardware))
        .cloned()
}

fn cpu_flag_expression_satisfied(requirement: &str, hardware: &HardwareReport) -> bool {
    requirement
        .split('|')
        .map(str::trim)
        .filter(|flag| !flag.is_empty())
        .any(|flag| match flag.to_ascii_lowercase().as_str() {
            "avx2" => hardware.cpu.flags.avx2,
            "avx512" | "avx512f" => hardware.cpu.flags.avx512,
            "neon" => hardware.cpu.flags.neon,
            _ => false,
        })
}

fn hardware_supports_compute_cap(hardware: &HardwareReport, min_compute_cap: &str) -> bool {
    let Some(minimum) = parse_compute_capability_pair(min_compute_cap) else {
        return false;
    };
    hardware
        .gpus
        .iter()
        .filter_map(|gpu| gpu.compute_capability.as_deref())
        .filter_map(parse_compute_capability_pair)
        .any(|capability| capability >= minimum)
}

fn best_compute_capability_label(hardware: &HardwareReport) -> String {
    hardware
        .gpus
        .iter()
        .filter_map(|gpu| gpu.compute_capability.as_deref())
        .filter_map(parse_compute_capability_pair)
        .max()
        .map(|(major, minor)| format!("{major}.{minor}"))
        .unwrap_or_else(|| "none".to_owned())
}

fn parse_compute_capability_pair(value: &str) -> Option<(u32, u32)> {
    let (major, minor) = value.trim().split_once('.')?;
    Some((major.parse().ok()?, minor.parse().ok()?))
}

fn total_dedicated_vram_bytes(hardware: &HardwareReport) -> u64 {
    hardware
        .gpus
        .iter()
        .filter(|gpu| !gpu.unified_memory)
        .filter_map(|gpu| gpu.memory_bytes)
        .sum()
}

fn gib_u64(gib: u64) -> u64 {
    gib.saturating_mul(1024 * 1024 * 1024)
}

fn print_catalog_list_report(report: &CatalogListReport) {
    println!(
        "Signed catalog: {} (hash {}, key {})",
        report.catalog_path.display(),
        report.catalog_hash,
        report.key_id
    );
    println!(
        "Scope: {} models, {} artifacts, tier filter {}",
        report.model_count, report.artifact_count, report.tier_filter
    );
    println!(
            "Authority: catalog approval is admin-signed; live routing comes from contract ledger state."
        );
    if let Some(hardware) = &report.local_hardware {
        println!(
            "Local hardware: {} selected_backend={}",
            hardware.host,
            hardware.selected_backend.as_deref().unwrap_or("none")
        );
    }

    for model in &report.models {
        println!();
        let params = if model.params_b < 0.1 {
            format!("{:.3}B", model.params_b)
        } else {
            format!("{:.1}B", model.params_b)
        };
        println!(
            "{} [{}] {} {}",
            model.model_id, model.tier, params, model.family
        );
        println!(
            "  price ref: {} {}",
            model.price_ref_mu.denom,
            format_rate_map(&model.price_ref_mu.rate_map)
        );
        if let Some(min_app_version) = model.min_app_version.as_deref() {
            println!("  min app version: Mayhem >= {min_app_version}");
        }
        let output = if model.caps.output_modalities.is_empty() {
            model
                .caps
                .output_modality
                .as_deref()
                .unwrap_or("unspecified")
                .to_owned()
        } else {
            model.caps.output_modalities.join(",")
        };
        println!(
            "  caps: ctx_max={} output={} tools={} json={} vision={} image={} video={} audio={}",
            model.caps.ctx_max,
            output,
            model.caps.tools,
            model.caps.json,
            model.caps.vision,
            model.caps.image,
            model.caps.video,
            model.caps.audio
        );
        println!(
            "  requirements: ram>={}GB vram_full_offload>={}GB backends={}",
            model.requirements.min_ram_gb,
            model.requirements.min_vram_gb_full_offload,
            model.requirements.backends.join(",")
        );
        println!(
            "  adapter: request_shape={} template={} tool_call={} reasoning={} modalities={} normalization={}",
            model.adapter.request_shape_family,
            model.adapter.chat_template_id,
            model.adapter.tool_call_strategy,
            model.adapter.reasoning_passthrough,
            model.adapter.modality_set.join(","),
            model.adapter.response_normalization
        );
        println!(
            "  canary: {} method={} match_min={} tolerance_bps={}",
            model.canary_set,
            model.canary_verification_method,
            model.canary_match_min,
            model
                .canary_verification_tolerance_bps
                .map(|value| value.to_string())
                .unwrap_or_else(|| "none".to_owned())
        );
        for artifact in &model.artifacts {
            let canary = match (
                model.canary_verification_method.as_str(),
                artifact.canary_fingerprint.as_deref(),
            ) {
                ("token_fingerprint", Some(fingerprint)) => short_hash(fingerprint),
                ("token_fingerprint", None) => "missing",
                _ => "n/a",
            };
            let compatibility = artifact
                .compatibility
                .as_ref()
                .map(|compat| {
                    let marker = if compat.compatible { "yes" } else { "no" };
                    format!("{marker} {}", compat.reason)
                })
                .unwrap_or_else(|| "n/a".to_owned());
            println!(
                "  - {} ({}) {} root={} canary={} compat={}",
                artifact.artifact,
                artifact.engine,
                artifact.weights_human,
                short_hash(&artifact.artifact_root),
                canary,
                compatibility
            );
            if let Some(suggestion) = artifact
                .compatibility
                .as_ref()
                .and_then(|compat| compat.suggestion.as_deref())
            {
                println!("    suggestion: {suggestion}");
            }
            println!(
                "    source: {}@{} {}",
                artifact.source_repo, artifact.source_revision, artifact.source_path
            );
        }
    }
}

fn format_rate_map(rate_map: &[RateMapEntry]) -> String {
    normalize_rate_map(rate_map.to_vec())
        .into_iter()
        .map(|entry| {
            format!(
                "{}={}/{}mu",
                entry.unit, entry.per_unit_mu, entry.granularity
            )
        })
        .collect::<Vec<_>>()
        .join(",")
}

fn short_hash(value: &str) -> &str {
    value.get(..12).unwrap_or(value)
}

fn human_bytes(bytes: u64) -> String {
    const GIB: f64 = 1024.0 * 1024.0 * 1024.0;
    const MIB: f64 = 1024.0 * 1024.0;
    if bytes >= 1024 * 1024 * 1024 {
        format!("{:.2}GiB", bytes as f64 / GIB)
    } else if bytes >= 1024 * 1024 {
        format!("{:.2}MiB", bytes as f64 / MIB)
    } else {
        format!("{bytes}B")
    }
}

fn catalog_verify(args: CatalogVerifyArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let signature_path = args
        .signature_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
    let signature_path = absolutize(signature_path)?;
    let keys_dir = args
        .keys_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let keys_dir = absolutize(keys_dir)?;
    let canaries_dir = args
        .canaries_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let canaries_dir = absolutize(canaries_dir)?;
    let hf_token_file = args.hf_token_file.map(absolutize).transpose()?;

    let report = catalog::verify(catalog::VerifyOptions {
        catalog_path,
        signature_path,
        keys_dir,
        canaries_dir,
        check_dev_downloads: args.check_dev_downloads,
        check_launch_sources: args.check_launch_sources,
        hf_token_file,
    })?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
        if !report.ok {
            bail!("catalog verification failed");
        }
    } else if report.ok {
        println!(
            "Catalog OK: {} models ({} dev, {} launch), {} artifacts, hash {}",
            report.model_count,
            report.dev_model_count,
            report.launch_model_count,
            report.artifact_count,
            report.catalog_hash
        );
        if !report.download_checks.is_empty() {
            println!("Dev downloads checked: {}", report.download_checks.len());
        }
        if !report.source_checks.is_empty() {
            println!("Launch sources checked: {}", report.source_checks.len());
        }
    } else {
        for error in &report.errors {
            eprintln!("Catalog error: {error}");
        }
        for check in report.source_checks.iter().filter(|check| !check.ok) {
            let metadata_errors = if check.metadata_errors.is_empty() {
                String::new()
            } else {
                format!(" metadata={}", check.metadata_errors.join(" | "))
            };
            eprintln!(
                "Catalog source error: {} / {} {}@{} {} status={}{}",
                check.model_id,
                check.artifact,
                check.repo,
                check.revision,
                check.path,
                check
                    .status
                    .map(|status| status.to_string())
                    .unwrap_or_else(|| check.error.as_deref().unwrap_or("error").to_owned()),
                metadata_errors
            );
        }
        bail!("catalog verification failed");
    }
    Ok(())
}

fn catalog_sign(args: CatalogSignArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let signature_output = absolutize(args.signature_output.clone())?;
    if signature_output.exists() && !args.force {
        bail!(
            "refusing to overwrite {}; pass --force after reviewing the catalog draft",
            signature_output.display()
        );
    }
    let keys_dir = args
        .keys_dir
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let keys_dir = absolutize(keys_dir)?;
    let seed_file = absolutize(args.seed_file.clone())?;

    let report = catalog_sign_report(CatalogSignRequest {
        catalog_path,
        signature_output,
        keys_dir,
        key_id: args.key_id,
        seed_file,
        write_key: args.write_key,
        created_at: args.created_at,
    })?;

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("Catalog signature written.");
        println!("Catalog: {}", report.catalog_path.display());
        println!("Signature: {}", report.signature_output.display());
        println!("Signed path: {}", report.signed_path);
        println!("Catalog blake3: {}", report.blake3);
        println!("Key id: {}", report.key_id);
        println!("Public key: {}", report.public_key);
        if let Some(key_path) = &report.key_path {
            println!(
                "Key record: {} ({})",
                key_path.display(),
                if report.key_written {
                    "written"
                } else {
                    "already matched"
                }
            );
        }
        println!();
        println!("Verify with:");
        println!(
            "mayhem catalog verify --catalog-path {} --signature-path {} --keys-dir {}",
            shell_single_quote(&report.catalog_path.display().to_string()),
            shell_single_quote(&report.signature_output.display().to_string()),
            shell_single_quote(&report.keys_dir.display().to_string())
        );
    }
    Ok(())
}

