fn catalog_apply_canary_reports(args: CatalogApplyCanaryReportsArgs) -> Result<()> {
    let catalog_path = args
        .catalog_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let canaries_dir = args
        .canaries_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let canaries_dir = absolutize(canaries_dir)?;
    let output = absolutize(args.output.clone())?;
    if output == catalog_path {
        bail!(
            "refusing to overwrite {}; pass a separate --output path for the unsigned catalog draft",
            catalog_path.display()
        );
    }
    let report_paths = args
        .reports
        .iter()
        .map(|path| absolutize(path.clone()))
        .collect::<Result<Vec<_>>>()?;
    let mut catalog_value = read_json_file(&catalog_path)?;
    let catalog_doc: catalog::CatalogDocument = serde_json::from_value(catalog_value.clone())
        .with_context(|| {
            format!(
                "parsing catalog {} before applying canary reports",
                catalog_path.display()
            )
        })?;
    let mut report = catalog_canary_evidence_report(
        &catalog_doc,
        catalog_path,
        canaries_dir,
        !args.include_dev,
        &report_paths,
        CatalogCanaryReportMode::ApplyToCatalog,
    );

    if report.ok {
        let applied = apply_canary_report_fingerprints(&mut catalog_value, &report)?;
        report.applied_count = Some(applied);
        write_json_file(&output, &catalog_value)?;
        report.output_path = Some(output.clone());
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("Canary calibration catalog apply.");
        println!("Catalog: {}", report.catalog_path.display());
        println!("Output: {}", output.display());
        println!(
            "Coverage: {} models, {} artifacts, {} reports, applied={}, ok={}",
            report.model_count,
            report.artifact_count,
            report.report_count,
            report.applied_count.unwrap_or(0),
            report.ok
        );
        for entry in &report.entries {
            let status = if entry.ok { "ok" } else { "error" };
            println!(
                "- {} / {} ({}) [{}]: {}",
                entry.model_id, entry.artifact, entry.engine, entry.canary_set, status
            );
            for error in &entry.errors {
                println!("  error: {error}");
            }
        }
        for error in &report.errors {
            println!("Global error: {error}");
        }
    }

    if !report.ok {
        bail!(
            "canary calibration catalog apply has {} error(s); no output was written",
            report.errors.len()
        );
    }
    Ok(())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum CatalogCanaryReportMode {
    VerifyMatchesCatalog,
    ApplyToCatalog,
}

fn catalog_canary_evidence_report(
    catalog_doc: &catalog::CatalogDocument,
    catalog_path: PathBuf,
    canaries_dir: PathBuf,
    launch_only: bool,
    report_paths: &[PathBuf],
    mode: CatalogCanaryReportMode,
) -> CatalogCanaryEvidenceReport {
    let mut entries = Vec::new();
    let mut entry_index = BTreeMap::new();
    let mut errors = Vec::new();

    for model in &catalog_doc.models {
        if launch_only && model.tier != "launch" {
            continue;
        }
        let canary_check = canary_set_matrix_check(&canaries_dir, &model.canary.set_id);
        let canary_set_sha256 = match canary_set_file_sha256(&canaries_dir, &model.canary.set_id) {
            Ok(hash) => Some(hash),
            Err(err) => {
                let message = format!("canary set hash error for {}: {err}", model.canary.set_id);
                errors.push(message.clone());
                None
            }
        };
        for (artifact_name, artifact) in &model.artifacts {
            let mut entry_errors = Vec::new();
            if let Err(err) = &canary_check {
                entry_errors.push(err.clone());
            }
            if canary_set_sha256.is_none() {
                entry_errors.push(format!(
                    "canary set {} sha256 could not be computed",
                    model.canary.set_id
                ));
            }
            let expected_fingerprint = model.canary.fingerprints.get(artifact_name).cloned();
            match expected_fingerprint.as_deref() {
                Some(value) if is_hex_len(value, 64) => {}
                Some(_) => entry_errors.push(format!(
                    "canary fingerprint for {artifact_name} must be 32-byte hex"
                )),
                None => entry_errors.push(format!(
                    "canary fingerprint missing artifact {artifact_name}"
                )),
            }
            let expected_token_prefixes = model.canary.token_prefixes.get(artifact_name).cloned();
            if mode == CatalogCanaryReportMode::VerifyMatchesCatalog {
                match expected_token_prefixes.as_ref() {
                    Some(prefixes) if !prefixes.is_empty() => {}
                    Some(_) => entry_errors.push(format!(
                        "canary token_prefixes for {artifact_name} must not be empty"
                    )),
                    None => entry_errors.push(format!(
                        "canary token_prefixes missing artifact {artifact_name}"
                    )),
                }
            }
            let prompt_count = canary_check.as_ref().ok().copied();
            let key = (model.model_id.clone(), artifact_name.clone());
            entry_index.insert(key, entries.len());
            entries.push(CatalogCanaryEvidenceEntry {
                model_id: model.model_id.clone(),
                tier: model.tier.clone(),
                artifact: artifact_name.clone(),
                engine: artifact.engine.clone(),
                canary_set: model.canary.set_id.clone(),
                canary_set_sha256: canary_set_sha256.clone(),
                prompt_count,
                expected_fingerprint,
                expected_token_prefixes,
                expected_artifact_binding: catalog_canary_artifact_binding(artifact),
                report_path: None,
                report_fingerprint: None,
                report_token_prefixes: None,
                report_canary_set_sha256: None,
                report_artifact_binding: None,
                matches_catalog: None,
                token_prefixes_match_catalog: None,
                ok: entry_errors.is_empty(),
                errors: entry_errors,
            });
        }
    }

    if entries.is_empty() {
        errors.push(if launch_only {
            "catalog has no launch model artifacts to verify".to_owned()
        } else {
            "catalog has no model artifacts to verify".to_owned()
        });
    }

    for path in report_paths {
        let report_value = match read_json_file(path) {
            Ok(value) => value,
            Err(err) => {
                errors.push(format!("{}: {err}", path.display()));
                continue;
            }
        };
        let calibration =
            match serde_json::from_value::<CatalogCanaryCalibrationReport>(report_value) {
                Ok(report) => report,
                Err(err) => {
                    errors.push(format!(
                        "{}: parsing calibration report: {err}",
                        path.display()
                    ));
                    continue;
                }
            };
        let key = (calibration.model_id.clone(), calibration.artifact.clone());
        let Some(entry_idx) = entry_index.get(&key).copied() else {
            errors.push(format!(
                "{} references {} / {}, which is outside the requested catalog scope",
                path.display(),
                calibration.model_id,
                calibration.artifact
            ));
            continue;
        };
        let entry = &mut entries[entry_idx];
        if entry.report_path.is_some() {
            let message = format!(
                "duplicate calibration report for {} / {}",
                calibration.model_id, calibration.artifact
            );
            entry.errors.push(message.clone());
            errors.push(format!("{}: {message}", path.display()));
            entry.ok = false;
            continue;
        }

        entry.report_path = Some(path.clone());
        entry.report_fingerprint = Some(calibration.catalog_fingerprint.clone());
        let report_token_prefixes = calibration
            .prompts
            .iter()
            .map(|prompt| (prompt.prompt_id.clone(), prompt.token_ids.clone()))
            .collect::<BTreeMap<_, _>>();
        entry.report_token_prefixes = Some(report_token_prefixes.clone());
        entry.report_canary_set_sha256 = Some(calibration.canary_set_sha256.clone());
        entry.report_artifact_binding = Some(calibration.artifact_binding.clone());
        let matches_catalog = entry
            .expected_fingerprint
            .as_ref()
            .map(|expected| expected == &calibration.catalog_fingerprint);
        entry.matches_catalog = matches_catalog;
        let token_prefixes_match_catalog = entry
            .expected_token_prefixes
            .as_ref()
            .map(|expected| expected == &report_token_prefixes);
        entry.token_prefixes_match_catalog = token_prefixes_match_catalog;

        if calibration.engine != entry.engine {
            entry.errors.push(format!(
                "report engine {} does not match catalog engine {}",
                calibration.engine, entry.engine
            ));
        }
        if calibration.canary_set != entry.canary_set {
            entry.errors.push(format!(
                "report canary set {} does not match catalog canary set {}",
                calibration.canary_set, entry.canary_set
            ));
        }
        if Some(&calibration.canary_set_sha256) != entry.canary_set_sha256.as_ref() {
            entry.errors.push(format!(
                "report canary_set_sha256 {} does not match current canary set hash {}",
                calibration.canary_set_sha256,
                entry.canary_set_sha256.as_deref().unwrap_or("<missing>")
            ));
        }
        if calibration.artifact_binding != entry.expected_artifact_binding {
            entry.errors.push(
                "report artifact binding does not match current catalog artifact root/source"
                    .to_owned(),
            );
        }
        if calibration.prompt_count != calibration.prompts.len() {
            entry.errors.push(format!(
                "report prompt_count {} does not match {} prompt reports",
                calibration.prompt_count,
                calibration.prompts.len()
            ));
        }
        if let Some(expected_count) = entry.prompt_count {
            if calibration.prompt_count != expected_count {
                entry.errors.push(format!(
                    "report prompt_count {} does not match canary set prompt count {}",
                    calibration.prompt_count, expected_count
                ));
            }
        }
        if !is_hex_len(&calibration.catalog_fingerprint, 64) {
            entry
                .errors
                .push("report catalog_fingerprint must be 32-byte hex".to_owned());
        }
        if !is_hex_len(&calibration.canary_set_sha256, 64) {
            entry
                .errors
                .push("report canary_set_sha256 must be 32-byte hex".to_owned());
        }
        if calibration.runtime_config.ctx_size == 0 {
            entry
                .errors
                .push("report runtime_config.ctx_size must be positive".to_owned());
        }
        if calibration.engine == "trt-llm"
            && calibration
                .runtime_config
                .trt_tensor_parallel
                .unwrap_or_default()
                == 0
        {
            entry.errors.push(
                "report runtime_config.trt_tensor_parallel must be positive for TensorRT"
                    .to_owned(),
            );
        }
        if calibration.existing_catalog_fingerprint != entry.expected_fingerprint {
            entry.errors.push(
                "report existing_catalog_fingerprint does not match current catalog".to_owned(),
            );
        }
        if mode == CatalogCanaryReportMode::VerifyMatchesCatalog && matches_catalog != Some(true) {
            entry.errors.push(format!(
                "report fingerprint {} does not match catalog fingerprint {}",
                calibration.catalog_fingerprint,
                entry.expected_fingerprint.as_deref().unwrap_or("<missing>")
            ));
        }
        if mode == CatalogCanaryReportMode::VerifyMatchesCatalog
            && calibration.matches_existing_catalog != Some(true)
        {
            entry
                .errors
                .push("report was not generated as a catalog match".to_owned());
        }
        let mut prompt_ids = BTreeSet::new();
        for prompt in &calibration.prompts {
            if !prompt_ids.insert(prompt.prompt_id.clone()) {
                entry
                    .errors
                    .push(format!("duplicate prompt report {}", prompt.prompt_id));
            }
            if !is_hex_len(&prompt.fingerprint, 64) {
                entry.errors.push(format!(
                    "prompt {} fingerprint must be 32-byte hex",
                    prompt.prompt_id
                ));
            }
            if prompt.token_count != prompt.completion_tokens as usize {
                entry.errors.push(format!(
                    "prompt {} token_count {} does not match completion_tokens {}",
                    prompt.prompt_id, prompt.token_count, prompt.completion_tokens
                ));
            }
            if prompt.token_count != prompt.token_ids.len() {
                entry.errors.push(format!(
                    "prompt {} token_count {} does not match token_ids length {}",
                    prompt.prompt_id,
                    prompt.token_count,
                    prompt.token_ids.len()
                ));
            }
            if prompt.token_ids.is_empty() {
                entry.errors.push(format!(
                    "prompt {} token_ids must not be empty",
                    prompt.prompt_id
                ));
            }
        }
        if mode == CatalogCanaryReportMode::VerifyMatchesCatalog
            && token_prefixes_match_catalog != Some(true)
        {
            entry
                .errors
                .push("report token_ids do not match catalog token_prefixes".to_owned());
        }
        entry.ok = entry.errors.is_empty();
    }

    for entry in &mut entries {
        if entry.report_path.is_none() {
            entry.errors.push("missing calibration report".to_owned());
        }
        entry.ok = entry.errors.is_empty();
        if !entry.ok {
            errors.extend(
                entry
                    .errors
                    .iter()
                    .map(|error| format!("{} {}: {error}", entry.model_id, entry.artifact)),
            );
        }
    }

    let model_count = entries
        .iter()
        .map(|entry| entry.model_id.as_str())
        .collect::<BTreeSet<_>>()
        .len();
    let report_count = entries
        .iter()
        .filter(|entry| entry.report_path.is_some())
        .count();
    CatalogCanaryEvidenceReport {
        catalog_path,
        canaries_dir,
        output_path: None,
        launch_only,
        model_count,
        artifact_count: entries.len(),
        report_count,
        applied_count: None,
        ok: errors.is_empty(),
        entries,
        errors,
    }
}

fn apply_canary_report_fingerprints(
    catalog_value: &mut Value,
    report: &CatalogCanaryEvidenceReport,
) -> Result<usize> {
    let models = catalog_value
        .get_mut("models")
        .and_then(Value::as_array_mut)
        .context("catalog JSON must contain models array")?;
    let mut applied = 0usize;
    for entry in &report.entries {
        let Some(fingerprint) = &entry.report_fingerprint else {
            continue;
        };
        let model = models
            .iter_mut()
            .find(|model| model.get("model_id").and_then(Value::as_str) == Some(&entry.model_id))
            .with_context(|| format!("model {} disappeared from catalog JSON", entry.model_id))?;
        let canary = model
            .get_mut("canary")
            .and_then(Value::as_object_mut)
            .with_context(|| format!("model {} has no canary object", entry.model_id))?;
        let fingerprints = canary
            .entry("fingerprints")
            .or_insert_with(|| json!({}))
            .as_object_mut()
            .with_context(|| {
                format!(
                    "model {} canary.fingerprints is not an object",
                    entry.model_id
                )
            })?;
        fingerprints.insert(entry.artifact.clone(), json!(fingerprint));
        let token_prefixes = canary
            .entry("token_prefixes")
            .or_insert_with(|| json!({}))
            .as_object_mut()
            .with_context(|| {
                format!(
                    "model {} canary.token_prefixes is not an object",
                    entry.model_id
                )
            })?;
        if let Some(prefixes) = &entry.report_token_prefixes {
            token_prefixes.insert(entry.artifact.clone(), json!(prefixes));
        }
        applied += 1;
    }
    Ok(applied)
}

struct CatalogCanaryPlanInput<'a> {
    catalog_doc: &'a catalog::CatalogDocument,
    catalog_path: PathBuf,
    canaries_dir: PathBuf,
    artifact_base: PathBuf,
    report_dir: PathBuf,
    catalog_output: PathBuf,
    trt_engine_base: PathBuf,
    catalog_sign: Option<CatalogCanaryPlanSignOptions>,
    launch_only: bool,
    args: &'a CatalogCanaryPlanArgs,
}

#[derive(Debug, Clone)]
struct CatalogCanaryPlanSignOptions {
    signature_output: PathBuf,
    key_id: String,
    seed_file: PathBuf,
    keys_dir: PathBuf,
    write_key: bool,
    created_at: Option<String>,
}

struct CatalogCanaryCalibrationPlanInput<'a> {
    catalog_path: &'a Path,
    canaries_dir: &'a Path,
    model: &'a catalog::CatalogModel,
    artifact_name: &'a str,
    artifact: &'a catalog::CatalogArtifact,
    artifact_path: &'a Path,
    report_path: &'a Path,
    trt_engine_dir: Option<&'a Path>,
    args: &'a CatalogCanaryPlanArgs,
}

fn catalog_canary_plan_report(input: CatalogCanaryPlanInput<'_>) -> CatalogCanaryPlanReport {
    let CatalogCanaryPlanInput {
        catalog_doc,
        catalog_path,
        canaries_dir,
        artifact_base,
        report_dir,
        catalog_output,
        trt_engine_base,
        catalog_sign,
        launch_only,
        args,
    } = input;
    let mut entries = Vec::new();
    let mut errors = Vec::new();

    for model in &catalog_doc.models {
        if launch_only && model.tier != "launch" {
            continue;
        }
        let canary_check = canary_set_matrix_check(&canaries_dir, &model.canary.set_id);
        for (artifact_name, artifact) in &model.artifacts {
            let mut entry_errors = Vec::new();
            if let Err(err) = &canary_check {
                entry_errors.push(err.clone());
            }
            let artifact_rel_path = PathBuf::from(&artifact.path);
            if artifact_rel_path.is_absolute() {
                entry_errors.push(format!(
                    "catalog artifact path {} must be relative to --artifact-base",
                    artifact.path
                ));
            }
            let artifact_path = catalog_canary_plan_artifact_path(&artifact_base, artifact);
            let report_path = report_dir
                .join(safe_path_component(&model.model_id))
                .join(format!(
                    "{}.canary.json",
                    safe_path_component(artifact_name)
                ));
            let trt_engine_dir = (artifact.engine == "trt-llm").then(|| {
                trt_engine_base
                    .join(safe_path_component(&model.model_id))
                    .join(safe_path_component(artifact_name))
            });
            let calibration_status = match artifact.engine.as_str() {
                "llama.cpp" | "mlx" => "ready",
                "trt-llm" => "requires-prebuilt-trt-engine",
                other => {
                    entry_errors.push(format!("unsupported calibration engine {other}"));
                    "unsupported-calibration-engine"
                }
            }
            .to_owned();
            let command =
                catalog_canary_calibration_plan_command(CatalogCanaryCalibrationPlanInput {
                    catalog_path: &catalog_path,
                    canaries_dir: &canaries_dir,
                    model,
                    artifact_name,
                    artifact,
                    artifact_path: &artifact_path,
                    report_path: &report_path,
                    trt_engine_dir: trt_engine_dir.as_deref(),
                    args,
                });
            let ok = entry_errors.is_empty();
            let entry = CatalogCanaryPlanEntry {
                model_id: model.model_id.clone(),
                tier: model.tier.clone(),
                artifact: artifact_name.clone(),
                engine: artifact.engine.clone(),
                canary_set: model.canary.set_id.clone(),
                prompt_count: canary_check.as_ref().ok().copied(),
                artifact_path,
                report_path,
                trt_engine_dir,
                calibration_status,
                command,
                ok,
                errors: entry_errors,
            };
            if !entry.ok {
                errors.extend(
                    entry
                        .errors
                        .iter()
                        .map(|error| format!("{} {}: {error}", entry.model_id, entry.artifact)),
                );
            }
            entries.push(entry);
        }
    }

    if entries.is_empty() {
        errors.push(if launch_only {
            "catalog has no launch model artifacts to plan".to_owned()
        } else {
            "catalog has no model artifacts to plan".to_owned()
        });
    }

    let report_paths = entries
        .iter()
        .map(|entry| entry.report_path.clone())
        .collect::<Vec<_>>();
    let apply_command = catalog_canary_plan_apply_command(
        &catalog_path,
        &canaries_dir,
        &catalog_output,
        launch_only,
        &report_paths,
    );
    let evidence_command = catalog_canary_plan_evidence_command(
        &catalog_output,
        &canaries_dir,
        launch_only,
        &report_paths,
    );
    let signature_command = catalog_sign
        .as_ref()
        .map(|sign| catalog_canary_plan_sign_command(&catalog_output, sign));
    let model_count = entries
        .iter()
        .map(|entry| entry.model_id.as_str())
        .collect::<BTreeSet<_>>()
        .len();
    CatalogCanaryPlanReport {
        catalog_path,
        canaries_dir,
        artifact_base,
        report_dir,
        catalog_output,
        trt_engine_base,
        launch_only,
        model_count,
        artifact_count: entries.len(),
        ok: errors.is_empty(),
        calibration_commands: entries,
        apply_command,
        signature_command,
        evidence_command,
        errors,
    }
}

fn catalog_canary_calibration_plan_command(
    input: CatalogCanaryCalibrationPlanInput<'_>,
) -> CatalogCanaryPlanCommand {
    let CatalogCanaryCalibrationPlanInput {
        catalog_path,
        canaries_dir,
        model,
        artifact_name,
        artifact,
        artifact_path,
        report_path,
        trt_engine_dir,
        args,
    } = input;
    let mut argv = vec![
        "mayhem".to_owned(),
        "catalog".to_owned(),
        "calibrate-canary".to_owned(),
    ];
    push_plan_path_arg(&mut argv, "--catalog-path", catalog_path);
    push_plan_path_arg(&mut argv, "--canaries-dir", canaries_dir);
    push_plan_value_arg(&mut argv, "--model", &model.model_id);
    push_plan_value_arg(&mut argv, "--artifact", artifact_name);
    push_plan_path_arg(&mut argv, "--artifact-path", artifact_path);
    push_plan_value_arg(&mut argv, "--ctx-size", args.ctx_size.max(1).to_string());
    push_plan_value_arg(&mut argv, "--seed", args.seed.to_string());
    if let Some(threads) = args.threads {
        push_plan_value_arg(&mut argv, "--threads", threads.to_string());
    }
    if let Some(gpu_layers) = args.gpu_layers {
        push_plan_value_arg(&mut argv, "--gpu-layers", gpu_layers.to_string());
    }
    if artifact.engine == "trt-llm" {
        if let Some(trt_engine_dir) = trt_engine_dir {
            push_plan_path_arg(&mut argv, "--trt-engine-dir", trt_engine_dir);
        }
        argv.push("--trt-require-engine-dir".to_owned());
        push_plan_value_arg(
            &mut argv,
            "--trt-tensor-parallel",
            args.trt_tensor_parallel.unwrap_or(1).max(1).to_string(),
        );
        if let Some(kv_cache_dtype) = &args.trt_kv_cache_dtype {
            push_plan_value_arg(&mut argv, "--trt-kv-cache-dtype", kv_cache_dtype);
        }
        if let Some(max_batch_size) = args.trt_max_batch_size {
            push_plan_value_arg(
                &mut argv,
                "--trt-max-batch-size",
                max_batch_size.max(1).to_string(),
            );
        }
        if let Some(max_num_tokens) = args.trt_max_num_tokens {
            push_plan_value_arg(
                &mut argv,
                "--trt-max-num-tokens",
                max_num_tokens.max(args.ctx_size.max(1)).max(1).to_string(),
            );
        }
    }
    push_plan_path_arg(&mut argv, "--report-output", report_path);
    argv.push("--json".to_owned());
    catalog_canary_plan_command(argv)
}

fn catalog_canary_plan_artifact_path(
    artifact_base: &Path,
    artifact: &catalog::CatalogArtifact,
) -> PathBuf {
    artifact_base
        .join(safe_path_component(&artifact.source.kind))
        .join(safe_path_component(&artifact.source.repo))
        .join(safe_path_component(&artifact.source.revision))
        .join(&artifact.path)
}

fn catalog_canary_plan_apply_command(
    catalog_path: &Path,
    canaries_dir: &Path,
    catalog_output: &Path,
    launch_only: bool,
    report_paths: &[PathBuf],
) -> CatalogCanaryPlanCommand {
    let mut argv = vec![
        "mayhem".to_owned(),
        "catalog".to_owned(),
        "apply-canary-reports".to_owned(),
    ];
    push_plan_path_arg(&mut argv, "--catalog-path", catalog_path);
    push_plan_path_arg(&mut argv, "--canaries-dir", canaries_dir);
    push_plan_path_arg(&mut argv, "--output", catalog_output);
    if !launch_only {
        argv.push("--include-dev".to_owned());
    }
    for report_path in report_paths {
        push_plan_path_arg(&mut argv, "--report", report_path);
    }
    argv.push("--json".to_owned());
    catalog_canary_plan_command(argv)
}

fn catalog_canary_plan_sign_command(
    catalog_output: &Path,
    sign: &CatalogCanaryPlanSignOptions,
) -> CatalogCanaryPlanCommand {
    let mut argv = vec!["mayhem".to_owned(), "catalog".to_owned(), "sign".to_owned()];
    push_plan_path_arg(&mut argv, "--catalog-path", catalog_output);
    push_plan_path_arg(&mut argv, "--signature-output", &sign.signature_output);
    push_plan_value_arg(&mut argv, "--key-id", &sign.key_id);
    push_plan_path_arg(&mut argv, "--seed-file", &sign.seed_file);
    push_plan_path_arg(&mut argv, "--keys-dir", &sign.keys_dir);
    if sign.write_key {
        argv.push("--write-key".to_owned());
    }
    if let Some(created_at) = &sign.created_at {
        push_plan_value_arg(&mut argv, "--created-at", created_at);
    }
    argv.push("--json".to_owned());
    catalog_canary_plan_command(argv)
}

fn catalog_canary_plan_evidence_command(
    catalog_path: &Path,
    canaries_dir: &Path,
    launch_only: bool,
    report_paths: &[PathBuf],
) -> CatalogCanaryPlanCommand {
    let mut argv = vec![
        "mayhem".to_owned(),
        "catalog".to_owned(),
        "canary-evidence".to_owned(),
    ];
    push_plan_path_arg(&mut argv, "--catalog-path", catalog_path);
    push_plan_path_arg(&mut argv, "--canaries-dir", canaries_dir);
    if !launch_only {
        argv.push("--include-dev".to_owned());
    }
    for report_path in report_paths {
        push_plan_path_arg(&mut argv, "--report", report_path);
    }
    argv.push("--json".to_owned());
    catalog_canary_plan_command(argv)
}

fn push_plan_path_arg(argv: &mut Vec<String>, flag: &str, path: &Path) {
    argv.push(flag.to_owned());
    argv.push(path.display().to_string());
}

fn push_plan_value_arg(argv: &mut Vec<String>, flag: &str, value: impl ToString) {
    argv.push(flag.to_owned());
    argv.push(value.to_string());
}

fn catalog_canary_plan_command(argv: Vec<String>) -> CatalogCanaryPlanCommand {
    let shell = argv
        .iter()
        .map(|arg| shell_single_quote(arg))
        .collect::<Vec<_>>()
        .join(" ");
    CatalogCanaryPlanCommand { argv, shell }
}

fn catalog_canary_matrix_report(
    catalog_doc: &catalog::CatalogDocument,
    catalog_path: PathBuf,
    canaries_dir: PathBuf,
    launch_only: bool,
) -> CatalogCanaryMatrixReport {
    let mut entries = Vec::new();
    let mut errors = Vec::new();
    for model in &catalog_doc.models {
        if launch_only && model.tier != "launch" {
            continue;
        }
        let canary_check = canary_set_matrix_check(&canaries_dir, &model.canary.set_id);
        for (artifact_name, artifact) in &model.artifacts {
            let mut entry_errors = Vec::new();
            if let Err(err) = &canary_check {
                entry_errors.push(err.clone());
            }
            let fingerprint = model.canary.fingerprints.get(artifact_name).cloned();
            match fingerprint.as_deref() {
                Some(value) if is_hex_len(value, 64) => {}
                Some(_) => entry_errors.push(format!(
                    "canary fingerprint for {artifact_name} must be 32-byte hex"
                )),
                None => entry_errors.push(format!(
                    "canary fingerprint missing artifact {artifact_name}"
                )),
            }
            let calibration_status = match artifact.engine.as_str() {
                "llama.cpp" | "mlx" => "local-calibration-supported",
                "trt-llm" => "hardware-gated-calibration",
                other => {
                    entry_errors.push(format!("unsupported calibration engine {other}"));
                    "unsupported-calibration-engine"
                }
            }
            .to_owned();
            let ok = entry_errors.is_empty();
            let entry = CatalogCanaryMatrixEntry {
                model_id: model.model_id.clone(),
                tier: model.tier.clone(),
                artifact: artifact_name.clone(),
                engine: artifact.engine.clone(),
                canary_set: model.canary.set_id.clone(),
                prompt_count: canary_check.as_ref().ok().copied(),
                fingerprint,
                calibration_status,
                ok,
                errors: entry_errors,
            };
            if !entry.ok {
                errors.extend(
                    entry
                        .errors
                        .iter()
                        .map(|error| format!("{} {}: {error}", entry.model_id, entry.artifact)),
                );
            }
            entries.push(entry);
        }
    }
    if entries.is_empty() {
        errors.push(if launch_only {
            "catalog has no launch model artifacts to audit".to_owned()
        } else {
            "catalog has no model artifacts to audit".to_owned()
        });
    }
    let model_count = entries
        .iter()
        .map(|entry| entry.model_id.as_str())
        .collect::<BTreeSet<_>>()
        .len();
    CatalogCanaryMatrixReport {
        catalog_path,
        canaries_dir,
        launch_only,
        model_count,
        artifact_count: entries.len(),
        ok: errors.is_empty(),
        entries,
        errors,
    }
}

fn canary_set_matrix_check(
    canaries_dir: &Path,
    set_id: &str,
) -> std::result::Result<usize, String> {
    load_canary_prompts(Some(canaries_dir), set_id, None)
        .map_err(|err| err.to_string())
        .and_then(|prompts| {
            for prompt in &prompts {
                if prompt.temperature.unwrap_or(0.0).abs() > f64::EPSILON {
                    return Err(format!(
                        "canary prompt {} in {set_id} must use temperature 0",
                        prompt.id
                    ));
                }
            }
            Ok(prompts.len())
        })
}

fn canary_set_file_sha256(
    canaries_dir: &Path,
    set_id: &str,
) -> std::result::Result<String, String> {
    file_sha256_hex(&canaries_dir.join(format!("{set_id}.json"))).map_err(|err| err.to_string())
}

fn catalog_calibration_backend(
    artifact: &catalog::CatalogArtifact,
    artifact_path: &Path,
    args: &CatalogCalibrateCanaryArgs,
) -> Result<Box<dyn EngineBackend>> {
    let mut config = match artifact.engine.as_str() {
        "llama.cpp" => LoadConfig::gguf(artifact_path),
        "mlx" => LoadConfig::mlx_safetensors(artifact_path),
        "trt-llm" => LoadConfig::trt_llm_checkpoint(artifact_path),
        "whisper.cpp" => LoadConfig::whisper_ggml(artifact_path),
        "piper" => LoadConfig::piper_voice(artifact_path),
        other => bail!("unsupported canary calibration engine {other}"),
    };
    config.ctx_size = args.ctx_size.max(1);
    config.threads = args.threads;
    config.gpu_layers = args.gpu_layers;
    if let Some(max_batch_size) = args.trt_max_batch_size {
        config.batch_size = max_batch_size.max(1);
    }
    if let Some(max_num_tokens) = args.trt_max_num_tokens {
        config.ubatch_size = max_num_tokens.max(config.ctx_size).max(1);
    }
    if let Some(sha256) = &artifact.source_sha256 {
        config.artifact = config.artifact.with_sha256(sha256.clone());
    }

    match artifact.engine.as_str() {
        "llama.cpp" => {
            let mut backend =
                mayhem_engine::LlamaCppBackend::new().context("initializing llama.cpp backend")?;
            backend
                .load(config)
                .context("loading llama.cpp canary calibration artifact")?;
            Ok(Box::new(backend))
        }
        "mlx" => {
            let mut backend =
                mayhem_engine::MlxBackend::new().context("initializing MLX backend")?;
            backend
                .load(config)
                .context("loading MLX canary calibration artifact")?;
            Ok(Box::new(backend))
        }
        "trt-llm" => {
            config.trt_engine_dir = Some(
                args.trt_engine_dir
                    .as_ref()
                    .map(|path| absolutize(path.clone()))
                    .transpose()?
                    .unwrap_or_else(|| trt_engine_cache_dir(artifact_path, "calibration")),
            );
            config.trt_tensor_parallel = Some(args.trt_tensor_parallel.unwrap_or(1));
            config.trt_kv_cache_dtype = args
                .trt_kv_cache_dtype
                .clone()
                .or_else(|| trt_kv_cache_dtype_for_artifact("calibration", artifact));
            config.trt_require_engine_dir =
                args.trt_require_engine_dir || args.trt_engine_dir.is_some();
            let mut backend =
                mayhem_engine::TrtLlmBackend::new().context("initializing TensorRT-LLM backend")?;
            backend
                .load(config)
                .context("loading TensorRT-LLM canary calibration artifact")?;
            Ok(Box::new(backend))
        }
        "whisper.cpp" | "piper" => {
            bail!(
                "audio engines are not token canary calibration backends; use I3-D4 audio-specific probes"
            )
        }
        _ => unreachable!("unsupported engines returned above"),
    }
}

fn calibrate_canary_prompt(
    backend: &mut dyn EngineBackend,
    model: &catalog::CatalogModel,
    prompt: &CanaryPrompt,
    seed: u32,
    include_output: bool,
) -> Result<CanaryCalibrationPromptReport> {
    let body = canary_probe_request(&model.model_id, prompt);
    let mut request = provider_engine_request_from_body(&body, &model.adapter)?;
    request.temperature = Some(prompt.temperature.unwrap_or(0.0) as f32);
    request.seed = Some(seed);
    let max_tokens = request.max_new_tokens;
    let mut token_ids = Vec::new();
    let output = backend
        .generate(request, &mut |chunk: mayhem_engine::TokenChunk| {
            token_ids.push(chunk.token_id);
            Ok(())
        })
        .with_context(|| format!("generating canary prompt {}", prompt.id))?;
    if token_ids.is_empty() {
        bail!("canary prompt {} produced no tokens", prompt.id);
    }
    let fingerprint = canary_token_fingerprint(token_ids.iter().copied());
    Ok(CanaryCalibrationPromptReport {
        prompt_id: prompt.id.clone(),
        max_tokens,
        prompt_tokens: output.usage.prompt_tokens,
        completion_tokens: output.usage.completion_tokens,
        token_count: token_ids.len(),
        token_ids,
        fingerprint,
        output_text: include_output.then_some(output.text),
    })
}

fn canary_token_fingerprint(tokens: impl IntoIterator<Item = i32>) -> String {
    let mut hasher = blake3::Hasher::new();
    for token in tokens {
        hasher.update(&token.to_be_bytes());
    }
    hasher.finalize().to_hex().to_string()
}

fn aggregate_canary_fingerprint(prompts: &[CanaryCalibrationPromptReport]) -> String {
    let mut hasher = blake3::Hasher::new();
    for prompt in prompts {
        let prompt_id = prompt.prompt_id.as_bytes();
        hasher.update(&(prompt_id.len() as u32).to_be_bytes());
        hasher.update(prompt_id);
        hasher.update(prompt.fingerprint.as_bytes());
    }
    hasher.finalize().to_hex().to_string()
}

async fn admin(command: AdminCommands) -> Result<()> {
    match &command {
        AdminCommands::EpochApply(args) => return run_admin_epoch_apply_feature(args).await,
        AdminCommands::TnkDeposit(args) => {
            return run_admin_deposit_feature(
                &args.tx,
                "tnkDeposit",
                admin_tnk_deposit_payload(args),
            )
            .await;
        }
        AdminCommands::TapDeposit(args) => {
            return run_admin_deposit_feature(
                &args.tx,
                "tapDeposit",
                admin_tap_deposit_payload(args),
            )
            .await;
        }
        AdminCommands::FiatDeposit(args) => {
            return run_admin_deposit_feature(
                &args.tx,
                "fiatDeposit",
                admin_fiat_deposit_payload(args)?,
            )
            .await;
        }
        AdminCommands::RateOracle(args) => {
            return run_admin_rate_feature(&args.tx, "rateOracle", admin_rate_oracle_payload(args))
                .await;
        }
        AdminCommands::TapRateOracle(args) => {
            return run_admin_rate_feature(
                &args.tx,
                "tapRateOracle",
                admin_tap_rate_oracle_payload(args),
            )
            .await;
        }
        AdminCommands::TnkSettlement(args) => {
            return run_admin_tnk_settlement_feature(args).await;
        }
        AdminCommands::PayoutConfirm(_) => {
            bail!(
                "payout-confirm is retired; use TNK tnk-settlement batch evidence, TAP claim-proof tools, or fiat paygate settlement"
            );
        }
        _ => {}
    }
    let tx_args = admin_tx_args(&command);
    let (tx_type, mut value) = admin_command_payload(&command)?;
    ensure_admin_command_signatures(tx_args, &mut value).await?;
    run_admin_command(tx_args, tx_type, value).await
}

async fn run_admin_epoch_apply_feature(args: &AdminEpochApplyArgs) -> Result<()> {
    let value = admin_epoch_apply_payload(args)?;
    let key = epoch_apply_feature_key(&value)?;
    run_admin_feature_command(&args.tx, "epochApply", key, value).await
}

async fn run_admin_deposit_feature(
    args: &AdminTxArgs,
    feature_type: &'static str,
    value: Value,
) -> Result<()> {
    let key = deposit_feature_key(&value)?;
    run_admin_feature_command(args, feature_type, key, value).await
}

async fn run_admin_rate_feature(
    args: &AdminTxArgs,
    feature_type: &'static str,
    value: Value,
) -> Result<()> {
    let key = rate_feature_key(&value)?;
    run_admin_feature_command(args, feature_type, key, value).await
}

async fn run_admin_tnk_settlement_feature(args: &AdminTnkSettlementArgs) -> Result<()> {
    if args.settlement_json.is_some() || args.settlement_file.is_some() {
        let value = admin_tnk_settlement_payload(args)?;
        let key = tnk_settlement_feature_key(&value)?;
        return run_admin_feature_command(&args.tx, "tnkSettlement", key, value).await;
    }
    run_admin_tnk_settlement_runner(args).await
}

fn admin_tx_args(command: &AdminCommands) -> &AdminTxArgs {
    match command {
        AdminCommands::SetRules(args) => &args.tx,
        AdminCommands::SetParams(args) => &args.tx,
        AdminCommands::SetModelRef(args) => &args.tx,
        AdminCommands::PublishCatalog(args) => &args.tx,
        AdminCommands::RegisterEnclave(args) => &args.tx,
        AdminCommands::RetireEnclave(args) => &args.tx,
        AdminCommands::OpenRoom(args) => &args.tx,
        AdminCommands::CloseRoom(args) => &args.tx,
        AdminCommands::SetPrice(args) => &args.tx,
        AdminCommands::SetProviderPayout(args) => &args.tx,
        AdminCommands::SetProviderKyb(args) => &args.tx,
        AdminCommands::RevokeProviderKyb(args) => &args.tx,
        AdminCommands::BanProvider(args) => &args.tx,
        AdminCommands::AuditorRegister(args) => &args.tx,
        AdminCommands::RateOracle(args) => &args.tx,
        AdminCommands::TapRateOracle(args) => &args.tx,
        AdminCommands::TnkSettlement(args) => &args.tx,
        AdminCommands::TnkDeposit(args) => &args.tx,
        AdminCommands::TapDeposit(args) => &args.tx,
        AdminCommands::FiatDeposit(args) => &args.tx,
        AdminCommands::FiatChargeback(args) => &args.tx,
        AdminCommands::PayoutConfirm(args) => &args.tx,
        AdminCommands::EpochCommit(args) => &args.tx,
        AdminCommands::EpochApply(args) => &args.tx,
    }
}

fn admin_command_payload(command: &AdminCommands) -> Result<(&'static str, Value)> {
    match command {
        AdminCommands::SetRules(args) => Ok(("setRules", admin_set_rules_payload(args))),
        AdminCommands::SetParams(args) => Ok(("setParams", admin_set_params_payload(args)?)),
        AdminCommands::SetModelRef(args) => Ok(("setModelRef", admin_set_model_ref_payload(args)?)),
        AdminCommands::PublishCatalog(args) => {
            Ok(("publishCatalog", admin_publish_catalog_payload(args)?))
        }
        AdminCommands::RegisterEnclave(args) => {
            Ok(("registerEnclave", admin_register_enclave_payload(args)?))
        }
        AdminCommands::RetireEnclave(args) => Ok((
            "retireEnclave",
            json!({
                "op": "retire_enclave",
                "enclave_id": &args.enclave_id,
            }),
        )),
        AdminCommands::OpenRoom(args) => Ok(("openRoom", admin_open_room_payload(args)?)),
        AdminCommands::CloseRoom(args) => Ok((
            "closeRoom",
            json!({
                "op": "close_room",
                "room_id": &args.room_id,
            }),
        )),
        AdminCommands::SetPrice(args) => Ok(("setPrice", admin_set_price_payload(args)?)),
        AdminCommands::SetProviderPayout(args) => Ok((
            "setProviderPayout",
            admin_set_provider_payout_payload(args)?,
        )),
        AdminCommands::SetProviderKyb(args) => {
            Ok(("setProviderKyb", admin_set_provider_kyb_payload(args)?))
        }
        AdminCommands::RevokeProviderKyb(args) => Ok((
            "revokeProviderKyb",
            admin_revoke_provider_kyb_payload(args)?,
        )),
        AdminCommands::BanProvider(args) => Ok(("banProvider", admin_ban_provider_payload(args)?)),
        AdminCommands::AuditorRegister(args) => {
            Ok(("auditorRegister", admin_auditor_register_payload(args)))
        }
        AdminCommands::RateOracle(_) | AdminCommands::TapRateOracle(_) => {
            bail!("rate oracle updates are free features, not paid admin txs")
        }
        AdminCommands::TnkSettlement(_) => {
            bail!("TNK settlement updates are free features, not paid admin txs")
        }
        AdminCommands::TnkDeposit(args) => Ok(("tnkDeposit", admin_tnk_deposit_payload(args))),
        AdminCommands::TapDeposit(args) => Ok(("tapDeposit", admin_tap_deposit_payload(args))),
        AdminCommands::FiatDeposit(args) => Ok(("fiatDeposit", admin_fiat_deposit_payload(args)?)),
        AdminCommands::FiatChargeback(args) => {
            Ok(("fiatChargeback", admin_fiat_chargeback_payload(args)?))
        }
        AdminCommands::PayoutConfirm(args) => {
            admin_payout_confirm_payload(args).map(|value| ("payoutConfirm", value))
        }
        AdminCommands::EpochCommit(args) => Ok(("epochCommit", admin_epoch_commit_payload(args)?)),
        AdminCommands::EpochApply(args) => Ok(("epochApply", admin_epoch_apply_payload(args)?)),
    }
}

async fn ensure_admin_command_signatures(args: &AdminTxArgs, value: &mut Value) -> Result<()> {
    if value.get("op").and_then(Value::as_str) != Some("set_provider_kyb")
        || value.get("admin_sig").is_some()
    {
        return Ok(());
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let wallet_password = args.wallet_password.as_deref().unwrap_or("");
    let wallet = resolve_cli_wallet(
        &home,
        config.as_ref(),
        &args.peer_store_name,
        wallet_password,
    )
    .await?;
    let keypair_path = PathBuf::from(&wallet.keypair_path);
    let signature = sign_message(&keypair_path, wallet_password, &provider_kyb_message(value))
        .await
        .context("signing provider KYB record with admin wallet")?;
    value["admin_sig"] = json!(signature);
    Ok(())
}

