fn admin_publish_catalog_payload(args: &AdminPublishCatalogArgs) -> Result<Value> {
    validate_catalog_source_url(&args.source_kind, &args.catalog_url, "--catalog-url")?;
    validate_catalog_source_url(&args.source_kind, &args.signature_url, "--signature-url")?;
    validate_catalog_source_url(
        &args.source_kind,
        &args.canaries_base_url,
        "--canaries-base-url",
    )?;

    let catalog_path = args
        .catalog_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    let signature_path = args
        .signature_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
    let signature_path = absolutize(signature_path)?;
    let keys_dir = args
        .keys_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let keys_dir = absolutize(keys_dir)?;
    let canaries_dir = args
        .canaries_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let canaries_dir = absolutize(canaries_dir)?;

    let report = catalog::verify(catalog::VerifyOptions {
        catalog_path: catalog_path.clone(),
        signature_path: signature_path.clone(),
        keys_dir,
        canaries_dir: canaries_dir.clone(),
        check_dev_downloads: false,
        check_launch_sources: false,
        hf_token_file: None,
    })?;
    if !report.ok {
        bail!("catalog verification failed; refusing to publish catalog anchor");
    }

    let catalog_doc = catalog::load_document(&catalog_path)?;
    let signature = read_json_file(&signature_path)
        .with_context(|| format!("reading {}", signature_path.display()))?;
    let key_id = required_json_string_for(&signature, "key_id", "catalog signature")?;
    let public_key = required_json_string_for(&signature, "public_key", "catalog signature")?;
    let signature_hash = blake3_file_hex(&signature_path)?;
    let canaries = report
        .canary_sets
        .iter()
        .map(|set_id| {
            let path = canaries_dir.join(format!("{set_id}.json"));
            Ok(json!({
                "set_id": set_id,
                "url": catalog_release_url_join(&args.canaries_base_url, &format!("{set_id}.json"))?,
                "hash": blake3_file_hex(&path)?,
            }))
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(json!({
        "op": "publish_catalog",
        "catalog_id": catalog_doc.catalog_id,
        "source_kind": args.source_kind,
        "catalog_url": args.catalog_url,
        "signature_url": args.signature_url,
        "catalog_hash": report.catalog_hash,
        "signature_hash": signature_hash,
        "key_id": key_id,
        "public_key": public_key,
        "model_count": report.model_count,
        "artifact_count": report.artifact_count,
        "canaries": canaries,
    }))
}

fn admin_register_enclave_payload(args: &AdminRegisterEnclaveArgs) -> Result<Value> {
    let binding = validate_admin_enclave_catalog_binding(args)?;
    let mut caps = json_arg_or_file_object(
        args.caps_json.as_deref(),
        args.caps_file.as_ref(),
        None,
        "enclave caps",
    )?;
    enforce_backend_caps(&args.backend, &mut caps)?;
    let mut payload = json!({
        "op": "register_enclave",
        "enclave_id": &args.enclave_id,
        "model_id": &args.model,
        "model_class": binding.model_class,
        "backend": &args.backend,
        "artifact_root": &args.artifact_root,
        "artifact_root_kind": &args.artifact_root_kind,
        "artifact_source": {
            "kind": "huggingface",
            "repo": &args.artifact_repo,
            "revision": args.artifact_revision.to_ascii_lowercase(),
            "path": &args.artifact_path,
        },
        "manifest_hash": &args.manifest_hash,
        "att_tier": args.att_tier,
        "binary_hash": &args.binary_hash,
        "caps": caps,
    });
    if let Some(source_sha256) = &args.source_sha256 {
        payload["source_sha256"] = json!(source_sha256.to_ascii_lowercase());
    }
    if !binding.artifact_sidecars.is_empty() {
        payload["artifact_sidecars"] = json!(binding.artifact_sidecars);
    }
    Ok(payload)
}

fn enforce_backend_caps(backend: &str, caps: &mut Value) -> Result<()> {
    if !backend_supports_tool_calls(backend) {
        if caps.get("tools").and_then(Value::as_bool) == Some(true) {
            bail!(
                "backend {backend} cannot advertise caps.tools=true; register this enclave with caps.tools=false until real constrained decoding is wired"
            );
        }
        caps.as_object_mut()
            .context("enclave caps must be a JSON object")?
            .insert("tools".to_owned(), json!(false));
    }
    Ok(())
}

fn backend_supports_tool_calls(backend: &str) -> bool {
    !matches!(backend, "mlx" | "trt-llm")
}

#[derive(Debug)]
struct AdminEnclaveCatalogBinding {
    model_class: String,
    artifact_sidecars: BTreeMap<String, CatalogSidecarPayload>,
}

#[derive(Debug, Serialize)]
struct CatalogSidecarPayload {
    source: LedgerArtifactSource,
    path: String,
    artifact_root: String,
    artifact_root_kind: String,
    weights_bytes: u64,
    source_sha256: String,
}

fn validate_admin_enclave_catalog_binding(
    args: &AdminRegisterEnclaveArgs,
) -> Result<AdminEnclaveCatalogBinding> {
    let catalog_path = args
        .catalog_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/models.json"))?;
    let catalog_path = absolutize(catalog_path)?;
    if args.dev_skip_catalog_verify {
        if !cfg!(debug_assertions) {
            bail!(
                "--dev-skip-catalog-verify is only available in debug builds for local smoke fixtures"
            );
        }
    } else {
        let signature_path = args
            .signature_path
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
        let keys_dir = args
            .keys_dir
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("catalog/keys"))?;
        let canaries_dir = args
            .canaries_dir
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("catalog/canaries"))?;
        let report = catalog::verify(catalog::VerifyOptions {
            catalog_path: catalog_path.clone(),
            signature_path: absolutize(signature_path)?,
            keys_dir: absolutize(keys_dir)?,
            canaries_dir: absolutize(canaries_dir)?,
            check_dev_downloads: false,
            check_launch_sources: false,
            hf_token_file: None,
        })?;
        if !report.ok {
            bail!(
                "signed admin catalog verification failed for register-enclave: {}",
                report.errors.join("; ")
            );
        }
    }

    let catalog_doc = catalog::load_document(&catalog_path)?;
    let model = catalog_doc
        .models
        .iter()
        .find(|model| model.model_id == args.model)
        .with_context(|| {
            format!(
                "--model {} is not present in admin catalog {}",
                args.model,
                catalog_path.display()
            )
        })?;
    let Some((_, artifact)) = model.artifacts.iter().find(|(_, artifact)| {
        artifact.engine == args.backend
            && artifact.source.kind == "huggingface"
            && artifact.source.repo == args.artifact_repo
            && artifact
                .source
                .revision
                .eq_ignore_ascii_case(&args.artifact_revision)
            && artifact.path == args.artifact_path
    }) else {
        bail!(
            "register-enclave source is not greenlit: no admin catalog artifact for model {}, backend {}, Hugging Face {}/resolve/{}/{}",
            args.model,
            args.backend,
            args.artifact_repo,
            args.artifact_revision,
            args.artifact_path
        );
    };
    ensure_catalog_text_match(
        "artifact_root_kind",
        &args.artifact_root_kind,
        &artifact.artifact_root_kind,
    )?;
    ensure_catalog_hex_match(
        "artifact_root",
        &args.artifact_root,
        &artifact.artifact_root,
    )?;
    ensure_catalog_optional_hex_match(
        "source_sha256",
        args.source_sha256.as_deref(),
        artifact.source_sha256.as_deref(),
    )?;
    Ok(AdminEnclaveCatalogBinding {
        model_class: model.model_class.clone(),
        artifact_sidecars: artifact
            .sidecars
            .iter()
            .map(|(name, sidecar)| {
                (
                    name.clone(),
                    CatalogSidecarPayload {
                        source: LedgerArtifactSource {
                            kind: sidecar.source.kind.clone(),
                            repo: sidecar.source.repo.clone(),
                            revision: sidecar.source.revision.to_ascii_lowercase(),
                            path: sidecar.path.clone(),
                        },
                        path: sidecar.path.clone(),
                        artifact_root: sidecar.artifact_root.clone(),
                        artifact_root_kind: sidecar.artifact_root_kind.clone(),
                        weights_bytes: sidecar.weights_bytes,
                        source_sha256: sidecar.source_sha256.to_ascii_lowercase(),
                    },
                )
            })
            .collect(),
    })
}

fn ensure_catalog_text_match(label: &str, requested: &str, catalog: &str) -> Result<()> {
    if requested == catalog {
        return Ok(());
    }
    bail!("register-enclave {label} mismatch: requested {requested}, signed catalog has {catalog}")
}

fn ensure_catalog_hex_match(label: &str, requested: &str, catalog: &str) -> Result<()> {
    if requested.eq_ignore_ascii_case(catalog) {
        return Ok(());
    }
    bail!("register-enclave {label} mismatch: requested {requested}, signed catalog has {catalog}")
}

fn ensure_catalog_optional_hex_match(
    label: &str,
    requested: Option<&str>,
    catalog: Option<&str>,
) -> Result<()> {
    match (requested, catalog) {
        (Some(left), Some(right)) if left.eq_ignore_ascii_case(right) => Ok(()),
        (None, None) => Ok(()),
        (Some(left), Some(right)) => {
            bail!("register-enclave {label} mismatch: requested {left}, signed catalog has {right}")
        }
        (None, Some(right)) => bail!(
            "register-enclave {label} mismatch: requested <missing>, signed catalog has {right}"
        ),
        (Some(left), None) => bail!(
            "register-enclave {label} mismatch: requested {left}, signed catalog has <missing>"
        ),
    }
}

fn admin_open_room_payload(args: &AdminOpenRoomArgs) -> Result<Value> {
    let policy = json_arg_or_file_object(
        args.policy_json.as_deref(),
        args.policy_file.as_ref(),
        Some(json!({})),
        "room policy",
    )?;
    let mut payload = json!({
        "op": "open_room",
        "enclave_id": &args.enclave_id,
        "nonce": &args.nonce,
        "label": &args.label,
        "policy": policy,
    });
    if let Some(model) = &args.model {
        payload["model_id"] = json!(model);
    }
    Ok(payload)
}

