fn rate_map_arg_or_file(
    inline: Option<&str>,
    file: Option<&PathBuf>,
    allow_zero_per_unit: bool,
    label: &str,
) -> Result<Vec<RateMapEntry>> {
    let value = json_arg_or_file_array(inline, file, None, label)?;
    let entries = serde_json::from_value::<Vec<RateMapEntry>>(value)
        .with_context(|| format!("parsing {label} entries"))?;
    validate_rate_map_entries(&entries, allow_zero_per_unit, label)?;
    Ok(normalize_rate_map(entries))
}

fn validate_rate_map_entries(
    entries: &[RateMapEntry],
    allow_zero_per_unit: bool,
    label: &str,
) -> Result<()> {
    if entries.is_empty() {
        bail!("{label} must contain at least one entry");
    }
    let mut units = BTreeSet::new();
    for entry in entries {
        if entry.unit.trim().is_empty() {
            bail!("{label} unit must not be empty");
        }
        if !units.insert(entry.unit.as_str()) {
            bail!("{label} contains duplicate unit {}", entry.unit);
        }
        if entry.granularity == 0 {
            bail!("{label} granularity must be positive");
        }
        if !allow_zero_per_unit && entry.per_unit_mu == 0 {
            bail!("{label} per_unit_mu must be positive");
        }
    }
    Ok(())
}

fn normalize_admin_fiat_currency(value: &str) -> Result<String> {
    let currency = value.trim().to_ascii_lowercase();
    match currency.as_str() {
        "usd" | "eur" => Ok(currency),
        _ => bail!("fiat currency must be usd or eur"),
    }
}

fn admin_set_provider_payout_payload(args: &AdminSetProviderPayoutArgs) -> Result<Value> {
    let mut payload = json!({
        "op": "set_provider_payout",
        "provider": &args.provider,
        "payout_method": args.payout_method.as_str(),
        "payout_addr": &args.payout_addr,
    });
    match args.payout_method {
        AdminPayoutMethod::Tnk => {
            if args.payout_currency.is_some() {
                bail!("TNK payout targets must not include --payout-currency");
            }
        }
        AdminPayoutMethod::Stripe => {
            let payout_currency = args
                .payout_currency
                .as_deref()
                .context("fiat payout targets require --payout-currency")?;
            payload["payout_currency"] = json!(normalize_admin_fiat_currency(payout_currency)?);
        }
    }
    Ok(payload)
}

fn admin_set_provider_kyb_payload(args: &AdminSetProviderKybArgs) -> Result<Value> {
    if !is_hex_len(&args.provider, 64) {
        bail!("--provider must be a 32-byte hex public key");
    }
    if !is_hex_len(&args.proof_hash, 64) {
        bail!("--proof-hash must be a 32-byte BLAKE3 hex digest");
    }
    if args.schema_version == 0 {
        bail!("--schema-version must be positive");
    }
    let legal_name = args.legal_name.trim();
    if legal_name.is_empty() || legal_name.chars().any(char::is_control) {
        bail!("--legal-name must be non-empty display text without control characters");
    }
    let jurisdiction = args.jurisdiction.trim().to_ascii_uppercase();
    if jurisdiction.is_empty()
        || jurisdiction.len() > 64
        || !jurisdiction
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | ':' | '-'))
    {
        bail!("--jurisdiction must be a compact jurisdiction code such as DE or US-CA");
    }
    let kyb_ref = args.kyb_ref.trim();
    if kyb_ref.is_empty()
        || kyb_ref.len() > 128
        || !kyb_ref
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | ':' | '-'))
    {
        bail!("--kyb-ref must be a compact off-ledger dossier reference");
    }

    let mut payload = json!({
        "op": "set_provider_kyb",
        "provider": args.provider.to_ascii_lowercase(),
        "legal_name": legal_name,
        "jurisdiction": jurisdiction,
        "proof_hash": args.proof_hash.to_ascii_lowercase(),
        "kyb_ref": kyb_ref,
        "verified_at": args.verified_at.unwrap_or(unix_epoch_seconds()?),
        "schema_version": args.schema_version,
    });
    if let Some(admin_sig) = &args.admin_sig {
        if !is_hex_len(admin_sig, 128) {
            bail!("--admin-sig must be a 64-byte Ed25519 signature hex string");
        }
        payload["admin_sig"] = json!(admin_sig.to_ascii_lowercase());
    }
    Ok(payload)
}

fn admin_revoke_provider_kyb_payload(args: &AdminRevokeProviderKybArgs) -> Result<Value> {
    if args.reason_hash.is_some() && args.reason.is_some() {
        bail!("pass only one of --reason-hash or --reason");
    }
    let reason_hash = args.reason_hash.clone().or_else(|| {
        args.reason
            .as_ref()
            .map(|reason| blake3::hash(reason.as_bytes()).to_hex().to_string())
    });
    let mut payload = json!({
        "op": "revoke_provider_kyb",
        "provider": &args.provider,
    });
    if let Some(reason_hash) = reason_hash {
        payload["reason_hash"] = json!(reason_hash);
    }
    Ok(payload)
}

