async fn pay_tnk(args: PayTnkArgs) -> Result<()> {
    if args.poll_interval_ms == 0 {
        bail!("--poll-interval-ms must be positive");
    }
    if args.submit_transfer && !args.submit_intent {
        bail!("--submit-transfer requires --submit-intent so the memo-bound contract intent exists before TNK moves");
    }
    if args.submit_transfer && args.sim {
        bail!("--submit-transfer cannot be combined with --sim");
    }
    if args.submit_transfer && args.msb_transfer_timeout_seconds == 0 {
        bail!("--msb-transfer-timeout-seconds must be positive");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let wallet = resolve_cli_wallet(
        &home,
        config.as_ref(),
        &args.peer_store_name,
        args.wallet_password.as_deref().unwrap_or(""),
    )
    .await?;
    let amount_mu = parse_usd_amount_to_mu(&args.amount)?;
    let treasury_address =
        resolve_cli_tnk_treasury_address(config.as_ref(), args.treasury_address.as_deref())?;
    let needs_rpc = args.tnk_usd_e6.is_none() || args.submit_intent || args.wait;
    let rpc_url = if needs_rpc {
        Some(resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?)
    } else {
        args.rpc_url.clone()
    };
    let rpc = match rpc_url.as_deref() {
        Some(url) if needs_rpc => Some(PeerRpcClient::new(url)?),
        _ => None,
    };
    let rate = resolve_tnk_rate(rpc.as_ref(), args.tnk_usd_e6).await?;
    let nonce = resolve_tnk_nonce(
        &wallet.public_key,
        amount_mu,
        &treasury_address,
        &rate,
        &args,
    )?;
    let memo_hash = derive_tnk_memo_hash(&wallet.public_key, &nonce)?;
    let tnk_e18 = mu_to_tnk_e18_ceil_u128(amount_mu, rate.tnk_usd_e6)?;
    let tnk_decimal = tnk_e18_to_decimal(tnk_e18);
    let quoted_credit_mu = tnk_e18_to_mu_floor(tnk_e18, rate.tnk_usd_e6)?;
    let intent_payload = pay_tnk_deposit_intent_payload(
        &memo_hash,
        &treasury_address,
        tnk_e18,
        quoted_credit_mu,
        &rate,
    );
    let msb_transfer_command = format!("/transfer {} {}", treasury_address, tnk_decimal);
    let deposit_intent_command = pay_tnk_deposit_intent_command(
        &args.amount,
        &treasury_address,
        &nonce,
        rate.tnk_usd_e6,
        rpc_url.as_deref(),
    );
    let keypair_path = PathBuf::from(wallet.keypair_path.clone());
    let intent_sig = sign_message(
        &keypair_path,
        args.wallet_password.as_deref().unwrap_or(""),
        &deposit_tnk_intent_message(&intent_payload),
    )
    .await?;
    let intent_feature_value = json!({
        "op": "deposit_tnk",
        "sender": wallet.public_key,
        "intent": intent_payload,
        "sig": intent_sig,
    });
    let intent_feature = json!({
        "feature": "mayhem",
        "key": deposit_feature_key(&intent_feature_value)?,
        "value": intent_feature_value,
    });
    let intent_feature_json = serde_json::to_string(&intent_feature)?;
    let intent_feature_rpc_command = rpc_url.as_deref().map(|url| {
        format!(
            "curl -sS -X POST {} -H 'content-type: application/json' --data {}",
            shell_single_quote(&format!("{}/contract/feature", url.trim_end_matches('/'))),
            shell_single_quote(&intent_feature_json)
        )
    });
    let admin_confirm_command = format!(
        "mayhem admin tnk-deposit --memo-hash {} --tnk-e18 {} --msb-tx-hash <msb-tx-hash> --epoch <epoch> --at <unix-seconds>",
        shell_single_quote(&memo_hash),
        tnk_e18
    );

    emit_tnk_handoff(
        args.json,
        amount_mu,
        &msb_transfer_command,
        &memo_hash,
        &deposit_intent_command,
    )?;

    let before_mu = if args.wait {
        let rpc = rpc.as_ref().context("--wait requires peer RPC")?;
        Some(read_user_balance_mu(rpc, &wallet.public_key, "tnk").await?)
    } else {
        None
    };

    let submitted = if args.submit_intent {
        let rpc = rpc.as_ref().context("--submit-intent requires peer RPC")?;
        if args.sim {
            Some(json!({ "sim": true, "submitted": false }))
        } else {
            let response = rpc
                .submit_feature(&intent_feature)
                .await
                .context("submitting free TNK deposit intent feature")?;
            if response.get("ok").and_then(Value::as_bool) != Some(true) {
                bail!("TNK deposit intent feature was not accepted: {response}");
            }
            Some(response)
        }
    } else {
        None
    };

    let msb_transfer = if args.submit_transfer {
        let keypair_path = PathBuf::from(wallet.keypair_path.clone());
        let (stores_directory, store_name) = msb_store_from_keypair_path(&keypair_path)?;
        let network = resolve_tnk_msb_network(args.msb_network.as_deref(), &treasury_address)?;
        Some(
            submit_msb_transfer(
                &network,
                &stores_directory,
                &store_name,
                &treasury_address,
                &tnk_decimal,
                args.msb_transfer_timeout_seconds,
            )
            .await?,
        )
    } else {
        None
    };

    let credit = if args.wait {
        let rpc = rpc.as_ref().context("--wait requires peer RPC")?;
        let before_mu = before_mu.context("--wait balance snapshot missing")?;
        let target_mu = before_mu
            .checked_add(amount_mu)
            .context("target balance overflowed")?;
        let status = wait_for_credit(
            rpc,
            &wallet.public_key,
            "tnk",
            before_mu,
            target_mu,
            Duration::from_secs(args.timeout_seconds),
            Duration::from_millis(args.poll_interval_ms),
        )
        .await?;
        Some(status)
    } else {
        None
    };

    let report = json!({
        "ok": (submitted.is_some() || !args.submit_intent) && (msb_transfer.is_some() || !args.submit_transfer),
        "rail": "tnk",
        "denom": "mu_usd",
        "amount_mu": amount_mu,
        "amount_usd": mu_to_usd_amount(amount_mu),
        "quoted_credit_mu": quoted_credit_mu,
        "who": wallet.public_key,
        "rpc_url": rpc_url,
        "treasury_address": treasury_address,
        "rate": {
            "denom": "tnk_usd_e6",
            "tnk_usd_e6": rate.tnk_usd_e6,
            "source": rate.source,
            "ts": rate.ts,
        },
        "deposit_intent": {
            "feature": intent_feature,
            "submitted": args.submit_intent && !args.sim,
            "sim": args.submit_intent && args.sim,
            "result": submitted,
        },
        "tnk": {
            "tnk_e18": tnk_e18.to_string(),
            "amount": tnk_decimal,
        },
        "msb_transfer": msb_transfer,
        "memo_hash": memo_hash,
        "nonce": nonce,
        "copy_paste": {
            "msb_transfer_command": msb_transfer_command,
            "transfer_memo_reference": memo_hash,
            "deposit_intent_command": deposit_intent_command,
            "deposit_intent_rpc_command": intent_feature_rpc_command,
            "admin_confirm_command": admin_confirm_command,
        },
        "credit": credit.as_ref().map(|status| json!({
            "credited": status.credited,
            "before_mu": status.before_mu,
            "current_mu": status.current_mu,
            "target_mu": status.target_mu,
            "waited_ms": status.waited_ms,
        })),
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
        if let Some(status) = credit.as_ref().filter(|status| !status.credited) {
            bail!(
                "timed out waiting for {} mu_usd credit; current balance {} mu_usd, target {} mu_usd",
                amount_mu,
                status.current_mu,
                status.target_mu
            );
        }
    } else {
        println!("TNK amount: {tnk_decimal} ({tnk_e18} e18)");
        println!("Treasury address: {treasury_address}");
        println!("Rate: {} tnk_usd_e6 ({})", rate.tnk_usd_e6, rate.source);
        if let Some(ts) = rate.ts {
            println!("Rate timestamp: {ts}");
        }
        if args.submit_intent {
            if args.sim {
                println!("Submitted deposit intent: false (--sim dry-run)");
            } else {
                println!("Submitted deposit intent: true");
            }
            if let Some(key) = report["deposit_intent"]["feature"]["key"].as_str() {
                println!("Deposit intent feature key: {key}");
            }
        } else {
            println!(
                "Submitted deposit intent: false (pass --submit-intent to sign and send through peer RPC)"
            );
        }
        if let Some(transfer) = report["msb_transfer"].as_object() {
            if let Some(tx_hash) = transfer.get("tx_hash").and_then(Value::as_str) {
                println!("Submitted MSB transfer: true");
                println!("MSB tx: {tx_hash}");
            }
        } else if args.submit_transfer {
            println!("Submitted MSB transfer: false");
        }
        if let Some(command) = report["copy_paste"]["deposit_intent_rpc_command"].as_str() {
            println!("Copy/paste deposit intent feature RPC command:");
            println!("{command}");
        }
        println!("Copy/paste admin/oracle confirmation command after MSB finality:");
        println!(
            "{}",
            report["copy_paste"]["admin_confirm_command"]
                .as_str()
                .unwrap_or("")
        );
        if let Some(status) = credit {
            if status.credited {
                println!(
                    "Credited: balance {} -> {} mu_usd.",
                    status.before_mu, status.current_mu
                );
            } else {
                bail!(
                    "timed out waiting for {} mu_usd credit; current balance {} mu_usd, target {} mu_usd",
                    amount_mu,
                    status.current_mu,
                    status.target_mu
                );
            }
        }
    }

    Ok(())
}

async fn pay(rail: PayRail, args: PayRailArgs) -> Result<()> {
    if args.poll_interval_ms == 0 {
        bail!("--poll-interval-ms must be positive");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let wallet = resolve_cli_wallet(
        &home,
        config.as_ref(),
        &args.peer_store_name,
        args.wallet_password.as_deref().unwrap_or(""),
    )
    .await?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let paygate_url = resolve_cli_paygate_url(config.as_ref(), args.paygate_url.as_deref());
    let amount_mu = parse_usd_amount_to_mu(&args.amount)?;
    let before_mu = read_user_balance_mu(&rpc, &wallet.public_key, rail.balance_rail()).await?;
    let checkout = create_pay_checkout(PayCheckoutRequest {
        rail,
        paygate_url: &paygate_url,
        who: &wallet.public_key,
        amount_mu,
        currency: &args.currency,
        locale: &args.locale,
        idempotency_key: args.idempotency_key.as_deref(),
        success_url: args.success_url.as_deref(),
        cancel_url: args.cancel_url.as_deref(),
    })
    .await?;
    emit_checkout_handoff(args.json, rail, amount_mu, &args.currency, &checkout.url)?;
    let opened = open_checkout_url(&checkout.url, args.no_open).await;
    let target_mu = before_mu
        .checked_add(amount_mu)
        .context("target balance overflowed")?;
    let status = if args.no_wait {
        PayCreditStatus {
            credited: false,
            before_mu,
            current_mu: before_mu,
            target_mu,
            waited_ms: 0,
        }
    } else {
        wait_for_credit(
            &rpc,
            &wallet.public_key,
            rail.balance_rail(),
            before_mu,
            target_mu,
            Duration::from_secs(args.timeout_seconds),
            Duration::from_millis(args.poll_interval_ms),
        )
        .await?
    };

    let report = json!({
        "ok": status.credited || args.no_wait,
        "rail": rail.as_str(),
        "denom": "mu_usd",
        "amount_mu": amount_mu,
        "amount_usd": mu_to_usd_amount(amount_mu),
        "currency": args.currency.to_ascii_lowercase(),
        "who": wallet.public_key,
        "paygate_url": paygate_url,
        "rpc_url": rpc_url,
        "checkout": {
            "id": checkout.id,
            "url": checkout.url,
            "reference": checkout.reference,
        },
        "copy_paste": checkout_copy_paste_value(&checkout.url),
        "opened": opened,
        "credit": {
            "credited": status.credited,
            "before_mu": status.before_mu,
            "current_mu": status.current_mu,
            "target_mu": status.target_mu,
            "waited_ms": status.waited_ms,
        },
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        if opened {
            println!("Opened checkout in your browser.");
        } else if !args.no_open {
            println!("Could not open a browser automatically; use the URL above.");
        }
        if args.no_wait {
            println!("Not waiting for ledger credit (--no-wait).");
        } else if status.credited {
            println!(
                "Credited: balance {} -> {} mu_usd.",
                status.before_mu, status.current_mu
            );
        }
    }

    if !args.no_wait && !status.credited {
        bail!(
            "timed out waiting for {} mu_usd credit; current balance {} mu_usd, target {} mu_usd",
            amount_mu,
            status.current_mu,
            status.target_mu
        );
    }

    Ok(())
}

async fn use_gateway(args: UseArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let bind = gateway_bind_addr(config.as_ref(), args.bind.as_deref(), args.port)?;
    let gateway_url = gateway_public_url(bind);
    let openai_base_url = gateway_v1_url(&gateway_url);
    let apple_app_attest_jwks = match &args.apple_app_attest_jwks_file {
        Some(path) => {
            let path = absolutize(path.clone())?;
            Some(read_json_file(&path).with_context(|| {
                format!("loading Apple App Attest JWKS from {}", path.display())
            })?)
        }
        None => None,
    };
    let nvidia_gb10_device_jwks = match &args.nvidia_gb10_device_jwks_file {
        Some(path) => {
            let path = absolutize(path.clone())?;
            Some(read_json_file(&path).with_context(|| {
                format!(
                    "loading NVIDIA GB10 device-attestation JWKS from {}",
                    path.display()
                )
            })?)
        }
        None => None,
    };
    let nvidia_nras_jwks = match &args.nvidia_nras_jwks_file {
        Some(path) => {
            let path = absolutize(path.clone())?;
            Some(
                read_json_file(&path)
                    .with_context(|| format!("loading NVIDIA NRAS JWKS from {}", path.display()))?,
            )
        }
        None => None,
    };
    let nvidia_offline_jwks = match &args.nvidia_offline_jwks_file {
        Some(path) => {
            let path = absolutize(path.clone())?;
            Some(read_json_file(&path).with_context(|| {
                format!(
                    "loading NVIDIA offline-verifier JWKS from {}",
                    path.display()
                )
            })?)
        }
        None => None,
    };
    let (state, source, model_count, backend, wallet_public_key, balance_mu, blocked_version_gates) =
        if args.dev_embedded_catalog {
            let state = GatewayState::from_embedded_catalog().with_dev_session_shim();
            (
                state,
                "dev-embedded-catalog".to_owned(),
                None,
                "local-openai-shape".to_owned(),
                None,
                None,
                Vec::new(),
            )
        } else {
            let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
            let rpc = PeerRpcClient::new(&rpc_url)?;
            let catalog_client = reqwest::Client::builder()
                .timeout(Duration::from_secs(30))
                .build()
                .context("building catalog release HTTP client")?;
            let release = read_catalog_release_anchor(&rpc).await?;
            let catalog_files =
                fetch_catalog_release_files(&catalog_client, &home, &release).await?;
            let catalog_doc =
                catalog::load_document(&catalog_files.catalog_path).with_context(|| {
                    format!(
                        "loading verified ledger catalog {}",
                        catalog_files.catalog_path.display()
                    )
                })?;
            let wallet_password = args.wallet_password.clone().unwrap_or_default();
            let wallet = resolve_cli_wallet_with_keypair(
                &home,
                config.as_ref(),
                args.keypair.as_deref(),
                &args.peer_store_name,
                &wallet_password,
            )
            .await?;
            let keypair_path = PathBuf::from(&wallet.keypair_path);
            let user_seed =
                wallet_signing_seed(&keypair_path, &wallet_password, &wallet.public_key)
                    .await
                    .with_context(|| {
                        format!(
                            "loading spend-voucher signing seed for wallet {}",
                            wallet.public_key
                        )
                    })?;
            let balance_mu =
                read_user_balance_mu(&rpc, &wallet.public_key, args.rail.as_str()).await?;
            let contract = read_contract_catalog(&rpc).await?;
            let models = gateway_models_from_contract(&contract)?;
            let (models, blocked_version_gates) =
                filter_gateway_models_by_app_version(models, &catalog_doc)?;
            let model_count = models.len();
            let provider_earnings = read_prefix_values::<LedgerEarningRecord>(&rpc, "earn/")
                .await?
                .into_iter()
                .map(earning_view)
                .map(|view| {
                    view.and_then(|view| {
                        serde_json::to_value(view).context("serializing provider earning view")
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            let (sc_bridge_url, sc_bridge_token) = resolve_cli_sc_bridge(
                Some(&home),
                args.sc_bridge_url.as_deref(),
                args.sc_bridge_token.as_deref(),
            )?;
            if args.session_open_timeout_seconds == Some(0) {
                bail!("--session-open-timeout-seconds must be positive");
            }
            if args.session_frame_timeout_seconds == Some(0) {
                bail!("--session-frame-timeout-seconds must be positive");
            }
            if args.session_ttft_timeout_seconds == Some(0) {
                bail!("--session-ttft-timeout-seconds must be positive");
            }
            if args
                .min_tok_s
                .is_some_and(|value| !value.is_finite() || value <= 0.0)
            {
                bail!("--min-tok-s must be a positive finite number");
            }
            let mut session_config =
                ScBridgeGatewaySessionConfig::new(sc_bridge_url.clone(), sc_bridge_token);
            if let Some(seconds) = args.session_open_timeout_seconds {
                session_config.open_timeout = Duration::from_secs(seconds);
            }
            if let Some(seconds) = args.session_ttft_timeout_seconds {
                session_config.ttft_timeout = Duration::from_secs(seconds);
            }
            if let Some(seconds) = args.session_frame_timeout_seconds {
                session_config.frame_timeout = Duration::from_secs(seconds);
            }
            session_config.min_tok_s = args.min_tok_s;
            let failover_policy = mayhem_gateway::openai::GatewayFailoverPolicyConfig {
                open_timeout_ms: Some(duration_millis_u64(session_config.open_timeout)),
                ttft_timeout_ms: Some(duration_millis_u64(session_config.ttft_timeout)),
                stall_timeout_ms: Some(duration_millis_u64(session_config.frame_timeout)),
                min_tok_s: session_config.min_tok_s,
            };
            let backend = ScBridgeGatewaySessionBackend::new(session_config);
            (
                GatewayState::from_models(models)
                    .with_provider_earnings(provider_earnings)
                    .with_failover_policy(failover_policy)
                    .with_receipt_user_seed(user_seed)
                    .with_receipt_balance_mu(balance_mu)
                    .with_session_backend(Arc::new(backend)),
                format!("contract:{rpc_url}; catalog:{}", release.catalog_hash),
                Some(model_count),
                format!("sc-bridge-direct-session:{sc_bridge_url}"),
                Some(wallet.public_key),
                Some(balance_mu),
                blocked_version_gates,
            )
        };
    let state = match apple_app_attest_jwks {
        Some(jwks) => state.with_apple_app_attest_jwks(jwks),
        None => state,
    };
    let state = match nvidia_gb10_device_jwks {
        Some(jwks) => state.with_nvidia_gb10_device_jwks(jwks),
        None => state,
    };
    let state = match nvidia_nras_jwks {
        Some(jwks) => state.with_nvidia_nras_jwks(jwks),
        None => state,
    };
    let state = match nvidia_offline_jwks {
        Some(jwks) => state.with_nvidia_offline_jwks(jwks),
        None => state,
    };
    let state = state.with_receipt_rail(args.rail.as_str());
    let dashboard_url = state.dashboard_url(&gateway_url);
    let dashboard_session_expires_in_seconds = state.dashboard_session_expires_in().as_secs();
    let report = json!({
        "ok": true,
        "home": home,
        "bind": bind.to_string(),
        "gateway_url": gateway_url,
        "openai_base_url": openai_base_url,
        "dashboard_url": dashboard_url,
        "dashboard_session_expires_in_seconds": dashboard_session_expires_in_seconds,
        "source": source,
        "backend": backend,
        "rail": args.rail.as_str(),
        "wallet": wallet_public_key.as_ref().map(|public_key| json!({
            "public_key": public_key,
            "balance_mu": balance_mu.unwrap_or(0),
            "balance_source": format!("bal/{}/{}", public_key, args.rail.as_str()),
        })),
        "models": model_count,
        "version_gates": &blocked_version_gates,
        "apple_app_attest_jwks": args.apple_app_attest_jwks_file.is_some(),
        "nvidia_gb10_device_jwks": args.nvidia_gb10_device_jwks_file.is_some(),
        "nvidia_nras_jwks": args.nvidia_nras_jwks_file.is_some(),
        "nvidia_offline_jwks": args.nvidia_offline_jwks_file.is_some(),
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!("Mayhem gateway starting.");
        println!("Bind: {bind}");
        println!("Rail: {}", args.rail.as_str());
        println!("Copy/paste OpenAI base URL: {openai_base_url}");
        println!("Copy/paste dashboard URL: {dashboard_url}");
        println!("Dashboard session expires in: {dashboard_session_expires_in_seconds}s");
        if args.dev_embedded_catalog {
            println!("Model source: development embedded catalog (non-canonical).");
            println!("Backend: local OpenAI-shape smoke backend (unbillable dev output).");
        } else {
            println!(
                "Model source: canonical contract state ({} models).",
                model_count.unwrap_or(0)
            );
            if !blocked_version_gates.is_empty() {
                println!(
                    "Hidden by app-version gate: {} model(s); run `mayhem update` for newer catalog entries.",
                    blocked_version_gates.len()
                );
                for gate in &blocked_version_gates {
                    println!("  {}", gate.message);
                }
            }
            println!("Backend: {backend}");
            if let Some(public_key) = wallet_public_key.as_deref() {
                println!("Wallet: {public_key}");
                println!(
                    "Balance snapshot: {} mu_usd from bal/{}/{}",
                    balance_mu.unwrap_or(0),
                    public_key,
                    args.rail.as_str()
                );
            }
            if args.apple_app_attest_jwks_file.is_some() {
                println!("Tier 2 Apple App Attest verification: trusted JWKS loaded.");
            }
            if args.nvidia_gb10_device_jwks_file.is_some() {
                println!("Tier 2 NVIDIA GB10 device verification: trusted JWKS loaded.");
            }
            if args.nvidia_nras_jwks_file.is_some() {
                println!("NVIDIA NRAS verification: trusted JWKS loaded.");
            }
            if args.nvidia_offline_jwks_file.is_some() {
                println!("NVIDIA offline verifier fallback: trusted JWKS loaded.");
            }
        }
        println!("Use Ctrl-C to stop.");
    }
    io::stdout().flush()?;

    serve_gateway(bind, state)
        .await
        .with_context(|| format!("serving Mayhem gateway on {bind}"))?;
    Ok(())
}

async fn models(args: ModelsArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }
    if let Some(min_att_tier) = args.min_att_tier {
        if !(1..=4).contains(&min_att_tier) {
            bail!("--min-att-tier must be between 1 and 4");
        }
        if !args.gateway {
            bail!("--min-att-tier requires --gateway because attestation tier is live provider capacity");
        }
    }
    if args.require_kyb && !args.gateway {
        bail!("--require-kyb requires --gateway because KYB is live provider capacity");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let timeout = Duration::from_secs(args.timeout_seconds);
    let client = reqwest::Client::builder().timeout(timeout).build()?;

    if args.gateway {
        let gateway_root = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
        let models = fetch_gateway_models(&client, &gateway_root).await?;
        let summaries = filter_model_summaries_by_require_kyb(
            filter_model_summaries_by_min_att_tier(
                gateway_model_summaries(&models)?,
                args.min_att_tier,
            ),
            args.require_kyb,
        );
        let report = json!({
            "ok": true,
            "source": "gateway_live",
            "gateway_url": gateway_root,
            "min_att_tier": args.min_att_tier,
            "require_kyb": args.require_kyb,
            "models": summaries,
        });

        if args.json {
            println!("{}", serde_json::to_string_pretty(&report)?);
        } else {
            print_models_report(&report)?;
        }
    } else {
        let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
        let rpc = PeerRpcClient::new(&rpc_url)?;
        let release = read_catalog_release_anchor(&rpc).await?;
        let files = fetch_catalog_release_files(&client, &home, &release).await?;
        let catalog_doc = catalog::load_document(&files.catalog_path)?;
        let hardware = probe(ProbeOptions {
            disk_path: home.clone(),
            run_disk_bench: false,
            disk_bench_mib: 1,
            fixture: None,
        });
        let catalog_report = catalog_list_report(
            &catalog_doc,
            files.catalog_path,
            files.signature_path,
            release.catalog_hash.clone(),
            release.key_id.clone(),
            CatalogListTier::Launch,
            Some(&hardware),
        );

        if args.json {
            let report = json!({
                "ok": true,
                "source": "ledger_catalog",
                "rpc_url": rpc_url,
                "release": release,
                "catalog": catalog_report,
            });
            println!("{}", serde_json::to_string_pretty(&report)?);
        } else {
            println!("Ledger catalog release: catalog/current via {rpc_url}");
            println!("Published catalog URL: {}", release.catalog_url);
            print_catalog_list_report(&catalog_report);
            println!();
            println!("Live routable provider capacity: run `mayhem models --gateway`.");
        }
    }
    Ok(())
}

async fn balance(args: BalanceArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    let who = if let Some(who) = args.who.clone() {
        who
    } else {
        resolve_cli_wallet(
            &home,
            config.as_ref(),
            &args.peer_store_name,
            args.wallet_password.as_deref().unwrap_or(""),
        )
        .await?
        .public_key
    };
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let rail = args.rail.as_str();
    let balance_record = read_balance_record(&rpc, &who, rail).await?;
    let mu = balance_record
        .get("mu")
        .and_then(Value::as_u64)
        .context("normalized balance record missing mu")?;
    let frozen = read_state_value(&rpc, &format!("frozen/{who}")).await?;
    let report = json!({
        "ok": true,
        "rpc_url": rpc_url,
        "who": who,
        "rail": rail,
        "balance": balance_record,
        "credit": {
            "denom": "mu_usd",
            "mu": mu,
            "usd": mu_to_usd_amount(mu),
        },
        "frozen": frozen,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_balance_report(&report);
    }
    Ok(())
}

async fn status(args: StatusArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    let gateway_root = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(args.timeout_seconds))
        .build()?;

    let wallet = match resolve_cli_wallet(
        &home,
        config.as_ref(),
        &args.peer_store_name,
        args.wallet_password.as_deref().unwrap_or(""),
    )
    .await
    {
        Ok(wallet) => json!({
            "ok": true,
            "public_key": wallet.public_key,
            "address": wallet.address,
            "keypair_path": wallet.keypair_path,
        }),
        Err(err) => component_error(err),
    };

    let peer = match PeerRpcClient::new(&rpc_url) {
        Ok(rpc) => {
            let rules = read_state_value(&rpc, "rules/current").await;
            let catalog = read_state_value(&rpc, "catalog/current").await;
            let rules_ok = rules.is_ok();
            let catalog_ok = catalog.is_ok();
            let rules_current = match rules {
                Ok(Some(value)) => value,
                Ok(None) => Value::Null,
                Err(err) => component_error(err),
            };
            let catalog_current = match catalog {
                Ok(Some(value)) => value,
                Ok(None) => Value::Null,
                Err(err) => component_error(err),
            };
            let balance = if let Some(who) = wallet.get("public_key").and_then(Value::as_str) {
                match read_balance_record(&rpc, who, "fiat").await {
                    Ok(value) => value,
                    Err(err) => component_error(err),
                }
            } else {
                Value::Null
            };
            json!({
                "ok": rules_ok && catalog_ok,
                "rpc_url": rpc_url,
                "rules_current": rules_current,
                "catalog_current": catalog_current,
                "wallet_balance": balance,
            })
        }
        Err(err) => component_error(err),
    };

    let gateway_status =
        fetch_gateway_json(&client, &format!("{gateway_root}/mayhem/status")).await;
    let gateway_receipts =
        fetch_gateway_json(&client, &format!("{gateway_root}/mayhem/receipts")).await;
    let gateway = json!({
        "ok": gateway_status.is_ok() && gateway_receipts.is_ok(),
        "url": gateway_root,
        "status": gateway_status.unwrap_or_else(component_error),
        "receipts": gateway_receipts.unwrap_or_else(component_error),
    });

    let report = json!({
        "ok": wallet.get("ok").and_then(Value::as_bool) == Some(true)
            && peer.get("ok").and_then(Value::as_bool) == Some(true)
            && gateway.get("ok").and_then(Value::as_bool) == Some(true),
        "node": {
            "home": home,
            "config_present": config.is_some(),
            "role": config
                .as_ref()
                .and_then(|config| config.role.as_ref())
                .and_then(|role| role.mode.as_deref())
                .unwrap_or("unknown"),
        },
        "wallet": wallet,
        "peer": peer,
        "gateway": gateway,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_status_report(&report);
    }
    Ok(())
}

async fn session_history(args: SessionHistoryArgs, group_sessions: bool) -> Result<()> {
    if args.limit == 0 {
        bail!("--limit must be positive");
    }
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let gateway_root = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let client = reqwest::Client::new();
    let receipts_response =
        fetch_gateway_json(&client, &format!("{gateway_root}/mayhem/receipts")).await?;
    let data = receipts_response
        .get("data")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut rows = data
        .iter()
        .map(receipt_history_summary)
        .filter(|entry| receipt_history_matches(entry, &args))
        .collect::<Vec<_>>();
    rows.reverse();
    let (receipts, sessions) = if group_sessions {
        let mut sessions = group_session_summaries(&rows);
        sessions.truncate(args.limit);
        (Value::Null, Value::Array(sessions))
    } else {
        rows.truncate(args.limit);
        (Value::Array(rows), Value::Null)
    };
    let report = json!({
        "ok": true,
        "mode": if group_sessions { "sessions" } else { "history" },
        "gateway_url": gateway_root,
        "filters": {
            "session_id": args.session_id,
            "provider": args.provider,
            "model": args.model,
        },
        "receipts": receipts,
        "sessions": sessions,
        "paused": receipts_response.get("paused").cloned().unwrap_or_else(|| json!([])),
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_session_history_report(&report)?;
    }
    Ok(())
}

async fn reputation(args: ReputationArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let provider = if let Some(provider) = args.provider.clone() {
        provider
    } else {
        resolve_cli_wallet(
            &home,
            config.as_ref(),
            &args.peer_store_name,
            args.wallet_password.as_deref().unwrap_or(""),
        )
        .await?
        .public_key
    };
    let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let reputation = read_state_value(&rpc, &format!("rep/{provider}")).await?;
    let events_head = read_state_value(&rpc, &format!("ev/rep/head/{provider}")).await?;
    let provider_record = read_state_value(&rpc, &format!("prov/{provider}")).await?;
    let earning = match read_state_value(&rpc, &format!("earn/fiat/{provider}")).await? {
        Some(value) => serde_json::from_value(value).context("parsing earning record")?,
        None => LedgerEarningRecord {
            provider: provider.clone(),
            rail: "fiat".to_owned(),
            denom: "mu_usd".to_owned(),
            total_mu: 0,
            held_mu: 0,
            paid_cum_mu: 0,
            holdbacks: Vec::new(),
            updated_epoch: 0,
            updated_at: None,
            last_holdback_release_epoch: None,
            last_payout_rate_ts: None,
            last_payout_msb_tx_hash: None,
            last_settlement_epoch: None,
            last_settlement_msb_tx_hash: None,
        },
    };
    let earning = earning_view(earning)?;
    let report = json!({
        "ok": true,
        "rpc_url": rpc_url,
        "provider": provider,
        "provider_record": provider_record,
        "reputation": reputation,
        "events_head": events_head,
        "earnings": earning,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_reputation_report(&report);
    }
    Ok(())
}

fn component_error(error: impl std::fmt::Display) -> Value {
    json!({
        "ok": false,
        "error": error.to_string(),
    })
}

fn receipt_history_summary(entry: &Value) -> Value {
    let null = Value::Null;
    let body = receipt_body(entry).unwrap_or(&null);
    json!({
        "session_id": body.get("session_id").and_then(Value::as_str).unwrap_or(""),
        "seq": body.get("seq").and_then(Value::as_u64),
        "model_id": body.get("model_id").and_then(Value::as_str),
        "provider": body.get("provider").and_then(Value::as_str),
        "user": body.get("user").and_then(Value::as_str),
        "enclave_id": body.get("enclave_id").and_then(Value::as_str),
        "mu_owed_cum": body.get("mu_owed_cum").and_then(Value::as_u64),
        "usage": body.get("usage").cloned().unwrap_or(Value::Null),
        "ts": body.get("ts").and_then(Value::as_u64),
        "final_receipt": body.get("final_receipt").and_then(Value::as_bool),
        "receipt_hash": stable_value_hash(entry),
    })
}

fn receipt_history_matches(entry: &Value, args: &SessionHistoryArgs) -> bool {
    if let Some(session_id) = args.session_id.as_deref() {
        if entry.get("session_id").and_then(Value::as_str) != Some(session_id) {
            return false;
        }
    }
    if let Some(provider) = args.provider.as_deref() {
        if entry.get("provider").and_then(Value::as_str) != Some(provider) {
            return false;
        }
    }
    if let Some(model) = args.model.as_deref() {
        if entry.get("model_id").and_then(Value::as_str) != Some(model) {
            return false;
        }
    }
    true
}

fn group_session_summaries(entries_latest_first: &[Value]) -> Vec<Value> {
    let mut positions = BTreeMap::<String, usize>::new();
    let mut groups = Vec::<Value>::new();
    for entry in entries_latest_first {
        let session_id = entry
            .get("session_id")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_owned();
        let index = if let Some(index) = positions.get(&session_id) {
            *index
        } else {
            let index = groups.len();
            positions.insert(session_id.clone(), index);
            groups.push(json!({
                "session_id": session_id,
                "receipts": 0_u64,
                "latest": entry.clone(),
            }));
            index
        };
        if let Some(object) = groups[index].as_object_mut() {
            let receipts = object.get("receipts").and_then(Value::as_u64).unwrap_or(0) + 1;
            object.insert("receipts".to_owned(), Value::Number(receipts.into()));
        }
    }
    groups
}

fn print_status_report(report: &Value) {
    println!(
        "Mayhem status: {}",
        if report["ok"].as_bool() == Some(true) {
            "ok"
        } else {
            "degraded"
        }
    );
    println!("Home: {}", report["node"]["home"].as_str().unwrap_or(""));
    println!(
        "Wallet: {}",
        if report["wallet"]["ok"].as_bool() == Some(true) {
            report["wallet"]["public_key"].as_str().unwrap_or("")
        } else {
            report["wallet"]["error"].as_str().unwrap_or("unavailable")
        }
    );
    println!(
        "Peer RPC: {}",
        if report["peer"]["ok"].as_bool() == Some(true) {
            "ok"
        } else {
            report["peer"]["error"].as_str().unwrap_or("degraded")
        }
    );
    println!(
        "Gateway: {}",
        if report["gateway"]["ok"].as_bool() == Some(true) {
            "ok"
        } else {
            report["gateway"]["status"]["error"]
                .as_str()
                .unwrap_or("degraded")
        }
    );
    let status = &report["gateway"]["status"];
    if status["ok"].as_bool() == Some(true) {
        println!(
            "Sessions: active={} paused={} receipts={}",
            status["sessions_active"].as_u64().unwrap_or(0),
            status["sessions_paused"].as_u64().unwrap_or(0),
            status["receipts"].as_u64().unwrap_or(0)
        );
    }
}

fn print_session_history_report(report: &Value) -> Result<()> {
    if report["mode"].as_str() == Some("sessions") {
        println!("Recent sessions");
        for entry in report["sessions"].as_array().into_iter().flatten() {
            let latest = &entry["latest"];
            println!(
                "{} receipts={} provider={} model={} mu={}",
                entry["session_id"].as_str().unwrap_or(""),
                entry["receipts"].as_u64().unwrap_or(0),
                latest["provider"].as_str().unwrap_or(""),
                latest["model_id"].as_str().unwrap_or(""),
                latest["mu_owed_cum"].as_u64().unwrap_or(0),
            );
        }
    } else {
        println!("Recent receipts");
        for entry in report["receipts"].as_array().into_iter().flatten() {
            println!(
                "{} seq={} provider={} model={} mu={}",
                entry["session_id"].as_str().unwrap_or(""),
                entry["seq"].as_u64().unwrap_or(0),
                entry["provider"].as_str().unwrap_or(""),
                entry["model_id"].as_str().unwrap_or(""),
                entry["mu_owed_cum"].as_u64().unwrap_or(0),
            );
        }
    }
    if let Some(paused) = report["paused"]
        .as_array()
        .filter(|paused| !paused.is_empty())
    {
        println!("Paused sessions:");
        println!("{}", serde_json::to_string(paused)?);
    }
    Ok(())
}

fn print_reputation_report(report: &Value) {
    println!("Provider: {}", report["provider"].as_str().unwrap_or(""));
    if report["reputation"].is_null() {
        println!("Reputation: not anchored yet");
    } else {
        println!(
            "Reputation: {} bps (raw {} milli)",
            report["reputation"]["r_bps"].as_u64().unwrap_or(0),
            report["reputation"]["raw_milli"].as_u64().unwrap_or(0)
        );
        println!(
            "Probation active: {}",
            report["reputation"]["probation"]["active"]
                .as_bool()
                .unwrap_or(false)
        );
    }
    println!(
        "Earnings: total={} held={} paid={} claimable={} mu_usd",
        report["earnings"]["total_mu"].as_u64().unwrap_or(0),
        report["earnings"]["held_mu"].as_u64().unwrap_or(0),
        report["earnings"]["paid_cum_mu"].as_u64().unwrap_or(0),
        report["earnings"]["claimable_mu"].as_u64().unwrap_or(0),
    );
}

fn config_get(args: ConfigGetArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let path = config_path_for_home(&home);
    let config = read_config_toml_value(&path)?;
    let key = args.key.as_deref().map(canonical_config_key).transpose()?;
    let value = key.and_then(|key| toml_get_path(&config, key));
    let value_json = value
        .map(serde_json::to_value)
        .transpose()?
        .unwrap_or(Value::Null);
    let report = json!({
        "ok": true,
        "home": home,
        "path": path,
        "key": key,
        "value": value_json,
        "config": serde_json::to_value(&config)?,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_config_get_report(&report, &config)?;
    }
    Ok(())
}

fn config_set(args: ConfigSetArgs) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let path = config_path_for_home(&home);
    let key = canonical_config_key(&args.key)?;
    let mut config = read_config_toml_value(&path)?;
    toml_set_string(&mut config, key, args.value.clone())?;
    write_config_toml_value(&path, &config)?;
    let report = json!({
        "ok": true,
        "home": home,
        "path": path,
        "key": key,
        "value": args.value,
        "config": serde_json::to_value(&config)?,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "Set {} = {} in {}",
            report["key"].as_str().unwrap_or(""),
            report["value"].as_str().unwrap_or(""),
            report["path"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

fn reset(args: ResetArgs, action: &'static str) -> Result<()> {
    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    if !args.yes {
        bail!(
            "refusing to {action} {}; pass --yes to remove local Mayhem state",
            home.display()
        );
    }
    let removed = remove_local_state_path(&home)?;
    let report = json!({
        "ok": true,
        "action": action,
        "home": home,
        "removed": removed,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if removed {
        println!(
            "{} OK: removed {}",
            action,
            report["home"].as_str().unwrap_or("")
        );
    } else {
        println!(
            "{} OK: no local state existed at {}",
            action,
            report["home"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

async fn opencode(args: OpencodeArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }

    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let gateway_root = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let opencode_config_path = args
        .opencode_config
        .clone()
        .map(absolutize)
        .transpose()?
        .unwrap_or(default_opencode_config_path()?);

    let timeout = Duration::from_secs(args.timeout_seconds);
    let client = reqwest::Client::builder().timeout(timeout).build()?;
    let models = if args.sync_models || args.run_smoke {
        Some(fetch_gateway_models(&client, &gateway_root).await?)
    } else {
        None
    };
    let merge = merge_mayhem_opencode_config(
        &opencode_config_path,
        &gateway_root,
        models.as_deref(),
        args.sync_models,
    )?;
    let run = if args.run_smoke {
        let selected = select_test_model(
            models
                .as_deref()
                .context("gateway models must be fetched before opencode smoke")?,
            args.model.as_deref(),
        )?;
        let opencode_bin = resolve_opencode_bin(&home, args.opencode_bin.as_deref());
        serde_json::to_value(
            run_opencode_smoke(&opencode_bin, &opencode_config_path, &selected.id, timeout).await?,
        )?
    } else {
        json!({ "skipped": true })
    };
    let report = json!({
        "ok": true,
        "home": home,
        "gateway_url": gateway_root,
        "models_fetched": models.as_ref().map(Vec::len),
        "opencode": {
            "config": merge,
            "run": run,
        },
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_opencode_report(&report);
    }
    Ok(())
}

fn print_config_get_report(report: &Value, config: &toml::Value) -> Result<()> {
    println!("Config: {}", report["path"].as_str().unwrap_or(""));
    if let Some(key) = report["key"].as_str() {
        if report["value"].is_null() {
            println!("{key} is not set");
        } else {
            println!("{key} = {}", report["value"]);
        }
    } else {
        let text = toml::to_string_pretty(config)?;
        if text.trim().is_empty() {
            println!("(empty)");
        } else {
            print!("{text}");
        }
    }
    Ok(())
}

fn print_opencode_report(report: &Value) {
    println!("opencode wired.");
    println!("Gateway: {}", report["gateway_url"].as_str().unwrap_or(""));
    println!(
        "Config: {}",
        report["opencode"]["config"]["path"].as_str().unwrap_or("")
    );
    println!(
        "Provider: {} ({})",
        report["opencode"]["config"]["provider_id"]
            .as_str()
            .unwrap_or(""),
        report["opencode"]["config"]["base_url"]
            .as_str()
            .unwrap_or("")
    );
    if let Some(models) = report["models_fetched"].as_u64() {
        println!("Gateway models fetched: {models}");
    }
    if report["opencode"]["run"]["skipped"]
        .as_bool()
        .unwrap_or(false)
    {
        println!("Smoke: skipped");
    } else {
        println!(
            "Smoke: ok ({})",
            report["opencode"]["run"]["model"].as_str().unwrap_or("")
        );
    }
}

async fn mayhem_test(args: TestArgs) -> Result<()> {
    if args.timeout_seconds == 0 {
        bail!("--timeout-seconds must be positive");
    }

    let home = args.home.clone().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let gateway_url = resolve_cli_gateway_url(config.as_ref(), args.gateway_url.as_deref());
    let gateway_root = normalize_gateway_root(&gateway_url);
    let timeout = Duration::from_secs(args.timeout_seconds);
    let client = reqwest::Client::builder().timeout(timeout).build()?;

    let gateway_status =
        fetch_gateway_json(&client, &format!("{gateway_root}/mayhem/status")).await?;
    let models = fetch_gateway_models(&client, &gateway_root).await?;
    let selected_model = select_test_model(&models, args.model.as_deref())?;
    let direct_tool = if args.skip_direct_tool_smoke {
        json!({ "skipped": true })
    } else {
        run_gateway_tool_smoke(&client, &gateway_root, &selected_model.id).await?
    };

    let peer_health = if args.skip_peer_health {
        json!({ "skipped": true })
    } else {
        let rpc_url = resolve_cli_rpc_url(Some(&home), args.rpc_url.as_deref())?;
        let rpc = PeerRpcClient::new(&rpc_url)?;
        json!({
            "skipped": false,
            "rpc_url": rpc_url,
            "health": rpc.health().await.context("checking peer RPC health")?,
        })
    };

    let opencode_config_path = args
        .opencode_config
        .clone()
        .map(absolutize)
        .transpose()?
        .unwrap_or(default_opencode_config_path()?);
    let existing_opencode_models =
        read_existing_mayhem_opencode_model_count(&opencode_config_path).unwrap_or(0);
    let should_write_models = args.sync_models
        || existing_opencode_models == 0
        || !opencode_model_exists(&opencode_config_path, &selected_model.id).unwrap_or(false);

    let opencode_merge = if args.skip_opencode {
        json!({ "skipped": true })
    } else {
        serde_json::to_value(merge_mayhem_opencode_config(
            &opencode_config_path,
            &gateway_root,
            if should_write_models {
                Some(&models)
            } else {
                None
            },
            should_write_models,
        )?)?
    };

    let opencode_run = if args.skip_opencode || args.no_opencode_run {
        json!({ "skipped": true })
    } else {
        let opencode_bin = resolve_opencode_bin(&home, args.opencode_bin.as_deref());
        serde_json::to_value(
            run_opencode_smoke(
                &opencode_bin,
                &opencode_config_path,
                &selected_model.id,
                timeout,
            )
            .await?,
        )?
    };

    let receipts = fetch_gateway_json(&client, &format!("{gateway_root}/mayhem/receipts")).await?;
    let receipt = latest_gateway_receipt(&receipts);
    let expected_evidence_key = receipt
        .as_ref()
        .and_then(expected_usage_evidence_key)
        .unwrap_or_else(|| "ev/use/<epoch>".to_owned());

    let report = json!({
        "ok": true,
        "home": home,
        "role": config
            .as_ref()
            .and_then(|config| config.role.as_ref())
            .and_then(|role| role.mode.as_deref())
            .unwrap_or("unknown"),
        "gateway": {
            "url": gateway_root,
            "status": gateway_status,
            "models": models.len(),
            "selected_model": selected_model,
            "direct_tool_call": direct_tool,
        },
        "peer": peer_health,
        "opencode": {
            "config": opencode_merge,
            "run": opencode_run,
        },
        "receipt": receipt,
        "expected_epoch_evidence_key": expected_evidence_key,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_test_report(&report);
    }

    Ok(())
}

