fn gateway_chat_observed_text(response: &Value) -> Result<String> {
    let message = response
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first())
        .and_then(|choice| choice.get("message"))
        .context("gateway canary response did not include choices[0].message")?;
    if let Some(content) = message.get("content").and_then(Value::as_str) {
        return Ok(content.to_owned());
    }
    if let Some(tool_calls) = message.get("tool_calls") {
        return Ok(tool_calls.to_string());
    }
    bail!("gateway canary response message had neither content nor tool_calls")
}

fn normalize_canary_text(value: &str) -> String {
    value.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn evaluate_text_match(expected: &str, observed: &str, min_match_bps: u32) -> TextMatchEvaluation {
    let expected = normalize_canary_text(expected);
    let observed = normalize_canary_text(observed);
    let expected_chars = expected.chars().collect::<Vec<_>>();
    let observed_chars = observed.chars().collect::<Vec<_>>();
    let total_positions = expected_chars.len() as u32;
    let matched_positions = expected_chars
        .iter()
        .zip(observed_chars.iter())
        .filter(|(expected, observed)| expected == observed)
        .count() as u32;
    let match_bps = if total_positions == 0 {
        0
    } else {
        ((u64::from(matched_positions) * 10_000) / u64::from(total_positions)) as u32
    };
    TextMatchEvaluation {
        expected_text_hash: blake3::hash(expected.as_bytes()).to_hex().to_string(),
        observed_text_hash: blake3::hash(observed.as_bytes()).to_hex().to_string(),
        matched_positions,
        total_positions,
        match_bps,
        pass: match_bps >= min_match_bps,
    }
}

fn stable_value_hash(value: &Value) -> String {
    let stable = stable_json_value(value);
    blake3::hash(stable.to_string().as_bytes())
        .to_hex()
        .to_string()
}

fn stable_json_value(value: &Value) -> Value {
    match value {
        Value::Array(items) => Value::Array(items.iter().map(stable_json_value).collect()),
        Value::Object(map) => {
            let mut stable = serde_json::Map::new();
            let mut entries = map.iter().collect::<Vec<_>>();
            entries.sort_by(|(left, _), (right, _)| left.cmp(right));
            for (key, value) in entries {
                stable.insert(key.clone(), stable_json_value(value));
            }
            Value::Object(stable)
        }
        value => value.clone(),
    }
}

async fn fetch_gateway_json(client: &reqwest::Client, url: &str) -> Result<Value> {
    let response = client
        .get(url)
        .send()
        .await
        .with_context(|| format!("requesting {url}"))?;
    let status = response.status();
    let body = response.text().await?;
    if !status.is_success() {
        bail!("gateway returned {status} for {url}: {body}");
    }
    serde_json::from_str(&body).with_context(|| format!("parsing JSON from {url}"))
}

async fn fetch_gateway_models(client: &reqwest::Client, gateway_root: &str) -> Result<Vec<Value>> {
    let value = fetch_gateway_json(client, &format!("{gateway_root}/v1/models")).await?;
    let models = value
        .get("data")
        .and_then(Value::as_array)
        .filter(|models| !models.is_empty())
        .context("gateway /v1/models returned no models")?
        .clone();
    Ok(models)
}

struct CatalogReleaseFiles {
    catalog_path: PathBuf,
    signature_path: PathBuf,
}

async fn read_catalog_release_anchor(rpc: &PeerRpcClient) -> Result<CatalogReleaseAnchor> {
    let value = read_state_value(rpc, "catalog/current").await?.context(
        "catalog/current not found; ask the admin to run `mayhem admin publish-catalog`",
    )?;
    let release: CatalogReleaseAnchor =
        serde_json::from_value(value).context("parsing catalog/current")?;
    if release.status != "active" {
        bail!("catalog/current is not active");
    }
    if release.published_by_role.as_deref() != Some("admin") {
        bail!("catalog/current is not admin-published");
    }
    validate_catalog_source_url(
        &release.source_kind,
        &release.catalog_url,
        "catalog/current catalog_url",
    )?;
    validate_catalog_source_url(
        &release.source_kind,
        &release.signature_url,
        "catalog/current signature_url",
    )?;
    if !is_hex_len(&release.catalog_hash, 64)
        || !is_hex_len(&release.signature_hash, 64)
        || !is_hex_len(&release.public_key, 64)
    {
        bail!("catalog/current has invalid hash or public key fields");
    }
    Ok(release)
}

async fn fetch_catalog_release_files(
    client: &reqwest::Client,
    home: &Path,
    release: &CatalogReleaseAnchor,
) -> Result<CatalogReleaseFiles> {
    let cache_dir = home.join("catalog-cache").join(&release.catalog_hash);
    let catalog_path = cache_dir.join("models.json");
    let signature_path = cache_dir.join("models.json.sig");
    let keys_dir = cache_dir.join("keys");
    let canaries_dir = cache_dir.join("canaries");
    fs::create_dir_all(&keys_dir).with_context(|| format!("creating {}", keys_dir.display()))?;
    fs::create_dir_all(&canaries_dir)
        .with_context(|| format!("creating {}", canaries_dir.display()))?;

    cache_release_url(
        client,
        &release.catalog_url,
        &catalog_path,
        &release.catalog_hash,
        64 * 1024 * 1024,
        "catalog models.json",
    )
    .await?;
    cache_release_url(
        client,
        &release.signature_url,
        &signature_path,
        &release.signature_hash,
        1024 * 1024,
        "catalog signature",
    )
    .await?;
    for canary in &release.canaries {
        validate_catalog_source_url(
            &release.source_kind,
            &canary.url,
            "catalog/current canary URL",
        )?;
        if !is_hex_len(&canary.hash, 64) {
            bail!("catalog/current canary {} has invalid hash", canary.set_id);
        }
        cache_release_url(
            client,
            &canary.url,
            &canaries_dir.join(format!("{}.json", canary.set_id)),
            &canary.hash,
            1024 * 1024,
            "catalog canary set",
        )
        .await?;
    }

    write_json_file(
        &keys_dir.join(format!("{}.json", release.key_id)),
        &json!({
            "key_id": release.key_id,
            "alg": "ed25519",
            "public_key": release.public_key,
            "status": "active",
            "created_at": "ledger-catalog-release",
        }),
    )?;

    let report = catalog::verify(catalog::VerifyOptions {
        catalog_path: catalog_path.clone(),
        signature_path: signature_path.clone(),
        keys_dir,
        canaries_dir,
        check_dev_downloads: false,
        check_launch_sources: false,
        hf_token_file: None,
    })?;
    if !report.ok {
        bail!("ledger catalog release verification failed");
    }
    if report.catalog_hash != release.catalog_hash
        || report.key_id != release.key_id
        || report.model_count != release.model_count
        || report.artifact_count != release.artifact_count
    {
        bail!("ledger catalog release metadata does not match fetched catalog");
    }

    Ok(CatalogReleaseFiles {
        catalog_path,
        signature_path,
    })
}

async fn cache_release_url(
    client: &reqwest::Client,
    url: &str,
    path: &Path,
    expected_hash: &str,
    max_bytes: usize,
    label: &str,
) -> Result<()> {
    if let Ok(bytes) = fs::read(path) {
        if blake3_bytes_hex(&bytes) == expected_hash {
            return Ok(());
        }
    }
    let bytes = fetch_release_bytes(client, url, max_bytes, label).await?;
    let actual = blake3_bytes_hex(&bytes);
    if actual != expected_hash {
        bail!("{label} hash mismatch from {url}: expected {expected_hash}, got {actual}");
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    fs::write(path, bytes).with_context(|| format!("writing {}", path.display()))?;
    Ok(())
}

async fn fetch_release_bytes(
    client: &reqwest::Client,
    url: &str,
    max_bytes: usize,
    label: &str,
) -> Result<Vec<u8>> {
    validate_https_url(url, label)?;
    let response = client
        .get(url)
        .send()
        .await
        .with_context(|| format!("requesting {label} {url}"))?;
    let status = response.status();
    if !status.is_success() {
        let body = response.text().await.unwrap_or_default();
        bail!("{label} fetch returned {status} for {url}: {body}");
    }
    let bytes = response
        .bytes()
        .await
        .with_context(|| format!("reading {label} body from {url}"))?;
    if bytes.len() > max_bytes {
        bail!("{label} from {url} exceeded {max_bytes} bytes");
    }
    Ok(bytes.to_vec())
}

fn select_test_model(models: &[Value], requested: Option<&str>) -> Result<TestModel> {
    let selected = if let Some(requested) = requested {
        models
            .iter()
            .find(|model| model.get("id").and_then(Value::as_str) == Some(requested))
            .with_context(|| format!("requested model {requested} was not in /v1/models"))?
    } else {
        models
            .iter()
            .find(|model| model_tool_capable(model))
            .unwrap_or(&models[0])
    };
    gateway_model_view(selected)
}

fn gateway_model_view(model: &Value) -> Result<TestModel> {
    let id = model
        .get("id")
        .and_then(Value::as_str)
        .filter(|id| !id.is_empty())
        .context("gateway model missing id")?;
    Ok(TestModel {
        id: id.to_owned(),
        tools: model_tool_capable(model),
        json: model
            .get("mayhem")
            .and_then(|mayhem| mayhem.get("caps"))
            .and_then(|caps| caps.get("json"))
            .and_then(Value::as_bool)
            .unwrap_or(false),
        context: model
            .get("mayhem")
            .and_then(|mayhem| mayhem.get("caps"))
            .and_then(|caps| caps.get("ctx"))
            .and_then(Value::as_u64)
            .unwrap_or(0),
        binary_hashes_by_enclave: model
            .get("mayhem")
            .and_then(|mayhem| mayhem.get("route_candidates"))
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|candidate| {
                Some((
                    candidate.get("enclave_id")?.as_str()?.to_owned(),
                    candidate.get("binary_hash")?.as_str()?.to_owned(),
                ))
            })
            .collect(),
    })
}

fn gateway_model_summaries(models: &[Value]) -> Result<Vec<ModelSummary>> {
    models.iter().map(gateway_model_summary).collect()
}

fn filter_model_summaries_by_min_att_tier(
    summaries: Vec<ModelSummary>,
    min_att_tier: Option<u8>,
) -> Vec<ModelSummary> {
    let Some(min_att_tier) = min_att_tier else {
        return summaries;
    };
    summaries
        .into_iter()
        .filter(|summary| summary.max_attestation_tier >= min_att_tier)
        .collect()
}

fn filter_model_summaries_by_require_kyb(
    summaries: Vec<ModelSummary>,
    require_kyb: bool,
) -> Vec<ModelSummary> {
    if !require_kyb {
        return summaries;
    }
    summaries
        .into_iter()
        .filter(|summary| !summary.kyb_identities.is_empty())
        .collect()
}

fn gateway_model_summary(model: &Value) -> Result<ModelSummary> {
    let id = model
        .get("id")
        .and_then(Value::as_str)
        .filter(|id| !id.is_empty())
        .context("gateway model missing id")?;
    let mayhem = model.get("mayhem").unwrap_or(&Value::Null);
    let price = mayhem.get("price_ref_mu").unwrap_or(&Value::Null);
    let caps = mayhem.get("caps").unwrap_or(&Value::Null);
    let attestation_tiers = mayhem
        .get("attestation_tiers")
        .and_then(Value::as_object)
        .map(|tiers| {
            tiers
                .iter()
                .filter_map(|(tier, value)| value.as_u64().map(|count| (tier.clone(), count)))
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default();
    let attestation_tier_labels = mayhem
        .get("attestation_tier_labels")
        .and_then(Value::as_object)
        .map(|labels| {
            labels
                .iter()
                .filter_map(|(tier, value)| {
                    value.as_str().map(|label| (tier.clone(), label.to_owned()))
                })
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_else(|| attestation_tier_labels_for_counts(&attestation_tiers));
    let max_attestation_tier = max_attestation_tier(&attestation_tiers);
    let prompt_confidential = attestation_tiers
        .get("T3")
        .or_else(|| attestation_tiers.get("3"))
        .copied()
        .unwrap_or(0)
        > 0;
    let kyb_identities = mayhem
        .get("kyb_identities")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|value| serde_json::from_value(value.clone()).context("parsing model KYB identity"))
        .collect::<Result<Vec<ProviderKybInfo>>>()?;
    Ok(ModelSummary {
        id: id.to_owned(),
        providers_online: mayhem
            .get("providers_online")
            .and_then(Value::as_u64)
            .unwrap_or(0),
        rooms: mayhem.get("rooms").and_then(Value::as_u64).unwrap_or(0),
        denom: price
            .get("denom")
            .and_then(Value::as_str)
            .unwrap_or("mu_usd")
            .to_owned(),
        rate_map: gateway_price_rate_map(price),
        tools: caps.get("tools").and_then(Value::as_bool).unwrap_or(false),
        json: caps.get("json").and_then(Value::as_bool).unwrap_or(false),
        context: caps.get("ctx").and_then(Value::as_u64).unwrap_or(0),
        image: caps.get("image").and_then(Value::as_bool).unwrap_or(false),
        video: caps.get("video").and_then(Value::as_bool).unwrap_or(false),
        audio: caps.get("audio").and_then(Value::as_bool).unwrap_or(false),
        output_modality: caps
            .get("output_modality")
            .and_then(Value::as_str)
            .map(str::to_owned),
        output_modalities: caps_output_modalities(caps),
        attestation_tiers,
        attestation_tier_labels,
        kyb_identities,
        max_attestation_tier,
        prompt_confidential,
        prompt_confidentiality_note: prompt_confidentiality_note(prompt_confidential).to_owned(),
    })
}

fn gateway_price_rate_map(price: &Value) -> Vec<RateMapEntry> {
    if let Some(rate_map) = price
        .get("rate_map")
        .cloned()
        .and_then(|value| serde_json::from_value::<Vec<RateMapEntry>>(value).ok())
    {
        if !rate_map.is_empty() {
            return normalize_rate_map(rate_map);
        }
    }
    text_generation_rate_map(
        price.get("in_per_1k").and_then(Value::as_u64).unwrap_or(0),
        price.get("out_per_1k").and_then(Value::as_u64).unwrap_or(0),
    )
}

fn max_attestation_tier(tiers: &BTreeMap<String, u64>) -> u8 {
    tiers
        .iter()
        .filter(|(_, count)| **count > 0)
        .filter_map(|(tier, _)| attestation_tier_number(tier))
        .max()
        .unwrap_or(1)
}

fn attestation_tier_number(tier: &str) -> Option<u8> {
    let tier = tier.trim();
    let tier = tier.strip_prefix('T').unwrap_or(tier);
    tier.parse::<u8>()
        .ok()
        .filter(|tier| (1..=4).contains(tier))
}

fn prompt_confidentiality_note(prompt_confidential: bool) -> &'static str {
    if prompt_confidential {
        "Tier 3 route available: prompt-confidential hardware compute may be selectable"
    } else {
        "Not prompt-confidential: providers on Tier 1, Tier 2, or Tier 4 can read prompts in memory"
    }
}

fn attestation_tier_labels_for_counts(tiers: &BTreeMap<String, u64>) -> BTreeMap<String, String> {
    tiers
        .keys()
        .map(|tier| (tier.clone(), attestation_tier_label(tier).to_owned()))
        .collect()
}

fn gateway_attestation_tier_labels_for_counts(
    tiers: &BTreeMap<String, u32>,
) -> BTreeMap<String, String> {
    tiers
        .keys()
        .map(|tier| (tier.clone(), attestation_tier_label(tier).to_owned()))
        .collect()
}

fn attestation_tier_label(tier: &str) -> &'static str {
    match tier {
        "T1" => "Tier 1 - software self-attestation; economic/trust only",
        "T2" => {
            "Tier 2 - hardware device identity; Apple App Attest strong / NVIDIA GB10 device medium; not prompt-confidential"
        }
        "T3" => "Tier 3 - hardware confidential compute; prompt-confidential when supported",
        "T4" => "Tier 4 - admin KYB verified identity; not prompt-confidential",
        _ => "Unknown attestation tier",
    }
}

fn model_tool_capable(model: &Value) -> bool {
    model
        .get("mayhem")
        .and_then(|mayhem| mayhem.get("caps"))
        .and_then(|caps| caps.get("tools"))
        .and_then(Value::as_bool)
        .unwrap_or(false)
}

async fn run_gateway_tool_smoke(
    client: &reqwest::Client,
    gateway_root: &str,
    model_id: &str,
) -> Result<Value> {
    let request = json!({
        "model": model_id,
        "messages": [{ "role": "user", "content": "Call the mayhem_ping tool." }],
        "tools": [{
            "type": "function",
            "function": {
                "name": "mayhem_ping",
                "description": "Return a small Mayhem smoke-test marker.",
                "parameters": {
                    "type": "object",
                    "properties": {},
                    "additionalProperties": false
                }
            }
        }],
        "tool_choice": { "type": "function", "function": { "name": "mayhem_ping" } }
    });
    let response = post_gateway_json(
        client,
        &format!("{gateway_root}/v1/chat/completions"),
        &request,
    )
    .await?;
    let tool_call = response
        .get("choices")
        .and_then(Value::as_array)
        .and_then(|choices| choices.first())
        .and_then(|choice| choice.get("message"))
        .and_then(|message| message.get("tool_calls"))
        .and_then(Value::as_array)
        .and_then(|calls| calls.first())
        .cloned()
        .context("gateway chat completion did not return a tool call")?;
    let tool_name = tool_call
        .get("function")
        .and_then(|function| function.get("name"))
        .and_then(Value::as_str)
        .context("gateway tool call missing function name")?;
    if tool_name != "mayhem_ping" {
        bail!("gateway returned unexpected tool call {tool_name}");
    }
    let tool_call_id = tool_call
        .get("id")
        .and_then(Value::as_str)
        .context("gateway tool call missing id")?;
    let followup = json!({
        "model": model_id,
        "messages": [
            { "role": "user", "content": "Call the mayhem_ping tool." },
            { "role": "assistant", "content": null, "tool_calls": [tool_call] },
            { "role": "tool", "tool_call_id": tool_call_id, "content": "{\"ok\":true}" }
        ]
    });
    let final_response = post_gateway_json(
        client,
        &format!("{gateway_root}/v1/chat/completions"),
        &followup,
    )
    .await?;
    Ok(json!({
        "tool_call": response,
        "followup": final_response,
    }))
}

async fn post_gateway_json(client: &reqwest::Client, url: &str, body: &Value) -> Result<Value> {
    let response = client
        .post(url)
        .json(body)
        .send()
        .await
        .with_context(|| format!("posting {url}"))?;
    let status = response.status();
    let response_body = response.text().await?;
    if !status.is_success() {
        bail!("gateway returned {status} for {url}: {response_body}");
    }
    serde_json::from_str(&response_body).with_context(|| format!("parsing JSON from {url}"))
}

fn default_opencode_config_path() -> Result<PathBuf> {
    if let Ok(path) = env::var("MAYHEM_OPENCODE_CONFIG") {
        if !path.trim().is_empty() {
            return absolutize(PathBuf::from(path));
        }
    }
    if cfg!(target_os = "windows") {
        if let Ok(appdata) = env::var("APPDATA") {
            if !appdata.trim().is_empty() {
                return Ok(PathBuf::from(appdata)
                    .join("opencode")
                    .join("opencode.json"));
            }
        }
    }
    if let Ok(config_home) = env::var("XDG_CONFIG_HOME") {
        if !config_home.trim().is_empty() {
            return Ok(PathBuf::from(config_home)
                .join("opencode")
                .join("opencode.json"));
        }
    }
    Ok(user_home_dir()?
        .join(".config")
        .join("opencode")
        .join("opencode.json"))
}

fn merge_mayhem_opencode_config(
    path: &Path,
    gateway_root: &str,
    models: Option<&[Value]>,
    write_models: bool,
) -> Result<OpencodeMergeReport> {
    let created = !path.exists();
    let mut root = if created {
        json!({ "$schema": OPENCODE_SCHEMA_URL })
    } else {
        let text =
            fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
        serde_json::from_str(&text).with_context(|| format!("parsing {}", path.display()))?
    };
    if !root.is_object() {
        bail!("{} must contain a JSON object", path.display());
    }
    let object = root.as_object_mut().expect("checked object");
    object
        .entry("$schema")
        .or_insert_with(|| Value::String(OPENCODE_SCHEMA_URL.to_owned()));
    if !object
        .get("provider")
        .is_some_and(|provider| provider.is_object())
    {
        object.insert("provider".to_owned(), Value::Object(Map::new()));
    }
    let provider = object
        .get_mut("provider")
        .and_then(Value::as_object_mut)
        .expect("provider object");
    let existing_models = provider
        .get(OPENCODE_PROVIDER_ID)
        .and_then(|entry| entry.get("models"))
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    let model_map = if write_models {
        opencode_models_from_gateway(models.unwrap_or(&[]))?
    } else {
        existing_models
    };
    let models_written = model_map.len();
    let default_model = model_map
        .keys()
        .next()
        .map(|model_id| opencode_model_ref(model_id));
    provider.insert(
        OPENCODE_PROVIDER_ID.to_owned(),
        json!({
            "npm": OPENCODE_PROVIDER_NPM,
            "name": OPENCODE_PROVIDER_NAME,
            "options": {
                "baseURL": gateway_v1_url(gateway_root),
                "apiKey": "mayhem-local",
                "timeout": false,
                "headerTimeout": false,
                "chunkTimeout": 300000
            },
            "models": Value::Object(model_map),
        }),
    );

    let default_model_added = if !object.contains_key("model") {
        if let Some(default_model) = default_model {
            object.insert("model".to_owned(), Value::String(default_model));
            true
        } else {
            false
        }
    } else {
        false
    };
    let enabled_provider_added = ensure_enabled_provider(object, OPENCODE_PROVIDER_ID);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    fs::write(path, serde_json::to_vec_pretty(&root)?)
        .with_context(|| format!("writing {}", path.display()))?;
    Ok(OpencodeMergeReport {
        path: path.to_path_buf(),
        provider_id: OPENCODE_PROVIDER_ID.to_owned(),
        base_url: gateway_v1_url(gateway_root),
        models_written,
        created,
        enabled_provider_added,
        default_model_added,
    })
}

fn read_existing_mayhem_opencode_model_count(path: &Path) -> Result<usize> {
    if !path.exists() {
        return Ok(0);
    }
    let text = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    let root: Value =
        serde_json::from_str(&text).with_context(|| format!("parsing {}", path.display()))?;
    Ok(root
        .get("provider")
        .and_then(|provider| provider.get(OPENCODE_PROVIDER_ID))
        .and_then(|provider| provider.get("models"))
        .and_then(Value::as_object)
        .map(Map::len)
        .unwrap_or(0))
}

fn opencode_model_exists(path: &Path, model_id: &str) -> Result<bool> {
    if !path.exists() {
        return Ok(false);
    }
    let text = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    let root: Value =
        serde_json::from_str(&text).with_context(|| format!("parsing {}", path.display()))?;
    Ok(root
        .get("provider")
        .and_then(|provider| provider.get(OPENCODE_PROVIDER_ID))
        .and_then(|provider| provider.get("models"))
        .and_then(Value::as_object)
        .is_some_and(|models| models.contains_key(model_id)))
}

fn opencode_models_from_gateway(models: &[Value]) -> Result<Map<String, Value>> {
    let mut out = Map::new();
    for model in models {
        let view = gateway_model_view(model)?;
        out.insert(
            view.id.clone(),
            json!({
                "name": view.id,
                "limit": {
                    "context": view.context.max(1),
                    "output": 4096
                },
                "tool_call": view.tools,
                "reasoning": false,
                "options": {
                    "temperature": 0,
                    "top_p": 1
                }
            }),
        );
    }
    Ok(out)
}

fn ensure_enabled_provider(root: &mut Map<String, Value>, provider_id: &str) -> bool {
    match root.get_mut("enabled_providers") {
        Some(Value::Array(providers)) => {
            if providers
                .iter()
                .any(|value| value.as_str() == Some(provider_id))
            {
                false
            } else {
                providers.push(Value::String(provider_id.to_owned()));
                true
            }
        }
        Some(_) => false,
        None => false,
    }
}

fn resolve_opencode_bin(home: &Path, requested: Option<&Path>) -> String {
    if let Some(requested) = requested {
        return requested.display().to_string();
    }
    let home_bin = if cfg!(target_os = "windows") {
        home.join("bin").join("opencode.exe")
    } else {
        home.join("bin").join("opencode")
    };
    if home_bin.exists() {
        home_bin.display().to_string()
    } else {
        "opencode".to_owned()
    }
}

async fn run_opencode_smoke(
    opencode_bin: &str,
    opencode_config_path: &Path,
    model_id: &str,
    timeout: Duration,
) -> Result<OpencodeRunReport> {
    let work_dir = temp_work_dir("mayhem-opencode-test")?;
    let model = opencode_model_ref(model_id);
    let mut command = Command::new(opencode_bin);
    command
        .arg("run")
        .arg("--pure")
        .arg("--model")
        .arg(&model)
        .arg("--title")
        .arg("mayhem-opencode-smoke")
        .arg("--format")
        .arg("json")
        .arg("--dangerously-skip-permissions")
        .arg("--dir")
        .arg(&work_dir)
        .arg("Use the bash tool once to print mayhem-opencode-tool-ok, then answer with mayhem-opencode-tool-ok.");
    command.env("OPENCODE_DISABLE_AUTOUPDATE", "1");
    let config_home = xdg_config_home_for_opencode_config(opencode_config_path).with_context(
        || {
            format!(
                "opencode only reads config paths shaped like <config-home>/opencode/opencode.json; got {}",
                opencode_config_path.display()
            )
        },
    )?;
    command.env("XDG_CONFIG_HOME", config_home);
    let output = tokio::time::timeout(timeout, command.output())
        .await
        .map_err(|_| anyhow::anyhow!("opencode run timed out after {}s", timeout.as_secs()))?
        .with_context(|| format!("running {opencode_bin}"))?;
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    if !output.status.success() {
        bail!("opencode run failed: {}", stderr.trim());
    }
    let parsed = parse_opencode_run_output(&stdout)?;
    if !parsed.tool_use_seen {
        bail!("opencode run did not exercise a tool call");
    }
    if !parsed.marker_seen {
        bail!("opencode run did not echo {OPENCODE_TEST_MARKER}");
    }
    Ok(OpencodeRunReport {
        binary: opencode_bin.to_owned(),
        model,
        session_id: parsed.session_id,
        tool_use_seen: parsed.tool_use_seen,
        marker_seen: parsed.marker_seen,
        work_dir,
        stdout_lines: parsed.stdout_lines,
    })
}

fn opencode_model_ref(model_id: &str) -> String {
    format!("{OPENCODE_PROVIDER_ID}/{model_id}")
}

#[derive(Debug)]
struct ParsedOpencodeOutput {
    session_id: Option<String>,
    tool_use_seen: bool,
    marker_seen: bool,
    stdout_lines: usize,
}

fn parse_opencode_run_output(stdout: &str) -> Result<ParsedOpencodeOutput> {
    let mut parsed = ParsedOpencodeOutput {
        session_id: None,
        tool_use_seen: false,
        marker_seen: stdout.contains(OPENCODE_TEST_MARKER),
        stdout_lines: 0,
    };
    for line in stdout.lines().filter(|line| !line.trim().is_empty()) {
        parsed.stdout_lines += 1;
        let Ok(value) = serde_json::from_str::<Value>(line) else {
            continue;
        };
        if parsed.session_id.is_none() {
            parsed.session_id = value
                .get("sessionID")
                .and_then(Value::as_str)
                .map(str::to_owned);
        }
        if value.get("type").and_then(Value::as_str) == Some("tool_use") {
            parsed.tool_use_seen = true;
        }
        if value.to_string().contains(OPENCODE_TEST_MARKER) {
            parsed.marker_seen = true;
        }
    }
    Ok(parsed)
}

fn xdg_config_home_for_opencode_config(path: &Path) -> Option<PathBuf> {
    if path.file_name().and_then(|name| name.to_str()) != Some("opencode.json") {
        return None;
    }
    let parent = path.parent()?;
    if parent.file_name().and_then(|name| name.to_str()) != Some("opencode") {
        return None;
    }
    parent.parent().map(Path::to_path_buf)
}

fn latest_gateway_receipt(receipts: &Value) -> Option<Value> {
    receipts
        .get("data")
        .and_then(Value::as_array)
        .and_then(|data| data.last())
        .cloned()
}

fn expected_usage_evidence_key(receipt: &Value) -> Option<String> {
    let body = receipt_body(receipt)?;
    let ts = body.get("ts")?.as_u64()?;
    Some(format!("ev/use/{}", ts / DEFAULT_EPOCH_LENGTH_MILLIS))
}

fn receipt_body(receipt: &Value) -> Option<&Value> {
    let receipt = receipt.get("receipt").unwrap_or(receipt);
    Some(receipt.get("body").unwrap_or(receipt))
}

fn normalize_gateway_root(gateway_url: &str) -> String {
    let trimmed = gateway_url.trim().trim_end_matches('/');
    trimmed
        .strip_suffix("/v1")
        .unwrap_or(trimmed)
        .trim_end_matches('/')
        .to_owned()
}

fn gateway_v1_url(gateway_root: &str) -> String {
    let root = normalize_gateway_root(gateway_root);
    format!("{root}/v1")
}

fn gateway_bind_addr(
    config: Option<&MayhemConfig>,
    bind: Option<&str>,
    port: u16,
) -> Result<SocketAddr> {
    if let Some(bind) = bind {
        let bind = bind.trim();
        if !bind.is_empty() {
            let bind = bind
                .parse()
                .with_context(|| format!("parsing gateway bind address {bind}"))?;
            validate_loopback_dashboard_bind(bind)?;
            return Ok(bind);
        }
    }
    let port = config
        .and_then(|config| config.network.as_ref())
        .and_then(|network| network.gateway_url.as_deref())
        .and_then(gateway_port_from_url)
        .unwrap_or(port);
    let bind = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    validate_loopback_dashboard_bind(bind)?;
    Ok(bind)
}

fn gateway_port_from_url(value: &str) -> Option<u16> {
    let root = normalize_gateway_root(value);
    reqwest::Url::parse(&root).ok()?.port()
}

fn gateway_public_url(bind: SocketAddr) -> String {
    match bind {
        SocketAddr::V4(addr) if addr.ip().is_unspecified() => {
            format!("http://127.0.0.1:{}", addr.port())
        }
        SocketAddr::V6(addr) if addr.ip().is_unspecified() => {
            format!("http://[::1]:{}", addr.port())
        }
        bind => format!("http://{bind}"),
    }
}

fn resolve_cli_gateway_url(config: Option<&MayhemConfig>, gateway_url: Option<&str>) -> String {
    if let Some(gateway_url) = gateway_url {
        let gateway_url = gateway_url.trim();
        if !gateway_url.is_empty() {
            return normalize_gateway_root(gateway_url);
        }
    }
    if let Ok(gateway_url) = env::var("MAYHEM_GATEWAY_URL") {
        let gateway_url = gateway_url.trim();
        if !gateway_url.is_empty() {
            return normalize_gateway_root(gateway_url);
        }
    }
    config
        .and_then(|config| config.network.as_ref())
        .and_then(|network| network.gateway_url.as_deref())
        .filter(|value| !value.trim().is_empty())
        .map(normalize_gateway_root)
        .unwrap_or_else(|| DEFAULT_GATEWAY_URL.to_owned())
}

fn temp_work_dir(prefix: &str) -> Result<PathBuf> {
    let path = env::temp_dir().join(format!(
        "{prefix}-{}-{}",
        std::process::id(),
        now_nanos_for_path()
    ));
    fs::create_dir_all(&path).with_context(|| format!("creating {}", path.display()))?;
    Ok(path)
}

fn now_nanos_for_path() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0)
}

fn now_millis_for_path() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis())
        .unwrap_or(0)
}

fn duration_millis_u64(duration: Duration) -> u64 {
    u64::try_from(duration.as_millis()).unwrap_or(u64::MAX)
}

fn print_test_report(report: &Value) {
    let gateway = &report["gateway"];
    println!("Mayhem test OK.");
    println!("Gateway: {}", gateway["url"].as_str().unwrap_or(""));
    println!(
        "Models: {} (selected {})",
        gateway["models"].as_u64().unwrap_or(0),
        gateway["selected_model"]["id"].as_str().unwrap_or("")
    );
    if report["peer"]["skipped"].as_bool().unwrap_or(false) {
        println!("Peer RPC: skipped");
    } else {
        println!("Peer RPC: ok");
    }
    if report["opencode"]["run"]["skipped"]
        .as_bool()
        .unwrap_or(false)
    {
        println!("opencode: skipped");
    } else {
        println!(
            "opencode: ok ({})",
            report["opencode"]["run"]["model"].as_str().unwrap_or("")
        );
    }
    if let Some(session_id) = receipt_body(&report["receipt"])
        .and_then(|body| body.get("session_id"))
        .and_then(Value::as_str)
    {
        println!("Receipt session: {session_id}");
    }
    println!(
        "Expected epoch evidence key: {}",
        report["expected_epoch_evidence_key"].as_str().unwrap_or("")
    );
}

fn print_models_report(report: &Value) -> Result<()> {
    println!("Gateway: {}", report["gateway_url"].as_str().unwrap_or(""));
    if let Some(min_att_tier) = report["min_att_tier"].as_u64() {
        println!("Filter: minimum attestation tier T{min_att_tier}");
    }
    if report["require_kyb"].as_bool() == Some(true) {
        println!("Filter: admin-KYB'd provider required");
    }
    println!(
        "Prompt privacy: only Tier 3 is prompt-confidential; Tier 1, Tier 2, and Tier 4 providers can read prompts in memory."
    );
    println!(
        "{:<44} {:>9} {:>5} {:>23} {:>7} {:>5} {:>5}  {:<44}",
        "MODEL", "PROVIDERS", "ROOMS", "RATE MAP", "CTX", "TOOLS", "JSON", "ATTESTATION"
    );
    for model in report["models"]
        .as_array()
        .context("models report missing models[]")?
    {
        let id = model["id"].as_str().unwrap_or("");
        let providers = model["providers_online"].as_u64().unwrap_or(0);
        let rooms = model["rooms"].as_u64().unwrap_or(0);
        let rate_map = model["rate_map"]
            .as_array()
            .cloned()
            .and_then(|value| serde_json::from_value::<Vec<RateMapEntry>>(Value::Array(value)).ok())
            .unwrap_or_default();
        let price = format_rate_map(&rate_map);
        let context = model["context"].as_u64().unwrap_or(0);
        let tools = bool_mark(model["tools"].as_bool().unwrap_or(false));
        let json = bool_mark(model["json"].as_bool().unwrap_or(false));
        let attestation = attestation_summary_for_model(model);
        println!(
            "{:<44} {:>9} {:>5} {:>23} {:>7} {:>5} {:>5}  {:<44}",
            truncate_for_table(id, 44),
            providers,
            rooms,
            truncate_for_table(&price, 23),
            context,
            tools,
            json,
            truncate_for_table(&attestation, 44)
        );
    }
    Ok(())
}

fn attestation_summary_for_model(model: &Value) -> String {
    let tiers = model
        .get("attestation_tiers")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    let labels = model
        .get("attestation_tier_labels")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    let mut parts = tiers
        .iter()
        .filter_map(|(tier, count)| {
            let count = count.as_u64()?;
            let label = labels
                .get(tier)
                .and_then(Value::as_str)
                .unwrap_or("attestation tier");
            Some(format!("{tier}={count} {label}"))
        })
        .collect::<Vec<_>>();
    if parts.is_empty() {
        "T1=0 Tier 1 - software self-attestation; economic/trust only".to_owned()
    } else {
        parts.sort();
        let mut summary = parts.join("; ");
        if let Some(identity) = model
            .get("kyb_identities")
            .and_then(Value::as_array)
            .and_then(|identities| identities.first())
        {
            let legal_name = identity
                .get("legal_name")
                .and_then(Value::as_str)
                .unwrap_or("");
            let jurisdiction = identity
                .get("jurisdiction")
                .and_then(Value::as_str)
                .unwrap_or("");
            if !legal_name.is_empty() && !jurisdiction.is_empty() {
                summary.push_str(&format!(
                    "; Tier 4 - verified: {legal_name} ({jurisdiction})"
                ));
            }
        }
        summary
    }
}

fn print_balance_report(report: &Value) {
    let balance = &report["balance"];
    let mu = report["credit"]["mu"].as_u64().unwrap_or(0);
    println!("Mayhem balance");
    println!("Public key: {}", report["who"].as_str().unwrap_or(""));
    println!("Rail: {}", report["rail"].as_str().unwrap_or(""));
    println!(
        "Credit: {} USD ({} mu_usd)",
        report["credit"]["usd"].as_str().unwrap_or("0.00"),
        mu
    );
    println!(
        "Updated epoch: {}",
        balance["updated_epoch"].as_u64().unwrap_or(0)
    );
    if let Some(updated_at) = balance.get("updated_at").and_then(Value::as_u64) {
        println!("Updated at: {updated_at}");
    }
    if let Some(status) = report["frozen"].get("status").and_then(Value::as_str) {
        println!("Frozen: {status}");
    } else {
        println!("Frozen: no");
    }
}

fn bool_mark(value: bool) -> &'static str {
    if value {
        "yes"
    } else {
        "no"
    }
}

fn truncate_for_table(value: &str, width: usize) -> String {
    let count = value.chars().count();
    if count <= width {
        return value.to_owned();
    }
    if width <= 1 {
        return ".".repeat(width);
    }
    let mut out = value.chars().take(width - 1).collect::<String>();
    out.push('.');
    out
}

async fn payouts(args: PayoutsArgs) -> Result<()> {
    let rpc_url = resolve_cli_rpc_url(args.home.as_ref(), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let report = if let Some(epoch) = args.epoch {
        json!({
            "rpc_url": rpc_url,
            "epoch": epoch,
            "claim_model": "tap_non_custodial_claim",
            "fee": read_state_value(&rpc, &format!("ev/fee/{epoch}")).await?,
        })
    } else {
        let mut fee_sweeps = read_prefix_entries(&rpc, "ev/fee/")
            .await?
            .into_iter()
            .filter(|entry| {
                entry
                    .value
                    .get("sweep_msb_tx_hash")
                    .and_then(Value::as_str)
                    .is_some()
            })
            .collect::<Vec<_>>();
        fee_sweeps.sort_by(|a, b| a.key.cmp(&b.key));
        json!({
            "rpc_url": rpc_url,
            "claim_model": "tap_non_custodial_claim",
            "fee_sweeps": fee_sweeps,
        })
    };

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_payouts_report(&report);
    }
    Ok(())
}

async fn earnings(args: EarningsArgs) -> Result<()> {
    let rpc_url = resolve_cli_rpc_url(args.home.as_ref(), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    let records = if let Some(provider) = &args.provider {
        read_prefix_values::<LedgerEarningRecord>(&rpc, "earn/")
            .await?
            .into_iter()
            .filter(|record| record.provider == *provider)
            .collect::<Vec<_>>()
    } else {
        read_prefix_values(&rpc, "earn/").await?
    };
    let mut views = records
        .into_iter()
        .map(earning_view)
        .collect::<Result<Vec<_>>>()?;
    views.sort_by(|a, b| {
        a.provider
            .cmp(&b.provider)
            .then_with(|| a.rail.cmp(&b.rail))
    });
    let report = json!({
        "rpc_url": rpc_url,
        "earnings": views,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_earnings_report(&report);
    }
    Ok(())
}

async fn receipts_export(args: ReceiptsExportArgs) -> Result<()> {
    let deposits = read_optional_json_array(args.deposits_file.as_deref(), "deposits")?;
    let receipts = read_receipts_for_export(&args).await?;
    let payouts = read_optional_json_array(args.payouts_file.as_deref(), "payouts")?;
    let prior_earnings = read_prior_earnings(args.prior_earnings_file.as_deref())?;
    let bundle = EpochAuditBundle {
        epoch: args.epoch,
        params: EpochAuditParams {
            fee_bps: args.fee_bps,
        },
        deposits,
        receipts,
        payouts,
        prior_earnings,
        prior_fee_cum_mu: args.prior_fee_cum_mu,
    };

    let output_path = args
        .output
        .as_ref()
        .map(|path| absolutize(path.clone()))
        .transpose()?;
    if let Some(path) = &output_path {
        write_json_file(path, &bundle)?;
    }

    let mut cleanup_path = None;
    let verifier_input_path = if let Some(path) = &output_path {
        path.clone()
    } else if args.no_verify {
        PathBuf::new()
    } else {
        let path = temp_audit_bundle_path(args.epoch)?;
        write_json_file(&path, &bundle)?;
        cleanup_path = Some(path.clone());
        path
    };

    let mut report = ReceiptsExportReport {
        bundle,
        bundle_path: output_path.clone(),
        recomputed: None,
        evidence: None,
        checks: Vec::new(),
        verified: false,
    };

    if !args.no_verify {
        let verifier_script = args
            .verifier_script
            .clone()
            .map(Ok)
            .unwrap_or_else(|| repo_path("intercom/scripts/recompute-epoch-roots.mjs"))?;
        let verifier_script = absolutize(verifier_script)?;
        let recomputed = run_epoch_recompute_script(&verifier_script, &verifier_input_path).await?;
        let evidence = read_evidence_for_export(&args).await?;
        let checks = verify_epoch_evidence(args.epoch, &recomputed, &evidence);
        let verified = checks.iter().all(|check| check.ok);
        report.recomputed = Some(recomputed);
        report.evidence = Some(evidence);
        report.checks = checks;
        report.verified = verified;
        if !verified {
            bail!(
                "exported receipt bundle did not verify against ev/* records; rerun with --json for details"
            );
        }
    }

    if let Some(path) = cleanup_path {
        let _ = fs::remove_file(path);
    }

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if output_path.is_none() {
        println!("{}", serde_json::to_string_pretty(&report.bundle)?);
    } else if report.verified {
        println!(
            "Receipt audit bundle verified for epoch {}: {} checks matched.",
            args.epoch,
            report.checks.len()
        );
    } else {
        println!("Receipt audit bundle written for epoch {}.", args.epoch);
    }
    Ok(())
}

async fn receipts_publish(args: ReceiptsPublishArgs) -> Result<()> {
    if args.poll_interval_ms == 0 {
        bail!("--poll-interval-ms must be positive");
    }
    let channel = epoch_sidechannel(args.epoch, args.channel.as_deref());
    let gateway_url = args
        .gateway_url
        .as_deref()
        .unwrap_or(DEFAULT_GATEWAY_URL)
        .trim_end_matches('/')
        .to_owned();
    let (sc_bridge_url, sc_bridge_token) = resolve_cli_sc_bridge(
        args.home.as_ref(),
        args.sc_bridge_url.as_deref(),
        args.sc_bridge_token.as_deref(),
    )?;
    let mut bridge = ScBridgeClient::connect(ScBridgeConfig::new(&sc_bridge_url, sc_bridge_token)?)
        .await
        .context("connecting to SC-Bridge for epoch receipt publish")?;
    bridge
        .join(&channel)
        .await
        .with_context(|| format!("joining sidechannel {channel}"))?;

    let deadline = (args.watch && args.timeout_seconds > 0)
        .then(|| Instant::now() + Duration::from_secs(args.timeout_seconds));
    let mut seen = BTreeSet::new();
    let mut published = 0usize;

    loop {
        let receipts = fetch_gateway_receipts(&gateway_url).await?;
        for receipt in receipts {
            let receipt_id = receipt_id(&receipt);
            if !seen.insert(receipt_id.clone()) {
                continue;
            }
            let message = epoch_receipt_message(args.epoch, receipt_id, receipt)?;
            bridge
                .send(&channel, &message)
                .await
                .with_context(|| format!("publishing receipt to {channel}"))?;
            published += 1;
            if args.max_receipts.is_some_and(|max| published >= max) {
                break;
            }
        }

        if !args.watch || args.max_receipts.is_some_and(|max| published >= max) {
            break;
        }
        if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
            break;
        }
        sleep(Duration::from_millis(args.poll_interval_ms)).await;
    }

    let report = json!({
        "epoch": args.epoch,
        "channel": channel,
        "gateway_url": gateway_url,
        "published": published,
        "seen": seen.len(),
        "watch": args.watch,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        println!(
            "Published {} unique receipt(s) to {}.",
            report["published"].as_u64().unwrap_or_default(),
            report["channel"].as_str().unwrap_or("")
        );
    }
    Ok(())
}

async fn receipts_collect(args: ReceiptsCollectArgs) -> Result<()> {
    let channel = epoch_sidechannel(args.epoch, args.channel.as_deref());
    let (sc_bridge_url, sc_bridge_token) = resolve_cli_sc_bridge(
        args.home.as_ref(),
        args.sc_bridge_url.as_deref(),
        args.sc_bridge_token.as_deref(),
    )?;
    let mut bridge = ScBridgeClient::connect(ScBridgeConfig::new(&sc_bridge_url, sc_bridge_token)?)
        .await
        .context("connecting to SC-Bridge for epoch receipt collection")?;
    bridge
        .subscribe([channel.as_str()])
        .await
        .with_context(|| format!("subscribing to sidechannel {channel}"))?;
    bridge
        .join(&channel)
        .await
        .with_context(|| format!("joining sidechannel {channel}"))?;

    let deadline = Instant::now() + Duration::from_secs(args.timeout_seconds);
    let mut seen = BTreeSet::new();
    let mut receipts = Vec::new();

    while Instant::now() < deadline {
        let remaining = deadline.saturating_duration_since(Instant::now());
        match bridge.next_sidechannel_message(remaining).await {
            Ok(event) => {
                let Some((receipt_id, receipt)) =
                    epoch_receipt_from_sidechannel_event(&event, args.epoch, &channel)
                else {
                    continue;
                };
                if seen.insert(receipt_id) {
                    receipts.push(receipt);
                }
                if args.max_receipts.is_some_and(|max| receipts.len() >= max) {
                    break;
                }
            }
            Err(mayhem_bridge::BridgeError::Timeout) => break,
            Err(err) => return Err(err).context("collecting epoch receipt sidechannel message"),
        }
    }

    let output = json!({
        "schema_version": 1,
        "epoch": args.epoch,
        "channel": channel,
        "collected_at_ms": unix_epoch_millis()?,
        "data": receipts,
    });

    let output_path = args
        .output
        .as_ref()
        .map(|path| absolutize(path.clone()))
        .transpose()?;
    if let Some(path) = &output_path {
        write_json_file(path, &output)?;
    }

    let report = json!({
        "epoch": args.epoch,
        "channel": output["channel"],
        "receipts": output["data"].as_array().map(Vec::len).unwrap_or(0),
        "output": output_path,
    });

    if args.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else if let Some(path) = output_path {
        println!(
            "Collected {} unique receipt(s) from {}.",
            report["receipts"].as_u64().unwrap_or_default(),
            report["channel"].as_str().unwrap_or("")
        );
        println!("Copy/paste receipts file: {}", path.display());
    } else {
        println!("{}", serde_json::to_string_pretty(&output)?);
    }
    Ok(())
}

fn epoch_sidechannel(epoch: u64, requested: Option<&str>) -> String {
    requested
        .filter(|channel| !channel.trim().is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| format!("mx/epoch/{epoch}"))
}

fn receipt_id(receipt: &Value) -> String {
    if let Some(body) = receipt_body(receipt) {
        if let (Some(session_id), Some(seq)) = (
            body.get("session_id").and_then(Value::as_str),
            body.get("seq").and_then(Value::as_u64),
        ) {
            return format!("{session_id}:{seq}");
        }
    }
    blake3::hash(&serde_json::to_vec(receipt).unwrap_or_else(|_| Vec::new()))
        .to_hex()
        .to_string()
}

fn epoch_receipt_message(epoch: u64, receipt_id: String, receipt: Value) -> Result<Value> {
    Ok(json!({
        "t": "epoch.receipt",
        "v": 1,
        "epoch": epoch,
        "receipt_id": receipt_id,
        "published_at_ms": unix_epoch_millis()?,
        "receipt": receipt,
    }))
}

fn epoch_receipt_from_sidechannel_event(
    event: &Value,
    epoch: u64,
    channel: &str,
) -> Option<(String, Value)> {
    if event.get("channel").and_then(Value::as_str) != Some(channel) {
        return None;
    }
    let message = event.get("message")?;
    if message.get("t").and_then(Value::as_str) != Some("epoch.receipt") {
        return None;
    }
    if message.get("epoch").and_then(Value::as_u64) != Some(epoch) {
        return None;
    }
    let receipt = message.get("receipt")?.clone();
    let receipt_id = message
        .get("receipt_id")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| receipt_id(&receipt));
    Some((receipt_id, receipt))
}

fn resolve_cli_sc_bridge(
    home: Option<&PathBuf>,
    sc_bridge_url: Option<&str>,
    sc_bridge_token: Option<&str>,
) -> Result<(String, String)> {
    let home = home.cloned().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    let url = sc_bridge_url
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .or_else(|| env::var("MAYHEM_SC_BRIDGE_URL").ok())
        .or_else(|| {
            config
                .as_ref()
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.sc_bridge_url.clone())
        })
        .unwrap_or_else(|| DEFAULT_SC_BRIDGE_URL.to_owned());
    let token = sc_bridge_token
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .or_else(|| env::var("MAYHEM_SC_BRIDGE_TOKEN").ok())
        .or_else(|| {
            config
                .as_ref()
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.sc_bridge_token.clone())
        })
        .context(
            "SC-Bridge token is required; pass --sc-bridge-token or set MAYHEM_SC_BRIDGE_TOKEN",
        )?;
    Ok((url, token))
}

fn resolve_cli_rpc_url(home: Option<&PathBuf>, rpc_url: Option<&str>) -> Result<String> {
    if let Some(rpc_url) = rpc_url {
        if !rpc_url.trim().is_empty() {
            return Ok(rpc_url.to_owned());
        }
    }
    let home = home.cloned().map(Ok).unwrap_or_else(default_home)?;
    let home = absolutize(home)?;
    let config = read_mayhem_config(&home)?;
    Ok(config
        .and_then(|config| config.network)
        .and_then(|network| network.rpc_url)
        .unwrap_or_else(|| DEFAULT_RPC_URL.to_owned()))
}

fn resolve_cli_paygate_url(config: Option<&MayhemConfig>, paygate_url: Option<&str>) -> String {
    if let Some(paygate_url) = paygate_url {
        let paygate_url = paygate_url.trim();
        if !paygate_url.is_empty() {
            return paygate_url.trim_end_matches('/').to_owned();
        }
    }
    if let Ok(paygate_url) = env::var("MAYHEM_PAYGATE_URL") {
        let paygate_url = paygate_url.trim();
        if !paygate_url.is_empty() {
            return paygate_url.trim_end_matches('/').to_owned();
        }
    }
    config
        .and_then(|config| config.network.as_ref())
        .and_then(|network| network.paygate_url.as_deref())
        .filter(|value| !value.trim().is_empty())
        .map(|value| value.trim_end_matches('/').to_owned())
        .unwrap_or_else(|| DEFAULT_PAYGATE_URL.to_owned())
}

fn resolve_cli_tnk_treasury_address(
    config: Option<&MayhemConfig>,
    treasury_address: Option<&str>,
) -> Result<String> {
    let value = treasury_address
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .or_else(|| {
            env::var("MAYHEM_TNK_TREASURY_ADDRESS")
                .ok()
                .map(|value| value.trim().to_owned())
                .filter(|value| !value.is_empty())
        })
        .or_else(|| {
            config
                .and_then(|config| config.network.as_ref())
                .and_then(|network| network.tnk_treasury_address.as_deref())
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_owned)
        })
        .context(
            "TNK treasury address required; pass --treasury-address, set MAYHEM_TNK_TREASURY_ADDRESS, or set network.tnk_treasury_address",
        )?;
    if value.split_whitespace().count() != 1 {
        bail!("TNK treasury address must not contain whitespace");
    }
    Ok(value)
}

fn resolve_tnk_msb_network(
    override_network: Option<&str>,
    treasury_address: &str,
) -> Result<String> {
    if let Some(network) = override_network
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        return match network.to_ascii_lowercase().as_str() {
            "mainnet" => Ok("mainnet".to_owned()),
            "testnet" | "testnet1" => Ok("testnet1".to_owned()),
            _ => bail!("--msb-network must be mainnet or testnet1"),
        };
    }

    if treasury_address.starts_with("testtrac1") {
        Ok("testnet1".to_owned())
    } else if treasury_address.starts_with("trac1") {
        Ok("mainnet".to_owned())
    } else {
        bail!(
            "could not infer MSB network from treasury address; pass --msb-network mainnet|testnet1"
        )
    }
}

fn msb_store_from_keypair_path(keypair_path: &Path) -> Result<(PathBuf, String)> {
    let keypair_file = keypair_path
        .file_name()
        .and_then(|value| value.to_str())
        .context("wallet keypair path has no filename")?;
    if keypair_file != "keypair.json" {
        bail!("wallet keypair path must end in db/keypair.json for MSB transfer submission");
    }
    let db_dir = keypair_path
        .parent()
        .context("wallet keypair path has no db directory")?;
    let db_name = db_dir
        .file_name()
        .and_then(|value| value.to_str())
        .context("wallet keypair db directory has no name")?;
    if db_name != "db" {
        bail!("wallet keypair path must end in db/keypair.json for MSB transfer submission");
    }
    let store_dir = db_dir
        .parent()
        .context("wallet keypair path has no store directory")?;
    let store_name = store_dir
        .file_name()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .context("wallet store directory has no name")?
        .to_owned();
    let stores_directory = store_dir
        .parent()
        .context("wallet store directory has no parent")?
        .to_path_buf();
    Ok((stores_directory, store_name))
}

async fn resolve_cli_wallet(
    home: &Path,
    config: Option<&MayhemConfig>,
    peer_store_name: &str,
    password: &str,
) -> Result<WalletInfo> {
    resolve_cli_wallet_with_keypair(home, config, None, peer_store_name, password).await
}

async fn resolve_cli_wallet_with_keypair(
    home: &Path,
    config: Option<&MayhemConfig>,
    keypair: Option<&Path>,
    peer_store_name: &str,
    password: &str,
) -> Result<WalletInfo> {
    let store_name = config
        .and_then(|config| config.identity.as_ref())
        .and_then(|identity| identity.store_name.as_deref())
        .unwrap_or(peer_store_name);
    let keypair_path = match keypair {
        Some(path) => absolutize(path.to_path_buf())?,
        None => config
            .and_then(|config| config.identity.as_ref())
            .and_then(|identity| identity.keypair_path.as_deref())
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                home.join("stores")
                    .join(store_name)
                    .join("db")
                    .join("keypair.json")
            }),
    };
    inspect_wallet(&keypair_path, password)
        .await
        .with_context(|| format!("reading wallet {}", keypair_path.display()))
}

fn pay_tnk_deposit_intent_payload(
    memo_hash: &str,
    treasury_address: &str,
    tnk_e18: u128,
    quoted_mu: u64,
    rate: &PayTnkRate,
) -> Value {
    json!({
        "op": "deposit_tnk",
        "memo_hash": memo_hash,
        "treasury_address": treasury_address,
        "tnk_e18": tnk_e18.to_string(),
        "quoted_mu": quoted_mu,
        "rate_tnk_usd_e6": rate.tnk_usd_e6,
        "rate_source": rate.source,
    })
}

fn deposit_tnk_intent_message(intent: &Value) -> String {
    format!("mayhem-deposit-tnk-intent-v1{}", stable_json_value(intent))
}

async fn resolve_tnk_rate(
    rpc: Option<&PeerRpcClient>,
    override_rate: Option<u64>,
) -> Result<PayTnkRate> {
    if let Some(tnk_usd_e6) = override_rate {
        if tnk_usd_e6 == 0 {
            bail!("--tnk-usd-e6 must be positive");
        }
        return Ok(PayTnkRate {
            tnk_usd_e6,
            source: "cli-override".to_owned(),
            ts: None,
        });
    }

    let rpc = rpc.context(
        "contract rate/latest requires peer RPC; pass --tnk-usd-e6 for offline preparation",
    )?;
    let value = read_state_value(rpc, "rate/latest").await?.context(
        "contract rate/latest not found; run mayhem admin rate-oracle or pass --tnk-usd-e6",
    )?;
    parse_tnk_rate(&value)
}

fn parse_tnk_rate(value: &Value) -> Result<PayTnkRate> {
    let tnk_usd_e6 = value
        .get("tnk_usd_e6")
        .and_then(Value::as_u64)
        .filter(|rate| *rate > 0)
        .context("rate/latest missing positive tnk_usd_e6")?;
    Ok(PayTnkRate {
        tnk_usd_e6,
        source: value
            .get("source")
            .and_then(Value::as_str)
            .unwrap_or("rate/latest")
            .to_owned(),
        ts: value.get("ts").and_then(Value::as_u64),
    })
}

fn now_unix_seconds() -> Result<u64> {
    Ok(SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system clock is before Unix epoch")?
        .as_secs())
}

fn resolve_tnk_operator_address(operator_tnk_address: Option<&str>) -> Result<String> {
    let value = operator_tnk_address
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .or_else(|| {
            env::var("MAYHEM_TNK_OPERATOR_ADDRESS")
                .ok()
                .map(|value| value.trim().to_owned())
                .filter(|value| !value.is_empty())
        })
        .context(
            "operator TNK address required; pass --operator-tnk-address or set MAYHEM_TNK_OPERATOR_ADDRESS",
        )?;
    if value.split_whitespace().count() != 1 {
        bail!("operator TNK address must not contain whitespace");
    }
    Ok(value)
}

fn validate_msb_tx_hash(value: &str) -> Result<String> {
    let value = value.trim().to_ascii_lowercase();
    if !is_hex_len(&value, 64) {
        bail!("MSB transaction hash must be 64 hex characters");
    }
    Ok(value)
}

async fn build_tnk_settlement_plan(
    rpc: &PeerRpcClient,
    epoch: u64,
    at: u64,
    network: &str,
    treasury_address: &str,
    operator_tnk_address: &str,
    msb_tx_hash: Option<&str>,
) -> Result<TnkSettlementPlan> {
    for (label, value) in [
        ("MSB network", network),
        ("treasury address", treasury_address),
        ("operator TNK address", operator_tnk_address),
    ] {
        if !is_safe_key_part(value) {
            bail!("{label} is not contract-safe");
        }
    }
    if let Some(existing) = read_state_value(rpc, &format!("settle/tnk/{epoch}")).await? {
        return Ok(TnkSettlementPlan {
            payload: existing.clone(),
            msb_outputs: Vec::new(),
            skipped_providers: Vec::new(),
            already_settled: Some(existing),
        });
    }

    let apply_state = read_state_value(rpc, "epoch/apply/state")
        .await?
        .context("epoch/apply/state not found; apply the epoch before TNK settlement")?;
    let applied_epoch = apply_state
        .get("updated_epoch")
        .and_then(Value::as_u64)
        .context("epoch/apply/state missing updated_epoch")?;
    if applied_epoch != epoch {
        bail!(
            "epoch/apply/state is at epoch {applied_epoch}, not requested settlement epoch {epoch}"
        );
    }
    let epoch_apply_hash = apply_state
        .get("last_apply_hash")
        .and_then(Value::as_str)
        .filter(|hash| is_hex_len(hash, 64))
        .context("epoch/apply/state missing 32-byte last_apply_hash")?
        .to_ascii_lowercase();

    let rate_value = read_state_value(rpc, "rate/latest")
        .await?
        .context("rate/latest not found; run the TNK rate watcher before settlement")?;
    let rate = parse_tnk_rate(&rate_value)?;
    if !matches!(rate.source.as_str(), "gate-spot" | "mexc-spot") {
        bail!(
            "rate/latest source {} is not supported for TNK settlement",
            rate.source
        );
    }
    let rate_ts = rate.ts.context(
        "rate/latest missing timestamp; settlement requires a contract oracle timestamp",
    )?;

    let params = read_tnk_settlement_params(rpc, at).await?;
    if rate_ts > at {
        bail!("rate/latest timestamp {rate_ts} is in the future relative to settlement timestamp {at}");
    }
    if at.saturating_sub(rate_ts) > params.rate_staleness_seconds {
        bail!(
            "rate/latest is stale: age {}s exceeds {}s",
            at.saturating_sub(rate_ts),
            params.rate_staleness_seconds
        );
    }

    let admin = read_state_value(rpc, "admin")
        .await?
        .and_then(|value| value.as_str().map(str::to_owned))
        .context("admin key missing; provider payout targets cannot be verified")?;
    let providers = read_prefix_entries(rpc, "prov/")
        .await?
        .into_iter()
        .filter_map(|entry| {
            let provider = entry
                .value
                .get("provider")
                .and_then(Value::as_str)?
                .to_owned();
            Some((provider, entry.value))
        })
        .collect::<BTreeMap<_, _>>();

    let mut skipped_providers = Vec::new();
    let mut outputs = Vec::new();
    let mut earnings = read_prefix_values::<LedgerEarningRecord>(rpc, "earn/tnk/").await?;
    earnings.sort_by(|left, right| left.provider.cmp(&right.provider));
    for earning in earnings {
        if earning.rail != "tnk" {
            continue;
        }
        let payable_mu = tnk_payable_earning_mu(rpc, &earning, epoch, &params).await?;
        if payable_mu == 0 {
            continue;
        }
        let Some(provider) = providers.get(&earning.provider) else {
            skipped_providers.push(json!({
                "provider": earning.provider,
                "mu": payable_mu,
                "reason": "provider record missing",
            }));
            continue;
        };
        match tnk_provider_payout_target(provider, &earning.provider, &admin) {
            Ok(to) => outputs.push(json!({
                "role": "provider",
                "provider": earning.provider,
                "to": to,
                "mu": payable_mu,
                "tnk_e18": mu_to_tnk_e18_ceil_u128(payable_mu, rate.tnk_usd_e6)?.to_string(),
            })),
            Err(error) => skipped_providers.push(json!({
                "provider": earning.provider,
                "mu": payable_mu,
                "reason": error.to_string(),
            })),
        }
    }

    let fee = read_tnk_fee_record(rpc).await?;
    let operator_fee_mu = fee
        .cum_mu
        .checked_sub(fee.swept_cum_mu)
        .context("fee/tnk/cum swept amount exceeds cumulative fee")?;
    if operator_fee_mu > 0 {
        outputs.push(json!({
            "role": "operator_fee",
            "to": operator_tnk_address,
            "mu": operator_fee_mu,
            "tnk_e18": mu_to_tnk_e18_ceil_u128(operator_fee_mu, rate.tnk_usd_e6)?.to_string(),
        }));
    }
    if outputs.is_empty() {
        bail!(
            "TNK settlement has no positive provider or operator fee outputs; nothing to broadcast"
        );
    }

    let totals = tnk_settlement_output_totals(&outputs)?;
    let transfer_root = stable_value_hash(&json!({
        "domain": "mayhem-tnk-settlement-transfer-root-v1",
        "value": outputs,
    }));
    let payload = json!({
        "op": "tnk_settlement",
        "epoch": epoch,
        "at": at,
        "rail": "tnk",
        "network": network,
        "treasury_from": treasury_address,
        "operator_to": operator_tnk_address,
        "epoch_apply_hash": epoch_apply_hash,
        "rate_tnk_usd_e6": rate.tnk_usd_e6,
        "rate_source": rate.source,
        "rate_ts": rate_ts,
        "msb_tx_hash": msb_tx_hash,
        "transfer_root": transfer_root,
        "provider_count": totals.provider_count,
        "provider_mu": totals.provider_mu,
        "operator_fee_mu": totals.operator_fee_mu,
        "gross_mu": totals.gross_mu,
        "tnk_e18": totals.tnk_e18,
        "outputs": outputs,
    });
    let msb_outputs = payload["outputs"]
        .as_array()
        .expect("outputs constructed as array")
        .iter()
        .map(|output| {
            let tnk_e18 = output
                .get("tnk_e18")
                .and_then(Value::as_str)
                .context("settlement output missing tnk_e18")?
                .parse::<u128>()
                .context("parsing settlement tnk_e18")?;
            Ok(MsbBatchTransferOutputEntry {
                to: output
                    .get("to")
                    .and_then(Value::as_str)
                    .context("settlement output missing recipient")?
                    .to_owned(),
                amount: tnk_e18_to_decimal(tnk_e18),
            })
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(TnkSettlementPlan {
        payload,
        msb_outputs,
        skipped_providers,
        already_settled: None,
    })
}

#[derive(Debug)]
struct TnkSettlementTotals {
    provider_count: u64,
    provider_mu: u64,
    operator_fee_mu: u64,
    gross_mu: u64,
    tnk_e18: String,
}

fn tnk_settlement_output_totals(outputs: &[Value]) -> Result<TnkSettlementTotals> {
    let mut provider_count = 0_u64;
    let mut provider_mu = 0_u64;
    let mut operator_fee_mu = 0_u64;
    let mut tnk_e18 = 0_u128;
    for output in outputs {
        let role = output
            .get("role")
            .and_then(Value::as_str)
            .context("TNK settlement output missing role")?;
        let mu = output
            .get("mu")
            .and_then(Value::as_u64)
            .context("TNK settlement output missing mu")?;
        let amount = output
            .get("tnk_e18")
            .and_then(Value::as_str)
            .context("TNK settlement output missing tnk_e18")?
            .parse::<u128>()
            .context("parsing TNK settlement tnk_e18")?;
        tnk_e18 = tnk_e18
            .checked_add(amount)
            .context("TNK settlement amount overflow")?;
        match role {
            "provider" => {
                provider_count = provider_count
                    .checked_add(1)
                    .context("TNK settlement provider count overflow")?;
                provider_mu = provider_mu
                    .checked_add(mu)
                    .context("TNK settlement provider amount overflow")?;
            }
            "operator_fee" => {
                operator_fee_mu = operator_fee_mu
                    .checked_add(mu)
                    .context("TNK settlement operator amount overflow")?;
            }
            _ => bail!("invalid TNK settlement output role {role}"),
        }
    }
    let gross_mu = provider_mu
        .checked_add(operator_fee_mu)
        .context("TNK settlement gross amount overflow")?;
    Ok(TnkSettlementTotals {
        provider_count,
        provider_mu,
        operator_fee_mu,
        gross_mu,
        tnk_e18: tnk_e18.to_string(),
    })
}

async fn read_tnk_settlement_params(rpc: &PeerRpcClient, at: u64) -> Result<TnkSettlementParams> {
    Ok(TnkSettlementParams {
        holdback_epochs: read_param_u64_at(rpc, "holdback_epochs", DEFAULT_HOLDBACK_EPOCHS, at)
            .await?,
        challenge_epochs: read_param_u64_at(rpc, "challenge_epochs", DEFAULT_CHALLENGE_EPOCHS, at)
            .await?,
        canary_probe_holdback_bps: read_param_u64_at(
            rpc,
            "canary_probe_holdback_bps",
            DEFAULT_CANARY_PROBE_HOLDBACK_BPS,
            at,
        )
        .await?,
        canary_probe_release_min_passes: read_param_u64_at(
            rpc,
            "canary_probe_release_min_passes",
            DEFAULT_CANARY_PROBE_RELEASE_MIN_PASSES,
            at,
        )
        .await?,
        rate_staleness_seconds: read_param_u64_at(
            rpc,
            "rate_staleness_seconds",
            DEFAULT_RATE_STALENESS_SECONDS,
            at,
        )
        .await?,
    })
}

async fn read_param_u64_at(rpc: &PeerRpcClient, key: &str, default: u64, at: u64) -> Result<u64> {
    let Some(record) = read_state_value(rpc, &format!("params/{key}")).await? else {
        return Ok(default);
    };
    let active = match record.get("pending") {
        Some(pending)
            if !pending.is_null()
                && pending
                    .get("effective_at")
                    .and_then(Value::as_u64)
                    .is_some_and(|effective_at| effective_at <= at) =>
        {
            pending
        }
        _ => record
            .get("current")
            .context("parameter record missing current entry")?,
    };
    active
        .get("value")
        .and_then(Value::as_u64)
        .with_context(|| format!("params/{key} active value is not a u64"))
}

async fn read_tnk_fee_record(rpc: &PeerRpcClient) -> Result<LedgerFeeRecord> {
    match read_state_value(rpc, "fee/tnk/cum").await? {
        Some(value) => serde_json::from_value(value).context("parsing fee/tnk/cum contract state"),
        None => Ok(LedgerFeeRecord {
            rail: "tnk".to_owned(),
            denom: "mu_usd".to_owned(),
            cum_mu: 0,
            swept_cum_mu: 0,
            updated_epoch: 0,
            updated_at: None,
            last_apply_hash: None,
            last_fee_bps: None,
            last_settlement_epoch: None,
            last_settlement_msb_tx_hash: None,
        }),
    }
}

async fn tnk_payable_earning_mu(
    rpc: &PeerRpcClient,
    earning: &LedgerEarningRecord,
    epoch: u64,
    params: &TnkSettlementParams,
) -> Result<u64> {
    let locked_epochs = params.holdback_epochs.max(params.challenge_epochs);
    let kept = refresh_tnk_holdbacks(rpc, earning, epoch, locked_epochs, params).await?;
    let held_mu = kept
        .iter()
        .try_fold(0_u64, |sum, bucket| sum.checked_add(bucket.mu))
        .context("TNK held amount overflow")?;
    let released_mu = earning
        .total_mu
        .checked_sub(held_mu)
        .context("TNK held amount exceeds total earnings")?;
    released_mu
        .checked_sub(earning.paid_cum_mu)
        .context("TNK paid amount exceeds released earnings")
}

async fn refresh_tnk_holdbacks(
    rpc: &PeerRpcClient,
    earning: &LedgerEarningRecord,
    current_epoch: u64,
    locked_epochs: u64,
    params: &TnkSettlementParams,
) -> Result<Vec<LedgerHoldbackBucket>> {
    let holdbacks = normalize_tnk_holdbacks(earning)?;
    let probe_gate_enabled =
        params.canary_probe_holdback_bps > 0 && params.canary_probe_release_min_passes > 0;
    let mut kept = Vec::new();
    for bucket in holdbacks {
        if bucket.epoch.saturating_add(locked_epochs) > current_epoch {
            kept.push(bucket);
            continue;
        }
        if !probe_gate_enabled {
            continue;
        }
        if tnk_probe_passed(
            rpc,
            &earning.provider,
            bucket.epoch,
            params.canary_probe_release_min_passes,
        )
        .await?
        {
            continue;
        }
        if bucket.probe_gate {
            kept.push(bucket);
            continue;
        }
        let gated_mu =
            (u128::from(bucket.mu) * u128::from(params.canary_probe_holdback_bps) / 10_000) as u64;
        if gated_mu > 0 {
            kept.push(LedgerHoldbackBucket {
                epoch: bucket.epoch,
                mu: gated_mu,
                probe_gate: true,
            });
        }
    }
    Ok(kept)
}

async fn tnk_probe_passed(
    rpc: &PeerRpcClient,
    provider: &str,
    epoch: u64,
    required_passes: u64,
) -> Result<bool> {
    let Some(record) = read_state_value(rpc, &format!("probe/pass/{provider}/{epoch}")).await?
    else {
        return Ok(false);
    };
    Ok(record
        .get("pass_count")
        .and_then(Value::as_u64)
        .unwrap_or(0)
        >= required_passes)
}

fn normalize_tnk_holdbacks(earning: &LedgerEarningRecord) -> Result<Vec<LedgerHoldbackBucket>> {
    if earning.holdbacks.is_empty() {
        if earning.held_mu == 0 {
            return Ok(Vec::new());
        }
        return Ok(vec![LedgerHoldbackBucket {
            epoch: earning.updated_epoch,
            mu: earning.held_mu,
            probe_gate: false,
        }]);
    }
    let mut by_bucket = BTreeMap::<(u64, bool), u64>::new();
    for bucket in &earning.holdbacks {
        if bucket.mu == 0 {
            bail!("TNK holdback bucket amount must be positive");
        }
        let key = (bucket.epoch, bucket.probe_gate);
        let next = by_bucket
            .get(&key)
            .copied()
            .unwrap_or(0)
            .checked_add(bucket.mu)
            .context("TNK holdback bucket overflow")?;
        by_bucket.insert(key, next);
    }
    Ok(by_bucket
        .into_iter()
        .map(|((epoch, probe_gate), mu)| LedgerHoldbackBucket {
            epoch,
            mu,
            probe_gate,
        })
        .collect())
}

fn tnk_provider_payout_target(provider: &Value, provider_id: &str, admin: &str) -> Result<String> {
    if provider.get("status").and_then(Value::as_str) != Some("active") {
        bail!("provider is not active");
    }
    let payout = provider
        .get("payout")
        .and_then(Value::as_object)
        .context("provider payout target is not set")?;
    if payout.get("method").and_then(Value::as_str) != Some("tnk") {
        bail!("provider payout target is not TNK");
    }
    if payout.get("set_by").and_then(Value::as_str) != Some(admin) {
        bail!("provider payout target was not set by the current admin");
    }
    if payout.get("set_by_role").and_then(Value::as_str) != Some("admin") {
        bail!("provider payout target must be admin-set");
    }
    let addr = payout
        .get("addr")
        .and_then(Value::as_str)
        .context("provider payout target missing address")?;
    if !is_safe_key_part(addr) {
        bail!("provider payout target address is not contract-safe");
    }
    if provider
        .get("provider")
        .and_then(Value::as_str)
        .is_some_and(|actual| actual != provider_id)
    {
        bail!("provider payout record owner mismatch");
    }
    Ok(addr.to_owned())
}

fn resolve_tnk_nonce(
    wallet_pubkey: &str,
    amount_mu: u64,
    treasury_address: &str,
    rate: &PayTnkRate,
    args: &PayTnkArgs,
) -> Result<String> {
    if let Some(nonce) = args.nonce.as_deref() {
        if !is_hex_len(nonce, 64) {
            bail!("--nonce must be a 32-byte hex string");
        }
        return Ok(nonce.to_ascii_lowercase());
    }
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system clock is before Unix epoch")?
        .as_nanos();
    Ok(blake3::hash(
        format!(
            "mayhem:tnk-deposit-nonce:v1:{wallet_pubkey}:{amount_mu}:{treasury_address}:{}:{now}:{}",
            rate.tnk_usd_e6,
            std::process::id()
        )
        .as_bytes(),
    )
    .to_hex()
    .to_string())
}

fn derive_tnk_memo_hash(wallet_pubkey: &str, nonce: &str) -> Result<String> {
    let pubkey = hex_decode_array::<32>(wallet_pubkey, "wallet public key")?;
    let nonce = hex_decode_array::<32>(nonce, "TNK deposit nonce")?;
    let mut hasher = blake3::Hasher::new();
    hasher.update(&pubkey);
    hasher.update(&nonce);
    Ok(hasher.finalize().to_hex().to_string())
}

fn mu_to_tnk_e18_ceil_u128(mu: u64, rate_tnk_usd_e6: u64) -> Result<u128> {
    if rate_tnk_usd_e6 == 0 {
        bail!("rate_tnk_usd_e6 must be positive");
    }
    let numerator = u128::from(mu)
        .checked_mul(TNK_E18)
        .context("TNK conversion overflow")?;
    Ok(numerator.div_ceil(u128::from(rate_tnk_usd_e6)))
}

fn tnk_e18_to_mu_floor(tnk_e18: u128, rate_tnk_usd_e6: u64) -> Result<u64> {
    let mu = tnk_e18
        .checked_mul(u128::from(rate_tnk_usd_e6))
        .context("TNK credit conversion overflow")?
        / TNK_E18;
    u64::try_from(mu).context("TNK credit conversion overflowed u64")
}

fn tnk_e18_to_decimal(tnk_e18: u128) -> String {
    let whole = tnk_e18 / TNK_E18;
    let fraction = tnk_e18 % TNK_E18;
    if fraction == 0 {
        return whole.to_string();
    }
    let mut fraction = format!("{fraction:018}");
    while fraction.ends_with('0') {
        fraction.pop();
    }
    format!("{whole}.{fraction}")
}

fn pay_tnk_deposit_intent_command(
    amount: &str,
    treasury_address: &str,
    nonce: &str,
    tnk_usd_e6: u64,
    rpc_url: Option<&str>,
) -> String {
    let mut command = format!(
        "mayhem pay tnk --amount {} --treasury-address {} --nonce {} --tnk-usd-e6 {} --submit-intent",
        shell_single_quote(amount),
        shell_single_quote(treasury_address),
        shell_single_quote(nonce),
        tnk_usd_e6
    );
    if let Some(rpc_url) = rpc_url.filter(|value| !value.trim().is_empty()) {
        command.push_str(" --rpc-url ");
        command.push_str(&shell_single_quote(rpc_url));
    }
    command
}

fn emit_tnk_handoff(
    json_output: bool,
    amount_mu: u64,
    msb_transfer_command: &str,
    memo_hash: &str,
    deposit_intent_command: &str,
) -> Result<()> {
    let lines = [
        format!("Mayhem tnk deposit for {}", mu_to_usd_amount(amount_mu)),
        format!("Copy/paste deposit intent command: {deposit_intent_command}"),
        format!("Copy/paste MSB transfer command: {msb_transfer_command}"),
        format!("Copy/paste transfer memo/reference: {memo_hash}"),
    ];
    if json_output {
        let mut stderr = io::stderr().lock();
        for line in lines {
            writeln!(stderr, "{line}")?;
        }
        stderr.flush()?;
    } else {
        let mut stdout = io::stdout().lock();
        for line in lines {
            writeln!(stdout, "{line}")?;
        }
        stdout.flush()?;
    }
    Ok(())
}

async fn submit_msb_transfer(
    network: &str,
    stores_directory: &Path,
    store_name: &str,
    to: &str,
    amount: &str,
    timeout_seconds: u64,
) -> Result<MsbTransferOutput> {
    run_msb_transfer_helper(vec![
        "transfer".to_owned(),
        "--network".to_owned(),
        network.to_owned(),
        "--stores-directory".to_owned(),
        stores_directory.display().to_string(),
        "--store-name".to_owned(),
        store_name.to_owned(),
        "--to".to_owned(),
        to.to_owned(),
        "--amount".to_owned(),
        amount.to_owned(),
        "--timeout-seconds".to_owned(),
        timeout_seconds.to_string(),
    ])
    .await
}

async fn submit_msb_batch_transfer(
    network: &str,
    stores_directory: &Path,
    store_name: &str,
    outputs: &[MsbBatchTransferOutputEntry],
    timeout_seconds: u64,
    max_retries: u64,
    expected_balance_before: Option<&str>,
) -> Result<MsbBatchTransferOutput> {
    let mut args = vec![
        "batch-transfer".to_owned(),
        "--network".to_owned(),
        network.to_owned(),
        "--stores-directory".to_owned(),
        stores_directory.display().to_string(),
        "--store-name".to_owned(),
        store_name.to_owned(),
        "--outputs-json".to_owned(),
        serde_json::to_string(outputs)?,
        "--timeout-seconds".to_owned(),
        timeout_seconds.to_string(),
        "--max-retries".to_owned(),
        max_retries.to_string(),
    ];
    if let Some(balance) = expected_balance_before {
        args.extend([
            "--expected-balance-before".to_owned(),
            balance.trim().to_owned(),
        ]);
    }
    run_msb_transfer_helper(args).await
}

async fn run_msb_transfer_helper<T>(args: Vec<String>) -> Result<T>
where
    T: DeserializeOwned,
{
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let repo_root = manifest_dir
        .parent()
        .and_then(Path::parent)
        .context("resolving repository root for MSB transfer helper")?;
    let msb_app = repo_root.join("intercom/trac/msb");
    let pear = env::var_os("MAYHEM_PEAR_BIN").unwrap_or_else(|| "pear".into());
    let mut helper_args = vec!["--transfer-helper".to_owned()];
    helper_args.extend(args);
    let output = Command::new(&pear)
        .arg("run")
        .arg("--no-ask")
        .arg(&msb_app)
        .args(helper_args)
        .output()
        .await
        .with_context(|| {
            format!(
                "running MSB transfer helper via Pear app {}",
                msb_app.display()
            )
        })?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let stdout = String::from_utf8_lossy(&output.stdout);
        bail!(
            "MSB transfer helper failed via Pear: {}{}{}",
            stderr.trim(),
            if stderr.trim().is_empty() || stdout.trim().is_empty() {
                ""
            } else {
                "; stdout: "
            },
            stdout.trim()
        );
    }
    serde_json::from_slice(&output.stdout).context("parsing Pear MSB transfer helper JSON output")
}

#[derive(Debug)]
struct PayCheckout {
    id: String,
    url: String,
    reference: Option<String>,
}

#[derive(Debug)]
struct PayCreditStatus {
    credited: bool,
    before_mu: u64,
    current_mu: u64,
    target_mu: u64,
    waited_ms: u64,
}

struct PayCheckoutRequest<'a> {
    rail: PayRail,
    paygate_url: &'a str,
    who: &'a str,
    amount_mu: u64,
    currency: &'a str,
    locale: &'a str,
    idempotency_key: Option<&'a str>,
    success_url: Option<&'a str>,
    cancel_url: Option<&'a str>,
}

#[cfg(test)]
fn checkout_handoff_lines(rail: PayRail, amount_mu: u64, url: &str) -> [String; 2] {
    checkout_handoff_lines_with_currency(rail, amount_mu, "usd", url)
}

fn checkout_handoff_lines_with_currency(
    rail: PayRail,
    amount_mu: u64,
    currency: &str,
    url: &str,
) -> [String; 2] {
    [
        format!(
            "Mayhem {} checkout for {} {}",
            rail.as_str(),
            mu_to_usd_amount(amount_mu),
            currency.to_ascii_uppercase()
        ),
        format!("Copy/paste checkout URL: {url}"),
    ]
}

fn checkout_copy_paste_value(url: &str) -> Value {
    json!({
        "checkout_url": url,
    })
}

fn emit_checkout_handoff(
    json_output: bool,
    rail: PayRail,
    amount_mu: u64,
    currency: &str,
    url: &str,
) -> Result<()> {
    let lines = checkout_handoff_lines_with_currency(rail, amount_mu, currency, url);
    if json_output {
        let mut stderr = io::stderr().lock();
        for line in lines {
            writeln!(stderr, "{line}")?;
        }
        stderr.flush()?;
    } else {
        let mut stdout = io::stdout().lock();
        for line in lines {
            writeln!(stdout, "{line}")?;
        }
        stdout.flush()?;
    }
    Ok(())
}

async fn create_pay_checkout(request: PayCheckoutRequest<'_>) -> Result<PayCheckout> {
    let client = reqwest::Client::new();
    let endpoint = "v1/stripe/checkout-sessions";
    let success_url = request
        .success_url
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| default_checkout_success_url(request.paygate_url, request.rail));
    let cancel_url = request
        .cancel_url
        .filter(|value| !value.trim().is_empty())
        .map(str::to_owned)
        .unwrap_or_else(|| default_checkout_cancel_url(request.paygate_url, request.rail));
    let mut body = json!({
        "who": request.who,
        "mu": request.amount_mu,
    });
    body["success_url"] = Value::String(success_url);
    body["cancel_url"] = Value::String(cancel_url);
    body["currency"] = Value::String(request.currency.to_ascii_lowercase());
    body["locale"] = Value::String(request.locale.to_ascii_lowercase());
    if let Some(idempotency_key) = request.idempotency_key.filter(|value| !value.is_empty()) {
        body["idempotency_key"] = Value::String(idempotency_key.to_owned());
    }

    let response = client
        .post(format!(
            "{}/{}",
            request.paygate_url.trim_end_matches('/'),
            endpoint
        ))
        .json(&body)
        .send()
        .await?;
    let status = response.status();
    let response_body = response.text().await?;
    if !status.is_success() {
        bail!("paygate returned {status}: {response_body}");
    }
    let value: Value = serde_json::from_str(&response_body)?;
    checkout_from_paygate_response(request.rail, &value)
}

fn checkout_from_paygate_response(rail: PayRail, value: &Value) -> Result<PayCheckout> {
    match rail {
        PayRail::Stripe => {
            let response_rail = required_json_string(value, "rail")?;
            if response_rail != "fiat" {
                bail!("paygate response rail must be fiat for Stripe checkout");
            }
            let processor_rail = required_json_string(value, "processor_rail")?;
            if processor_rail != "stripe" {
                bail!("paygate response processor_rail must be stripe for Stripe checkout");
            }
            let session = value
                .get("checkout_session")
                .ok_or_else(|| anyhow::anyhow!("paygate response missing checkout_session"))?;
            Ok(PayCheckout {
                id: required_json_string(session, "id")?,
                url: {
                    let url = required_hosted_checkout_url(session, "url", "checkout.stripe.com")?;
                    validate_response_copy_paste_url(value, &url)?;
                    url
                },
                reference: session
                    .get("payment_intent")
                    .and_then(Value::as_str)
                    .map(str::to_owned),
            })
        }
    }
}

fn required_json_string(value: &Value, field: &str) -> Result<String> {
    value
        .get(field)
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .ok_or_else(|| anyhow::anyhow!("paygate response missing {field}"))
}

fn required_hosted_checkout_url(value: &Value, field: &str, expected_host: &str) -> Result<String> {
    let url = required_json_string(value, field)?;
    let parsed = reqwest::Url::parse(&url)
        .with_context(|| format!("paygate response {field} is not a valid URL"))?;
    if parsed.scheme() != "https" || parsed.host_str() != Some(expected_host) {
        bail!("paygate response {field} must be an HTTPS URL on {expected_host}");
    }
    Ok(url)
}

fn validate_response_copy_paste_url(value: &Value, url: &str) -> Result<()> {
    if let Some(copy_paste_url) = value
        .get("copy_paste")
        .and_then(|copy_paste| copy_paste.get("checkout_url"))
        .and_then(Value::as_str)
    {
        if copy_paste_url != url {
            bail!("paygate response copy_paste.checkout_url does not match hosted checkout URL");
        }
    }
    Ok(())
}

fn default_checkout_success_url(paygate_url: &str, rail: PayRail) -> String {
    let base = paygate_url.trim_end_matches('/');
    match rail {
        PayRail::Stripe => {
            format!("{base}/v1/stripe/return?session_id={{CHECKOUT_SESSION_ID}}")
        }
    }
}

fn default_checkout_cancel_url(paygate_url: &str, rail: PayRail) -> String {
    let base = paygate_url.trim_end_matches('/');
    match rail {
        PayRail::Stripe => format!("{base}/v1/stripe/cancel"),
    }
}

async fn open_checkout_url(url: &str, disabled: bool) -> bool {
    if disabled {
        return false;
    }
    let mut command = if cfg!(target_os = "macos") {
        let mut command = Command::new("open");
        command.arg(url);
        command
    } else if cfg!(target_os = "windows") {
        let mut command = Command::new("cmd");
        command.args(["/C", "start", "", url]);
        command
    } else {
        let mut command = Command::new("xdg-open");
        command.arg(url);
        command
    };
    command.status().await.is_ok_and(|status| status.success())
}

async fn wait_for_credit(
    rpc: &PeerRpcClient,
    who: &str,
    rail: &str,
    before_mu: u64,
    target_mu: u64,
    timeout: Duration,
    interval: Duration,
) -> Result<PayCreditStatus> {
    let started = Instant::now();
    loop {
        let current_mu = read_user_balance_mu(rpc, who, rail).await?;
        if current_mu >= target_mu {
            return Ok(PayCreditStatus {
                credited: true,
                before_mu,
                current_mu,
                target_mu,
                waited_ms: millis_since(started),
            });
        }
        if started.elapsed() >= timeout {
            return Ok(PayCreditStatus {
                credited: false,
                before_mu,
                current_mu,
                target_mu,
                waited_ms: millis_since(started),
            });
        }
        sleep(interval).await;
    }
}

fn millis_since(started: Instant) -> u64 {
    u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX)
}

async fn read_user_balance_mu(rpc: &PeerRpcClient, who: &str, rail: &str) -> Result<u64> {
    read_balance_record(rpc, who, rail)
        .await?
        .get("mu")
        .and_then(Value::as_u64)
        .ok_or_else(|| anyhow::anyhow!("normalized {rail} balance record for {who} is missing mu"))
}

async fn read_balance_record(rpc: &PeerRpcClient, who: &str, rail: &str) -> Result<Value> {
    let value = read_state_value(rpc, &format!("bal/{who}/{rail}")).await?;
    normalize_balance_record(who, rail, value)
}

fn normalize_balance_record(who: &str, rail: &str, value: Option<Value>) -> Result<Value> {
    let mut record = value.unwrap_or_else(|| {
        json!({
            "user": who,
            "rail": rail,
            "denom": "mu_usd",
            "mu": 0,
            "updated_epoch": 0,
            "updated_at": null,
        })
    });
    let object = record
        .as_object_mut()
        .context("balance record must be a JSON object")?;
    match object.get("denom").and_then(Value::as_str) {
        Some("mu_usd") | None => {
            object
                .entry("denom")
                .or_insert_with(|| Value::String("mu_usd".to_owned()));
        }
        Some(denom) => bail!("balance record for {who} has unsupported denomination {denom}"),
    }
    match object.get("user").and_then(Value::as_str) {
        Some(user) if user == who => {}
        Some(user) => bail!("balance record user mismatch: expected {who}, got {user}"),
        None => {
            object.insert("user".to_owned(), Value::String(who.to_owned()));
        }
    }
    match object.get("rail").and_then(Value::as_str) {
        Some(value) if value == rail => {}
        Some(value) => bail!("balance record rail mismatch: expected {rail}, got {value}"),
        None => {
            object.insert("rail".to_owned(), Value::String(rail.to_owned()));
        }
    }
    if object.get("mu").and_then(Value::as_u64).is_none() {
        bail!("balance record for {who} is missing non-negative integer mu");
    }
    object
        .entry("updated_epoch")
        .or_insert_with(|| Value::Number(0_u64.into()));
    object.entry("updated_at").or_insert(Value::Null);
    Ok(record)
}

fn parse_usd_amount_to_mu(amount: &str) -> Result<u64> {
    let amount = amount.trim();
    if amount.is_empty() {
        bail!("--amount must be positive");
    }
    if amount.starts_with('-') || amount.starts_with('+') {
        bail!("--amount must be positive USD");
    }
    let (dollars, cents) = match amount.split_once('.') {
        Some((dollars, cents)) => {
            if cents.is_empty() || cents.len() > 2 {
                bail!("--amount supports at most two decimal places");
            }
            (dollars, cents)
        }
        None => (amount, ""),
    };
    if dollars.is_empty()
        || !dollars.as_bytes().iter().all(u8::is_ascii_digit)
        || !cents.as_bytes().iter().all(u8::is_ascii_digit)
    {
        bail!("--amount must be a USD decimal, for example 10 or 10.25");
    }
    let dollars = dollars.parse::<u64>()?;
    let cents = match cents.len() {
        0 => 0,
        1 => cents.parse::<u64>()? * 10,
        2 => cents.parse::<u64>()?,
        _ => unreachable!("length checked above"),
    };
    let total_cents = dollars
        .checked_mul(100)
        .and_then(|value| value.checked_add(cents))
        .context("--amount overflowed")?;
    if total_cents == 0 {
        bail!("--amount must be positive");
    }
    total_cents
        .checked_mul(10_000)
        .context("--amount overflowed mu_usd")
}

fn mu_to_usd_amount(mu: u64) -> String {
    let cents = mu / 10_000;
    format!("{}.{:02}", cents / 100, cents % 100)
}

fn earning_view(record: LedgerEarningRecord) -> Result<EarningsView> {
    let locked = record
        .held_mu
        .checked_add(record.paid_cum_mu)
        .context("earning held_mu + paid_cum_mu overflowed")?;
    if record.total_mu < locked {
        bail!(
            "earning record for {} violates total >= held + paid",
            record.provider
        );
    }
    Ok(EarningsView {
        provider: record.provider,
        rail: record.rail,
        denom: record.denom,
        total_mu: record.total_mu,
        held_mu: record.held_mu,
        paid_cum_mu: record.paid_cum_mu,
        released_mu: record.total_mu - locked,
        claimable_mu: record.total_mu - locked,
        claim_model: "tap_non_custodial_claim".to_owned(),
        holdbacks: record.holdbacks,
        updated_epoch: record.updated_epoch,
        last_payout_msb_tx_hash: record.last_payout_msb_tx_hash,
    })
}

fn print_payouts_report(report: &Value) {
    if let Some(epoch) = report.get("epoch").and_then(Value::as_u64) {
        println!("Provider payouts for epoch {epoch}: non-custodial TAP claims from earning roots");
        print_optional_evidence("fee", report.get("fee"));
        return;
    }
    println!("Provider payouts: non-custodial TAP claims from earning roots");
    for entry in report
        .get("fee_sweeps")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        let key = entry.get("key").and_then(Value::as_str).unwrap_or("");
        let value = entry.get("value").unwrap_or(&Value::Null);
        println!(
            "{key}: fee sweep mu={} msb_tx={}",
            value.get("sweep_mu").and_then(Value::as_u64).unwrap_or(0),
            value
                .get("sweep_msb_tx_hash")
                .and_then(Value::as_str)
                .unwrap_or("")
        );
    }
}

fn print_optional_evidence(label: &str, value: Option<&Value>) {
    match value {
        Some(Value::Null) | None => println!("{label}: missing"),
        Some(value) => println!(
            "{label}: {}",
            serde_json::to_string(value).unwrap_or_default()
        ),
    }
}

fn print_earnings_report(report: &Value) {
    println!("Provider earnings");
    for entry in report
        .get("earnings")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        println!(
            "{}/{}: total={} held={} paid={} released={} claimable={} {}",
            entry.get("rail").and_then(Value::as_str).unwrap_or("fiat"),
            entry.get("provider").and_then(Value::as_str).unwrap_or(""),
            entry.get("total_mu").and_then(Value::as_u64).unwrap_or(0),
            entry.get("held_mu").and_then(Value::as_u64).unwrap_or(0),
            entry
                .get("paid_cum_mu")
                .and_then(Value::as_u64)
                .unwrap_or(0),
            entry
                .get("released_mu")
                .and_then(Value::as_u64)
                .unwrap_or(0),
            entry
                .get("claimable_mu")
                .and_then(Value::as_u64)
                .unwrap_or(0),
            entry
                .get("denom")
                .and_then(Value::as_str)
                .unwrap_or("mu_usd")
        );
    }
}

async fn read_receipts_for_export(args: &ReceiptsExportArgs) -> Result<Vec<Value>> {
    if let Some(path) = args.receipts_file.as_deref() {
        return read_json_array(path, "receipts");
    }
    let base = args
        .gateway_url
        .as_deref()
        .unwrap_or(DEFAULT_GATEWAY_URL)
        .trim_end_matches('/');
    fetch_gateway_receipts(base).await
}

async fn fetch_gateway_receipts(gateway_url: &str) -> Result<Vec<Value>> {
    let url = format!("{}/mayhem/receipts", gateway_url.trim_end_matches('/'));
    let response: Value = reqwest::get(&url)
        .await
        .with_context(|| format!("fetching {url}"))?
        .error_for_status()
        .with_context(|| format!("gateway returned an error for {url}"))?
        .json()
        .await
        .with_context(|| format!("parsing {url} response"))?;
    response
        .get("data")
        .and_then(Value::as_array)
        .cloned()
        .context("gateway /mayhem/receipts response did not include data[]")
}

fn read_optional_json_array(path: Option<&Path>, label: &str) -> Result<Vec<Value>> {
    match path {
        Some(path) => read_json_array(path, label),
        None => Ok(Vec::new()),
    }
}

fn read_json_array(path: &Path, label: &str) -> Result<Vec<Value>> {
    let value = read_json_file(path)?;
    if let Some(array) = value.as_array() {
        return Ok(array.clone());
    }
    if let Some(array) = value.get("data").and_then(Value::as_array) {
        return Ok(array.clone());
    }
    bail!(
        "{label} file {} must be a JSON array or object with data[]",
        path.display()
    );
}

fn read_prior_earnings(path: Option<&Path>) -> Result<BTreeMap<String, u64>> {
    let Some(path) = path else {
        return Ok(BTreeMap::new());
    };
    let value = read_json_file(path)?;
    let object = value
        .as_object()
        .with_context(|| format!("{} must contain a JSON object", path.display()))?;
    let mut out = BTreeMap::new();
    for (key, value) in object {
        let mu = value
            .as_u64()
            .or_else(|| value.get("total_mu").and_then(Value::as_u64))
            .with_context(|| format!("prior earning for {key} must be a u64 or record.total_mu"))?;
        let rail_key = match (
            value.get("rail").and_then(Value::as_str),
            value.get("provider").and_then(Value::as_str),
        ) {
            (Some(rail), Some(provider)) => format!("{rail}/{provider}"),
            _ => key.clone(),
        };
        out.insert(rail_key, mu);
    }
    Ok(out)
}

async fn read_evidence_for_export(args: &ReceiptsExportArgs) -> Result<EpochEvidenceSnapshot> {
    if let Some(path) = args.evidence_file.as_deref() {
        return read_evidence_file(path, args.epoch);
    }
    let rpc_url = resolve_cli_rpc_url(args.home.as_ref(), args.rpc_url.as_deref())?;
    let rpc = PeerRpcClient::new(&rpc_url)?;
    Ok(EpochEvidenceSnapshot {
        dep: read_state_value(&rpc, &format!("ev/dep/{}", args.epoch)).await?,
        r#use: read_state_value(&rpc, &format!("ev/use/{}", args.epoch)).await?,
        earn: read_state_value(&rpc, &format!("ev/earn/{}", args.epoch)).await?,
        fee: read_state_value(&rpc, &format!("ev/fee/{}", args.epoch)).await?,
    })
}

fn read_evidence_file(path: &Path, epoch: u64) -> Result<EpochEvidenceSnapshot> {
    let value = read_json_file(path)?;
    Ok(EpochEvidenceSnapshot {
        dep: evidence_record(&value, epoch, "dep"),
        r#use: evidence_record(&value, epoch, "use"),
        earn: evidence_record(&value, epoch, "earn"),
        fee: evidence_record(&value, epoch, "fee"),
    })
}

fn evidence_record(value: &Value, epoch: u64, kind: &str) -> Option<Value> {
    value
        .get(kind)
        .cloned()
        .or_else(|| value.get(format!("ev/{kind}/{epoch}")).cloned())
}

fn read_json_file(path: &Path) -> Result<Value> {
    let bytes = fs::read(path).with_context(|| format!("reading {}", path.display()))?;
    serde_json::from_slice(&bytes).with_context(|| format!("parsing {}", path.display()))
}

fn write_json_file(path: &Path, value: &impl Serialize) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    fs::write(path, serde_json::to_vec_pretty(value)?)
        .with_context(|| format!("writing {}", path.display()))
}

fn blake3_file_hex(path: &Path) -> Result<String> {
    let bytes = fs::read(path).with_context(|| format!("reading {}", path.display()))?;
    Ok(blake3::hash(&bytes).to_hex().to_string())
}

fn blake3_bytes_hex(bytes: &[u8]) -> String {
    blake3::hash(bytes).to_hex().to_string()
}

fn required_json_string_for(value: &Value, field: &str, label: &str) -> Result<String> {
    value
        .get(field)
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .ok_or_else(|| anyhow::anyhow!("{label} missing {field}"))
}

fn validate_https_url(value: &str, label: &str) -> Result<()> {
    let parsed = reqwest::Url::parse(value).with_context(|| format!("{label} is not a URL"))?;
    if parsed.scheme() != "https" || parsed.host_str().is_none() {
        bail!("{label} must be an HTTPS URL");
    }
    Ok(())
}

fn validate_catalog_source_url(source_kind: &str, value: &str, label: &str) -> Result<()> {
    validate_https_url(value, label)?;
    match source_kind {
        "https" => Ok(()),
        "huggingface" => validate_pinned_huggingface_resolve_url(value, label),
        _ => bail!("unsupported catalog source kind: {source_kind}"),
    }
}

fn validate_pinned_huggingface_resolve_url(value: &str, label: &str) -> Result<()> {
    let parsed = reqwest::Url::parse(value).with_context(|| format!("{label} is not a URL"))?;
    if parsed.host_str() != Some("huggingface.co") {
        bail!("{label} must use huggingface.co for source_kind=huggingface");
    }
    let segments = parsed
        .path_segments()
        .map(|segments| segments.collect::<Vec<_>>())
        .unwrap_or_default();
    let Some(resolve_index) = segments.iter().position(|segment| *segment == "resolve") else {
        bail!("{label} must use a pinned Hugging Face /resolve/<40-hex-revision>/ URL");
    };
    let Some(revision) = segments.get(resolve_index + 1) else {
        bail!("{label} must include a pinned Hugging Face revision");
    };
    if !is_hex_len(revision, 40) {
        bail!("{label} must use a 40-hex Hugging Face commit revision");
    }
    if segments.get(resolve_index + 2).is_none() {
        bail!("{label} must include a file path after the Hugging Face revision");
    }
    Ok(())
}

fn catalog_release_url_join(base: &str, path: &str) -> Result<String> {
    validate_https_url(base, "catalog release base URL")?;
    let mut base = base.trim().trim_end_matches('/').to_owned();
    base.push('/');
    let joined = format!("{base}{}", path.trim_start_matches('/'));
    validate_https_url(&joined, "catalog release URL")?;
    Ok(joined)
}

fn temp_audit_bundle_path(epoch: u64) -> Result<PathBuf> {
    Ok(env::temp_dir().join(format!(
        "mayhem-receipts-export-{epoch}-{}-{}.json",
        std::process::id(),
        unix_epoch_millis()?
    )))
}

async fn run_epoch_recompute_script(script: &Path, bundle: &Path) -> Result<Value> {
    let output = Command::new("node")
        .arg(script)
        .arg(bundle)
        .output()
        .await
        .with_context(|| format!("running {}", script.display()))?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        bail!("{} failed: {}", script.display(), stderr.trim());
    }
    serde_json::from_slice(&output.stdout)
        .with_context(|| format!("parsing {} output", script.display()))
}

fn verify_epoch_evidence(
    epoch: u64,
    recomputed: &Value,
    evidence: &EpochEvidenceSnapshot,
) -> Vec<EvidenceCheck> {
    let roots = &recomputed["roots"];
    let totals = &recomputed["totals"];
    let mut checks = Vec::new();
    push_evidence_check(
        &mut checks,
        &format!("ev/dep/{epoch}.merkle_root"),
        &roots["dep"],
        evidence.dep.as_ref(),
        "merkle_root",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/dep/{epoch}.count"),
        &totals["dep_count"],
        evidence.dep.as_ref(),
        "count",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/dep/{epoch}.mu_total"),
        &totals["dep_mu"],
        evidence.dep.as_ref(),
        "mu_total",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/use/{epoch}.merkle_root"),
        &roots["use"],
        evidence.r#use.as_ref(),
        "merkle_root",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/use/{epoch}.sessions"),
        &totals["use_count"],
        evidence.r#use.as_ref(),
        "sessions",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/use/{epoch}.mu_total"),
        &totals["use_mu"],
        evidence.r#use.as_ref(),
        "mu_total",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/use/{epoch}.providers"),
        &totals["provider_count"],
        evidence.r#use.as_ref(),
        "providers",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/earn/{epoch}.merkle_root"),
        &roots["earn"],
        evidence.earn.as_ref(),
        "merkle_root",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/earn/{epoch}.provider_count"),
        &totals["provider_count"],
        evidence.earn.as_ref(),
        "provider_count",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/earn/{epoch}.mu_cum_total"),
        &totals["earn_mu"],
        evidence.earn.as_ref(),
        "mu_cum_total",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/fee/{epoch}.merkle_root"),
        &roots["fee"],
        evidence.fee.as_ref(),
        "merkle_root",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/fee/{epoch}.mu_fee_epoch"),
        &totals["fee_mu"],
        evidence.fee.as_ref(),
        "mu_fee_epoch",
    );
    push_evidence_check(
        &mut checks,
        &format!("ev/fee/{epoch}.mu_fee_cum"),
        &totals["fee_cum_mu"],
        evidence.fee.as_ref(),
        "mu_fee_cum",
    );
    checks
}

fn push_evidence_check(
    checks: &mut Vec<EvidenceCheck>,
    key: &str,
    expected: &Value,
    record: Option<&Value>,
    field: &str,
) {
    let actual = record
        .and_then(|value| value.get(field))
        .cloned()
        .unwrap_or(Value::Null);
    checks.push(EvidenceCheck {
        key: key.to_owned(),
        ok: &actual == expected,
        expected: expected.clone(),
        actual,
    });
}

