async fn provider_join(args: ProviderJoinArgs) -> Result<()> {
    let ctx = provider_tx_context(&args.tx).await?;
    let contract = read_contract_catalog(&ctx.rpc).await?;
    let enclave = resolve_provider_lifecycle_enclave(&contract.enclaves, &args.enclave)?;
    let price = require_current_mu_usd_price(&contract.prices, &enclave.enclave_id)?;
    let rooms = select_provider_rooms(&contract.rooms, &enclave, &args.rooms)?;
    let provider_feature = ensure_provider_registered(
        &ctx.rpc,
        &ctx.keypair_path,
        &ctx.password,
        &ctx.wallet,
        args.tx.sim,
    )
    .await?;
    let serve_feature = ensure_joined_enclave(
        &ctx.rpc,
        &ctx.keypair_path,
        &ctx.password,
        &ctx.wallet,
        &enclave,
        args.tx.sim,
    )
    .await?;
    let room_features = ensure_joined_rooms(
        &ctx.rpc,
        &ctx.keypair_path,
        &ctx.password,
        &ctx.wallet,
        &enclave,
        &rooms,
        args.tx.sim,
    )
    .await?;
    let report = json!({
        "ok": true,
        "action": "join",
        "home": ctx.home,
        "rpc_url": ctx.rpc_url,
        "provider": ctx.wallet.public_key,
        "sim": args.tx.sim,
        "enclave": enclave,
        "price": price,
        "rooms": rooms,
        "features": {
            "provider": provider_feature,
            "serve": serve_feature,
            "rooms": room_features,
        },
    });
    print_provider_lifecycle_report(&report, args.tx.json)
}

async fn provider_leave(args: ProviderLeaveArgs) -> Result<()> {
    let ctx = provider_tx_context(&args.tx).await?;
    let contract = read_contract_catalog(&ctx.rpc).await?;
    let serves = read_active_provider_serves(&ctx.rpc, &ctx.wallet.public_key).await?;
    let enclave = resolve_provider_leave_enclave(&contract.enclaves, &serves, &args.enclave)?;
    let rooms = select_provider_rooms_to_leave(
        &contract.roomserve,
        &ctx.wallet.public_key,
        &enclave.enclave_id,
        &args.rooms,
    )?;
    let room_features =
        leave_provider_rooms(&ctx, &enclave.enclave_id, &rooms, args.tx.sim).await?;
    let serve_feature = ensure_left_enclave(&ctx, &enclave.enclave_id, args.tx.sim).await?;
    let report = json!({
        "ok": true,
        "action": "leave",
        "home": ctx.home,
        "rpc_url": ctx.rpc_url,
        "provider": ctx.wallet.public_key,
        "sim": args.tx.sim,
        "enclave": enclave,
        "rooms": rooms,
        "features": {
            "rooms": room_features,
            "serve": serve_feature,
        },
    });
    print_provider_lifecycle_report(&report, args.tx.json)
}

async fn provider_stop(args: ProviderStopArgs) -> Result<()> {
    let ctx = provider_tx_context(&args.tx).await?;
    let contract = read_contract_catalog(&ctx.rpc).await?;
    let mut active_rooms = contract
        .roomserve
        .iter()
        .filter(|room| room.provider == ctx.wallet.public_key && room.status == "active")
        .cloned()
        .collect::<Vec<_>>();
    active_rooms.sort_by(|a, b| {
        a.enclave_id
            .cmp(&b.enclave_id)
            .then_with(|| a.room_id.cmp(&b.room_id))
    });
    let mut room_features = Vec::with_capacity(active_rooms.len());
    for room in &active_rooms {
        room_features.push(
            ensure_left_room(&ctx, &room.room_id, &room.enclave_id, args.tx.sim)
                .await
                .with_context(|| {
                    format!(
                        "leaving room {} for enclave {}",
                        room.room_id, room.enclave_id
                    )
                })?,
        );
    }

    let serves = read_active_provider_serves(&ctx.rpc, &ctx.wallet.public_key).await?;
    let mut serve_features = Vec::with_capacity(serves.len());
    for serve in &serves {
        serve_features.push(
            ensure_left_enclave(&ctx, &serve.enclave_id, args.tx.sim)
                .await
                .with_context(|| format!("leaving enclave {}", serve.enclave_id))?,
        );
    }
    let report = json!({
        "ok": true,
        "action": "stop",
        "home": ctx.home,
        "rpc_url": ctx.rpc_url,
        "provider": ctx.wallet.public_key,
        "sim": args.tx.sim,
        "rooms": active_rooms,
        "enclaves": serves,
        "features": {
            "rooms": room_features,
            "serves": serve_features,
        },
    });
    print_provider_lifecycle_report(&report, args.tx.json)
}

async fn provider_room_join(args: ProviderRoomJoinArgs) -> Result<()> {
    let ctx = provider_tx_context(&args.tx).await?;
    let contract = read_contract_catalog(&ctx.rpc).await?;
    let enclave = contract
        .enclaves
        .iter()
        .find(|enclave| enclave.enclave_id == args.enclave)
        .with_context(|| format!("enclave {} is not in contract state", args.enclave))?;
    if enclave.status != "active" {
        bail!("enclave {} is not active", enclave.enclave_id);
    }
    let room = contract
        .rooms
        .iter()
        .find(|room| room.room_id == args.room)
        .with_context(|| format!("room {} is not in contract state", args.room))?;
    if room.status != "open" {
        bail!("room {} is not open", room.room_id);
    }
    require_admin_role_marker("room.creator_role", room.creator_role.as_deref())
        .with_context(|| format!("room {} is not admin-created", room.room_id))?;
    require_canonical_room_transport(room)?;
    if !room_matches_enclave(room, enclave) {
        bail!(
            "room {} is for model {} / enclave {}, not model {} / enclave {}",
            room.room_id,
            room.model_id,
            room.enclave_id
                .as_deref()
                .unwrap_or("<missing-enclave-room>"),
            enclave.model_id,
            enclave.enclave_id
        );
    }
    let price = require_current_mu_usd_price(&contract.prices, &enclave.enclave_id)?;
    let serve_key = format!("serve/{}/{}", ctx.wallet.public_key, enclave.enclave_id);
    let serving = read_state_value(&ctx.rpc, &serve_key).await?;
    if serving
        .as_ref()
        .and_then(|value| value.get("status"))
        .and_then(Value::as_str)
        != Some("active")
    {
        bail!(
            "provider {} is not serving enclave {}; run `mayhem provider join --enclave {}` first",
            ctx.wallet.public_key,
            enclave.enclave_id,
            enclave.enclave_id
        );
    }
    let room_features = ensure_joined_rooms(
        &ctx.rpc,
        &ctx.keypair_path,
        &ctx.password,
        &ctx.wallet,
        enclave,
        std::slice::from_ref(room),
        args.tx.sim,
    )
    .await?;
    let report = json!({
        "ok": true,
        "action": "rooms.join",
        "home": ctx.home,
        "rpc_url": ctx.rpc_url,
        "provider": ctx.wallet.public_key,
        "sim": args.tx.sim,
        "enclave": enclave,
        "price": price,
        "rooms": [room],
        "features": {
            "rooms": room_features,
        },
    });
    print_provider_lifecycle_report(&report, args.tx.json)
}

async fn provider_room_leave(args: ProviderRoomLeaveArgs) -> Result<()> {
    let ctx = provider_tx_context(&args.tx).await?;
    let room_feature = ensure_left_room(&ctx, &args.room, &args.enclave, args.tx.sim).await?;
    let report = json!({
        "ok": true,
        "action": "rooms.leave",
        "home": ctx.home,
        "rpc_url": ctx.rpc_url,
        "provider": ctx.wallet.public_key,
        "sim": args.tx.sim,
        "room_id": args.room,
        "enclave_id": args.enclave,
        "features": {
            "room": room_feature,
        },
    });
    print_provider_lifecycle_report(&report, args.tx.json)
}

#[derive(Serialize)]
struct ProviderLifecycleIntentSigningEnvelope<'a> {
    domain: &'static str,
    signing_version: u32,
    intent: &'a Value,
}

fn provider_lifecycle_intent_message(intent: &Value) -> String {
    provider_lifecycle_intent_message_for_version(intent, CONTRACT_SIGNING_MESSAGE_VERSION)
}

fn provider_lifecycle_intent_message_for_version(intent: &Value, signing_version: u32) -> String {
    match signing_version {
        1 => format!("mayhem-provider-lifecycle-v1{}", stable_json_value(intent)),
        2 => {
            let stable_intent = stable_json_value(intent);
            serde_json::to_string(&ProviderLifecycleIntentSigningEnvelope {
                domain: "mayhem-provider-lifecycle",
                signing_version: 2,
                intent: &stable_intent,
            })
            .expect("provider lifecycle signing message serializes")
        }
        _ => {
            let stable_intent = stable_json_value(intent);
            serde_json::to_string(&ProviderLifecycleIntentSigningEnvelope {
                domain: "mayhem-provider-lifecycle-unsupported",
                signing_version,
                intent: &stable_intent,
            })
            .expect("provider lifecycle signing message serializes")
        }
    }
}

fn provider_lifecycle_feature_key(intent: &Value) -> Result<String> {
    provider_lifecycle_feature_key_for_version(intent, CONTRACT_SIGNING_MESSAGE_VERSION)
}

fn provider_lifecycle_feature_key_for_version(
    intent: &Value,
    signing_version: u32,
) -> Result<String> {
    let provider = intent
        .get("provider")
        .and_then(Value::as_str)
        .context("provider lifecycle intent missing provider")?;
    let op = intent
        .get("op")
        .and_then(Value::as_str)
        .context("provider lifecycle intent missing op")?;
    let digest = blake3::hash(
        provider_lifecycle_intent_message_for_version(intent, signing_version).as_bytes(),
    )
    .to_hex()
    .to_string();
    Ok(format!("intent/provider/{provider}/{op}/{digest}"))
}

fn provider_lifecycle_nonce(
    provider: &str,
    op: &str,
    enclave_id: Option<&str>,
    room_id: Option<&str>,
) -> Result<String> {
    Ok(stable_value_hash(&json!({
        "domain": "mayhem-provider-lifecycle-nonce-v1",
        "provider": provider,
        "op": op,
        "enclave_id": enclave_id,
        "room_id": room_id,
        "at_ms": unix_epoch_millis()?,
    })))
}

fn provider_lifecycle_intent(
    provider: &str,
    op: &str,
    enclave_id: Option<&str>,
    room_id: Option<&str>,
) -> Result<Value> {
    let nonce = provider_lifecycle_nonce(provider, op, enclave_id, room_id)?;
    let value = match (enclave_id, room_id) {
        (Some(enclave_id), Some(room_id)) => json!({
            "op": op,
            "provider": provider,
            "enclave_id": enclave_id,
            "room_id": room_id,
            "nonce": nonce,
        }),
        (Some(enclave_id), None) => json!({
            "op": op,
            "provider": provider,
            "enclave_id": enclave_id,
            "nonce": nonce,
        }),
        (None, None) => json!({
            "op": op,
            "provider": provider,
            "nonce": nonce,
        }),
        (None, Some(_)) => bail!("room lifecycle intent requires enclave_id"),
    };
    Ok(value)
}

fn resolve_provider_lifecycle_enclave(
    enclaves: &[LedgerEnclave],
    requested: &str,
) -> Result<LedgerEnclave> {
    if let Some(enclave) = enclaves
        .iter()
        .find(|enclave| enclave.enclave_id == requested && enclave.status == "active")
    {
        require_admin_role_marker(
            "enclave.created_by_role",
            enclave.created_by_role.as_deref(),
        )
        .with_context(|| format!("enclave {} is not admin-created", enclave.enclave_id))?;
        return Ok(enclave.clone());
    }
    let mut matches = enclaves
        .iter()
        .filter(|enclave| {
            enclave.model_id == requested
                && enclave.status == "active"
                && admin_role_marker_ok(enclave.created_by_role.as_deref())
        })
        .cloned()
        .collect::<Vec<_>>();
    matches.sort_by(|a, b| a.enclave_id.cmp(&b.enclave_id));
    match matches.len() {
        0 => bail!(
            "requested {requested} is not an active admin-created enclave id or model lookup"
        ),
        1 => Ok(matches.remove(0)),
        _ => bail!(
            "model {requested} has multiple active admin-created enclaves; pass a concrete enclave id"
        ),
    }
}

fn current_mu_usd_price(schedule: &LedgerPriceSchedule) -> Option<&LedgerPriceRecord> {
    let current = schedule.current.as_ref()?;
    (schedule.denom == "mu_usd"
        && current.denom == "mu_usd"
        && !current.rate_map.is_empty()
        && admin_role_marker_ok(current.set_by_role.as_deref()))
    .then_some(current)
}

fn admin_role_marker_ok(role: Option<&str>) -> bool {
    role == Some("admin")
}

fn active_provider_kyb_info(record: &LedgerProviderKyb) -> Option<ProviderKybInfo> {
    if record.status != "verified" || !admin_role_marker_ok(record.verified_by_role.as_deref()) {
        return None;
    }
    if !is_hex_len(&record.provider, 64)
        || !is_hex_len(&record.proof_hash, 64)
        || !is_hex_len(&record.admin_sig, 128)
        || record.legal_name.trim().is_empty()
        || record.jurisdiction.trim().is_empty()
        || record.kyb_ref.trim().is_empty()
        || record.schema_version == 0
    {
        return None;
    }
    Some(ProviderKybInfo {
        provider: record.provider.to_ascii_lowercase(),
        legal_name: record.legal_name.clone(),
        jurisdiction: record.jurisdiction.clone(),
        proof_hash: record.proof_hash.to_ascii_lowercase(),
        kyb_ref: record.kyb_ref.clone(),
    })
}

fn require_admin_role_marker(field: &str, role: Option<&str>) -> Result<()> {
    if admin_role_marker_ok(role) {
        return Ok(());
    }
    bail!("{field} must be admin; got {}", role.unwrap_or("<missing>"))
}

fn require_current_mu_usd_price<'a>(
    prices: &'a [LedgerPriceSchedule],
    enclave_id: &str,
) -> Result<&'a LedgerPriceSchedule> {
    let schedule = prices
        .iter()
        .find(|price| price.enclave_id == enclave_id)
        .with_context(|| {
            format!(
                "enclave {enclave_id} has no admin price; ask the admin to run `mayhem admin set-price` before providers join it"
            )
        })?;
    if current_mu_usd_price(schedule).is_none() {
        bail!(
            "enclave {enclave_id} has no current mu_usd admin price; ask the admin to run `mayhem admin set-price` before providers join it"
        );
    }
    Ok(schedule)
}

fn resolve_provider_leave_enclave(
    enclaves: &[LedgerEnclave],
    serves: &[LedgerServe],
    requested: &str,
) -> Result<LedgerEnclave> {
    if let Some(enclave) = enclaves
        .iter()
        .find(|enclave| enclave.enclave_id == requested)
    {
        return Ok(enclave.clone());
    }
    let mut matches = serves
        .iter()
        .filter(|serve| serve.model_id == requested && serve.status == "active")
        .cloned()
        .collect::<Vec<_>>();
    matches.sort_by(|a, b| a.enclave_id.cmp(&b.enclave_id));
    match matches.len() {
        0 => bail!(
            "requested {requested} is not a known admin-created enclave id or active provider model lookup"
        ),
        1 => enclaves
            .iter()
            .find(|enclave| enclave.enclave_id == matches[0].enclave_id)
            .cloned()
            .with_context(|| {
                format!(
                    "provider is serving enclave {}, but its admin-created enclave record is missing",
                    matches[0].enclave_id
                )
            }),
        _ => bail!(
            "model {requested} has multiple active provider serving rows; pass a concrete enclave id"
        ),
    }
}

fn select_provider_rooms_to_leave(
    roomserve: &[LedgerRoomServe],
    provider: &str,
    enclave_id: &str,
    requested: &str,
) -> Result<Vec<String>> {
    let active = roomserve
        .iter()
        .filter(|row| {
            row.provider == provider && row.enclave_id == enclave_id && row.status == "active"
        })
        .map(|row| row.room_id.clone())
        .collect::<BTreeSet<_>>();
    if requested.trim().eq_ignore_ascii_case("auto") {
        return Ok(active.into_iter().collect());
    }
    let requested_ids = requested
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    if requested_ids.is_empty() {
        bail!("--rooms must be auto or a comma-separated list of room ids");
    }
    for room_id in &requested_ids {
        if !active.contains(*room_id) {
            bail!("provider is not actively serving room {room_id} with enclave {enclave_id}");
        }
    }
    Ok(requested_ids.into_iter().map(str::to_owned).collect())
}

async fn leave_provider_rooms(
    ctx: &ProviderTxContext,
    enclave_id: &str,
    rooms: &[String],
    sim: bool,
) -> Result<Vec<Value>> {
    let mut reports = Vec::with_capacity(rooms.len());
    for room_id in rooms {
        reports.push(ensure_left_room(ctx, room_id, enclave_id, sim).await?);
    }
    Ok(reports)
}

async fn ensure_left_room(
    ctx: &ProviderTxContext,
    room_id: &str,
    enclave_id: &str,
    sim: bool,
) -> Result<Value> {
    let key = format!(
        "roomserve/{}/{}/{}",
        room_id, ctx.wallet.public_key, enclave_id
    );
    let existing = read_state_value(&ctx.rpc, &key).await?;
    if existing
        .as_ref()
        .and_then(|value| value.get("status"))
        .and_then(Value::as_str)
        != Some("active")
    {
        return Ok(json!({
            "room_id": room_id,
            "enclave_id": enclave_id,
            "skipped": true,
            "reason": "not_joined_room",
            "state": existing,
        }));
    }
    let submitted = submit_provider_lifecycle_feature(
        ProviderLifecycleSubmitContext {
            rpc: &ctx.rpc,
            keypair_path: &ctx.keypair_path,
            password: &ctx.password,
            wallet: &ctx.wallet,
            sim,
        },
        "leave_room",
        Some(enclave_id),
        Some(room_id),
    )
    .await?;
    if sim {
        return Ok(json!({ "room_id": room_id, "enclave_id": enclave_id, "feature": submitted }));
    }
    let state = wait_for_state(&ctx.rpc, &key, |value| {
        value.get("status").and_then(Value::as_str) == Some("inactive")
    })
    .await?;
    Ok(json!({
        "room_id": room_id,
        "enclave_id": enclave_id,
        "skipped": false,
        "feature": submitted,
        "state": state,
    }))
}

async fn ensure_left_enclave(
    ctx: &ProviderTxContext,
    enclave_id: &str,
    sim: bool,
) -> Result<Value> {
    let key = format!("serve/{}/{}", ctx.wallet.public_key, enclave_id);
    let existing = read_state_value(&ctx.rpc, &key).await?;
    if existing
        .as_ref()
        .and_then(|value| value.get("status"))
        .and_then(Value::as_str)
        != Some("active")
    {
        return Ok(json!({
            "enclave_id": enclave_id,
            "skipped": true,
            "reason": "not_serving_enclave",
            "state": existing,
        }));
    }
    let submitted = submit_provider_lifecycle_feature(
        ProviderLifecycleSubmitContext {
            rpc: &ctx.rpc,
            keypair_path: &ctx.keypair_path,
            password: &ctx.password,
            wallet: &ctx.wallet,
            sim,
        },
        "leave_enclave",
        Some(enclave_id),
        None,
    )
    .await?;
    if sim {
        return Ok(json!({ "enclave_id": enclave_id, "feature": submitted }));
    }
    let state = wait_for_state(&ctx.rpc, &key, |value| {
        value.get("status").and_then(Value::as_str) == Some("inactive")
    })
    .await?;
    Ok(json!({
        "enclave_id": enclave_id,
        "skipped": false,
        "feature": submitted,
        "state": state,
    }))
}

async fn read_active_provider_serves(
    rpc: &PeerRpcClient,
    provider: &str,
) -> Result<Vec<LedgerServe>> {
    let prefix = format!("serve/{provider}/");
    let mut serves = read_prefix_entries(rpc, &prefix)
        .await?
        .into_iter()
        .map(|entry| serde_json::from_value(entry.value).context("parsing provider serve record"))
        .collect::<Result<Vec<LedgerServe>>>()?
        .into_iter()
        .filter(|serve| serve.provider == provider && serve.status == "active")
        .collect::<Vec<_>>();
    serves.sort_by(|a, b| a.enclave_id.cmp(&b.enclave_id));
    Ok(serves)
}

fn provider_heartbeat_cache_path(home: &Path, provider: &str) -> PathBuf {
    home.join("provider")
        .join("heartbeats")
        .join(format!("{provider}.json"))
}

fn write_provider_heartbeat_cache(
    home: &Path,
    provider: &str,
    enclave_id: &str,
    heartbeats: &[Value],
) -> Result<Value> {
    if heartbeats.is_empty() {
        return Ok(Value::Null);
    }
    let path = provider_heartbeat_cache_path(home, provider);
    let updated_at_ms = unix_epoch_millis()?;
    let cache = json!({
        "provider": provider,
        "enclave_id": enclave_id,
        "updated_at_ms": updated_at_ms,
        "heartbeat_count": heartbeats.len(),
        "heartbeats": heartbeats,
    });
    write_json_file(&path, &cache)?;
    Ok(json!({
        "ok": true,
        "path": path,
        "updated_at_ms": updated_at_ms,
        "heartbeat_count": heartbeats.len(),
    }))
}

fn normalize_provider_accepted_rails_arg(raw: &str) -> Result<Vec<String>> {
    let mut seen = BTreeSet::new();
    let mut rails = Vec::new();
    for value in raw
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let rail = value.to_ascii_lowercase();
        if !PROVIDER_ACCEPTED_RAIL_ORDER.contains(&rail.as_str()) {
            bail!("unsupported provider payment rail {value}; expected fiat, tap, or tnk");
        }
        if !seen.insert(rail.clone()) {
            bail!("duplicate provider payment rail {rail}");
        }
        rails.push(rail);
    }
    if rails.is_empty() {
        bail!("provider accepted rails cannot be empty");
    }
    rails.sort_by_key(|rail| {
        PROVIDER_ACCEPTED_RAIL_ORDER
            .iter()
            .position(|known| known == rail)
            .unwrap_or(usize::MAX)
    });
    Ok(rails)
}

fn read_provider_heartbeat_cache(home: &Path, provider: &str) -> Value {
    let path = provider_heartbeat_cache_path(home, provider);
    match read_json_file(&path) {
        Ok(cache) => {
            let updated_at_ms = cache
                .get("updated_at_ms")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            let age_ms = unix_epoch_millis()
                .ok()
                .map(|now| now.saturating_sub(updated_at_ms));
            let live = age_ms
                .map(|age| age <= DEFAULT_PROVIDER_HEARTBEAT_TTL_MILLIS)
                .unwrap_or(false);
            json!({
                "ok": true,
                "path": path,
                "live": live,
                "updated_at_ms": updated_at_ms,
                "age_ms": age_ms,
                "ttl_ms": DEFAULT_PROVIDER_HEARTBEAT_TTL_MILLIS,
                "cache": cache,
            })
        }
        Err(err) => json!({
            "ok": false,
            "path": path,
            "live": false,
            "ttl_ms": DEFAULT_PROVIDER_HEARTBEAT_TTL_MILLIS,
            "error": err.to_string(),
        }),
    }
}

fn active_provider_serves_from_contract(
    contract: &ContractCatalog,
    provider: &str,
) -> Vec<LedgerServe> {
    let mut serves = contract
        .serves
        .iter()
        .filter(|serve| serve.provider == provider && serve.status == "active")
        .cloned()
        .collect::<Vec<_>>();
    serves.sort_by(|a, b| {
        a.enclave_id
            .cmp(&b.enclave_id)
            .then_with(|| a.model_id.cmp(&b.model_id))
    });
    serves
}

fn active_provider_roomserves_from_contract(
    contract: &ContractCatalog,
    provider: &str,
) -> Vec<LedgerRoomServe> {
    let mut rows = contract
        .roomserve
        .iter()
        .filter(|row| row.provider == provider && row.status == "active")
        .cloned()
        .collect::<Vec<_>>();
    rows.sort_by(|a, b| {
        a.enclave_id
            .cmp(&b.enclave_id)
            .then_with(|| a.room_id.cmp(&b.room_id))
    });
    rows
}

fn provider_list_summary(contract: &ContractCatalog, provider: &str) -> Value {
    let active_serves = active_provider_serves_from_contract(contract, provider);
    let active_rooms = active_provider_roomserves_from_contract(contract, provider);
    let provider_record = contract
        .providers
        .iter()
        .find(|record| record.provider == provider)
        .cloned();
    let kyb = contract
        .kyb
        .iter()
        .find(|record| record.provider == provider)
        .cloned();
    let serves = active_serves
        .iter()
        .map(|serve| provider_serve_summary(contract, serve, &active_rooms))
        .collect::<Vec<_>>();
    let rooms = active_rooms
        .iter()
        .map(|row| provider_roomserve_summary(contract, row))
        .collect::<Vec<_>>();
    json!({
        "provider": provider,
        "provider_record": provider_record,
        "kyb": kyb,
        "active_serves": serves,
        "active_rooms": rooms,
        "stop_plan": {
            "rooms": active_rooms,
            "enclaves": active_serves,
        },
    })
}

fn provider_serve_summary(
    contract: &ContractCatalog,
    serve: &LedgerServe,
    active_rooms: &[LedgerRoomServe],
) -> Value {
    let enclave = contract
        .enclaves
        .iter()
        .find(|enclave| enclave.enclave_id == serve.enclave_id)
        .cloned();
    let price = contract
        .prices
        .iter()
        .find(|price| price.enclave_id == serve.enclave_id)
        .cloned();
    let rooms = active_rooms
        .iter()
        .filter(|row| row.enclave_id == serve.enclave_id && row.provider == serve.provider)
        .map(|row| provider_roomserve_summary(contract, row))
        .collect::<Vec<_>>();
    let room_count = rooms.len();
    json!({
        "provider": &serve.provider,
        "enclave_id": &serve.enclave_id,
        "model_id": &serve.model_id,
        "status": &serve.status,
        "rooms": rooms,
        "room_count": room_count,
        "enclave": enclave,
        "price": price,
    })
}

fn provider_roomserve_summary(contract: &ContractCatalog, row: &LedgerRoomServe) -> Value {
    let room = contract
        .rooms
        .iter()
        .find(|room| room.room_id == row.room_id)
        .cloned();
    json!({
        "room_id": &row.room_id,
        "provider": &row.provider,
        "enclave_id": &row.enclave_id,
        "model_id": &row.model_id,
        "status": &row.status,
        "room": room,
    })
}

fn provider_gateway_route_summaries(models: &[Value], provider: &str) -> Vec<Value> {
    let mut routes = Vec::new();
    for model in models {
        let model_id = model.get("id").and_then(Value::as_str).unwrap_or("");
        let mayhem = model.get("mayhem").unwrap_or(&Value::Null);
        let providers_online = mayhem
            .get("providers_online")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let rooms = mayhem.get("rooms").and_then(Value::as_u64).unwrap_or(0);
        for candidate in mayhem
            .get("route_candidates")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
        {
            if candidate.get("provider").and_then(Value::as_str) == Some(provider) {
                routes.push(json!({
                    "model_id": model_id,
                    "providers_online": providers_online,
                    "rooms": rooms,
                    "provider": candidate.get("provider").cloned().unwrap_or(Value::Null),
                    "enclave_id": candidate.get("enclave_id").cloned().unwrap_or(Value::Null),
                    "room_id": candidate.get("room_id").cloned().unwrap_or(Value::Null),
                    "price_ver": candidate.get("price_ver").cloned().unwrap_or(Value::Null),
                    "att_tier": candidate.get("att_tier").cloned().unwrap_or(Value::Null),
                    "kyb": candidate.get("kyb").cloned().unwrap_or(Value::Null),
                }));
            }
        }
    }
    routes.sort_by(|a, b| {
        let left = (
            a.get("model_id").and_then(Value::as_str).unwrap_or(""),
            a.get("enclave_id").and_then(Value::as_str).unwrap_or(""),
            a.get("room_id").and_then(Value::as_str).unwrap_or(""),
        );
        let right = (
            b.get("model_id").and_then(Value::as_str).unwrap_or(""),
            b.get("enclave_id").and_then(Value::as_str).unwrap_or(""),
            b.get("room_id").and_then(Value::as_str).unwrap_or(""),
        );
        left.cmp(&right)
    });
    routes
}

fn print_provider_list_report(report: &Value, json_output: bool) -> Result<()> {
    if json_output {
        println!("{}", serde_json::to_string_pretty(report)?);
        return Ok(());
    }
    println!("Provider: {}", report["provider"].as_str().unwrap_or(""));
    print_provider_list_rows(&report["ledger"]);
    Ok(())
}

fn print_provider_health_report(report: &Value, json_output: bool) -> Result<()> {
    if json_output {
        println!("{}", serde_json::to_string_pretty(report)?);
        return Ok(());
    }
    println!(
        "Provider health: {}",
        if report["ok"].as_bool() == Some(true) {
            "healthy"
        } else {
            "degraded"
        }
    );
    println!("Provider: {}", report["provider"].as_str().unwrap_or(""));
    print_provider_list_rows(&report["ledger"]);
    println!(
        "Heartbeat: {}",
        if report["heartbeat"]["live"].as_bool() == Some(true) {
            "live"
        } else {
            report["heartbeat"]["error"].as_str().unwrap_or("stale")
        }
    );
    println!(
        "Gateway: {}",
        if report["gateway"]["ok"].as_bool() == Some(true) {
            "ok"
        } else {
            report["gateway"]["status"]["error"]
                .as_str()
                .or_else(|| report["gateway"]["routes"]["error"].as_str())
                .unwrap_or("degraded")
        }
    );
    println!(
        "Gateway routes visible: {}",
        report["gateway"]["route_count"].as_u64().unwrap_or(0)
    );
    Ok(())
}

fn print_provider_rails_report(report: &Value, json_output: bool) -> Result<()> {
    if json_output {
        println!("{}", serde_json::to_string_pretty(report)?);
        return Ok(());
    }
    println!("Provider rails command complete.");
    println!("Action: {}", report["action"].as_str().unwrap_or(""));
    if let Some(provider) = report["provider"].as_str() {
        println!("Provider: {provider}");
    }
    if !report["rails"].is_null() {
        println!("{}", serde_json::to_string_pretty(&report["rails"])?);
    }
    if let Some(command) = report["copy_paste"]["intercom_sim"].as_str() {
        println!("Copy/paste Intercom sim command:");
        println!("{command}");
    }
    if report["submitted"].as_bool() == Some(true) {
        println!("Submitted: true");
        if let Some(tx) = report["tx"]["tx"].as_str() {
            println!("Tx: {tx}");
        }
    }
    Ok(())
}

fn print_provider_list_rows(ledger: &Value) {
    let serves = ledger["active_serves"]
        .as_array()
        .map(Vec::len)
        .unwrap_or(0);
    let rooms = ledger["active_rooms"].as_array().map(Vec::len).unwrap_or(0);
    println!("Active enclaves: {serves}");
    for serve in ledger["active_serves"].as_array().into_iter().flatten() {
        println!(
            "- {} model={} rooms={} status={}",
            serve["enclave_id"].as_str().unwrap_or(""),
            serve["model_id"].as_str().unwrap_or(""),
            serve["room_count"].as_u64().unwrap_or(0),
            serve["status"].as_str().unwrap_or("")
        );
    }
    println!("Active rooms: {rooms}");
    for room in ledger["active_rooms"].as_array().into_iter().flatten() {
        println!(
            "- {} model={} enclave={} status={}",
            room["room_id"].as_str().unwrap_or(""),
            room["model_id"].as_str().unwrap_or(""),
            room["enclave_id"].as_str().unwrap_or(""),
            room["status"].as_str().unwrap_or("")
        );
    }
}

fn print_provider_lifecycle_report(report: &Value, json_output: bool) -> Result<()> {
    if json_output {
        println!("{}", serde_json::to_string_pretty(report)?);
        return Ok(());
    }
    println!("Provider lifecycle command complete.");
    println!("Action: {}", report["action"].as_str().unwrap_or(""));
    println!("Provider: {}", report["provider"].as_str().unwrap_or(""));
    if let Some(enclave_id) = report["enclave"]["enclave_id"].as_str() {
        println!("Enclave: {enclave_id}");
    }
    let room_count = report["rooms"].as_array().map(Vec::len).unwrap_or(0);
    println!("Rooms touched: {room_count}");
    if report["sim"].as_bool() == Some(true) {
        println!("Simulation: true");
    }
    Ok(())
}

fn provider_log(args: &ProviderStartArgs, message: &str) {
    if !args.print_json {
        println!("-> {message}");
    } else if env::var_os("MAYHEM_PROVIDER_START_PROGRESS").is_some()
        || env::var_os("MAYHEM_PROVIDER_SESSION_DEBUG").is_some()
    {
        eprintln!("[provider-start] {message}");
    }
}

fn validate_provider_start_security_mode(
    args: &ProviderStartArgs,
    debug_build: bool,
) -> Result<()> {
    if args.serve_sessions && args.dev_session_shim && !debug_build {
        bail!(
            "--dev-session-shim is debug-build only and cannot serve from an admin-trusted release binary"
        );
    }
    if args.serve_sessions && args.dev_skip_catalog_verify && !debug_build {
        bail!(
            "--serve-sessions requires a signed admin catalog in release builds; --dev-skip-catalog-verify is smoke-test only"
        );
    }
    Ok(())
}

fn provider_session_debug(message: impl AsRef<str>) {
    if std::env::var_os("MAYHEM_PROVIDER_SESSION_DEBUG").is_some() {
        eprintln!("[provider-session] {}", message.as_ref());
    }
}

fn verify_or_hash_catalog(args: &ProviderStartArgs, catalog_path: &Path) -> Result<String> {
    if args.dev_skip_catalog_verify {
        let bytes = fs::read(catalog_path)
            .with_context(|| format!("reading {}", catalog_path.display()))?;
        return Ok(blake3::hash(&bytes).to_hex().to_string());
    }

    let signature_path = args
        .signature_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/signatures/models.json.sig"))?;
    let keys_dir = args
        .keys_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/keys"))?;
    let canaries_dir = args
        .canaries_dir
        .clone()
        .map(Ok)
        .unwrap_or_else(|| repo_path("catalog/canaries"))?;
    let report = catalog::verify(catalog::VerifyOptions {
        catalog_path: catalog_path.to_path_buf(),
        signature_path: absolutize(signature_path)?,
        keys_dir: absolutize(keys_dir)?,
        canaries_dir: absolutize(canaries_dir)?,
        check_dev_downloads: false,
        check_launch_sources: false,
        hf_token_file: None,
    })?;
    if !report.ok {
        bail!("catalog verification failed: {}", report.errors.join("; "));
    }
    Ok(report.catalog_hash)
}

fn provider_hwprobe(args: &ProviderStartArgs) -> Result<HardwareReport> {
    let fixture = args
        .fixture
        .as_deref()
        .map(|value| {
            FixtureProfile::parse(value).with_context(|| {
                format!(
                    "unknown fixture {value}; expected apple-silicon, linux-nvidia, or cpu-only"
                )
            })
        })
        .transpose()?;
    let mut options = ProbeOptions::default();
    if let Some(path) = &args.disk_path {
        options.disk_path = absolutize(path.clone())?;
    }
    options.run_disk_bench = !args.skip_disk_bench;
    options.fixture = fixture;
    Ok(probe(options))
}

async fn read_contract_catalog(rpc: &PeerRpcClient) -> Result<ContractCatalog> {
    let prices = read_prefix_entries(rpc, "price/")
        .await?
        .into_iter()
        .filter(|entry| {
            entry
                .key
                .strip_prefix("price/")
                .is_some_and(|tail| !tail.contains('/'))
        })
        .map(|entry| serde_json::from_value(entry.value).context("parsing price schedule"))
        .collect::<Result<Vec<LedgerPriceSchedule>>>()?;
    Ok(ContractCatalog {
        enclaves: read_prefix_values_filtered(rpc, "enclave/", |tail| !tail.contains('/')).await?,
        rooms: read_prefix_values_filtered(rpc, "room/", |tail| !tail.contains('/')).await?,
        roomserve: read_prefix_values(rpc, "roomserve/").await?,
        serves: read_prefix_values(rpc, "serve/").await?,
        providers: read_prefix_values_filtered(rpc, "prov/", |tail| !tail.contains('/')).await?,
        kyb: read_prefix_values_filtered(rpc, "kyb/", |tail| !tail.contains('/')).await?,
        prices,
        rules: read_state_value(rpc, "rules/current")
            .await?
            .map(serde_json::from_value)
            .transpose()
            .context("parsing rules/current")?,
    })
}

async fn read_prefix_values<T>(rpc: &PeerRpcClient, prefix: &str) -> Result<Vec<T>>
where
    T: DeserializeOwned,
{
    read_prefix_values_filtered(rpc, prefix, |_| true).await
}

async fn read_prefix_values_filtered<T, F>(
    rpc: &PeerRpcClient,
    prefix: &str,
    include_tail: F,
) -> Result<Vec<T>>
where
    T: DeserializeOwned,
    F: Fn(&str) -> bool,
{
    read_prefix_entries(rpc, prefix)
        .await?
        .into_iter()
        .filter(|entry| entry.key.strip_prefix(prefix).is_some_and(&include_tail))
        .map(|entry| {
            let key = entry.key;
            serde_json::from_value(entry.value)
                .with_context(|| format!("parsing contract state record {key}"))
        })
        .collect()
}

async fn read_prefix_entries(rpc: &PeerRpcClient, prefix: &str) -> Result<Vec<PrefixStateEntry>> {
    let response = rpc
        .state_prefix(prefix, Some(false), Some(1000))
        .await
        .with_context(|| format!("reading {prefix}* from peer RPC"))?;
    let parsed: PrefixStateResponse = serde_json::from_value(response)
        .with_context(|| format!("parsing {prefix}* state response"))?;
    Ok(parsed
        .values
        .into_iter()
        .filter(|entry| entry.key.starts_with(prefix))
        .collect())
}

fn gateway_models_from_contract(contract: &ContractCatalog) -> Result<Vec<GatewayModel>> {
    let active_enclaves = contract
        .enclaves
        .iter()
        .filter(|enclave| {
            enclave.status == "active" && admin_role_marker_ok(enclave.created_by_role.as_deref())
        })
        .map(|enclave| (enclave.enclave_id.clone(), enclave))
        .collect::<BTreeMap<_, _>>();
    let open_rooms = contract
        .rooms
        .iter()
        .filter(|room| {
            room.status == "open"
                && admin_role_marker_ok(room.creator_role.as_deref())
                && canonical_room_transport_ok(room)
        })
        .collect::<Vec<_>>();
    let active_providers = contract
        .providers
        .iter()
        .filter(|provider| provider.status == "active")
        .map(|provider| provider.provider.as_str())
        .collect::<BTreeSet<_>>();
    let active_provider_by_id = contract
        .providers
        .iter()
        .filter(|provider| provider.status == "active")
        .map(|provider| (provider.provider.as_str(), provider))
        .collect::<BTreeMap<_, _>>();
    let active_kyb_by_provider = contract
        .kyb
        .iter()
        .filter_map(active_provider_kyb_info)
        .filter(|kyb| active_providers.contains(kyb.provider.as_str()))
        .map(|kyb| (kyb.provider.clone(), kyb))
        .collect::<BTreeMap<_, _>>();
    let mut rooms_by_id = BTreeMap::new();
    let mut rooms_by_model: BTreeMap<String, u32> = BTreeMap::new();
    for room in &open_rooms {
        rooms_by_id.insert(room.room_id.clone(), *room);
        let count = rooms_by_model.entry(room.model_id.clone()).or_default();
        *count = count.saturating_add(1);
    }

    let mut prices_by_enclave = BTreeMap::new();
    for schedule in &contract.prices {
        let Some(price) = current_mu_usd_price(schedule) else {
            continue;
        };
        prices_by_enclave.insert(schedule.enclave_id.clone(), price.clone());
    }

    let mut caps_by_model: BTreeMap<String, ModelCaps> = BTreeMap::new();
    let mut class_by_model: BTreeMap<String, String> = BTreeMap::new();
    for enclave in active_enclaves.values() {
        if rooms_by_model.get(&enclave.model_id).copied().unwrap_or(0) == 0 {
            continue;
        }
        if !prices_by_enclave.contains_key(&enclave.enclave_id) {
            continue;
        };
        class_by_model
            .entry(enclave.model_id.clone())
            .or_insert_with(|| enclave.model_class.clone());
        caps_by_model
            .entry(enclave.model_id.clone())
            .and_modify(|caps| merge_model_caps(caps, &gateway_caps_from_contract(&enclave.caps)))
            .or_insert_with(|| gateway_caps_from_contract(&enclave.caps));
    }

    let mut served_price_by_model: BTreeMap<String, LedgerPriceRecord> = BTreeMap::new();
    for serving in contract
        .roomserve
        .iter()
        .filter(|serving| serving.status == "active")
    {
        if !active_providers.contains(serving.provider.as_str()) {
            continue;
        }
        let Some(room) = rooms_by_id.get(&serving.room_id) else {
            continue;
        };
        let Some(enclave) = active_enclaves.get(&serving.enclave_id) else {
            continue;
        };
        if !room_matches_enclave(room, enclave) {
            continue;
        }
        let Some(serving_price) = prices_by_enclave.get(&serving.enclave_id) else {
            continue;
        };
        if enclave.model_id != serving.model_id {
            continue;
        }
        served_price_by_model
            .entry(enclave.model_id.clone())
            .and_modify(|existing| {
                if price_sort_key(serving_price) < price_sort_key(existing) {
                    *existing = serving_price.clone();
                }
            })
            .or_insert_with(|| serving_price.clone());
    }

    let mut providers_by_model: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut tiers_by_model: BTreeMap<String, BTreeMap<String, BTreeSet<String>>> = BTreeMap::new();
    let mut kyb_by_model: BTreeMap<String, BTreeMap<String, ProviderKybInfo>> = BTreeMap::new();
    let mut route_candidates_by_model: BTreeMap<String, BTreeMap<String, GatewayRouteCandidate>> =
        BTreeMap::new();
    for serving in contract
        .roomserve
        .iter()
        .filter(|serving| serving.status == "active")
    {
        if !active_providers.contains(serving.provider.as_str()) {
            continue;
        }
        let Some(room) = rooms_by_id.get(&serving.room_id) else {
            continue;
        };
        let Some(enclave) = active_enclaves.get(&serving.enclave_id) else {
            continue;
        };
        if !room_matches_enclave(room, enclave) {
            continue;
        }
        let Some(selected_price) = served_price_by_model.get(&enclave.model_id) else {
            continue;
        };
        let Some(serving_price) = prices_by_enclave.get(&serving.enclave_id) else {
            continue;
        };
        if enclave.model_id != serving.model_id
            || !same_gateway_price_terms(serving_price, selected_price)
        {
            continue;
        }
        providers_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .insert(serving.provider.clone());
        let kyb = active_kyb_by_provider.get(&serving.provider).cloned();
        if let Some(kyb) = &kyb {
            kyb_by_model
                .entry(enclave.model_id.clone())
                .or_default()
                .insert(serving.provider.clone(), kyb.clone());
        }
        let effective_att_tier = kyb.as_ref().map(|_| 4).unwrap_or(enclave.att_tier);
        route_candidates_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .insert(
                format!(
                    "{}:{}:{}",
                    serving.provider, serving.room_id, serving.enclave_id
                ),
                GatewayRouteCandidate {
                    provider: serving.provider.clone(),
                    accepted_rails: active_provider_by_id
                        .get(serving.provider.as_str())
                        .map(|provider| provider.accepted_rails.clone())
                        .unwrap_or_default(),
                    enclave_id: serving.enclave_id.clone(),
                    room_id: serving.room_id.clone(),
                    price_ver: serving_price.ver,
                    att_tier: effective_att_tier,
                    admin_pubkey: enclave.created_by.clone(),
                    artifact_root: enclave.artifact_root.clone(),
                    artifact_sidecar_roots: enclave_artifact_sidecar_roots(enclave),
                    manifest_hash: enclave.manifest_hash.clone(),
                    binary_hash: enclave.binary_hash.clone(),
                    kyb,
                    caps: enclave.caps.clone(),
                },
            );
        let tier = format!("T{effective_att_tier}");
        tiers_by_model
            .entry(enclave.model_id.clone())
            .or_default()
            .entry(tier)
            .or_default()
            .insert(serving.provider.clone());
    }

    let mut models = Vec::new();
    for (model_id, price) in served_price_by_model {
        let rooms = rooms_by_model.get(&model_id).copied().unwrap_or(0);
        let route_candidates = route_candidates_by_model
            .remove(&model_id)
            .unwrap_or_default()
            .into_values()
            .collect::<Vec<_>>();
        let kyb_identities = kyb_by_model
            .remove(&model_id)
            .unwrap_or_default()
            .into_values()
            .collect::<Vec<_>>();
        let providers_online = providers_by_model
            .get(&model_id)
            .map(|providers| usize_to_u32(providers.len()))
            .unwrap_or(0);
        if rooms == 0 || providers_online == 0 {
            continue;
        }
        let attestation_tiers = tiers_by_model
            .remove(&model_id)
            .unwrap_or_default()
            .into_iter()
            .map(|(tier, providers)| (tier, usize_to_u32(providers.len())))
            .collect::<BTreeMap<_, _>>();
        models.push(GatewayModel {
            id: model_id.clone(),
            created: 1_782_950_400,
            owned_by: "mayhem".to_owned(),
            mayhem: MayhemModelInfo {
                model_class: class_by_model
                    .remove(&model_id)
                    .unwrap_or_else(|| DEFAULT_MODEL_CLASS.to_owned()),
                providers_online,
                rooms,
                price_ref_mu: PriceRefMu {
                    denom: "mu_usd".to_owned(),
                    ver: price.ver,
                    rate_map: normalize_rate_map(price.rate_map.clone()),
                },
                attestation_tier_labels: gateway_attestation_tier_labels_for_counts(
                    &attestation_tiers,
                ),
                attestation_tiers,
                min_app_version: None,
                caps: caps_by_model
                    .remove(&model_id)
                    .unwrap_or_else(empty_gateway_caps),
                adapter: mayhem_gateway::openai::ShapeAdapterInfo::default(),
                failover: mayhem_gateway::openai::GatewayFailoverPolicyConfig::default(),
                source: "contract".to_owned(),
                kyb_identities,
                route_candidates,
            },
        });
    }
    if models.is_empty() {
        bail!(
            "no canonical contract-backed models found; ask the admin to register an enclave, set a current mu_usd price, open a room, and confirm an active provider joined it, or use --dev-embedded-catalog for local smoke only"
        );
    }
    Ok(models)
}

#[derive(Debug, Clone, Eq, PartialEq, Serialize)]
struct ModelVersionGate {
    model_id: String,
    min_app_version: String,
    installed_app_version: String,
    message: String,
}

fn installed_app_version() -> &'static str {
    env!("CARGO_PKG_VERSION")
}

fn model_app_version_gate(
    model_id: &str,
    min_app_version: Option<&str>,
) -> Result<Option<ModelVersionGate>> {
    let Some(min_app_version) = min_app_version
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(None);
    };
    let installed = installed_app_version();
    if app_version_satisfies_min(installed, min_app_version)? {
        return Ok(None);
    }
    let message = upgrade_required_message(model_id, min_app_version, installed);
    Ok(Some(ModelVersionGate {
        model_id: model_id.to_owned(),
        min_app_version: min_app_version.to_owned(),
        installed_app_version: installed.to_owned(),
        message,
    }))
}

fn app_version_satisfies_min(installed: &str, min_app_version: &str) -> Result<bool> {
    let installed = parse_app_version(installed, "installed Mayhem")?;
    let min_app_version = parse_app_version(min_app_version, "catalog min_app_version")?;
    Ok(installed >= min_app_version)
}

fn parse_app_version(value: &str, label: &str) -> Result<semver::Version> {
    let trimmed = value.trim();
    semver::Version::parse(trimmed)
        .with_context(|| format!("{label} must be a semantic version like 0.1.0, got {trimmed:?}"))
}

fn upgrade_required_message(
    model_id: &str,
    min_app_version: &str,
    installed_app_version: &str,
) -> String {
    format!(
        "upgrade required: model {model_id} requires Mayhem >= {min_app_version}; installed {installed_app_version}; run `mayhem update`"
    )
}

fn version_gate_summary(action: &str, gates: &[ModelVersionGate]) -> String {
    if gates.len() == 1 {
        return format!(
            "{}; this node cannot {action} it until upgraded",
            gates[0].message
        );
    }
    let installed = gates
        .first()
        .map(|gate| gate.installed_app_version.clone())
        .unwrap_or_else(|| installed_app_version().to_owned());
    let details = gates
        .iter()
        .map(|gate| format!("{} >= {}", gate.model_id, gate.min_app_version))
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        "upgrade required: {} models require a newer Mayhem before this node can {action}: {details}; installed {installed}; run `mayhem update`",
        gates.len()
    )
}

fn filter_gateway_models_by_app_version(
    models: Vec<GatewayModel>,
    catalog_doc: &catalog::CatalogDocument,
) -> Result<(Vec<GatewayModel>, Vec<ModelVersionGate>)> {
    let min_versions = catalog_doc
        .models
        .iter()
        .filter_map(|model| {
            model
                .min_app_version
                .as_ref()
                .map(|version| (model.model_id.as_str(), version.as_str()))
        })
        .collect::<BTreeMap<_, _>>();
    let mut allowed = Vec::new();
    let mut blocked = Vec::new();
    for mut model in models {
        if let Some(min_app_version) = min_versions.get(model.id.as_str()).copied() {
            model.mayhem.min_app_version = Some(min_app_version.to_owned());
            if let Some(gate) = model_app_version_gate(&model.id, Some(min_app_version))? {
                blocked.push(gate);
                continue;
            }
        }
        allowed.push(model);
    }
    if allowed.is_empty() && !blocked.is_empty() {
        bail!("{}", version_gate_summary("route", &blocked));
    }
    Ok((allowed, blocked))
}

fn price_sort_key(price: &LedgerPriceRecord) -> (u64, u64, u64, u64) {
    (
        rate_map_cost_basis_per_1k(&price.rate_map),
        text_rate_per_1k_mu(&price.rate_map, INPUT_TOKEN_UNIT),
        text_rate_per_1k_mu(&price.rate_map, OUTPUT_TOKEN_UNIT),
        price.ver,
    )
}

fn same_gateway_price_terms(left: &LedgerPriceRecord, right: &LedgerPriceRecord) -> bool {
    left.ver == right.ver
        && left.denom == right.denom
        && normalize_rate_map(left.rate_map.clone()) == normalize_rate_map(right.rate_map.clone())
}

fn room_matches_enclave(room: &LedgerRoom, enclave: &LedgerEnclave) -> bool {
    room.model_id == enclave.model_id && room.enclave_id.as_ref() == Some(&enclave.enclave_id)
}

fn canonical_room_transport_ok(room: &LedgerRoom) -> bool {
    is_hex_len(&room.room_id, 32) && room.sidechannel == format!("mx/room/{}", room.room_id)
}

fn require_canonical_room_transport(room: &LedgerRoom) -> Result<()> {
    if canonical_room_transport_ok(room) {
        return Ok(());
    }
    bail!(
        "room {} is not a canonical contract room: room_id must be 32 hex chars and sidechannel must equal mx/room/<room_id>",
        room.room_id
    )
}

fn empty_gateway_caps() -> ModelCaps {
    ModelCaps {
        tools: false,
        json: false,
        ctx: 0,
        vision: false,
        image: false,
        video: false,
        audio: false,
        output_modality: None,
        output_modalities: Vec::new(),
    }
}

fn gateway_caps_from_contract(caps: &Value) -> ModelCaps {
    ModelCaps {
        tools: caps.get("tools").and_then(Value::as_bool).unwrap_or(false),
        json: caps.get("json").and_then(Value::as_bool).unwrap_or(false),
        ctx: caps
            .get("ctx")
            .or_else(|| caps.get("ctx_max"))
            .and_then(Value::as_u64)
            .and_then(|ctx| u32::try_from(ctx).ok())
            .unwrap_or(0),
        vision: caps.get("vision").and_then(Value::as_bool).unwrap_or(false),
        image: caps.get("image").and_then(Value::as_bool).unwrap_or(false),
        video: caps.get("video").and_then(Value::as_bool).unwrap_or(false),
        audio: caps.get("audio").and_then(Value::as_bool).unwrap_or(false),
        output_modality: caps
            .get("output_modality")
            .and_then(Value::as_str)
            .map(str::to_owned),
        output_modalities: caps_output_modalities(caps),
    }
}

fn caps_output_modalities(caps: &Value) -> Vec<String> {
    if let Some(entries) = caps.get("output_modalities").and_then(Value::as_array) {
        return entries
            .iter()
            .filter_map(Value::as_str)
            .filter(|modality| !modality.is_empty())
            .map(str::to_owned)
            .collect();
    }
    caps.get("output_modality")
        .and_then(Value::as_str)
        .filter(|modality| !modality.is_empty())
        .map(|modality| vec![modality.to_owned()])
        .unwrap_or_default()
}

fn enclave_cap_u32(caps: &Value, key: &'static str, default: u32) -> Result<u32> {
    match caps.get(key) {
        None => Ok(default),
        Some(value) => value
            .as_u64()
            .and_then(|value| u32::try_from(value).ok())
            .filter(|value| *value > 0)
            .with_context(|| format!("enclave caps {key} must be a positive u32")),
    }
}

fn enclave_tp_degree(caps: &Value) -> Result<u32> {
    enclave_cap_u32(caps, "tp_degree", 1)
}

fn enclave_max_batch_size(caps: &Value) -> Result<Option<u32>> {
    match caps.get("max_batch_size") {
        None => Ok(None),
        Some(_) => Ok(Some(enclave_cap_u32(caps, "max_batch_size", 1)?)),
    }
}

fn enclave_max_num_tokens(caps: &Value) -> Result<Option<u32>> {
    match caps.get("max_num_tokens") {
        None => Ok(None),
        Some(_) => Ok(Some(enclave_cap_u32(caps, "max_num_tokens", 1)?)),
    }
}

fn tensor_parallel_capable_gpu_count(hardware: &HardwareReport) -> usize {
    hardware
        .gpus
        .iter()
        .filter(|gpu| gpu.supports_tensor_parallel)
        .count()
}

fn merge_model_caps(target: &mut ModelCaps, next: &ModelCaps) {
    target.tools |= next.tools;
    target.json |= next.json;
    target.vision |= next.vision;
    target.ctx = target.ctx.max(next.ctx);
}

fn usize_to_u32(value: usize) -> u32 {
    u32::try_from(value).unwrap_or(u32::MAX)
}

fn build_provider_candidates(
    contract: &ContractCatalog,
    catalog_doc: &catalog::CatalogDocument,
    hardware: &HardwareReport,
    args: &ProviderStartArgs,
) -> Result<Vec<ProviderCandidate>> {
    let requested_backend = requested_backend(args, hardware)?;
    let requested_enclave = args.enclave.as_deref();
    let mut candidates = Vec::new();
    let mut rejections = Vec::new();
    let mut version_gates = BTreeMap::new();
    for enclave in contract.enclaves.iter().filter(|enclave| {
        enclave.status == "active" && admin_role_marker_ok(enclave.created_by_role.as_deref())
    }) {
        if let Some(requested) = &requested_backend {
            if &enclave.backend != requested {
                rejections.push(provider_rejection(
                    enclave,
                    format!(
                        "requested backend {requested}, but enclave uses {}",
                        enclave.backend
                    ),
                    None,
                ));
                continue;
            }
        }
        if enclave.att_tier > hardware.tee.tier {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "attestation tier mismatch: enclave requires tier {}, local hardware reports tier {}",
                    enclave.att_tier, hardware.tee.tier
                ),
                None,
            ));
            continue;
        }
        let Some(model) = catalog_doc
            .models
            .iter()
            .find(|model| model.model_id == enclave.model_id)
        else {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "model {} is not present in the signed admin catalog",
                    enclave.model_id
                ),
                None,
            ));
            continue;
        };
        if enclave.model_class != model.model_class {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "model_class mismatch: ledger has {}, signed catalog has {}",
                    enclave.model_class, model.model_class
                ),
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        }
        if let Some(gate) =
            model_app_version_gate(&model.model_id, model.min_app_version.as_deref())?
        {
            if args
                .enclave
                .as_deref()
                .is_some_and(|requested| requested_provider_enclave_matches(requested, enclave))
            {
                bail!("{}", gate.message);
            }
            version_gates
                .entry(gate.model_id.clone())
                .or_insert_with(|| gate.clone());
            rejections.push(provider_rejection(
                enclave,
                gate.message.clone(),
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        }
        let Some(verdict) = hardware
            .backend_verdicts
            .iter()
            .find(|verdict| verdict.backend == enclave.backend)
        else {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "backend {} is not reported by hwprobe on this host",
                    enclave.backend
                ),
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        };
        if verdict.status == VerdictStatus::Insufficient {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "{}; {}",
                    backend_requirement_hint(&enclave.backend),
                    verdict
                        .reason
                        .as_deref()
                        .unwrap_or("hwprobe marked this backend insufficient")
                ),
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        }
        if enclave.backend == "trt-llm" {
            let Ok(tp_degree) = enclave_tp_degree(&enclave.caps) else {
                rejections.push(provider_rejection(
                    enclave,
                    "trt-llm enclave caps are missing a valid tp_degree".to_owned(),
                    compatible_catalog_artifact_suggestion(model, hardware, None),
                ));
                continue;
            };
            if tp_degree > 1
                && tensor_parallel_capable_gpu_count(hardware)
                    < usize::try_from(tp_degree).unwrap_or(usize::MAX)
            {
                rejections.push(provider_rejection(
                    enclave,
                    format!(
                        "tensor-parallel mismatch: enclave requires tp_degree {tp_degree}, local hardware has {} matching tensor-parallel GPU(s)",
                        tensor_parallel_capable_gpu_count(hardware)
                    ),
                    compatible_catalog_artifact_suggestion(model, hardware, None),
                ));
                continue;
            }
        }
        let Some((artifact_name, artifact)) =
            select_catalog_artifact(model, &enclave.backend, hardware)
        else {
            let backend_artifacts = model
                .artifacts
                .iter()
                .filter(|(_, artifact)| artifact.engine == enclave.backend)
                .map(|(name, artifact)| {
                    let compatibility =
                        artifact_hardware_compatibility(model, name, artifact, hardware);
                    format!("{name}: {}", compatibility.reason)
                })
                .collect::<Vec<_>>();
            let reason = if backend_artifacts.is_empty() {
                format!(
                    "signed catalog has no artifact for backend {} on model {}",
                    enclave.backend, model.model_id
                )
            } else {
                format!(
                    "no local-compatible artifact for backend {} on model {}; {}",
                    enclave.backend,
                    model.model_id,
                    backend_artifacts.join("; ")
                )
            };
            rejections.push(provider_rejection(
                enclave,
                reason,
                compatible_catalog_artifact_suggestion(model, hardware, None),
            ));
            continue;
        };
        if !ledger_enclave_matches_catalog_artifact(enclave, &artifact) {
            rejections.push(provider_rejection(
                enclave,
                format!(
                    "ledger artifact binding does not match signed catalog artifact {artifact_name} ({})",
                    artifact.engine
                ),
                compatible_catalog_artifact_suggestion(model, hardware, Some(&artifact_name)),
            ));
            continue;
        }
        let Some(price) = contract
            .prices
            .iter()
            .find(|price| price.enclave_id == enclave.enclave_id)
            .filter(|price| current_mu_usd_price(price).is_some())
            .cloned()
        else {
            rejections.push(provider_rejection(
                enclave,
                "missing current mu_usd admin price for this enclave".to_owned(),
                None,
            ));
            continue;
        };
        candidates.push(ProviderCandidate {
            enclave: enclave.clone(),
            model: model.clone(),
            artifact_name,
            artifact,
            verdict: verdict.clone(),
            price: Some(price),
        });
    }
    if let Some(requested) = requested_enclave {
        if !candidates
            .iter()
            .any(|candidate| requested_provider_enclave_matches(requested, &candidate.enclave))
        {
            let relevant = rejections
                .iter()
                .filter(|rejection| requested_provider_rejection_matches(requested, rejection))
                .collect::<Vec<_>>();
            if !relevant.is_empty() {
                bail!("{}", provider_rejection_summary(requested, &relevant));
            }
        }
    }
    if candidates.is_empty() {
        if !version_gates.is_empty() {
            let gates = version_gates.into_values().collect::<Vec<_>>();
            bail!("{}", version_gate_summary("serve", &gates));
        }
        if !rejections.is_empty() {
            let relevant = rejections.iter().collect::<Vec<_>>();
            bail!("{}", provider_rejection_summary("auto", &relevant));
        }
        bail!(
            "no feasible active admin-created enclaves with a current mu_usd admin price found in contract state; providers can only join priced enclaves the admin already registered"
        );
    }
    Ok(candidates)
}

fn requested_provider_enclave_matches(requested: &str, enclave: &LedgerEnclave) -> bool {
    if is_32_byte_hex(requested) {
        enclave.enclave_id == requested
    } else {
        enclave.model_id == requested
    }
}

fn provider_rejection(
    enclave: &LedgerEnclave,
    reason: String,
    suggestion: Option<String>,
) -> ProviderCandidateRejection {
    ProviderCandidateRejection {
        enclave_id: enclave.enclave_id.clone(),
        model_id: enclave.model_id.clone(),
        backend: enclave.backend.clone(),
        reason,
        suggestion,
    }
}

fn requested_provider_rejection_matches(
    requested: &str,
    rejection: &ProviderCandidateRejection,
) -> bool {
    if is_32_byte_hex(requested) {
        rejection.enclave_id == requested
    } else {
        rejection.model_id == requested
    }
}

fn provider_rejection_summary(
    requested: &str,
    rejections: &[&ProviderCandidateRejection],
) -> String {
    let mut lines = Vec::new();
    let prefix = if requested == "auto" {
        "no feasible active admin-created enclaves for this hardware".to_owned()
    } else {
        format!("requested enclave/model {requested} is not feasible on this hardware")
    };
    lines.push(prefix);
    for rejection in rejections.iter().take(6) {
        lines.push(format!(
            "- {} via {} (enclave {}): {}",
            rejection.model_id,
            rejection.backend,
            short_hash(&rejection.enclave_id),
            rejection.reason
        ));
        if let Some(suggestion) = &rejection.suggestion {
            lines.push(format!("  suggestion: {suggestion}"));
        }
    }
    if rejections.len() > 6 {
        lines.push(format!(
            "- ... {} more rejected enclave(s)",
            rejections.len() - 6
        ));
    }
    lines.join("\n")
}

fn ledger_enclave_matches_catalog_artifact(
    enclave: &LedgerEnclave,
    artifact: &catalog::CatalogArtifact,
) -> bool {
    enclave.artifact_root == artifact.artifact_root
        && enclave.artifact_root_kind == artifact.artifact_root_kind
        && enclave.artifact_source.kind == artifact.source.kind
        && enclave.artifact_source.repo == artifact.source.repo
        && enclave.artifact_source.revision == artifact.source.revision
        && enclave.artifact_source.path == artifact.path
        && enclave.source_sha256 == artifact.source_sha256
        && ledger_sidecars_match_catalog(&enclave.artifact_sidecars, &artifact.sidecars)
}

fn ledger_sidecars_match_catalog(
    ledger: &BTreeMap<String, LedgerArtifactSidecar>,
    catalog: &BTreeMap<String, catalog::CatalogArtifactSidecar>,
) -> bool {
    ledger.len() == catalog.len()
        && catalog.iter().all(|(name, catalog_sidecar)| {
            ledger.get(name).is_some_and(|ledger_sidecar| {
                ledger_sidecar.source.kind == catalog_sidecar.source.kind
                    && ledger_sidecar.source.repo == catalog_sidecar.source.repo
                    && ledger_sidecar.source.revision == catalog_sidecar.source.revision
                    && ledger_sidecar.source.path == catalog_sidecar.path
                    && ledger_sidecar.path == catalog_sidecar.path
                    && ledger_sidecar.artifact_root == catalog_sidecar.artifact_root
                    && ledger_sidecar.artifact_root_kind == catalog_sidecar.artifact_root_kind
                    && ledger_sidecar.weights_bytes == catalog_sidecar.weights_bytes
                    && ledger_sidecar
                        .source_sha256
                        .eq_ignore_ascii_case(&catalog_sidecar.source_sha256)
            })
        })
}

fn enclave_artifact_sidecar_roots(enclave: &LedgerEnclave) -> BTreeMap<String, String> {
    enclave
        .artifact_sidecars
        .iter()
        .map(|(name, sidecar)| (name.clone(), sidecar.artifact_root.clone()))
        .collect()
}

fn requested_backend(
    args: &ProviderStartArgs,
    hardware: &HardwareReport,
) -> Result<Option<String>> {
    let requested = args.engine_backend.trim();
    if requested.eq_ignore_ascii_case("auto") {
        return Ok(None);
    }
    let valid = hardware
        .backend_verdicts
        .iter()
        .any(|verdict| verdict.backend == requested);
    if !valid {
        bail!("unknown backend {requested}; expected auto or a backend reported by hwprobe");
    }
    Ok(Some(requested.to_owned()))
}

fn select_catalog_artifact(
    model: &catalog::CatalogModel,
    backend: &str,
    hardware: &HardwareReport,
) -> Option<(String, catalog::CatalogArtifact)> {
    let mut artifacts = model
        .artifacts
        .iter()
        .filter(|(_, artifact)| artifact.engine == backend)
        .filter(|(name, artifact)| {
            artifact_hardware_compatibility_base(model, name, artifact, hardware).compatible
        })
        .collect::<Vec<_>>();
    if backend == "trt-llm" {
        let supports_nvfp4 = hardware.gpus.iter().any(|gpu| gpu.supports_nvfp4);
        let preferred = if supports_nvfp4 { "nvfp4" } else { "trt-fp8" };
        if let Some((name, artifact)) = artifacts
            .iter()
            .find(|(name, _)| name.as_str() == preferred)
        {
            return Some(((*name).clone(), (*artifact).clone()));
        }
    }
    artifacts
        .pop()
        .map(|(name, artifact)| (name.clone(), artifact.clone()))
}

fn select_provider_candidate(
    candidates: &[ProviderCandidate],
    requested: Option<&str>,
) -> Result<ProviderCandidate> {
    if let Some(requested) = requested {
        let by_id = is_32_byte_hex(requested);
        return candidates
            .iter()
            .find(|candidate| {
                if by_id {
                    candidate.enclave.enclave_id == requested
                } else {
                    candidate.enclave.model_id == requested
                }
            })
            .cloned()
            .with_context(|| {
                format!(
                    "requested enclave {requested} is not an active feasible admin-created enclave"
                )
            });
    }

    candidates
        .iter()
        .max_by_key(|candidate| backend_rank(&candidate.enclave.backend))
        .cloned()
        .context("no provider candidate available")
}

fn backend_rank(backend: &str) -> u8 {
    match backend {
        "trt-llm" => 3,
        "mlx" => 2,
        "llama.cpp" => 1,
        "stable-diffusion.cpp" | "whisper.cpp" | "piper" => 0,
        _ => 0,
    }
}

fn select_provider_rooms(
    rooms: &[LedgerRoom],
    enclave: &LedgerEnclave,
    requested: &str,
) -> Result<Vec<LedgerRoom>> {
    if requested.trim().eq_ignore_ascii_case("auto") {
        let mut selected = rooms
            .iter()
            .filter(|room| {
                room.status == "open"
                    && admin_role_marker_ok(room.creator_role.as_deref())
                    && canonical_room_transport_ok(room)
                    && room_matches_enclave(room, enclave)
            })
            .cloned()
            .collect::<Vec<_>>();
        selected.sort_by(|a, b| a.room_id.cmp(&b.room_id));
        return Ok(selected);
    }

    let requested_ids = requested
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    if requested_ids.is_empty() {
        bail!("--rooms must be auto or a comma-separated list of room ids");
    }
    let mut selected = Vec::new();
    for room_id in requested_ids {
        let room = rooms
            .iter()
            .find(|room| room.room_id == room_id)
            .with_context(|| format!("room {room_id} is not in contract state"))?;
        if room.status != "open" {
            bail!("room {room_id} is not open");
        }
        require_admin_role_marker("room.creator_role", room.creator_role.as_deref())
            .with_context(|| format!("room {room_id} is not admin-created"))?;
        require_canonical_room_transport(room)?;
        if !room_matches_enclave(room, enclave) {
            bail!(
                "room {room_id} is for model {} / enclave {}, not model {} / enclave {}",
                room.model_id,
                room.enclave_id
                    .as_deref()
                    .unwrap_or("<missing-enclave-room>"),
                enclave.model_id,
                enclave.enclave_id
            );
        }
        selected.push(room.clone());
    }
    Ok(selected)
}

async fn derive_provider_secret(
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
) -> Result<Vec<u8>> {
    let sig = sign_message(
        keypair_path,
        password,
        &format!("mayhem-provider-sealing-v1:{}", wallet.public_key),
    )
    .await?;
    Ok(blake3::hash(sig.as_bytes()).as_bytes().to_vec())
}

async fn download_provider_artifact(
    args: &ProviderStartArgs,
    downloads_dir: &Path,
    selected: &ProviderCandidate,
) -> Result<ProviderArtifactPaths> {
    require_provider_merkle_artifact(selected)?;
    let primary = if let Some(path) = &args.artifact {
        let source = absolutize(path.clone())?;
        let merkle = build_merkle_manifest(&source, args.chunk_size).with_context(|| {
            format!(
                "verifying local admin-approved artifact {}",
                source.display()
            )
        })?;
        if merkle.root != selected.enclave.artifact_root {
            bail!(
                "local artifact root mismatch for {}; expected admin enclave artifact_root {}, got {}",
                source.display(),
                selected.enclave.artifact_root,
                merkle.root
            );
        }
        verify_artifact_sha256(&source, &selected.artifact)?;
        source
    } else {
        let artifact_file = format!(
            "{}-{}",
            safe_path_component(&selected.enclave.enclave_id),
            safe_path_component(&selected.artifact_name)
        );
        let destination = downloads_dir.join(artifact_file);
        if destination.exists() {
            let merkle = build_merkle_manifest(&destination, args.chunk_size)?;
            if merkle.root == selected.enclave.artifact_root
                && artifact_sha256_matches(&destination, &selected.artifact)?
            {
                destination
            } else {
                download_provider_primary_artifact(args, selected, destination)?
            }
        } else {
            download_provider_primary_artifact(args, selected, destination)?
        }
    };

    let mut sidecars = BTreeMap::new();
    for (name, sidecar) in &selected.artifact.sidecars {
        let ledger_sidecar = selected
            .enclave
            .artifact_sidecars
            .get(name)
            .with_context(|| format!("admin enclave is missing catalog sidecar {name}"))?;
        let path = download_provider_sidecar_artifact(
            args,
            downloads_dir,
            selected,
            name,
            sidecar,
            ledger_sidecar,
        )?;
        sidecars.insert(name.clone(), path);
    }

    Ok(ProviderArtifactPaths { primary, sidecars })
}

fn download_provider_primary_artifact(
    args: &ProviderStartArgs,
    selected: &ProviderCandidate,
    destination: PathBuf,
) -> Result<PathBuf> {
    let source = if selected.artifact.source.kind == "huggingface" {
        DownloadSource::Http {
            url: catalog::huggingface_resolve_url(
                &selected.artifact.source,
                &selected.artifact.path,
            )?,
            bearer_token: read_optional_token(args.hf_token_file.as_deref())?,
        }
    } else {
        bail!(
            "unsupported artifact source kind {}; pass --artifact with a local copy that matches the admin enclave artifact_root",
            selected.artifact.source.kind
        );
    };

    let mut request = DownloadRequest::new(source, destination.clone());
    request.chunk_size = args.chunk_size;
    request.expected_merkle_root = Some(selected.enclave.artifact_root.clone());
    download_resumable(&request).with_context(|| {
        format!(
            "downloading and verifying artifact root {}",
            selected.enclave.artifact_root
        )
    })?;
    verify_artifact_sha256(&destination, &selected.artifact)?;
    Ok(destination)
}

fn download_provider_sidecar_artifact(
    args: &ProviderStartArgs,
    downloads_dir: &Path,
    selected: &ProviderCandidate,
    name: &str,
    sidecar: &catalog::CatalogArtifactSidecar,
    ledger_sidecar: &LedgerArtifactSidecar,
) -> Result<PathBuf> {
    if sidecar.artifact_root_kind != "blake3_merkle_v1" {
        bail!(
            "provider serving requires admin sidecar artifact_root_kind blake3_merkle_v1 for {}/{} sidecar {}; catalog has {}",
            selected.model.model_id,
            selected.artifact_name,
            name,
            sidecar.artifact_root_kind
        );
    }
    let artifact_file = format!(
        "{}-{}-{}",
        safe_path_component(&selected.enclave.enclave_id),
        safe_path_component(&selected.artifact_name),
        safe_path_component(name)
    );
    let destination = downloads_dir.join(artifact_file);
    if destination.exists() {
        let merkle = build_merkle_manifest(&destination, args.chunk_size)?;
        if merkle.root == ledger_sidecar.artifact_root
            && file_sha256_hex(&destination)?.eq_ignore_ascii_case(&sidecar.source_sha256)
        {
            return Ok(destination);
        }
    }
    let source = if sidecar.source.kind == "huggingface" {
        DownloadSource::Http {
            url: catalog::huggingface_resolve_url(&sidecar.source, &sidecar.path)?,
            bearer_token: read_optional_token(args.hf_token_file.as_deref())?,
        }
    } else {
        bail!(
            "unsupported sidecar source kind {}; sidecar {name} must be an admin-pinned Hugging Face artifact",
            sidecar.source.kind
        );
    };

    let mut request = DownloadRequest::new(source, destination.clone());
    request.chunk_size = args.chunk_size;
    request.expected_merkle_root = Some(ledger_sidecar.artifact_root.clone());
    download_resumable(&request).with_context(|| {
        format!(
            "downloading and verifying sidecar {name} root {}",
            ledger_sidecar.artifact_root
        )
    })?;
    let actual = file_sha256_hex(&destination)?;
    if !actual.eq_ignore_ascii_case(&sidecar.source_sha256) {
        bail!(
            "sidecar {name} sha256 mismatch for {}; expected admin catalog source_sha256 {}, got {}",
            destination.display(),
            sidecar.source_sha256,
            actual
        );
    }
    Ok(destination)
}

fn require_provider_merkle_artifact(selected: &ProviderCandidate) -> Result<()> {
    if selected.artifact.artifact_root_kind != "blake3_merkle_v1" {
        bail!(
            "provider serving requires admin artifact_root_kind blake3_merkle_v1 for {}/{}; catalog has {}",
            selected.model.model_id,
            selected.artifact_name,
            selected.artifact.artifact_root_kind
        );
    }
    Ok(())
}

fn artifact_sha256_matches(path: &Path, artifact: &catalog::CatalogArtifact) -> Result<bool> {
    let Some(expected) = &artifact.source_sha256 else {
        return Ok(true);
    };
    if path.is_dir() {
        return Ok(true);
    }
    Ok(file_sha256_hex(path)? == expected.to_ascii_lowercase())
}

fn verify_artifact_sha256(path: &Path, artifact: &catalog::CatalogArtifact) -> Result<()> {
    if artifact_sha256_matches(path, artifact)? {
        return Ok(());
    }
    bail!(
        "artifact sha256 mismatch for {}; expected admin catalog source_sha256 {}",
        path.display(),
        artifact.source_sha256.as_deref().unwrap_or("<missing>")
    )
}

fn file_sha256_hex(path: &Path) -> Result<String> {
    let mut file = fs::File::open(path).with_context(|| format!("opening {}", path.display()))?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 1024 * 64];
    loop {
        let read = file
            .read(&mut buffer)
            .with_context(|| format!("reading {}", path.display()))?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

fn sha256_bytes_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

fn read_optional_token(path: Option<&Path>) -> Result<Option<String>> {
    if let Some(path) = path {
        return fs::read_to_string(path)
            .with_context(|| format!("reading token file {}", path.display()))
            .map(|value| Some(value.trim().to_owned()));
    }
    Ok(env::var("HF_TOKEN")
        .ok()
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty()))
}

fn seal_provider_artifact(
    artifact_path: &Path,
    sealed_store: &Path,
    key_context: &KeyContext,
    provider_secret: &[u8],
    chunk_size: usize,
) -> Result<DownloadReport> {
    if sealed_store.join(SEALED_STORE_MANIFEST).exists() {
        let merkle = build_merkle_manifest(artifact_path, chunk_size)?;
        return Ok(DownloadReport {
            destination: artifact_path.to_path_buf(),
            resumed_from: 0,
            bytes_written: 0,
            total_bytes: merkle.total_bytes,
            merkle,
        });
    }

    let mut options = SealOptions::new(
        artifact_path,
        sealed_store,
        key_context.clone(),
        provider_secret.to_vec(),
    );
    options.chunk_size = chunk_size;
    options.expected_merkle_root = Some(key_context.artifact_root.clone());
    let report = seal_artifact(&options)?;
    Ok(DownloadReport {
        destination: report.store_dir,
        resumed_from: 0,
        bytes_written: report.total_bytes,
        total_bytes: report.total_bytes,
        merkle: build_merkle_manifest(artifact_path, chunk_size)?,
    })
}

async fn ensure_provider_registered(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    sim: bool,
) -> Result<Value> {
    let key = format!("prov/{}", wallet.public_key);
    if let Some(existing) = read_state_value(rpc, &key).await? {
        let status = existing.get("status").and_then(Value::as_str).unwrap_or("");
        if status == "active" {
            return Ok(
                json!({ "skipped": true, "reason": "already_registered", "state": existing }),
            );
        }
        bail!("provider registration exists but is not active: {existing}");
    }

    let submitted = submit_provider_lifecycle_feature(
        ProviderLifecycleSubmitContext {
            rpc,
            keypair_path,
            password,
            wallet,
            sim,
        },
        "register_provider",
        None,
        None,
    )
    .await?;
    if sim {
        return Ok(submitted);
    }
    let state = wait_for_state(rpc, &key, |value| {
        value.get("status").and_then(Value::as_str) == Some("active")
    })
    .await?;
    Ok(json!({ "skipped": false, "feature": submitted, "state": state }))
}

async fn ensure_joined_enclave(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    enclave: &LedgerEnclave,
    sim: bool,
) -> Result<Value> {
    let key = format!("serve/{}/{}", wallet.public_key, enclave.enclave_id);
    if let Some(existing) = read_state_value(rpc, &key).await? {
        if existing.get("status").and_then(Value::as_str) == Some("active") {
            return Ok(
                json!({ "skipped": true, "reason": "already_joined_enclave", "state": existing }),
            );
        }
    }
    let submitted = submit_provider_lifecycle_feature(
        ProviderLifecycleSubmitContext {
            rpc,
            keypair_path,
            password,
            wallet,
            sim,
        },
        "join_enclave",
        Some(&enclave.enclave_id),
        None,
    )
    .await?;
    if sim {
        return Ok(submitted);
    }
    let state = wait_for_state(rpc, &key, |value| {
        value.get("status").and_then(Value::as_str) == Some("active")
    })
    .await?;
    Ok(json!({ "skipped": false, "feature": submitted, "state": state }))
}

async fn ensure_joined_rooms(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    enclave: &LedgerEnclave,
    rooms: &[LedgerRoom],
    sim: bool,
) -> Result<Vec<Value>> {
    let mut reports = Vec::new();
    for room in rooms {
        let key = format!(
            "roomserve/{}/{}/{}",
            room.room_id, wallet.public_key, enclave.enclave_id
        );
        if let Some(existing) = read_state_value(rpc, &key).await? {
            if existing.get("status").and_then(Value::as_str) == Some("active") {
                reports.push(json!({
                    "room_id": room.room_id,
                    "skipped": true,
                    "reason": "already_joined_room",
                    "state": existing,
                }));
                continue;
            }
        }
        let submitted = submit_provider_lifecycle_feature(
            ProviderLifecycleSubmitContext {
                rpc,
                keypair_path,
                password,
                wallet,
                sim,
            },
            "join_room",
            Some(&enclave.enclave_id),
            Some(&room.room_id),
        )
        .await?;
        if sim {
            reports.push(json!({ "room_id": room.room_id, "feature": submitted }));
            continue;
        }
        let state = wait_for_state(rpc, &key, |value| {
            value.get("status").and_then(Value::as_str) == Some("active")
        })
        .await?;
        reports.push(
            json!({ "room_id": room.room_id, "skipped": false, "feature": submitted, "state": state }),
        );
    }
    Ok(reports)
}

async fn submit_contract_command(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    wallet: &WalletInfo,
    tx_type: &str,
    value: Value,
    sim: bool,
) -> Result<Value> {
    let prepared_command = json!({
        "type": tx_type,
        "value": value,
    });
    let nonce_response = rpc
        .contract_nonce()
        .await
        .context("requesting contract nonce")?;
    let nonce = nonce_response
        .get("nonce")
        .and_then(Value::as_str)
        .context("RPC nonce response did not include nonce")?;
    let prepared = rpc
        .prepare_tx(json!({
            "prepared_command": prepared_command.clone(),
            "address": wallet.public_key,
            "nonce": nonce,
        }))
        .await
        .with_context(|| format!("preparing {tx_type} tx"))?;
    let tx = prepared
        .get("tx")
        .and_then(Value::as_str)
        .context("RPC prepare response did not include tx")?
        .to_owned();
    let command_hash = prepared
        .get("command_hash")
        .and_then(Value::as_str)
        .map(str::to_owned);
    let signature = sign_hex(keypair_path, password, &tx).await?;
    let submitted = rpc
        .submit_tx(json!({
            "tx": tx,
            "prepared_command": prepared_command.clone(),
            "address": wallet.public_key,
            "signature": signature,
            "nonce": nonce,
            "sim": sim,
        }))
        .await
        .with_context(|| format!("submitting {tx_type} tx"))?;
    let result = submitted
        .get("result")
        .cloned()
        .unwrap_or_else(|| submitted.clone());
    let accepted = result.get("ok").and_then(Value::as_bool) == Some(true)
        || (result.get("local").and_then(Value::as_bool) == Some(true)
            && result.get("txo").is_some());
    if !accepted {
        bail!("contract {tx_type} rejected command: {result}");
    }
    Ok(json!({
        "tx": tx,
        "command_hash": command_hash,
        "result": result,
    }))
}

struct ProviderLifecycleSubmitContext<'a> {
    rpc: &'a PeerRpcClient,
    keypair_path: &'a Path,
    password: &'a str,
    wallet: &'a WalletInfo,
    sim: bool,
}

async fn submit_provider_lifecycle_feature(
    ctx: ProviderLifecycleSubmitContext<'_>,
    op: &str,
    enclave_id: Option<&str>,
    room_id: Option<&str>,
) -> Result<Value> {
    let intent = provider_lifecycle_intent(&ctx.wallet.public_key, op, enclave_id, room_id)?;
    let sig = sign_message(
        ctx.keypair_path,
        ctx.password,
        &provider_lifecycle_intent_message(&intent),
    )
    .await?;
    let key = provider_lifecycle_feature_key(&intent)?;
    let value = json!({
        "op": "provider_lifecycle",
        "intent": intent,
        "sig": sig,
    });
    if ctx.sim {
        return Ok(json!({
            "feature": "mayhem",
            "key": key,
            "value": value,
            "sim": true,
            "submitted": false,
        }));
    }
    let submitted = ctx
        .rpc
        .submit_feature(json!({
            "feature": "mayhem",
            "key": key,
            "value": value,
        }))
        .await
        .with_context(|| format!("submitting free provider lifecycle feature {op}"))?;
    if submitted.get("ok").and_then(Value::as_bool) != Some(true) {
        bail!("provider lifecycle feature {op} was not accepted: {submitted}");
    }
    Ok(json!({
        "feature": "mayhem",
        "key": key,
        "value": value,
        "result": submitted,
    }))
}

async fn read_state_value(rpc: &PeerRpcClient, key: &str) -> Result<Option<Value>> {
    let state = rpc
        .state(Some(key), Some(false))
        .await
        .with_context(|| format!("reading {key} from peer RPC"))?;
    Ok(state.get("value").cloned().filter(|value| !value.is_null()))
}

async fn wait_for_state<F>(rpc: &PeerRpcClient, key: &str, predicate: F) -> Result<Value>
where
    F: Fn(&Value) -> bool,
{
    let mut last = Value::Null;
    for _ in 0..120 {
        last = read_state_value(rpc, key).await?.unwrap_or(Value::Null);
        if predicate(&last) {
            return Ok(last);
        }
        sleep(Duration::from_millis(500)).await;
    }
    bail!("timed out waiting for {key}; last value: {last}");
}

async fn emit_provider_heartbeats(ctx: HeartbeatContext<'_>) -> Result<Vec<Value>> {
    let sc_bridge_url = ctx.args.sc_bridge_url.clone().or_else(|| {
        ctx.config
            .as_ref()
            .and_then(|config| config.network.as_ref())
            .and_then(|network| network.sc_bridge_url.clone())
    });
    let sc_bridge_token = ctx.args.sc_bridge_token.clone().or_else(|| {
        ctx.config
            .as_ref()
            .and_then(|config| config.network.as_ref())
            .and_then(|network| network.sc_bridge_token.clone())
    });
    let (Some(url), Some(token)) = (sc_bridge_url, sc_bridge_token) else {
        provider_log(
            ctx.args,
            "SC-Bridge URL/token not configured; skipping live heartbeat send",
        );
        return Ok(Vec::new());
    };
    let mut bridge = ScBridgeClient::connect(ScBridgeConfig::new(url, token)?)
        .await
        .context("connecting to SC-Bridge for provider heartbeats")?;
    let mut sent = Vec::new();
    let count = u64::from(ctx.args.heartbeat_count.max(1));
    for seq in 0..count {
        sent.extend(send_provider_heartbeat_round(&mut bridge, &ctx, seq, seq == 0).await?);
    }
    Ok(sent)
}

async fn send_provider_heartbeat_round(
    bridge: &mut ScBridgeClient,
    ctx: &HeartbeatContext<'_>,
    seq: u64,
    join_rooms: bool,
) -> Result<Vec<Value>> {
    let mut sent = Vec::new();
    let caps = provider_heartbeat_caps(ctx.selected);
    for room in ctx.rooms {
        if join_rooms {
            bridge
                .join(&room.sidechannel)
                .await
                .with_context(|| format!("joining sidechannel {}", room.sidechannel))?;
        }
        let ts = unix_epoch_millis()?;
        let mut heartbeat = json!({
            "t": "hb",
            "v": 1,
            "contract_version": CONTRACT_VERSION,
            "provider": ctx.wallet.public_key,
            "enclave_id": ctx.selected.enclave.enclave_id,
            "model_id": ctx.selected.enclave.model_id,
            "room_id": room.room_id,
            "sat": 0.0,
            "slots": {
                "active": 0,
                "max": ctx.selected.verdict.max_sessions,
            },
            "q": {
                "depth": 0,
                "est_wait_ms": 0,
            },
            "perf": {
                "tok_s": ctx.selected.verdict.est_tok_s,
                "ttft_ms": 0,
            },
            "price_ver": ctx.selected
                .price
                .as_ref()
                .and_then(|price| price.current.as_ref())
                .map(|price| price.ver)
                .unwrap_or(0),
            "caps": {
                "tools": caps.tools,
                "json": caps.json,
                "ctx": caps.ctx,
                "vision": caps.vision,
            },
            "att": {
                "epoch": ctx.attestation.report.boot_epoch,
                "head": ctx.attestation_head,
            },
            "ts": ts,
            "nonce": blake3::hash(format!("{}:{}:{}:{}", room.room_id, ctx.wallet.public_key, ts, seq).as_bytes()).to_hex().to_string(),
        });
        let signing_payload = String::from_utf8(heartbeat_signing_payload(&heartbeat)?)
            .context("heartbeat signing payload was not UTF-8")?;
        let sig = sign_message(ctx.keypair_path, ctx.password, &signing_payload).await?;
        heartbeat["sig"] = json!(sig);
        bridge
            .send(&room.sidechannel, &heartbeat)
            .await
            .with_context(|| format!("sending heartbeat to {}", room.sidechannel))?;
        sent.push(json!({
            "room_id": room.room_id,
            "sidechannel": room.sidechannel,
            "seq": seq,
        }));
    }
    Ok(sent)
}

fn provider_heartbeat_caps(selected: &ProviderCandidate) -> ModelCaps {
    let mut caps = gateway_caps_from_contract(&selected.enclave.caps);
    if caps.ctx == 0 {
        caps.ctx = u32::try_from(selected.model.caps.ctx_max).unwrap_or(u32::MAX);
    }
    if !backend_supports_tool_calls(&selected.enclave.backend) {
        caps.tools = false;
    }
    caps
}

async fn serve_provider_sessions(
    ctx: ProviderSessionContext<'_>,
    runtime: ProviderSessionRuntime<'_>,
    mut responder: Box<dyn ProviderSessionResponder>,
) -> Result<()> {
    let terms = provider_session_terms(&ctx)?;
    let (sc_bridge_url, sc_bridge_token) = resolve_cli_sc_bridge(
        ctx.args.home.as_ref(),
        ctx.args.sc_bridge_url.as_deref(),
        ctx.args.sc_bridge_token.as_deref(),
    )?;
    provider_session_debug(format!("connecting to SC-Bridge {sc_bridge_url}"));
    let mut bridge = ScBridgeClient::connect(ScBridgeConfig::new(&sc_bridge_url, sc_bridge_token)?)
        .await
        .context("connecting to SC-Bridge for provider session serving")?;
    provider_session_debug("subscribing to all direct session frames");
    let subscription = bridge
        .session_subscribe_all()
        .await
        .context("subscribing to all direct session frames")?;
    if !subscription
        .get("all_sessions")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        bail!("SC-Bridge does not support all-session subscription; update the local Intercom app");
    }
    provider_session_debug("session frame subscription ready");

    provider_log(
        ctx.args,
        &format!(
            "Provider session server listening on {} for enclave {} across {} canonical room(s) with {}",
            sc_bridge_url,
            terms.enclave_id,
            ctx.rooms.len(),
            responder.mode()
        ),
    );

    let no_config = None;
    let heartbeat_ctx = HeartbeatContext {
        args: ctx.args,
        config: &no_config,
        keypair_path: ctx.keypair_path,
        password: ctx.password,
        wallet: ctx.wallet,
        selected: ctx.selected,
        rooms: ctx.rooms,
        attestation: ctx.attestation,
        attestation_head: ctx.attestation_head,
    };
    let heartbeat_enabled = !ctx.args.no_heartbeat && !ctx.rooms.is_empty();
    let mut heartbeat_seq = 0_u64;
    let mut heartbeat_rooms_joined = false;
    let mut next_heartbeat_at = Instant::now();
    let deadline = (ctx.args.serve_sessions_seconds > 0)
        .then(|| Instant::now() + Duration::from_secs(ctx.args.serve_sessions_seconds));
    let mut sessions = HashMap::new();
    loop {
        let now = Instant::now();
        if heartbeat_enabled && now >= next_heartbeat_at {
            send_provider_heartbeat_round(
                &mut bridge,
                &heartbeat_ctx,
                heartbeat_seq,
                !heartbeat_rooms_joined,
            )
            .await?;
            heartbeat_rooms_joined = true;
            heartbeat_seq = heartbeat_seq.saturating_add(1);
            next_heartbeat_at = Instant::now() + Duration::from_secs(2);
        }
        let mut wait = deadline
            .map(|deadline| deadline.saturating_duration_since(Instant::now()))
            .filter(|remaining| !remaining.is_zero())
            .unwrap_or_else(|| Duration::from_secs(1));
        if heartbeat_enabled {
            let heartbeat_wait = next_heartbeat_at.saturating_duration_since(Instant::now());
            if heartbeat_wait < wait {
                wait = heartbeat_wait;
            }
        }
        if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
            break;
        }
        if wait.is_zero() {
            continue;
        }
        match bridge.next_session_frame(wait).await {
            Ok(event) => {
                let frame_type = event
                    .get("frame")
                    .and_then(|frame| frame.get("t"))
                    .and_then(Value::as_str)
                    .unwrap_or("frame");
                provider_session_debug(format!(
                    "received session event {} type {frame_type}",
                    event
                        .get("session_id")
                        .and_then(Value::as_str)
                        .unwrap_or("")
                ));
                handle_provider_session_frame(
                    &mut bridge,
                    &mut sessions,
                    &terms,
                    &runtime,
                    responder.as_mut(),
                    event,
                )
                .await?;
            }
            Err(BridgeError::Timeout) => {
                if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
                    break;
                }
            }
            Err(err) => return Err(err).context("reading provider session frame"),
        }
    }
    Ok(())
}

async fn handle_provider_session_frame(
    bridge: &mut ScBridgeClient,
    sessions: &mut HashMap<String, ActiveProviderSession>,
    terms: &ProviderSessionTerms,
    runtime: &ProviderSessionRuntime<'_>,
    responder: &mut dyn ProviderSessionResponder,
    event: Value,
) -> Result<()> {
    let frame = event.get("frame").cloned().unwrap_or(Value::Null);
    let session_id = event
        .get("session_id")
        .and_then(Value::as_str)
        .or_else(|| frame.get("session_id").and_then(Value::as_str))
        .unwrap_or("")
        .to_owned();
    let remote = event
        .get("remote")
        .and_then(Value::as_str)
        .filter(|remote| !remote.is_empty())
        .context("provider session frame missing remote peer")?
        .to_owned();
    match frame.get("t").and_then(Value::as_str) {
        Some("s.open") => {
            provider_session_debug(format!(
                "handling s.open for session {session_id} from {remote}"
            ));
            provider_session_debug(format!("opening provider side of session {session_id}"));
            bridge
                .session_open(&remote, &session_id)
                .await
                .context("opening provider side direct session")?;
            provider_session_debug(format!("provider side session {session_id} opened"));
            let session_rail = provider_session_frame_rail(&frame).unwrap_or_default();
            let static_decision = provider_session_open_decision(&frame, terms);
            let decision = match static_decision {
                ProviderSessionDecision::Accept => {
                    provider_session_debug("s.open static decision accepted; rechecking contract");
                    let live_decision = provider_session_current_state_decision(
                        runtime.rpc,
                        terms,
                        runtime.rooms,
                        &session_rail,
                    )
                    .await?;
                    match live_decision {
                        ProviderSessionDecision::Accept => {
                            provider_session_spend_reservation_decision(
                                runtime.rpc,
                                runtime.keypair_path,
                                runtime.password,
                                terms,
                                &frame,
                                &session_rail,
                            )
                            .await?
                        }
                        reject => reject,
                    }
                }
                reject => reject,
            };
            match decision {
                ProviderSessionDecision::Accept => {
                    provider_session_debug(format!("sending s.accept for session {session_id}"));
                    sessions.insert(
                        session_id.clone(),
                        ActiveProviderSession {
                            remote: remote.clone(),
                            rail: session_rail.to_owned(),
                            user_pubkey: frame
                                .get("user")
                                .and_then(Value::as_str)
                                .unwrap_or_default()
                                .to_owned(),
                            session_id: session_id.clone(),
                        },
                    );
                    let ts = unix_epoch_millis()?;
                    let open_head =
                        session_frame_head(&frame).context("hashing s.open frame for s.accept")?;
                    let att_nonce = frame
                        .get("att_nonce")
                        .and_then(Value::as_str)
                        .context("accepted s.open missing validated att_nonce")?;
                    let session_attestation =
                        provider_session_attestation(runtime, terms, att_nonce)
                            .await
                            .context("building per-session s.accept attestation")?;
                    let mut accept_frame = json!({
                        "t": "s.accept",
                        "v": 1,
                        "contract_version": terms.contract_version,
                        "session_id": session_id,
                        "open_head": open_head,
                        "att_nonce": att_nonce,
                        "att_report": session_attestation.report,
                        "engine": {
                            "ctx": terms.ctx,
                            "mode": "provider-session-server-v1",
                        },
                        "ts": ts,
                        "nonce": stable_value_hash(&json!({
                            "session_id": frame.get("session_id"),
                            "provider": terms.provider,
                            "kind": "accept",
                            "ts": ts,
                        })),
                    });
                    let accept_payload = session_accept_signing_bytes(&accept_frame)
                        .context("building s.accept signing payload")?;
                    let accept_sig = sign_hex(
                        runtime.keypair_path,
                        runtime.password,
                        &hex_encode(&accept_payload),
                    )
                    .await
                    .context("signing s.accept")?;
                    accept_frame["sig"] = json!(accept_sig);
                    bridge
                        .session_send(&remote, &session_id, accept_frame)
                        .await
                        .context("sending s.accept")?;
                    provider_session_debug(format!("sent s.accept for session {session_id}"));
                }
                ProviderSessionDecision::Reject { code, reason } => {
                    provider_session_debug(format!(
                        "sending s.reject {code} for session {session_id}: {reason}"
                    ));
                    bridge
                        .session_send(
                            &remote,
                            &session_id,
                            json!({
                                "t": "s.reject",
                                "v": 1,
                                "expected_contract_version": terms.contract_version,
                                "session_id": session_id,
                                "code": code,
                                "reason": reason,
                                "retry_after_ms": 0,
                                "alt_rooms": [],
                            }),
                        )
                        .await
                        .context("sending s.reject")?;
                    provider_session_debug(format!("sent s.reject for session {session_id}"));
                }
            }
        }
        Some("s.req") => {
            provider_session_debug(format!("handling s.req for session {session_id}"));
            let Some(active) = sessions.get(&session_id).cloned() else {
                provider_session_debug(format!(
                    "closing unknown session {session_id} after s.req from {remote}"
                ));
                send_provider_session_close(bridge, &remote, &session_id, "err:unknown_session")
                    .await?;
                return Ok(());
            };
            let request_id = frame
                .get("rid")
                .and_then(Value::as_str)
                .filter(|rid| !rid.is_empty())
                .unwrap_or("missing-rid");
            let body = frame.get("body").cloned().unwrap_or(Value::Null);
            provider_session_debug(format!(
                "building response for session {session_id} request {request_id}"
            ));
            let output = match responder.respond(terms, &body) {
                Ok(output) => output,
                Err(err) => {
                    provider_session_debug(format!(
                        "response failed for session {session_id}: {err:#}"
                    ));
                    send_provider_session_error(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        request_id,
                        "provider_response_failed",
                        &err.to_string(),
                    )
                    .await?;
                    send_provider_session_close(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        "err:provider_response_failed",
                    )
                    .await?;
                    sessions.remove(&session_id);
                    return Ok(());
                }
            };
            provider_session_debug(format!(
                "sending response for session {session_id} request {request_id}"
            ));
            let receipt = match send_provider_session_output(
                bridge,
                &active,
                request_id,
                terms,
                &body,
                &output,
                runtime.runtime_keypair,
            )
            .await
            {
                Ok(receipt) => receipt,
                Err(err) => {
                    provider_session_debug(format!(
                        "sending response failed for session {session_id}: {err:#}"
                    ));
                    send_provider_session_error(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        request_id,
                        "provider_send_failed",
                        &err.to_string(),
                    )
                    .await
                    .ok();
                    send_provider_session_close(
                        bridge,
                        &active.remote,
                        &active.session_id,
                        "err:provider_send_failed",
                    )
                    .await
                    .ok();
                    sessions.remove(&session_id);
                    return Ok(());
                }
            };
            provider_session_debug(format!(
                "waiting for receipt ack on session {session_id} request {request_id}"
            ));
            if wait_for_provider_receipt_ack(bridge, &active, &receipt, Duration::from_secs(5))
                .await
                .is_err()
            {
                provider_session_debug(format!(
                    "receipt ack timeout on session {session_id} request {request_id}"
                ));
                send_provider_session_close(
                    bridge,
                    &active.remote,
                    &active.session_id,
                    "err:receipt_ack",
                )
                .await?;
                sessions.remove(&session_id);
                return Ok(());
            }
            provider_session_debug(format!(
                "receipt ack received on session {session_id} request {request_id}"
            ));
            send_provider_session_close(bridge, &active.remote, &active.session_id, "done").await?;
            sessions.remove(&session_id);
        }
        Some("s.close") => {
            sessions.remove(&session_id);
        }
        _ => {}
    }
    Ok(())
}

async fn send_provider_session_output(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    request_id: &str,
    terms: &ProviderSessionTerms,
    body: &Value,
    output: &ProviderSessionOutput,
    runtime_keypair: &RuntimeKeypair,
) -> Result<ProviderSignedSessionReceipt> {
    let mut index = 0_u64;
    if output.tool.is_none() {
        for part in provider_stream_parts(&output.content) {
            provider_session_debug(format!(
                "sending content s.delta #{index} for session {} request {request_id}",
                active.session_id
            ));
            bridge
                .session_send(
                    &active.remote,
                    &active.session_id,
                    json!({
                        "t": "s.delta",
                        "rid": request_id,
                        "i": index,
                        "d": part,
                        "tool": null,
                        "fin": null,
                    }),
                )
                .await
                .context("sending content s.delta")?;
            maybe_provider_session_delta_delay(&active.session_id, request_id, index).await;
            index = index.saturating_add(1);
        }
    }

    for frame in provider_session_artifact_delta_frames(request_id, index, &output.artifacts) {
        provider_session_debug(format!(
            "sending artifact s.delta #{} for session {} request {request_id}",
            frame.get("i").and_then(Value::as_u64).unwrap_or(index),
            active.session_id,
        ));
        bridge
            .session_send(&active.remote, &active.session_id, frame)
            .await
            .context("sending artifact s.delta")?;
        index = index.saturating_add(1);
    }

    provider_session_debug(format!(
        "sending final s.delta #{index} for session {} request {request_id}",
        active.session_id
    ));
    bridge
        .session_send(
            &active.remote,
            &active.session_id,
            json!({
                "t": "s.delta",
                "rid": request_id,
                "i": index,
                "d": "",
                "tool": output.tool.as_ref(),
                "embeddings": output.embeddings.as_ref(),
                "fin": output.finish_reason,
                "usage": output.usage,
                "token_ids": &output.token_ids,
                "artifacts": provider_session_artifact_summaries(&output.artifacts),
            }),
        )
        .await
        .context("sending final s.delta")?;

    let receipt = provider_session_receipt(terms, active, body, output, runtime_keypair)
        .context("building provider session receipt")?;
    provider_session_debug(format!(
        "sending s.receipt seq {} for session {} request {request_id}",
        receipt.body.seq, active.session_id
    ));
    bridge
        .session_send(
            &active.remote,
            &active.session_id,
            json!({
                "t": "s.receipt",
                "v": 1,
                "session_id": &active.session_id,
                "seq": receipt.body.seq,
                "receipt": receipt,
            }),
        )
        .await
        .context("sending s.receipt")?;
    Ok(receipt)
}

fn provider_session_artifact_delta_frames(
    request_id: &str,
    start_index: u64,
    artifacts: &[ProviderSessionArtifact],
) -> Vec<Value> {
    let mut frames = Vec::new();
    let mut index = start_index;
    for artifact in artifacts {
        let total_len = artifact.bytes.len();
        let digest = blake3_bytes_hex(&artifact.bytes);
        if artifact.bytes.is_empty() {
            frames.push(provider_session_artifact_delta_frame(
                request_id,
                index,
                artifact,
                &digest,
                0,
                &[],
                true,
            ));
            index = index.saturating_add(1);
            continue;
        }
        for (chunk_index, chunk) in artifact
            .bytes
            .chunks(PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE)
            .enumerate()
        {
            let offset = chunk_index * PROVIDER_SESSION_ARTIFACT_CHUNK_SIZE;
            let final_chunk = offset + chunk.len() >= total_len;
            frames.push(provider_session_artifact_delta_frame(
                request_id,
                index,
                artifact,
                &digest,
                offset,
                chunk,
                final_chunk,
            ));
            index = index.saturating_add(1);
        }
    }
    frames
}

fn provider_session_artifact_delta_frame(
    request_id: &str,
    index: u64,
    artifact: &ProviderSessionArtifact,
    digest: &str,
    offset: usize,
    chunk: &[u8],
    final_chunk: bool,
) -> Value {
    json!({
        "t": "s.delta",
        "rid": request_id,
        "i": index,
        "d": "",
        "tool": null,
        "fin": null,
        "artifact": {
            "id": artifact.id,
            "content_type": artifact.content_type,
            "encoding": "hex",
            "offset": offset,
            "len": chunk.len(),
            "total_len": artifact.bytes.len(),
            "blake3": digest,
            "data": hex_encode(chunk),
            "final": final_chunk,
        },
    })
}

fn provider_session_artifact_summaries(artifacts: &[ProviderSessionArtifact]) -> Vec<Value> {
    artifacts
        .iter()
        .map(|artifact| {
            json!({
                "id": artifact.id,
                "content_type": artifact.content_type,
                "bytes": artifact.bytes.len(),
                "blake3": blake3_bytes_hex(&artifact.bytes),
            })
        })
        .collect()
}

async fn maybe_provider_session_delta_delay(session_id: &str, request_id: &str, index: u64) {
    let Some(delay) = provider_session_delta_delay() else {
        return;
    };
    if index >= provider_session_delta_delay_count() {
        return;
    }
    provider_session_debug(format!(
        "delaying after content s.delta #{index} for session {session_id} request {request_id} by {}ms",
        delay.as_millis()
    ));
    tokio::time::sleep(delay).await;
}

fn provider_session_delta_delay() -> Option<Duration> {
    let millis = std::env::var("MAYHEM_PROVIDER_SESSION_DELTA_DELAY_MS")
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .unwrap_or(0);
    (millis > 0).then(|| Duration::from_millis(millis.min(60_000)))
}

fn provider_session_delta_delay_count() -> u64 {
    std::env::var("MAYHEM_PROVIDER_SESSION_DELTA_DELAY_COUNT")
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .unwrap_or(1)
}

async fn send_provider_session_error(
    bridge: &mut ScBridgeClient,
    remote: &str,
    session_id: &str,
    request_id: &str,
    code: &str,
    message: &str,
) -> Result<()> {
    bridge
        .session_send(
            remote,
            session_id,
            json!({
                "t": "s.error",
                "v": 1,
                "session_id": session_id,
                "rid": request_id,
                "code": code,
                "message": message,
            }),
        )
        .await
        .with_context(|| format!("sending s.error for {session_id}"))?;
    Ok(())
}

async fn wait_for_provider_receipt_ack(
    bridge: &mut ScBridgeClient,
    active: &ActiveProviderSession,
    receipt: &ProviderSignedSessionReceipt,
    wait: Duration,
) -> Result<ReceiptAck> {
    let deadline = Instant::now() + wait;
    loop {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            bail!(
                "timed out waiting for s.receipt_ack on {}",
                active.session_id
            );
        }
        match bridge.next_session_frame(remaining).await {
            Ok(event) => {
                if event.get("session_id").and_then(Value::as_str)
                    != Some(active.session_id.as_str())
                {
                    continue;
                }
                let frame = event.get("frame").cloned().unwrap_or(Value::Null);
                match frame.get("t").and_then(Value::as_str) {
                    Some("s.receipt_ack") => {
                        return provider_session_receipt_ack_from_frame(&frame, active, receipt);
                    }
                    Some("s.close") => {
                        bail!("session {} closed before s.receipt_ack", active.session_id);
                    }
                    _ => {}
                }
            }
            Err(BridgeError::Timeout) => {
                bail!(
                    "timed out waiting for s.receipt_ack on {}",
                    active.session_id
                );
            }
            Err(err) => return Err(err).context("reading s.receipt_ack"),
        }
    }
}

fn provider_session_receipt_ack_from_frame(
    frame: &Value,
    active: &ActiveProviderSession,
    receipt: &ProviderSignedSessionReceipt,
) -> Result<ReceiptAck> {
    if frame.get("t").and_then(Value::as_str) != Some("s.receipt_ack") {
        bail!("receipt ack frame must have t=s.receipt_ack");
    }
    if frame.get("session_id").and_then(Value::as_str) != Some(active.session_id.as_str()) {
        bail!("receipt ack session_id mismatch");
    }
    let ack = ReceiptAck {
        session_id: active.session_id.clone(),
        seq: frame
            .get("seq")
            .and_then(Value::as_u64)
            .context("receipt ack missing seq")?,
        user_sig: frame
            .get("user_sig")
            .and_then(Value::as_str)
            .context("receipt ack missing user_sig")?
            .to_owned(),
    };
    if ack.seq != receipt.body.seq {
        bail!("receipt ack seq mismatch");
    }
    verify_provider_session_receipt_ack(&ack, &active.user_pubkey, &receipt.body)?;
    Ok(ack)
}

fn verify_provider_session_receipt_ack(
    ack: &ReceiptAck,
    user_pubkey: &str,
    body: &ReceiptBody,
) -> Result<()> {
    let key_bytes = hex_decode_array::<32>(user_pubkey, "receipt ack user pubkey")?;
    let sig_bytes = hex_decode_array::<64>(&ack.user_sig, "receipt ack user signature")?;
    let verifying_key =
        VerifyingKey::from_bytes(&key_bytes).context("invalid receipt ack user pubkey")?;
    let signature = Signature::from_bytes(&sig_bytes);
    let payloads = supported_receipt_signing_bytes(body)?;
    if payloads
        .iter()
        .any(|payload| verifying_key.verify(payload, &signature).is_ok())
    {
        return Ok(());
    }
    bail!("receipt ack user signature failed")
}

async fn send_provider_session_close(
    bridge: &mut ScBridgeClient,
    remote: &str,
    session_id: &str,
    reason: &str,
) -> Result<()> {
    bridge
        .session_send(
            remote,
            session_id,
            json!({
                "t": "s.close",
                "v": 1,
                "session_id": session_id,
                "reason": reason,
            }),
        )
        .await
        .with_context(|| format!("sending s.close for {session_id}"))?;
    Ok(())
}

fn provider_session_receipt(
    terms: &ProviderSessionTerms,
    active: &ActiveProviderSession,
    body: &Value,
    output: &ProviderSessionOutput,
    runtime_keypair: &RuntimeKeypair,
) -> Result<ProviderSignedSessionReceipt> {
    let usage = output.usage.clone();
    let receipt_body = ReceiptBody {
        schema_version: SESSION_RECEIPT_SCHEMA_VERSION,
        session_id: active.session_id.clone(),
        seq: 1,
        final_receipt: true,
        rail: active.rail.clone(),
        user: active.user_pubkey.clone(),
        provider: terms.provider.clone(),
        enclave_id: terms.enclave_id.clone(),
        model_id: terms.model_id.clone(),
        price_ver: terms.price_ver,
        rules_ver: terms.rules_ver,
        usage: usage.clone(),
        mu_owed_cum: provider_session_mu_owed(terms, &usage),
        prompt_hash: provider_session_prompt_hash(body),
        ts: unix_epoch_millis()?,
    };
    let payload = receipt_signing_bytes(&receipt_body).context("building receipt signing bytes")?;
    Ok(ProviderSignedSessionReceipt {
        body: receipt_body,
        enclave_sig: runtime_keypair.sign_hex(&payload),
    })
}

fn provider_session_mu_owed(terms: &ProviderSessionTerms, usage: &ReceiptUsage) -> u64 {
    text_usage_mu(&terms.rate_map, usage)
}

fn provider_session_prompt_hash(body: &Value) -> String {
    blake3::hash(provider_session_prompt_text(body).as_bytes())
        .to_hex()
        .to_string()
}

fn provider_session_prompt_text(body: &Value) -> String {
    if body.get("kind").and_then(Value::as_str) == Some("embedding") {
        return provider_embedding_prompt_text(body);
    }
    if body.get("kind").and_then(Value::as_str) == Some("image_generation") {
        return stable_json_value(body).to_string();
    }
    if matches!(
        body.get("kind").and_then(Value::as_str),
        Some("audio_transcription" | "audio_speech")
    ) {
        return stable_json_value(body).to_string();
    }
    body.get("messages")
        .and_then(Value::as_array)
        .map(|messages| {
            messages
                .iter()
                .map(provider_message_to_text)
                .collect::<Vec<_>>()
                .join("\n")
        })
        .unwrap_or_default()
}

fn provider_embedding_prompt_text(body: &Value) -> String {
    match provider_embedding_input_texts_from_body(body) {
        Ok(inputs) => stable_json_value(&json!({
            "kind": "embedding",
            "input": inputs,
        }))
        .to_string(),
        Err(_) => String::new(),
    }
}

fn provider_embedding_input_texts_from_body(body: &Value) -> Result<Vec<String>> {
    let input = body
        .get("input")
        .context("embedding request missing input")?;
    provider_embedding_input_texts_from_value(input)
}

fn provider_embedding_input_texts_from_value(value: &Value) -> Result<Vec<String>> {
    match value {
        Value::String(text) => {
            if text.is_empty() {
                bail!("embedding input must not be empty");
            }
            Ok(vec![text.clone()])
        }
        Value::Array(items) => {
            if items.is_empty() {
                bail!("embedding input array must not be empty");
            }
            let mut inputs = Vec::with_capacity(items.len());
            for item in items {
                match item {
                    Value::String(text) if !text.is_empty() => inputs.push(text.clone()),
                    Value::String(_) => bail!("embedding input strings must not be empty"),
                    _ => bail!("embedding input must be a string or an array of strings"),
                }
            }
            Ok(inputs)
        }
        _ => bail!("embedding input must be a string or an array of strings"),
    }
}

async fn provider_session_attestation(
    runtime: &ProviderSessionRuntime<'_>,
    terms: &ProviderSessionTerms,
    att_nonce: &str,
) -> Result<Tier1AttestationReport> {
    let report_ts = unix_epoch_seconds()?;
    let draft = prepare_provider_session_attestation(ProviderSessionAttestationInput {
        identity: &runtime.attestation_identity,
        runtime_keypair: runtime.runtime_keypair,
        provider_pubkey: &terms.provider,
        binary_path: runtime.binary_path,
        boot_epoch: runtime.boot_epoch,
        report_ts,
        att_nonce,
        runtime_config: runtime.runtime_config.clone(),
    })?;
    let provider_attestation_sig = sign_hex(
        runtime.keypair_path,
        runtime.password,
        &draft.provider_signing_message_hex,
    )
    .await?;
    finalize_tier1_attestation_report(draft, provider_attestation_sig)
        .context("finalizing per-session provider attestation")
}

struct ProviderSessionAttestationInput<'a> {
    identity: &'a CatalogEnclaveIdentity,
    runtime_keypair: &'a RuntimeKeypair,
    provider_pubkey: &'a str,
    binary_path: &'a Path,
    boot_epoch: u64,
    report_ts: u64,
    att_nonce: &'a str,
    runtime_config: AttestationRuntimeConfig,
}

fn prepare_provider_session_attestation(
    input: ProviderSessionAttestationInput<'_>,
) -> Result<Tier1AttestationDraft> {
    prepare_tier1_attestation_report(&Tier1ExternalProviderAttestationOptions {
        identity: input.identity.clone(),
        runtime_keypair: input.runtime_keypair.clone(),
        provider_pubkey: input.provider_pubkey.to_owned(),
        binary_path: input.binary_path.to_path_buf(),
        boot_epoch: input.boot_epoch,
        report_ts: input.report_ts,
        nonce_u: input.att_nonce.to_owned(),
        runtime_config: input.runtime_config,
    })
    .context("preparing per-session provider attestation")
}

fn provider_session_responder(
    ctx: &ProviderSessionContext<'_>,
) -> Result<Box<dyn ProviderSessionResponder>> {
    if ctx.args.dev_session_shim {
        if !ctx.args.dev_skip_catalog_verify {
            bail!("--dev-session-shim requires --dev-skip-catalog-verify and is never canonical");
        }
        return Ok(Box::new(DeterministicProviderSessionResponder));
    }

    provider_log(
        ctx.args,
        &format!(
            "Loading {} session engine from verified admin artifact {}",
            ctx.selected.artifact.engine,
            ctx.artifact_paths.primary.display()
        ),
    );
    let load_config = provider_engine_load_config(ctx.selected, ctx.artifact_paths)?;
    match ctx.selected.artifact.engine.as_str() {
        "llama.cpp" => {
            let mut backend = mayhem_engine::LlamaCppBackend::new()
                .context("initializing llama.cpp provider session engine")?;
            backend
                .load(load_config)
                .context("loading llama.cpp provider session engine")?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "mlx" => {
            let mut backend = mayhem_engine::MlxBackend::new()
                .context("initializing MLX provider session engine")?;
            backend
                .load(load_config)
                .context("loading MLX provider session engine")?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "trt-llm" => {
            let mut backend = mayhem_engine::TrtLlmBackend::new()
                .context("initializing TensorRT-LLM provider session engine")?;
            backend
                .load(load_config)
                .context("loading TensorRT-LLM provider session engine")?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "stable-diffusion.cpp" => {
            let mut backend = mayhem_engine::StableDiffusionCppBackend::new()
                .context("initializing stable-diffusion.cpp provider session engine")?;
            backend
                .load(load_config)
                .context("loading stable-diffusion.cpp provider session engine")?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "whisper.cpp" => {
            let mut backend = mayhem_engine::WhisperCppBackend::new()
                .context("initializing whisper.cpp provider session engine")?;
            backend
                .load(load_config)
                .context("loading whisper.cpp provider session engine")?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        "piper" => {
            let mut backend = mayhem_engine::PiperBackend::new()
                .context("initializing piper provider session engine")?;
            backend
                .load(load_config)
                .context("loading piper provider session engine")?;
            Ok(Box::new(EngineProviderSessionResponder {
                backend: Box::new(backend),
            }))
        }
        other => bail!(
            "provider session engine for {other} is not wired locally yet; do not serve this enclave until its admin-approved engine adapter is available"
        ),
    }
}

fn provider_engine_load_config(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
) -> Result<LoadConfig> {
    let ctx_size = u32::try_from(selected.model.caps.ctx_max).with_context(|| {
        format!(
            "catalog ctx_max {} for {} exceeds engine ctx_size range",
            selected.model.caps.ctx_max, selected.model.model_id
        )
    })?;
    let mut artifact_path_buf = artifact_paths.primary.clone();
    let mut materialized_trt_engine_dir = None;
    if selected.artifact.engine == "trt-llm" {
        let layout = materialize_trt_llm_artifacts(selected, artifact_paths)?;
        artifact_path_buf = layout.checkpoint_dir;
        materialized_trt_engine_dir = Some(layout.engine_dir);
    }
    let artifact_path = artifact_path_buf.as_path();
    let artifact = match selected.artifact.engine.as_str() {
        "llama.cpp" => ModelArtifact::gguf(artifact_path),
        "mlx" => ModelArtifact::mlx_safetensors(artifact_path),
        "trt-llm" => ModelArtifact::trt_llm_checkpoint(artifact_path),
        "stable-diffusion.cpp" => ModelArtifact::stable_diffusion_checkpoint(artifact_path),
        "whisper.cpp" => ModelArtifact::whisper_ggml(artifact_path),
        "piper" => ModelArtifact::piper_voice(artifact_path),
        other => bail!("unsupported local provider session engine {other}"),
    };
    let artifact = if let Some(sha256) = &selected.artifact.source_sha256 {
        artifact.with_sha256(sha256.clone())
    } else {
        artifact
    };
    let mut config = match selected.artifact.engine.as_str() {
        "llama.cpp" => LoadConfig::gguf(artifact_path),
        "mlx" => LoadConfig::mlx_safetensors(artifact_path),
        "trt-llm" => LoadConfig::trt_llm_checkpoint(artifact_path),
        "stable-diffusion.cpp" => LoadConfig::stable_diffusion_checkpoint(artifact_path),
        "whisper.cpp" => LoadConfig::whisper_ggml(artifact_path),
        "piper" => LoadConfig::piper_voice(artifact_path),
        other => bail!("unsupported local provider session engine {other}"),
    };
    config.artifact = artifact;
    config.ctx_size = ctx_size.max(1);
    config.gpu_layers = selected.verdict.n_layers_gpu;
    if let Some(mmproj_path) = artifact_paths.sidecars.get("mmproj") {
        let sidecar = selected
            .artifact
            .sidecars
            .get("mmproj")
            .context("downloaded mmproj sidecar is missing from selected catalog artifact")?;
        config.vision_projector =
            Some(ModelArtifact::gguf(mmproj_path).with_sha256(sidecar.source_sha256.clone()));
    }
    if let Some(piper_config_path) = artifact_paths.sidecars.get("piper_config") {
        let sidecar =
            selected.artifact.sidecars.get("piper_config").context(
                "downloaded piper_config sidecar is missing from selected catalog artifact",
            )?;
        config.piper_config = Some(
            ModelArtifact::piper_config(piper_config_path)
                .with_sha256(sidecar.source_sha256.clone()),
        );
    }
    if selected.artifact.engine == "trt-llm" {
        config.trt_engine_dir = materialized_trt_engine_dir
            .or_else(|| Some(trt_engine_cache_dir(artifact_path, &selected.artifact_name)));
        config.trt_tensor_parallel = Some(enclave_tp_degree(&selected.enclave.caps)?);
        if let Some(max_batch_size) = enclave_max_batch_size(&selected.enclave.caps)? {
            config.batch_size = max_batch_size;
        }
        if let Some(max_num_tokens) = enclave_max_num_tokens(&selected.enclave.caps)? {
            config.ubatch_size = max_num_tokens.max(config.ctx_size);
        }
        config.trt_kv_cache_dtype =
            trt_kv_cache_dtype_for_artifact(&selected.artifact_name, &selected.artifact);
        config.trt_require_engine_dir = true;
    }
    Ok(config)
}

struct TrtLlmMaterializedLayout {
    checkpoint_dir: PathBuf,
    engine_dir: PathBuf,
}

fn materialize_trt_llm_artifacts(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
) -> Result<TrtLlmMaterializedLayout> {
    let checkpoint_dir = if artifact_paths.primary.is_dir() {
        artifact_paths.primary.clone()
    } else {
        let checkpoint_dir =
            trt_checkpoint_cache_dir(&artifact_paths.primary, &selected.artifact_name);
        fs::create_dir_all(&checkpoint_dir).with_context(|| {
            format!(
                "creating TensorRT-LLM checkpoint layout {}",
                checkpoint_dir.display()
            )
        })?;
        let payload_name = catalog_path_file_name(
            &selected.artifact.path,
            "TensorRT-LLM primary checkpoint artifact",
        )?;
        link_or_copy_file(&artifact_paths.primary, &checkpoint_dir.join(payload_name))?;
        checkpoint_dir
    };

    for (sidecar, filename) in TRT_CHECKPOINT_REQUIRED_SIDECARS {
        materialize_trt_sidecar(
            selected,
            artifact_paths,
            sidecar,
            &checkpoint_dir,
            filename,
            true,
        )?;
    }
    for (sidecar, filename) in TRT_CHECKPOINT_OPTIONAL_SIDECARS {
        materialize_trt_sidecar(
            selected,
            artifact_paths,
            sidecar,
            &checkpoint_dir,
            filename,
            false,
        )?;
    }

    let engine_dir = trt_engine_cache_dir(&artifact_paths.primary, &selected.artifact_name);
    fs::create_dir_all(&engine_dir).with_context(|| {
        format!(
            "creating TensorRT-LLM engine layout {}",
            engine_dir.display()
        )
    })?;
    materialize_trt_sidecar(
        selected,
        artifact_paths,
        TRT_ENGINE_CONFIG_SIDECAR,
        &engine_dir,
        "config.json",
        true,
    )?;
    let tp_degree = enclave_tp_degree(&selected.enclave.caps)?;
    for rank in 0..tp_degree {
        let sidecar = format!("trt_engine_rank{rank}");
        let filename = format!("rank{rank}.engine");
        materialize_trt_sidecar(
            selected,
            artifact_paths,
            &sidecar,
            &engine_dir,
            &filename,
            true,
        )?;
    }

    Ok(TrtLlmMaterializedLayout {
        checkpoint_dir,
        engine_dir,
    })
}

fn materialize_trt_sidecar(
    selected: &ProviderCandidate,
    artifact_paths: &ProviderArtifactPaths,
    sidecar: &str,
    target_dir: &Path,
    filename: &str,
    required: bool,
) -> Result<()> {
    let destination = target_dir.join(filename);
    if destination.is_file() {
        return Ok(());
    }
    let Some(source) = artifact_paths.sidecars.get(sidecar) else {
        if required {
            bail!(
                "TensorRT-LLM artifact {}/{} requires admin catalog sidecar {} -> {}",
                selected.model.model_id,
                selected.artifact_name,
                sidecar,
                filename
            );
        }
        return Ok(());
    };
    link_or_copy_file(source, &destination).with_context(|| {
        format!(
            "materializing TensorRT-LLM sidecar {} at {}",
            sidecar,
            destination.display()
        )
    })
}

fn catalog_path_file_name(path: &str, label: &str) -> Result<String> {
    Path::new(path)
        .file_name()
        .and_then(OsStr::to_str)
        .filter(|name| !name.is_empty())
        .map(ToOwned::to_owned)
        .with_context(|| format!("{label} path {path} has no file name"))
}

fn link_or_copy_file(source: &Path, destination: &Path) -> Result<()> {
    if !source.is_file() {
        bail!("{} is not a file", source.display());
    }
    if let Some(parent) = destination.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    if destination.exists() {
        if same_canonical_path(source, destination) {
            return Ok(());
        }
        fs::remove_file(destination)
            .with_context(|| format!("removing stale {}", destination.display()))?;
    }
    if fs::hard_link(source, destination).is_err() {
        fs::copy(source, destination).with_context(|| {
            format!("copying {} to {}", source.display(), destination.display())
        })?;
    }
    Ok(())
}

fn same_canonical_path(left: &Path, right: &Path) -> bool {
    match (left.canonicalize(), right.canonicalize()) {
        (Ok(left), Ok(right)) => left == right,
        _ => false,
    }
}

fn provider_attestation_runtime_config(
    selected: &ProviderCandidate,
) -> Result<AttestationRuntimeConfig> {
    let ctx = u32::try_from(selected.model.caps.ctx_max).with_context(|| {
        format!(
            "catalog ctx_max {} for {} exceeds attestation runtime config range",
            selected.model.caps.ctx_max, selected.model.model_id
        )
    })?;
    let tp_degree = if selected.artifact.engine == "trt-llm" {
        enclave_tp_degree(&selected.enclave.caps)?
    } else {
        1
    };
    let max_num_tokens =
        enclave_max_num_tokens(&selected.enclave.caps)?.map(|tokens| tokens.max(ctx));
    Ok(AttestationRuntimeConfig {
        model_class: selected.enclave.model_class.clone(),
        backend: selected.artifact.engine.clone(),
        ctx,
        tp_degree,
        max_batch_size: enclave_max_batch_size(&selected.enclave.caps)?,
        max_num_tokens,
    })
}

fn trt_engine_cache_dir(artifact_path: &Path, artifact_name: &str) -> PathBuf {
    let base = if artifact_path.is_dir() {
        artifact_path.to_path_buf()
    } else {
        artifact_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."))
    };
    base.join(".trtllm-engines")
        .join(safe_path_component(artifact_name))
}

fn trt_checkpoint_cache_dir(artifact_path: &Path, artifact_name: &str) -> PathBuf {
    let base = if artifact_path.is_dir() {
        artifact_path.to_path_buf()
    } else {
        artifact_path
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."))
    };
    base.join(".trtllm-checkpoints")
        .join(safe_path_component(artifact_name))
}

fn trt_kv_cache_dtype_for_artifact(
    _artifact_name: &str,
    artifact: &catalog::CatalogArtifact,
) -> Option<String> {
    let mut haystack = String::new();
    if let Some(notes) = &artifact.notes {
        haystack.push_str(&notes.to_ascii_lowercase());
    }
    if haystack.contains("kv_cache_dtype=nvfp4")
        || haystack.contains("kv-cache-dtype=nvfp4")
        || haystack.contains("kv_cache_dtype: nvfp4")
        || haystack.contains("kv-cache-dtype: nvfp4")
    {
        Some("nvfp4".to_owned())
    } else if haystack.contains("kv_cache_dtype=fp8")
        || haystack.contains("kv-cache-dtype=fp8")
        || haystack.contains("kv_cache_dtype: fp8")
        || haystack.contains("kv-cache-dtype: fp8")
    {
        Some("fp8".to_owned())
    } else {
        None
    }
}

fn provider_session_terms(ctx: &ProviderSessionContext<'_>) -> Result<ProviderSessionTerms> {
    let price = ctx
        .selected
        .price
        .as_ref()
        .and_then(current_mu_usd_price)
        .context("selected provider enclave has no current admin price")?;
    Ok(ProviderSessionTerms {
        contract_version: CONTRACT_VERSION,
        provider: ctx.wallet.public_key.clone(),
        enclave_id: ctx.selected.enclave.enclave_id.clone(),
        model_id: ctx.selected.enclave.model_id.clone(),
        adapter: ctx.selected.model.adapter.clone(),
        room_ids: ctx.rooms.iter().map(|room| room.room_id.clone()).collect(),
        price_ver: price.ver,
        rate_map: price.rate_map.clone(),
        rules_ver: ctx.rules.ver,
        ctx: ctx.selected.model.caps.ctx_max,
    })
}

async fn provider_session_current_state_decision(
    rpc: &PeerRpcClient,
    terms: &ProviderSessionTerms,
    startup_rooms: &[LedgerRoom],
    rail: &str,
) -> Result<ProviderSessionDecision> {
    let contract = read_contract_catalog(rpc).await?;
    Ok(provider_session_contract_decision(
        &contract,
        terms,
        startup_rooms,
        rail,
    ))
}

fn provider_session_contract_decision(
    contract: &ContractCatalog,
    terms: &ProviderSessionTerms,
    startup_rooms: &[LedgerRoom],
    rail: &str,
) -> ProviderSessionDecision {
    let reject = |code, reason: String| ProviderSessionDecision::Reject { code, reason };
    if contract.rules.as_ref().map(|rules| rules.ver) != Some(terms.rules_ver) {
        return reject(
            "CONSENT",
            "current contract rules version no longer matches provider startup terms".to_owned(),
        );
    }
    let Some(provider_record) = contract
        .providers
        .iter()
        .find(|provider| provider.provider == terms.provider)
    else {
        return reject(
            "BANNED",
            "provider is no longer active in contract state".to_owned(),
        );
    };
    if provider_record.status != "active" {
        return reject(
            "BANNED",
            "provider is no longer active in contract state".to_owned(),
        );
    }
    if !provider_record
        .accepted_rails
        .iter()
        .any(|accepted| accepted == rail)
    {
        return reject(
            "RAIL",
            format!("provider does not accept the {rail} payment rail in contract state"),
        );
    }
    let Some(enclave) = contract
        .enclaves
        .iter()
        .find(|enclave| enclave.enclave_id == terms.enclave_id)
    else {
        return reject(
            "ENCLAVE",
            "admin enclave is no longer present in contract state".to_owned(),
        );
    };
    if enclave.status != "active" || enclave.model_id != terms.model_id {
        return reject(
            "ENCLAVE",
            "admin enclave is no longer active for this model".to_owned(),
        );
    }
    if !admin_role_marker_ok(enclave.created_by_role.as_deref()) {
        return reject(
            "ENCLAVE",
            "enclave record is explicitly not admin-created".to_owned(),
        );
    }
    if !contract.serves.iter().any(|serve| {
        serve.provider == terms.provider
            && serve.enclave_id == terms.enclave_id
            && serve.status == "active"
    }) {
        return reject(
            "SERVE",
            "provider is no longer actively serving this admin enclave".to_owned(),
        );
    }
    let Some(schedule) = contract
        .prices
        .iter()
        .find(|price| price.enclave_id == terms.enclave_id)
    else {
        return reject(
            "PRICE_VER",
            "admin price schedule is no longer present for this enclave".to_owned(),
        );
    };
    let Some(current_price) = current_mu_usd_price(schedule) else {
        return reject(
            "PRICE_VER",
            "admin price schedule is no longer current mu_usd".to_owned(),
        );
    };
    if current_price.ver != terms.price_ver {
        return reject(
            "PRICE_VER",
            "current admin price version changed after provider startup".to_owned(),
        );
    }

    let startup_room_ids = terms.room_ids.iter().collect::<BTreeSet<_>>();
    let startup_rooms_by_id = startup_rooms
        .iter()
        .map(|room| (room.room_id.as_str(), room))
        .collect::<BTreeMap<_, _>>();
    let live_rooms_by_id = contract
        .rooms
        .iter()
        .map(|room| (room.room_id.as_str(), room))
        .collect::<BTreeMap<_, _>>();
    let has_active_roomserve = contract.roomserve.iter().any(|serving| {
        if serving.provider != terms.provider
            || serving.enclave_id != terms.enclave_id
            || serving.status != "active"
            || !startup_room_ids.contains(&serving.room_id)
        {
            return false;
        }
        let Some(startup_room) = startup_rooms_by_id.get(serving.room_id.as_str()) else {
            return false;
        };
        let Some(live_room) = live_rooms_by_id.get(serving.room_id.as_str()) else {
            return false;
        };
        live_room.status == "open"
            && admin_role_marker_ok(live_room.creator_role.as_deref())
            && admin_role_marker_ok(startup_room.creator_role.as_deref())
            && canonical_room_transport_ok(live_room)
            && canonical_room_transport_ok(startup_room)
            && room_matches_enclave(live_room, enclave)
            && room_matches_enclave(startup_room, enclave)
    });
    if !has_active_roomserve {
        return reject(
            "ROOM",
            "provider is no longer active in any startup canonical room".to_owned(),
        );
    }
    ProviderSessionDecision::Accept
}

async fn provider_session_spend_reservation_decision(
    rpc: &PeerRpcClient,
    keypair_path: &Path,
    password: &str,
    terms: &ProviderSessionTerms,
    frame: &Value,
    rail: &str,
) -> Result<ProviderSessionDecision> {
    let reject = |reason: String| ProviderSessionDecision::Reject {
        code: "BALANCE",
        reason,
    };
    let epoch = active_billing_epoch(rpc).await?;
    let at = unix_epoch_seconds()?;
    let mut value = match provider_session_spend_reservation_value(terms, frame, rail, epoch, at) {
        Ok(value) => value,
        Err(err) => return Ok(reject(format!("invalid spend reservation: {err:#}"))),
    };
    let message = spend_reservation_message(&value);
    let provider_sig = sign_message(keypair_path, password, &message)
        .await
        .context("signing provider spend reservation")?;
    value["provider_sig"] = json!(provider_sig);
    let key = spend_reservation_feature_key(&value)?;
    let submitted = match rpc
        .submit_feature(json!({
            "feature": "mayhem",
            "key": key,
            "value": value,
        }))
        .await
    {
        Ok(submitted) => submitted,
        Err(err) => {
            return Ok(reject(format!(
                "could not reserve user balance on contract before serving: {err}"
            )));
        }
    };
    if submitted.get("ok").and_then(Value::as_bool) == Some(true) {
        return Ok(ProviderSessionDecision::Accept);
    }
    let reason = submitted
        .get("message")
        .and_then(Value::as_str)
        .map(str::to_owned)
        .or_else(|| {
            submitted
                .get("result")
                .and_then(|result| result.get("message"))
                .and_then(Value::as_str)
                .map(str::to_owned)
        })
        .unwrap_or_else(|| submitted.to_string());
    Ok(reject(format!(
        "contract spend reservation rejected before serving: {reason}"
    )))
}

async fn active_billing_epoch(rpc: &PeerRpcClient) -> Result<u64> {
    let updated_epoch = read_state_value(rpc, "epoch/apply/state")
        .await?
        .and_then(|value| value.get("updated_epoch").and_then(Value::as_u64))
        .unwrap_or(0);
    updated_epoch
        .checked_add(1)
        .context("active billing epoch overflowed")
}

fn provider_session_spend_reservation_value(
    terms: &ProviderSessionTerms,
    frame: &Value,
    rail: &str,
    epoch: u64,
    at: u64,
) -> Result<Value> {
    let session_id = frame
        .get("session_id")
        .and_then(Value::as_str)
        .context("s.open missing session_id")?;
    let user = frame
        .get("user")
        .and_then(Value::as_str)
        .context("s.open missing user")?;
    let voucher = frame
        .get("voucher")
        .cloned()
        .context("s.open missing spend voucher")?;
    let max_spend_mu = voucher
        .get("max_spend_mu")
        .and_then(Value::as_u64)
        .context("spend voucher missing max_spend_mu")?;
    Ok(json!({
        "op": "spend_reserve",
        "contract_version": CONTRACT_VERSION,
        "session_id": session_id,
        "epoch": epoch,
        "at": at,
        "rail": rail,
        "user": user,
        "provider": terms.provider,
        "enclave_id": terms.enclave_id,
        "price_ver": terms.price_ver,
        "rules_ver": terms.rules_ver,
        "max_spend_mu": max_spend_mu,
        "voucher": voucher,
        "provider_sig": "",
    }))
}

fn spend_reservation_evidence(value: &Value) -> Value {
    json!({
        "contract_version": value.get("contract_version").cloned().unwrap_or(Value::Null),
        "session_id": value.get("session_id").cloned().unwrap_or(Value::Null),
        "epoch": value.get("epoch").cloned().unwrap_or(Value::Null),
        "at": value.get("at").cloned().unwrap_or(Value::Null),
        "rail": value.get("rail").cloned().unwrap_or(Value::Null),
        "user": value.get("user").cloned().unwrap_or(Value::Null),
        "provider": value.get("provider").cloned().unwrap_or(Value::Null),
        "enclave_id": value.get("enclave_id").cloned().unwrap_or(Value::Null),
        "price_ver": value.get("price_ver").cloned().unwrap_or(Value::Null),
        "rules_ver": value.get("rules_ver").cloned().unwrap_or(Value::Null),
        "max_spend_mu": value.get("max_spend_mu").cloned().unwrap_or(Value::Null),
        "voucher": stable_json_value(value.get("voucher").unwrap_or(&Value::Null)),
    })
}

fn spend_reservation_message(value: &Value) -> String {
    format!(
        "mayhem-spend-reservation-v1{}",
        stable_json_value(&spend_reservation_evidence(value))
    )
}

fn spend_reservation_feature_key(value: &Value) -> Result<String> {
    let rail = value
        .get("rail")
        .and_then(Value::as_str)
        .context("spend reservation missing rail")?;
    let user = value
        .get("user")
        .and_then(Value::as_str)
        .context("spend reservation missing user")?;
    let epoch = value
        .get("epoch")
        .and_then(Value::as_u64)
        .context("spend reservation missing epoch")?;
    let session_id = value
        .get("session_id")
        .and_then(Value::as_str)
        .context("spend reservation missing session_id")?;
    let digest = stable_value_hash(&json!({
        "domain": "mayhem-spend-reservation-feature-v1",
        "value": spend_reservation_evidence(value),
    }));
    Ok(format!(
        "hold/reserve/{rail}/{user}/{epoch}/{session_id}/{digest}"
    ))
}

fn provider_session_open_decision(
    frame: &Value,
    terms: &ProviderSessionTerms,
) -> ProviderSessionDecision {
    let reject = |code, reason: String| ProviderSessionDecision::Reject { code, reason };
    if frame.get("t").and_then(Value::as_str) != Some("s.open") {
        return reject("SCHEMA", "session open frame must have t=s.open".to_owned());
    }
    let actual_contract_version = frame_contract_version(frame);
    if actual_contract_version != Some(terms.contract_version) {
        return reject(
            "UPGRADE_REQUIRED",
            contract_upgrade_required_reason(terms.contract_version, actual_contract_version),
        );
    }
    let session_id = frame
        .get("session_id")
        .and_then(Value::as_str)
        .unwrap_or("");
    if !is_hex_len(session_id, 64) {
        return reject("SCHEMA", "session_id must be 32 bytes of hex".to_owned());
    }
    let user = frame.get("user").and_then(Value::as_str).unwrap_or("");
    if !is_hex_len(user, 64) {
        return reject("USER", "session user must be 32 bytes of hex".to_owned());
    }
    let att_nonce = frame.get("att_nonce").and_then(Value::as_str).unwrap_or("");
    if !is_hex_len(att_nonce, 64) {
        return reject(
            "ATTESTATION",
            "att_nonce must be 32 bytes of hex".to_owned(),
        );
    }
    if frame.get("enclave_id").and_then(Value::as_str) != Some(terms.enclave_id.as_str()) {
        return reject(
            "ENCLAVE",
            "session enclave_id is not this admin-created enclave".to_owned(),
        );
    }
    if frame.get("price_ver").and_then(Value::as_u64) != Some(terms.price_ver) {
        return reject(
            "PRICE_VER",
            "session price_ver does not match the current admin price".to_owned(),
        );
    }
    if frame.get("rules_ver").and_then(Value::as_u64) != Some(terms.rules_ver) {
        return reject(
            "CONSENT",
            "session rules_ver does not match current rules".to_owned(),
        );
    }
    let rail = provider_session_frame_rail(frame).unwrap_or("");
    if !matches!(rail, "fiat" | "tap" | "tnk") {
        return reject(
            "RAIL",
            "session rail must be one of fiat, tap, or tnk".to_owned(),
        );
    }
    let voucher = match frame
        .get("voucher")
        .cloned()
        .ok_or_else(|| anyhow::anyhow!("missing voucher"))
        .and_then(|voucher| {
            serde_json::from_value::<SpendVoucher>(voucher).context("invalid spend voucher")
        }) {
        Ok(voucher) => voucher,
        Err(err) => return reject("VOUCHER", format!("{err:#}")),
    };
    if voucher.body.session_id.as_str() != session_id {
        return reject("VOUCHER", "voucher session_id mismatch".to_owned());
    }
    if voucher.body.rail.as_str() != rail {
        return reject("VOUCHER", "voucher rail mismatch".to_owned());
    }
    if voucher.body.enclave_id.as_str() != terms.enclave_id.as_str() {
        return reject("VOUCHER", "voucher enclave_id mismatch".to_owned());
    }
    if voucher.body.price_ver != terms.price_ver {
        return reject("VOUCHER", "voucher price_ver mismatch".to_owned());
    }
    if voucher.body.max_spend_mu == 0 {
        return reject(
            "BALANCE",
            "voucher max_spend_mu must be positive".to_owned(),
        );
    }
    if frame.get("sig").and_then(Value::as_str) != Some(voucher.user_sig.as_str()) {
        return reject(
            "SIGNATURE",
            "session open signature must match voucher user_sig".to_owned(),
        );
    }
    if let Err(err) = verify_provider_session_spend_voucher(&voucher, user) {
        return reject("SIGNATURE", format!("{err:#}"));
    }
    ProviderSessionDecision::Accept
}

fn provider_session_frame_rail(frame: &Value) -> Option<&str> {
    frame.get("rail").and_then(Value::as_str)
}

fn frame_contract_version(frame: &Value) -> Option<u32> {
    frame
        .get("contract_version")
        .and_then(Value::as_u64)
        .and_then(|version| u32::try_from(version).ok())
}

fn contract_upgrade_required_reason(expected: u32, actual: Option<u32>) -> String {
    let actual = actual
        .map(|version| version.to_string())
        .unwrap_or_else(|| "missing/legacy".to_owned());
    format!(
        "contract upgrade required: expected CONTRACT_VERSION {expected}, got {actual}; update Mayhem on the out-of-sync node before opening sessions"
    )
}

fn verify_provider_session_spend_voucher(voucher: &SpendVoucher, user_pubkey: &str) -> Result<()> {
    let key_bytes = hex_decode_array::<32>(user_pubkey, "spend voucher user pubkey")?;
    let sig_bytes = hex_decode_array::<64>(&voucher.user_sig, "spend voucher user signature")?;
    let verifying_key =
        VerifyingKey::from_bytes(&key_bytes).context("invalid spend voucher user pubkey")?;
    let signature = Signature::from_bytes(&sig_bytes);
    let payloads = supported_spend_voucher_signing_bytes(&voucher.body)?;
    if payloads
        .iter()
        .any(|payload| verifying_key.verify(payload, &signature).is_ok())
    {
        return Ok(());
    }
    bail!("spend voucher user signature failed")
}

#[derive(Clone, Debug, PartialEq)]
struct ProviderSessionArtifact {
    id: String,
    content_type: String,
    bytes: Vec<u8>,
}

#[derive(Clone, Debug, PartialEq)]
struct ProviderSessionOutput {
    content: String,
    tool: Option<Value>,
    embeddings: Option<Vec<Vec<f32>>>,
    artifacts: Vec<ProviderSessionArtifact>,
    finish_reason: String,
    prompt_tokens: u64,
    completion_tokens: u64,
    token_ids: Vec<i32>,
    usage: ReceiptUsage,
}

fn provider_engine_session_response(
    backend: &mut dyn EngineBackend,
    adapter: &catalog::CatalogAdapter,
    body: &Value,
) -> Result<ProviderSessionOutput> {
    if body.get("kind").and_then(Value::as_str) == Some("audio_transcription") {
        let request = provider_audio_transcription_request_from_body(body)?;
        let audio_seconds = request.audio_seconds;
        let output = backend
            .transcribe(request.engine)
            .context("transcribing provider session audio with mayhem-engine")?;
        return Ok(ProviderSessionOutput {
            content: output.text,
            tool: None,
            embeddings: None,
            artifacts: Vec::new(),
            finish_reason: "stop".to_owned(),
            prompt_tokens: 0,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage: provider_audio_transcription_usage(audio_seconds),
        });
    }

    if body.get("kind").and_then(Value::as_str) == Some("audio_speech") {
        let request = provider_speech_request_from_body(body)?;
        let input_characters = u64::try_from(request.input.chars().count())
            .context("audio_speech input character count overflowed u64")?;
        let mut artifact_chunks = Vec::new();
        let output = backend
            .synthesize_speech(request, &mut |chunk: ArtifactChunk| {
                artifact_chunks.push(chunk);
                Ok(())
            })
            .context("synthesizing provider session speech with mayhem-engine")?;
        let artifacts = provider_session_artifacts_from_chunks(artifact_chunks)?;
        if artifacts.is_empty() {
            bail!("provider speech engine produced no audio artifact");
        }
        return Ok(ProviderSessionOutput {
            content: String::new(),
            tool: None,
            embeddings: None,
            artifacts,
            finish_reason: "stop".to_owned(),
            prompt_tokens: 0,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage: provider_audio_speech_usage(input_characters, output.audio_seconds),
        });
    }

    if body.get("kind").and_then(Value::as_str) == Some("image_generation") {
        let (request, image_count, steps) = provider_image_generation_request_from_body(body)?;
        let mut artifact_chunks = Vec::new();
        let output = backend
            .generate_with_artifacts(
                request,
                &mut |_chunk: mayhem_engine::TokenChunk| Ok(()),
                &mut |chunk: ArtifactChunk| {
                    artifact_chunks.push(chunk);
                    Ok(())
                },
            )
            .context("generating provider session image artifact with mayhem-engine")?;
        let artifacts = provider_session_artifacts_from_chunks(artifact_chunks)?;
        if artifacts.is_empty() {
            bail!("provider image generation engine produced no image artifacts");
        }
        let usage = provider_image_generation_usage(artifacts.len() as u64, steps);
        if artifacts.len() as u32 != image_count {
            bail!(
                "provider image generation engine produced {} artifact(s), expected {image_count}",
                artifacts.len()
            );
        }
        return Ok(ProviderSessionOutput {
            content: String::new(),
            tool: None,
            embeddings: None,
            artifacts,
            finish_reason: output.finish_reason.to_string(),
            prompt_tokens: 0,
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage,
        });
    }

    if body.get("kind").and_then(Value::as_str) == Some("embedding") {
        let inputs = provider_embedding_input_texts_from_body(body)?;
        let dimensions = body
            .get("dimensions")
            .and_then(Value::as_u64)
            .map(|value| usize::try_from(value).context("embedding dimensions overflow usize"))
            .transpose()?;
        let output = backend
            .embed(mayhem_engine::EmbeddingRequest { inputs, dimensions })
            .context("generating provider session embeddings with mayhem-engine")?;
        return Ok(ProviderSessionOutput {
            content: String::new(),
            tool: None,
            embeddings: Some(output.embeddings),
            artifacts: Vec::new(),
            finish_reason: "stop".to_owned(),
            prompt_tokens: u64::from(output.usage.prompt_tokens),
            completion_tokens: 0,
            token_ids: Vec::new(),
            usage: ReceiptUsage::text(u64::from(output.usage.prompt_tokens), 0),
        });
    }

    let tool_mode = provider_engine_tool_request(body, adapter)?.map(|(strategy, _)| strategy);
    let request = provider_engine_request_from_body(body, adapter)?;
    let mut token_ids = Vec::new();
    let mut artifact_chunks = Vec::new();
    let output = backend
        .generate_with_artifacts(
            request,
            &mut |chunk: mayhem_engine::TokenChunk| {
                token_ids.push(chunk.token_id);
                Ok(())
            },
            &mut |chunk: ArtifactChunk| {
                artifact_chunks.push(chunk);
                Ok(())
            },
        )
        .context("generating provider session response with mayhem-engine")?;
    let artifacts = provider_session_artifacts_from_chunks(artifact_chunks)?;
    let tool = if let Some(strategy) = tool_mode {
        Some(
            provider_engine_tool_call_output(&output.text, strategy).with_context(|| {
                format!(
                    "provider engine did not return valid tool-call JSON: {}",
                    output.text.trim()
                )
            })?,
        )
    } else {
        None
    };
    Ok(ProviderSessionOutput {
        usage: ReceiptUsage::text(
            u64::from(output.usage.prompt_tokens),
            u64::from(output.usage.completion_tokens),
        ),
        content: if tool.is_some() {
            String::new()
        } else {
            output.text
        },
        tool,
        embeddings: None,
        artifacts,
        finish_reason: if tool_mode.is_some() {
            "tool_calls".to_owned()
        } else {
            output.finish_reason.to_string()
        },
        prompt_tokens: u64::from(output.usage.prompt_tokens),
        completion_tokens: u64::from(output.usage.completion_tokens),
        token_ids,
    })
}

struct ProviderAudioTranscriptionRequest {
    engine: EngineAudioTranscriptionRequest,
    audio_seconds: u64,
}

fn provider_audio_transcription_request_from_body(
    body: &Value,
) -> Result<ProviderAudioTranscriptionRequest> {
    let audio = body
        .get("audio")
        .context("audio_transcription request missing audio")?;
    let encoding = audio
        .get("encoding")
        .and_then(Value::as_str)
        .unwrap_or("hex");
    if encoding != "hex" {
        bail!("audio_transcription audio.encoding must be hex");
    }
    let bytes_hex = audio
        .get("data")
        .and_then(Value::as_str)
        .filter(|value| !value.is_empty())
        .context("audio_transcription audio.data missing")?;
    let bytes = hex_decode_vec(bytes_hex, "audio_transcription audio.data")?;
    let audio_seconds = body
        .get("audio_seconds")
        .and_then(Value::as_u64)
        .unwrap_or_else(|| wav_duration_seconds_ceil(&bytes).unwrap_or(1));
    Ok(ProviderAudioTranscriptionRequest {
        engine: EngineAudioTranscriptionRequest {
            audio: bytes,
            content_type: audio
                .get("content_type")
                .and_then(Value::as_str)
                .map(str::to_owned),
            language: body
                .get("language")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .map(str::to_owned),
            prompt: body
                .get("prompt")
                .and_then(Value::as_str)
                .filter(|value| !value.is_empty())
                .map(str::to_owned),
        },
        audio_seconds,
    })
}

fn provider_speech_request_from_body(body: &Value) -> Result<SpeechRequest> {
    let input = body
        .get("input")
        .and_then(Value::as_str)
        .filter(|input| !input.trim().is_empty())
        .context("audio_speech request missing input")?
        .to_owned();
    Ok(SpeechRequest {
        input,
        voice: body
            .get("voice")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .map(str::to_owned),
        response_format: Some(
            body.get("response_format")
                .and_then(Value::as_str)
                .unwrap_or("wav")
                .to_owned(),
        ),
        speed: body.get("speed").and_then(Value::as_f64),
    })
}

fn provider_image_generation_request_from_body(
    body: &Value,
) -> Result<(GenerateRequest, u32, u64)> {
    let prompt = body
        .get("prompt")
        .and_then(Value::as_str)
        .filter(|prompt| !prompt.trim().is_empty())
        .context("image_generation request missing prompt")?
        .to_owned();
    let image_count = body
        .get("n")
        .and_then(Value::as_u64)
        .unwrap_or(1)
        .clamp(1, 4);
    let image_count = u32::try_from(image_count).context("image_generation n overflowed u32")?;
    let steps = body
        .get("steps")
        .and_then(Value::as_u64)
        .unwrap_or(1)
        .clamp(1, 150);
    let cfg_scale = body
        .get("cfg_scale")
        .and_then(Value::as_f64)
        .unwrap_or(1.0)
        .clamp(0.0, 50.0) as f32;
    let (width, height) = provider_image_generation_size(body)?;
    let mut request = GenerateRequest::new(prompt);
    request.artifact_count = Some(image_count);
    request.steps = Some(u32::try_from(steps).context("image_generation steps overflowed u32")?);
    request.cfg_scale = Some(cfg_scale);
    request.width = Some(width);
    request.height = Some(height);
    if let Some(seed) = body.get("seed").and_then(Value::as_u64) {
        request.seed = Some(u32::try_from(seed).context("image_generation seed exceeds u32")?);
    }
    Ok((request, image_count, steps))
}

fn provider_image_generation_size(body: &Value) -> Result<(u32, u32)> {
    let size = body
        .get("size")
        .and_then(Value::as_str)
        .unwrap_or("512x512");
    let (width, height) = size
        .split_once('x')
        .context("image_generation size must be WIDTHxHEIGHT")?;
    let width = width
        .parse::<u32>()
        .context("image_generation width is not a positive integer")?;
    let height = height
        .parse::<u32>()
        .context("image_generation height is not a positive integer")?;
    if width == 0 || height == 0 {
        bail!("image_generation dimensions must be greater than zero");
    }
    Ok((width, height))
}

fn provider_image_generation_usage(image_count: u64, steps: u64) -> ReceiptUsage {
    ReceiptUsage::from_units([
        (USAGE_IMAGE, image_count),
        (USAGE_STEP, image_count.saturating_mul(steps)),
    ])
}

fn provider_audio_transcription_usage(audio_seconds: u64) -> ReceiptUsage {
    ReceiptUsage::from_units([(USAGE_AUDIO_SECOND, audio_seconds)])
}

fn provider_audio_speech_usage(input_characters: u64, audio_seconds: u64) -> ReceiptUsage {
    ReceiptUsage::from_units([
        (USAGE_INPUT_CHARACTER, input_characters),
        (USAGE_AUDIO_SECOND, audio_seconds),
    ])
}

fn provider_session_artifacts_from_chunks(
    chunks: Vec<ArtifactChunk>,
) -> Result<Vec<ProviderSessionArtifact>> {
    let mut grouped: BTreeMap<String, Vec<ArtifactChunk>> = BTreeMap::new();
    for chunk in chunks {
        if chunk.artifact_id.trim().is_empty() {
            bail!("provider engine emitted artifact chunk with empty id");
        }
        if chunk.content_type.trim().is_empty() {
            bail!(
                "provider engine emitted artifact {} with empty content type",
                chunk.artifact_id
            );
        }
        grouped
            .entry(chunk.artifact_id.clone())
            .or_default()
            .push(chunk);
    }

    let mut artifacts = Vec::new();
    for (artifact_id, mut chunks) in grouped {
        chunks.sort_by_key(|chunk| chunk.index);
        let content_type = chunks
            .first()
            .map(|chunk| chunk.content_type.clone())
            .unwrap_or_default();
        let mut bytes = Vec::new();
        let mut final_seen = false;
        for (expected, chunk) in chunks.into_iter().enumerate() {
            let expected =
                u32::try_from(expected).context("artifact chunk count overflowed u32")?;
            if chunk.index != expected {
                bail!(
                    "provider engine artifact {artifact_id} chunk index gap: expected {expected}, got {}",
                    chunk.index
                );
            }
            if chunk.content_type != content_type {
                bail!("provider engine artifact {artifact_id} changed content type mid-stream");
            }
            final_seen |= chunk.final_chunk;
            bytes.extend_from_slice(&chunk.bytes);
        }
        if !final_seen {
            bail!("provider engine artifact {artifact_id} missing final chunk marker");
        }
        artifacts.push(ProviderSessionArtifact {
            id: artifact_id,
            content_type,
            bytes,
        });
    }
    Ok(artifacts)
}

fn provider_engine_request_from_body(
    body: &Value,
    adapter: &catalog::CatalogAdapter,
) -> Result<GenerateRequest> {
    let messages = body
        .get("messages")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    let prompt = provider_engine_prompt(messages, adapter)?;
    let mut request = GenerateRequest::new(prompt);
    request.media = provider_engine_media_inputs(messages);
    if let Some(max_tokens) = body
        .get("max_tokens")
        .or_else(|| body.get("max_completion_tokens"))
        .and_then(Value::as_u64)
    {
        request.max_new_tokens = u32::try_from(max_tokens)
            .context("max_tokens exceeds provider engine request range")?;
    }
    if let Some(temperature) = body.get("temperature").and_then(Value::as_f64) {
        request.temperature = Some(temperature as f32);
    }
    if let Some(top_p) = body.get("top_p").and_then(Value::as_f64) {
        request.top_p = Some(top_p as f32);
    }
    if let Some(seed) = body.get("seed").and_then(Value::as_u64) {
        request.seed = Some(u32::try_from(seed).context("seed exceeds u32")?);
    }
    if let Some((strategy, tools)) = provider_engine_tool_request(body, adapter)? {
        match strategy {
            ProviderEngineToolStrategy::MayhemJson => {
                request.grammar = Some(GrammarSpec::ToolCall { tools });
            }
            ProviderEngineToolStrategy::OpenAiToolCalls => {
                request.grammar = Some(GrammarSpec::JsonSchema {
                    schema: provider_openai_tool_calls_json_schema(&tools),
                });
            }
        }
        return Ok(request);
    }
    if provider_wants_json(body) {
        request.grammar = Some(GrammarSpec::JsonSchema {
            schema: provider_response_json_schema(body),
        });
    }
    Ok(request)
}

fn provider_engine_media_inputs(messages: &[Value]) -> Vec<MediaInput> {
    messages
        .iter()
        .filter_map(|message| message.get("content").and_then(Value::as_array))
        .flat_map(|parts| parts.iter())
        .filter_map(provider_content_part_media_input)
        .collect()
}

fn provider_content_part_media_input(part: &Value) -> Option<MediaInput> {
    match part.get("type").and_then(Value::as_str) {
        Some("image_url") => {
            let url = part
                .get("image_url")
                .and_then(|image| image.get("url"))
                .or_else(|| part.get("url"))
                .and_then(Value::as_str)?
                .to_owned();
            Some(MediaInput {
                kind: "image".to_owned(),
                content_type: data_url_content_type(&url),
                url: Some(url),
                data: None,
            })
        }
        Some("input_audio") => {
            let audio = part.get("input_audio")?;
            let data = audio.get("data").and_then(Value::as_str)?.to_owned();
            if data.is_empty() {
                return None;
            }
            let format = audio.get("format").and_then(Value::as_str).unwrap_or("wav");
            Some(MediaInput {
                kind: "audio".to_owned(),
                content_type: Some(audio_content_type(format).to_owned()),
                url: None,
                data: Some(data),
            })
        }
        _ => None,
    }
}

fn data_url_content_type(url: &str) -> Option<String> {
    let rest = url.strip_prefix("data:")?;
    let (content_type, _) = rest.split_once(';')?;
    (!content_type.trim().is_empty()).then(|| content_type.to_owned())
}

fn audio_content_type(format: &str) -> &'static str {
    match format {
        "mp3" => "audio/mpeg",
        "opus" => "audio/ogg",
        "aac" => "audio/aac",
        "flac" => "audio/flac",
        "pcm" => "audio/L16",
        _ => "audio/wav",
    }
}

fn provider_engine_prompt(messages: &[Value], adapter: &catalog::CatalogAdapter) -> Result<String> {
    match adapter.chat_template_id.as_str() {
        "generic_chatml" | "qwen2.5-instruct" => {
            Ok(provider_engine_generic_chatml_prompt(messages, adapter))
        }
        "llama3-instruct" => Ok(provider_engine_llama3_prompt(messages, adapter)),
        "smolvlm2-instruct" => Ok(provider_engine_smolvlm2_prompt(messages, adapter)),
        other => bail!("unsupported catalog adapter.chat_template_id: {other}"),
    }
}

fn provider_engine_generic_chatml_prompt(
    messages: &[Value],
    adapter: &catalog::CatalogAdapter,
) -> String {
    let mut prompt = String::new();
    for message in messages {
        let role = message
            .get("role")
            .and_then(Value::as_str)
            .unwrap_or("user");
        let content = provider_message_to_text_for_adapter(message, adapter);
        let _ = writeln!(prompt, "{role}: {content}");
    }
    prompt.push_str("assistant:");
    prompt
}

fn provider_engine_llama3_prompt(messages: &[Value], adapter: &catalog::CatalogAdapter) -> String {
    let mut prompt = String::new();
    for message in messages {
        let role = message
            .get("role")
            .and_then(Value::as_str)
            .unwrap_or("user");
        let content = provider_message_to_text_for_adapter(message, adapter);
        let _ = write!(
            prompt,
            "<|start_header_id|>{role}<|end_header_id|>\n\n{content}<|eot_id|>"
        );
    }
    prompt.push_str("<|start_header_id|>assistant<|end_header_id|>\n\n");
    prompt
}

fn provider_engine_smolvlm2_prompt(
    messages: &[Value],
    adapter: &catalog::CatalogAdapter,
) -> String {
    let mut prompt = String::new();
    for message in messages {
        let role = smolvlm2_role(
            message
                .get("role")
                .and_then(Value::as_str)
                .unwrap_or("user"),
        );
        let content = provider_message_to_text_for_adapter(message, adapter);
        if provider_message_starts_with_image(message) && adapter_supports_image_input(adapter) {
            let _ = write!(prompt, "<|im_start|>{role}:{content}<end_of_utterance>\n");
        } else {
            let _ = write!(prompt, "<|im_start|>{role}: {content}<end_of_utterance>\n");
        }
    }
    prompt.push_str("Assistant:");
    prompt
}

fn smolvlm2_role(role: &str) -> &'static str {
    match role {
        "assistant" => "Assistant",
        "system" => "System",
        _ => "User",
    }
}

fn provider_message_starts_with_image(message: &Value) -> bool {
    message
        .get("content")
        .and_then(Value::as_array)
        .and_then(|parts| parts.first())
        .and_then(|part| part.get("type"))
        .and_then(Value::as_str)
        == Some("image_url")
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ProviderEngineToolStrategy {
    MayhemJson,
    OpenAiToolCalls,
}

fn provider_engine_tool_request(
    body: &Value,
    adapter: &catalog::CatalogAdapter,
) -> Result<Option<(ProviderEngineToolStrategy, Vec<ToolSpec>)>> {
    if body.get("tool_choice").and_then(Value::as_str) == Some("none") {
        return Ok(None);
    }
    let tools = provider_engine_tool_specs(body)?;
    if tools.is_empty() {
        return Ok(None);
    }
    let strategy = match adapter.tool_call_strategy.as_str() {
        "mayhem_json" => ProviderEngineToolStrategy::MayhemJson,
        "openai_tool_calls" => ProviderEngineToolStrategy::OpenAiToolCalls,
        "none" => return Ok(None),
        other => bail!("unsupported catalog adapter.tool_call_strategy: {other}"),
    };
    Ok(Some((strategy, tools)))
}

fn provider_engine_tool_specs(body: &Value) -> Result<Vec<ToolSpec>> {
    let chosen = body
        .get("tool_choice")
        .and_then(|choice| choice.get("function"))
        .and_then(|function| function.get("name"))
        .and_then(Value::as_str);
    let tools = body
        .get("tools")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    let mut specs = Vec::new();
    for tool in tools {
        let Some(function) = tool.get("function") else {
            continue;
        };
        let Some(name) = function.get("name").and_then(Value::as_str) else {
            continue;
        };
        if chosen.is_some_and(|chosen| chosen != name) {
            continue;
        }
        let parameters = function
            .get("parameters")
            .cloned()
            .unwrap_or_else(|| json!({ "type": "object", "additionalProperties": true }));
        let mut spec = ToolSpec::new(name, parameters);
        spec.description = function
            .get("description")
            .and_then(Value::as_str)
            .map(str::to_owned);
        specs.push(spec);
    }
    Ok(specs)
}

fn provider_openai_tool_calls_json_schema(tools: &[ToolSpec]) -> Value {
    let names = tools
        .iter()
        .map(|tool| Value::String(tool.name.clone()))
        .collect::<Vec<_>>();
    json!({
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "title": "OpenAIToolCalls",
        "type": "object",
        "additionalProperties": false,
        "required": ["tool_calls"],
        "properties": {
            "tool_calls": {
                "type": "array",
                "minItems": 1,
                "items": {
                    "type": "object",
                    "additionalProperties": false,
                    "required": ["id", "type", "function"],
                    "properties": {
                        "id": { "type": "string" },
                        "type": { "const": "function" },
                        "function": {
                            "type": "object",
                            "additionalProperties": false,
                            "required": ["name", "arguments"],
                            "properties": {
                                "name": { "type": "string", "enum": names },
                                "arguments": { "type": "string" },
                            },
                        },
                    },
                },
            },
        },
    })
}

fn provider_response_json_schema(body: &Value) -> Value {
    body.get("response_format")
        .and_then(|format| format.get("json_schema"))
        .and_then(|json_schema| json_schema.get("schema"))
        .cloned()
        .unwrap_or_else(|| json!({ "type": "object", "additionalProperties": true }))
}

fn provider_engine_tool_call_output(
    text: &str,
    strategy: ProviderEngineToolStrategy,
) -> Option<Value> {
    match strategy {
        ProviderEngineToolStrategy::MayhemJson => provider_mayhem_json_tool_call_output(text),
        ProviderEngineToolStrategy::OpenAiToolCalls => provider_openai_tool_calls_output(text),
    }
}

fn provider_mayhem_json_tool_call_output(text: &str) -> Option<Value> {
    let value: Value = serde_json::from_str(text.trim()).ok()?;
    let name = value
        .get("tool")
        .or_else(|| value.get("name"))
        .and_then(Value::as_str)?
        .to_owned();
    let arguments = provider_tool_arguments_string(
        value.get("arguments").cloned().unwrap_or_else(|| json!({})),
    );
    Some(provider_normalized_tool_call(None, name, arguments))
}

fn provider_openai_tool_calls_output(text: &str) -> Option<Value> {
    let value: Value = serde_json::from_str(text.trim()).ok()?;
    let call = value
        .get("tool_calls")
        .and_then(Value::as_array)
        .and_then(|calls| calls.first())
        .or_else(|| {
            if value.get("function").is_some() {
                Some(&value)
            } else {
                None
            }
        })?;
    let function = call.get("function")?;
    let name = function.get("name").and_then(Value::as_str)?.to_owned();
    let arguments = provider_tool_arguments_string(
        function
            .get("arguments")
            .cloned()
            .unwrap_or_else(|| json!({})),
    );
    let id = call.get("id").and_then(Value::as_str).map(str::to_owned);
    Some(provider_normalized_tool_call(id, name, arguments))
}

fn provider_tool_arguments_string(arguments: Value) -> String {
    arguments
        .as_str()
        .map(str::to_owned)
        .unwrap_or_else(|| arguments.to_string())
}

fn provider_normalized_tool_call(id: Option<String>, name: String, arguments: String) -> Value {
    let id = id.unwrap_or_else(|| {
        format!(
            "call-{}",
            stable_value_hash(&json!({ "tool": name, "arguments": arguments }))
        )
    });
    json!({
        "id": id,
        "name": name,
        "arguments": arguments,
    })
}

fn provider_session_response(terms: &ProviderSessionTerms, body: &Value) -> ProviderSessionOutput {
    let messages = body
        .get("messages")
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[]);
    let prompt = messages
        .iter()
        .map(provider_message_to_text)
        .collect::<Vec<_>>()
        .join("\n");
    let prompt_tokens = rough_text_tokens(&prompt);
    if let Some(tool_result) = messages
        .iter()
        .rev()
        .find(|message| message.get("role").and_then(Value::as_str) == Some("tool"))
        .map(provider_message_to_text)
    {
        let content = format!("Tool result received: {tool_result}");
        return ProviderSessionOutput {
            usage: ReceiptUsage::text(prompt_tokens, rough_text_tokens(&content)),
            completion_tokens: rough_text_tokens(&content),
            token_ids: content.bytes().map(i32::from).collect(),
            content,
            tool: None,
            embeddings: None,
            artifacts: Vec::new(),
            finish_reason: "stop".to_owned(),
            prompt_tokens,
        };
    }
    let prompt_lower = prompt.to_lowercase();
    if prompt.contains(OPENCODE_TEST_MARKER) || prompt_lower.contains("bash tool") {
        return ProviderSessionOutput {
            usage: ReceiptUsage::text(prompt_tokens, 1),
            content: String::new(),
            tool: Some(json!({
                "id": format!("call-{}", stable_value_hash(&json!({ "tool": "bash", "prompt": prompt }))),
                "name": "bash",
                "arguments": provider_tool_arguments("bash"),
            })),
            finish_reason: "tool_calls".to_owned(),
            embeddings: None,
            artifacts: Vec::new(),
            prompt_tokens,
            completion_tokens: 1,
            token_ids: Vec::new(),
        };
    }
    if let Some(tool_name) = provider_requested_tool_name(body) {
        return ProviderSessionOutput {
            usage: ReceiptUsage::text(prompt_tokens, 1),
            content: String::new(),
            tool: Some(json!({
                "id": format!("call-{}", stable_value_hash(&json!({ "tool": tool_name, "prompt": prompt }))),
                "name": tool_name,
                "arguments": provider_tool_arguments(&tool_name),
            })),
            finish_reason: "tool_calls".to_owned(),
            embeddings: None,
            artifacts: Vec::new(),
            prompt_tokens,
            completion_tokens: 1,
            token_ids: Vec::new(),
        };
    }
    let content = if provider_wants_json(body) {
        json!({
            "ok": true,
            "model": &terms.model_id,
            "provider": &terms.provider,
        })
        .to_string()
    } else {
        format!(
            "Mayhem provider response from {}: {}",
            terms.model_id,
            provider_last_user_text(messages)
        )
    };
    ProviderSessionOutput {
        usage: ReceiptUsage::text(prompt_tokens, rough_text_tokens(&content)),
        completion_tokens: rough_text_tokens(&content),
        token_ids: content.bytes().map(i32::from).collect(),
        content,
        tool: None,
        embeddings: None,
        artifacts: Vec::new(),
        finish_reason: "stop".to_owned(),
        prompt_tokens,
    }
}

fn provider_requested_tool_name(body: &Value) -> Option<String> {
    if body.get("tool_choice").and_then(Value::as_str) == Some("none") {
        return None;
    }
    if let Some(name) = body
        .get("tool_choice")
        .and_then(|choice| choice.get("function"))
        .and_then(|function| function.get("name"))
        .and_then(Value::as_str)
    {
        return Some(name.to_owned());
    }
    body.get("tools")?.as_array()?.iter().find_map(|tool| {
        tool.get("function")?
            .get("name")?
            .as_str()
            .map(str::to_owned)
    })
}

fn provider_tool_arguments(name: &str) -> String {
    match name {
        "bash" => json!({ "command": "printf mayhem-opencode-tool-ok" }).to_string(),
        "write" => {
            json!({ "filePath": "mayhem-opencode-tool-ok.txt", "content": "mayhem-opencode-tool-ok" })
                .to_string()
        }
        _ => "{}".to_owned(),
    }
}

fn provider_wants_json(body: &Value) -> bool {
    matches!(
        body.get("response_format")
            .and_then(|format| format.get("type"))
            .and_then(Value::as_str),
        Some("json_object" | "json_schema")
    )
}

fn provider_last_user_text(messages: &[Value]) -> String {
    messages
        .iter()
        .rev()
        .find(|message| message.get("role").and_then(Value::as_str) == Some("user"))
        .map(provider_message_to_text)
        .unwrap_or_default()
}

fn provider_message_to_text(message: &Value) -> String {
    provider_content_to_text(message.get("content").unwrap_or(&Value::Null))
}

fn provider_message_to_text_for_adapter(
    message: &Value,
    adapter: &catalog::CatalogAdapter,
) -> String {
    let content = provider_content_to_text_for_adapter(
        message.get("content").unwrap_or(&Value::Null),
        adapter,
    );
    if adapter.reasoning_passthrough != "preserve" {
        return content;
    }
    let Some(reasoning) = message.get("reasoning").and_then(Value::as_str) else {
        return content;
    };
    if content.trim().is_empty() {
        reasoning.to_owned()
    } else {
        format!("{reasoning}\n{content}")
    }
}

fn provider_content_to_text_for_adapter(
    value: &Value,
    adapter: &catalog::CatalogAdapter,
) -> String {
    match value {
        Value::Null => String::new(),
        Value::String(text) => text.clone(),
        Value::Array(parts) => parts
            .iter()
            .map(|part| provider_content_part_to_text_for_adapter(part, adapter))
            .collect::<Vec<_>>()
            .join(""),
        other => other.to_string(),
    }
}

fn provider_content_part_to_text_for_adapter(
    part: &Value,
    adapter: &catalog::CatalogAdapter,
) -> String {
    if part.get("type").and_then(Value::as_str) == Some("image_url")
        && adapter_supports_image_input(adapter)
    {
        return MTMD_MEDIA_MARKER.to_owned();
    }
    provider_content_part_to_text(part)
}

fn adapter_supports_image_input(adapter: &catalog::CatalogAdapter) -> bool {
    adapter
        .modality_set
        .iter()
        .any(|modality| matches!(modality.as_str(), "image" | "vision"))
}

fn provider_content_to_text(value: &Value) -> String {
    match value {
        Value::Null => String::new(),
        Value::String(text) => text.clone(),
        Value::Array(parts) => parts
            .iter()
            .map(provider_content_part_to_text)
            .collect::<Vec<_>>()
            .join(""),
        other => other.to_string(),
    }
}

fn provider_content_part_to_text(part: &Value) -> String {
    match part.get("type").and_then(Value::as_str) {
        Some("text") => part
            .get("text")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned(),
        Some("image_url") => {
            let url = part
                .get("image_url")
                .and_then(|image| image.get("url"))
                .or_else(|| part.get("url"))
                .and_then(Value::as_str)
                .unwrap_or_default();
            format!("[image:{}]", blake3::hash(url.as_bytes()).to_hex())
        }
        Some("input_audio") => {
            let audio = part.get("input_audio").unwrap_or(&Value::Null);
            let format = audio
                .get("format")
                .and_then(Value::as_str)
                .unwrap_or("unknown");
            let data = audio
                .get("data")
                .and_then(Value::as_str)
                .unwrap_or_default();
            format!(
                "[audio:{format}:{}]",
                blake3::hash(data.as_bytes()).to_hex()
            )
        }
        _ => part
            .get("text")
            .and_then(Value::as_str)
            .map(str::to_owned)
            .unwrap_or_else(|| provider_content_to_text(part)),
    }
}

fn provider_stream_parts(content: &str) -> Vec<String> {
    let mut parts = content
        .split_inclusive(' ')
        .map(str::to_owned)
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>();
    if parts.is_empty() && !content.is_empty() {
        parts.push(content.to_owned());
    }
    parts
}

fn rough_text_tokens(text: &str) -> u64 {
    if text.trim().is_empty() {
        0
    } else {
        text.split_whitespace().count() as u64
    }
}

fn is_hex_len(value: &str, len: usize) -> bool {
    value.len() == len && value.as_bytes().iter().all(|byte| byte.is_ascii_hexdigit())
}

fn is_safe_key_part(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 128
        && value
            .as_bytes()
            .iter()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b':' | b'-'))
}

fn is_false(value: &bool) -> bool {
    !*value
}

fn hex_encode(bytes: &[u8]) -> String {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(HEX[(byte >> 4) as usize] as char);
        out.push(HEX[(byte & 0x0f) as usize] as char);
    }
    out
}

fn hex_decode_array<const N: usize>(value: &str, label: &str) -> Result<[u8; N]> {
    if value.len() != N * 2 {
        bail!("{label} must be {N} bytes of hex");
    }
    let mut out = [0_u8; N];
    let bytes = value.as_bytes();
    for index in 0..N {
        let high = hex_nibble(bytes[index * 2]).with_context(|| format!("{label} is not hex"))?;
        let low =
            hex_nibble(bytes[index * 2 + 1]).with_context(|| format!("{label} is not hex"))?;
        out[index] = (high << 4) | low;
    }
    Ok(out)
}

fn hex_decode_vec(value: &str, label: &str) -> Result<Vec<u8>> {
    if value.len() % 2 != 0 {
        bail!("{label} must be even-length hex");
    }
    let bytes = value.as_bytes();
    let mut out = Vec::with_capacity(bytes.len() / 2);
    for index in (0..bytes.len()).step_by(2) {
        let high = hex_nibble(bytes[index]).with_context(|| format!("{label} is not hex"))?;
        let low = hex_nibble(bytes[index + 1]).with_context(|| format!("{label} is not hex"))?;
        out.push((high << 4) | low);
    }
    Ok(out)
}

fn hex_nibble(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn wav_duration_seconds_ceil(bytes: &[u8]) -> Option<u64> {
    if bytes.len() < 44 || &bytes[0..4] != b"RIFF" || &bytes[8..12] != b"WAVE" {
        return None;
    }
    let mut offset = 12usize;
    let mut sample_rate = None;
    let mut channels = None;
    let mut bits_per_sample = None;
    let mut data_len = None;
    while offset.saturating_add(8) <= bytes.len() {
        let chunk_id = &bytes[offset..offset + 4];
        let chunk_len = u32::from_le_bytes([
            bytes[offset + 4],
            bytes[offset + 5],
            bytes[offset + 6],
            bytes[offset + 7],
        ]) as usize;
        let chunk_start = offset + 8;
        let chunk_end = chunk_start.saturating_add(chunk_len).min(bytes.len());
        if chunk_id == b"fmt " && chunk_len >= 16 && chunk_end <= bytes.len() {
            channels = Some(u16::from_le_bytes([
                bytes[chunk_start + 2],
                bytes[chunk_start + 3],
            ]));
            sample_rate = Some(u32::from_le_bytes([
                bytes[chunk_start + 4],
                bytes[chunk_start + 5],
                bytes[chunk_start + 6],
                bytes[chunk_start + 7],
            ]));
            bits_per_sample = Some(u16::from_le_bytes([
                bytes[chunk_start + 14],
                bytes[chunk_start + 15],
            ]));
        } else if chunk_id == b"data" {
            data_len = Some(chunk_len);
        }
        let padded = chunk_len + (chunk_len % 2);
        offset = chunk_start.saturating_add(padded);
    }
    let sample_rate = u64::from(sample_rate?);
    let channels = u64::from(channels?);
    let bits_per_sample = u64::from(bits_per_sample?);
    let data_len = u64::try_from(data_len?).ok()?;
    let bytes_per_second = sample_rate
        .saturating_mul(channels)
        .saturating_mul(bits_per_sample)
        .checked_div(8)?;
    if bytes_per_second == 0 {
        return None;
    }
    Some(data_len.div_ceil(bytes_per_second).max(1))
}

fn safe_path_component(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.') {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

fn is_32_byte_hex(value: &str) -> bool {
    value.len() == 64 && value.as_bytes().iter().all(u8::is_ascii_hexdigit)
}

fn unix_epoch_seconds() -> Result<u64> {
    Ok(SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system time is before Unix epoch")?
        .as_secs())
}

fn unix_epoch_millis() -> Result<u64> {
    let millis = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .context("system time is before Unix epoch")?
        .as_millis();
    u64::try_from(millis).context("Unix epoch milliseconds overflowed u64")
}

fn default_home() -> Result<PathBuf> {
    if let Ok(home) = env::var("MAYHEM_HOME") {
        let home = home.trim();
        if !home.is_empty() {
            return Ok(PathBuf::from(home));
        }
    }

    let user_home = env::var("HOME").context("HOME is not set; pass --home")?;
    Ok(PathBuf::from(user_home).join(".mayhem"))
}

fn user_home_dir() -> Result<PathBuf> {
    if let Ok(home) = env::var("HOME") {
        let home = home.trim();
        if !home.is_empty() {
            return Ok(PathBuf::from(home));
        }
    }
    if let Ok(home) = env::var("USERPROFILE") {
        let home = home.trim();
        if !home.is_empty() {
            return Ok(PathBuf::from(home));
        }
    }
    bail!("HOME/USERPROFILE is not set; pass an explicit path")
}

fn repo_path(relative: &str) -> Result<PathBuf> {
    let path = absolutize(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../..")
            .join(relative),
    )?;
    Ok(fs::canonicalize(&path).unwrap_or(path))
}

fn default_rules_path() -> Result<PathBuf> {
    let repo_rules = repo_path("RULES.md")?;
    if repo_rules.exists() {
        return absolutize(repo_rules);
    }
    absolutize(PathBuf::from("RULES.md"))
}

fn absolutize(path: PathBuf) -> Result<PathBuf> {
    if path.is_absolute() {
        return Ok(path);
    }
    Ok(env::current_dir()?.join(path))
}

fn read_mayhem_config(home: &Path) -> Result<Option<MayhemConfig>> {
    let config_path = home.join("config.toml");
    if !config_path.exists() {
        return Ok(None);
    }
    let text = fs::read_to_string(&config_path)
        .with_context(|| format!("reading {}", config_path.display()))?;
    let config =
        toml::from_str(&text).with_context(|| format!("parsing {}", config_path.display()))?;
    Ok(Some(config))
}

fn config_path_for_home(home: &Path) -> PathBuf {
    home.join("config.toml")
}

fn read_config_toml_value(path: &Path) -> Result<toml::Value> {
    if !path.exists() {
        return Ok(toml::Value::Table(toml::map::Map::new()));
    }
    let text = fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
    if text.trim().is_empty() {
        return Ok(toml::Value::Table(toml::map::Map::new()));
    }
    let value: toml::Value =
        toml::from_str(&text).with_context(|| format!("parsing {}", path.display()))?;
    if !value.is_table() {
        bail!("{} must contain a TOML table", path.display());
    }
    Ok(value)
}

fn write_config_toml_value(path: &Path, value: &toml::Value) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    fs::write(path, toml::to_string_pretty(value)?)
        .with_context(|| format!("writing {}", path.display()))?;
    Ok(())
}

fn canonical_config_key(key: &str) -> Result<&'static str> {
    let normalized = key.trim().replace('-', "_");
    match normalized.as_str() {
        "home" | "mayhem_home" => {
            bail!("home selects the config location and is not stored inside config.toml")
        }
        "rpc_url" | "network.rpc_url" => Ok("network.rpc_url"),
        "gateway_url" | "network.gateway_url" => Ok("network.gateway_url"),
        "paygate_url" | "network.paygate_url" => Ok("network.paygate_url"),
        "sc_bridge_url" | "network.sc_bridge_url" => Ok("network.sc_bridge_url"),
        "sc_bridge_token" | "network.sc_bridge_token" => Ok("network.sc_bridge_token"),
        "tnk_treasury_address" | "network.tnk_treasury_address" => {
            Ok("network.tnk_treasury_address")
        }
        "keypair_path" | "identity.keypair_path" => Ok("identity.keypair_path"),
        "store_name" | "identity.store_name" => Ok("identity.store_name"),
        "engine_backend" | "provider.engine_backend" => Ok("provider.engine_backend"),
        "role" | "role.mode" => Ok("role.mode"),
        "" => bail!("config key must not be empty"),
        _ => bail!("unsupported config key {key}; supported keys are rpc_url, gateway_url, paygate_url, sc_bridge_url, sc_bridge_token, tnk_treasury_address, identity.keypair_path, identity.store_name, provider.engine_backend, and role.mode"),
    }
}

fn toml_get_path<'a>(value: &'a toml::Value, key: &str) -> Option<&'a toml::Value> {
    let mut cursor = value;
    for segment in key.split('.') {
        cursor = cursor.as_table()?.get(segment)?;
    }
    Some(cursor)
}

fn toml_set_string(value: &mut toml::Value, key: &str, new_value: String) -> Result<()> {
    let segments = key.split('.').collect::<Vec<_>>();
    let Some((last, parents)) = segments.split_last() else {
        bail!("config key must not be empty");
    };
    let mut table = value
        .as_table_mut()
        .context("config root must contain a TOML table")?;
    for segment in parents {
        let entry = table
            .entry((*segment).to_owned())
            .or_insert_with(|| toml::Value::Table(toml::map::Map::new()));
        if !entry.is_table() {
            bail!("{segment} exists in config.toml but is not a table");
        }
        table = entry.as_table_mut().expect("checked table");
    }
    table.insert((*last).to_owned(), toml::Value::String(new_value));
    Ok(())
}

fn remove_local_state_path(path: &Path) -> Result<bool> {
    if !path.exists() {
        return Ok(false);
    }
    let metadata =
        fs::symlink_metadata(path).with_context(|| format!("reading {}", path.display()))?;
    let file_type = metadata.file_type();
    if file_type.is_dir() && !file_type.is_symlink() {
        fs::remove_dir_all(path).with_context(|| format!("removing {}", path.display()))?;
    } else {
        fs::remove_file(path).with_context(|| format!("removing {}", path.display()))?;
    }
    Ok(true)
}

fn read_rules_doc(path: Option<&Path>) -> Result<RulesDoc> {
    let path = match path {
        Some(path) => absolutize(path.to_path_buf())?,
        None => default_rules_path()?,
    };
    let path = fs::canonicalize(&path).unwrap_or(path);
    let bytes = fs::read(&path).with_context(|| format!("reading {}", path.display()))?;
    let text = String::from_utf8(bytes.clone())
        .with_context(|| format!("{} must be valid UTF-8", path.display()))?;
    let hash = blake3::hash(&bytes).to_hex().to_string();
    Ok(RulesDoc {
        path,
        text,
        hash,
        bytes: bytes.len(),
    })
}

fn rules_state_dir(home: &Path) -> PathBuf {
    home.join("rules")
}

fn read_current_accepted_rules(home: &Path) -> Result<Option<String>> {
    let path = rules_state_dir(home).join("current.md");
    if !path.exists() {
        return Ok(None);
    }
    let text = fs::read_to_string(&path).with_context(|| format!("reading {}", path.display()))?;
    Ok(Some(text))
}

fn persist_rules_acceptance(home: &Path, rules_doc: &RulesDoc, rules: &RulesRef) -> Result<()> {
    let dir = rules_state_dir(home);
    fs::create_dir_all(&dir).with_context(|| format!("creating {}", dir.display()))?;
    let versioned_path = dir.join(format!("accepted-{}-{}.md", rules.ver, rules.hash));
    fs::write(&versioned_path, &rules_doc.text)
        .with_context(|| format!("writing {}", versioned_path.display()))?;
    fs::write(dir.join("current.md"), &rules_doc.text)
        .with_context(|| format!("writing {}", dir.join("current.md").display()))?;
    fs::write(
        dir.join("current.json"),
        serde_json::to_vec_pretty(&json!({
            "ver": rules.ver,
            "hash": rules.hash,
            "path": rules_doc.path,
            "bytes": rules_doc.bytes,
            "accepted_text": versioned_path,
        }))?,
    )
    .with_context(|| format!("writing {}", dir.join("current.json").display()))?;
    Ok(())
}

fn print_rules_review(
    home: &Path,
    rules_doc: &RulesDoc,
    rules: &RulesRef,
    previous_rules: Option<&str>,
    prior_consent: Option<&Value>,
) -> Result<()> {
    println!("Mayhem rules review");
    println!("Home: {}", home.display());
    println!("Rules file: {}", rules_doc.path.display());
    println!("Rules version: {}", rules.ver);
    println!("BLAKE3(RULES.md): {}", rules_doc.hash);
    if let Some(consent) = prior_consent {
        let ver = consent.get("ver").and_then(Value::as_u64).unwrap_or(0);
        let hash = consent.get("hash").and_then(Value::as_str).unwrap_or("");
        println!("Existing consent: v{ver} {hash}");
    } else {
        println!("Existing consent: none");
    }

    match previous_rules {
        Some(previous) if previous == rules_doc.text => {
            println!();
            println!("Local accepted rules text is unchanged.");
        }
        Some(previous) => {
            println!();
            println!("Diff from locally accepted rules:");
            println!("{}", render_line_diff(previous, &rules_doc.text));
        }
        None => {
            println!();
            println!("No locally accepted rules text was found. Current rules text follows.");
            println!();
            println!("{}", rules_doc.text);
        }
    }
    Ok(())
}

fn render_line_diff(old: &str, new: &str) -> String {
    let old_lines = old.lines().collect::<Vec<_>>();
    let new_lines = new.lines().collect::<Vec<_>>();
    let max_len = old_lines.len().max(new_lines.len());
    let mut out = String::new();
    for i in 0..max_len {
        match (old_lines.get(i), new_lines.get(i)) {
            (Some(old), Some(new)) if old == new => {
                let _ = writeln!(out, "  {old}");
            }
            (Some(old), Some(new)) => {
                let _ = writeln!(out, "- {old}");
                let _ = writeln!(out, "+ {new}");
            }
            (Some(old), None) => {
                let _ = writeln!(out, "- {old}");
            }
            (None, Some(new)) => {
                let _ = writeln!(out, "+ {new}");
            }
            (None, None) => {}
        }
    }
    out
}

fn confirm_rules_acceptance(yes: bool) -> Result<()> {
    if yes {
        return Ok(());
    }
    if !io::stdin().is_terminal() {
        bail!("Pass --yes to accept and sign the current RULES.md in non-interactive mode.");
    }

    eprint!("Type 'agree' to sign consent for these rules: ");
    io::stderr().flush()?;
    let mut answer = String::new();
    io::stdin().read_line(&mut answer)?;
    if answer.trim() != "agree" {
        bail!("Rules consent was not signed.");
    }
    Ok(())
}

fn select_role(role: Option<Role>) -> Result<Role> {
    if let Some(role) = role {
        return Ok(role);
    }

    if !io::stdin().is_terminal() {
        bail!("Pass --role provider, --role user, or --role both for non-interactive setup.");
    }

    loop {
        print!("Choose role [provider/user/both]: ");
        io::stdout().flush()?;
        let mut answer = String::new();
        io::stdin().read_line(&mut answer)?;
        match answer.trim().to_lowercase().as_str() {
            "provider" | "prov" | "p" => return Ok(Role::Provider),
            "user" | "u" => return Ok(Role::User),
            "both" | "b" => return Ok(Role::Both),
            _ => eprintln!("Please enter provider, user, or both."),
        }
    }
}

async fn materialize_wallet(
    args: &SetupArgs,
    keypair_path: &Path,
    password: &str,
) -> Result<WalletInfo> {
    let exists = keypair_path.exists();
    match args.wallet {
        WalletMode::Auto => {
            if exists {
                inspect_wallet(keypair_path, password).await
            } else {
                create_wallet(keypair_path, password, args.mnemonic.as_deref(), false).await
            }
        }
        WalletMode::Create => {
            if exists && !args.force {
                bail!(
                    "{} already exists; use --wallet reuse or pass --force.",
                    keypair_path.display()
                );
            }
            create_wallet(keypair_path, password, args.mnemonic.as_deref(), args.force).await
        }
        WalletMode::Import => {
            if exists && !args.force {
                bail!(
                    "{} already exists; use --wallet reuse or pass --force.",
                    keypair_path.display()
                );
            }
            let mnemonic = args
                .mnemonic
                .as_deref()
                .context("--wallet import requires --mnemonic")?;
            create_wallet(keypair_path, password, Some(mnemonic), true).await
        }
        WalletMode::Reuse => {
            if !exists {
                bail!(
                    "{} does not exist; use --wallet create/import.",
                    keypair_path.display()
                );
            }
            inspect_wallet(keypair_path, password).await
        }
    }
}

async fn create_wallet(
    keypair_path: &Path,
    password: &str,
    mnemonic: Option<&str>,
    force: bool,
) -> Result<WalletInfo> {
    let mut args = vec![
        "create".to_owned(),
        "--keypair".to_owned(),
        keypair_path.display().to_string(),
    ];
    if !password.is_empty() {
        args.extend(["--password".to_owned(), password.to_owned()]);
    }
    if let Some(mnemonic) = mnemonic {
        args.extend(["--mnemonic".to_owned(), mnemonic.to_owned()]);
    }
    if force {
        args.push("--force".to_owned());
    }
    run_wallet_helper(args).await
}

