    #[test]
    fn participant_dispute_and_fraud_proof_cli_parse() {
        let dispute = Cli::try_parse_from([
            "mayhem",
            "dispute",
            "--session-id",
            "session-1",
            "--reason",
            "service_failure",
            "--provider",
            "55",
            "--evidence-json",
            r#"{"kind":"timeout"}"#,
            "--json",
        ])
        .unwrap();
        let Commands::Dispute(args) = dispute.command else {
            panic!("expected dispute command");
        };
        assert_eq!(args.session_id, "session-1");
        assert_eq!(args.provider.as_deref(), Some("55"));
        assert!(args.tx.json);

        let fraud = Cli::try_parse_from([
            "mayhem",
            "fraud-proof",
            "submit",
            "--epoch",
            "1",
            "--proof-epoch",
            "2",
            "--receipt-json",
            r#"{"receipt":{"body":{"session_id":"s1"}}}"#,
            "--claimed-mu-owed-cum",
            "2000",
            "--previous-mu-owed-cum",
            "1000",
            "--json",
        ])
        .unwrap();
        let Commands::FraudProof { command } = fraud.command else {
            panic!("expected fraud-proof command");
        };
        let FraudProofCommands::Submit(args) = command else {
            panic!("expected fraud-proof submit command");
        };
        assert_eq!(args.epoch, 1);
        assert_eq!(args.proof_epoch, 2);
        assert_eq!(args.claimed_mu_owed_cum, 2000);
        assert_eq!(args.previous_mu_owed_cum, Some(1000));
        assert!(args.tx.json);

        let challenge = Cli::try_parse_from([
            "mayhem",
            "fraud-proof",
            "challenge",
            "--epoch",
            "1",
            "--proof-epoch",
            "2",
            "--receipts-file",
            "/tmp/mayhem-receipts.json",
            "--max-challenges",
            "1",
            "--json",
        ])
        .unwrap();
        let Commands::FraudProof { command } = challenge.command else {
            panic!("expected fraud-proof command");
        };
        let FraudProofCommands::Challenge(args) = command else {
            panic!("expected fraud-proof challenge command");
        };
        assert_eq!(args.epoch, Some(1));
        assert_eq!(args.proof_epoch, Some(2));
        assert_eq!(args.max_challenges, Some(1));
        assert!(args.tx.json);
    }

    #[test]
    fn participant_dispute_and_fraud_proof_payloads_match_contract_schema() {
        let dispute = dispute_payload(&DisputeArgs {
            tx: test_participant_tx_args(),
            session_id: "session-1".to_owned(),
            reason: "service_failure".to_owned(),
            provider: Some("55".repeat(32)),
            counterparty: None,
            enclave_id: Some("11".repeat(32)),
            epoch: Some(7),
            at: Some(42),
            evidence_hash: None,
            evidence_json: Some(r#"{"kind":"timeout","detail":"no final receipt"}"#.to_owned()),
            evidence_file: None,
        })
        .unwrap();
        assert_eq!(dispute["op"], "dispute");
        assert_eq!(dispute["session_id"], "session-1");
        assert_eq!(dispute["provider"].as_str(), Some("55".repeat(32).as_str()));
        assert_eq!(
            dispute["enclave_id"].as_str(),
            Some("11".repeat(32).as_str())
        );
        assert_eq!(dispute["epoch"].as_u64(), Some(7));
        assert_eq!(dispute["at"].as_u64(), Some(42));
        assert_eq!(dispute["evidence_hash"].as_str().map(str::len), Some(64));
        assert_eq!(dispute["evidence"]["kind"].as_str(), Some("timeout"));

        let fraud = fraud_proof_payload(&FraudProofSubmitArgs {
            tx: test_participant_tx_args(),
            epoch: 1,
            proof_epoch: 2,
            at: Some(43),
            reason: "over_credit".to_owned(),
            receipt_json: Some(
                r#"{"receipt":{"body":{"session_id":"s1","mu_owed_cum":1000}}}"#.to_owned(),
            ),
            receipt_file: None,
            claimed_mu_owed_cum: 2000,
            previous_mu_owed_cum: Some(1000),
        })
        .unwrap();
        assert_eq!(fraud["op"], "fraud_proof");
        assert_eq!(fraud["epoch"].as_u64(), Some(1));
        assert_eq!(fraud["proof_epoch"].as_u64(), Some(2));
        assert_eq!(fraud["at"].as_u64(), Some(43));
        assert_eq!(fraud["reason"], "over_credit");
        assert_eq!(fraud["claimed_mu_owed_cum"].as_u64(), Some(2000));
        assert_eq!(fraud["previous_mu_owed_cum"].as_u64(), Some(1000));
        assert_eq!(fraud["receipt"]["receipt"]["body"]["session_id"], "s1");

        let err = fraud_proof_payload(&FraudProofSubmitArgs {
            reason: "other".to_owned(),
            ..FraudProofSubmitArgs {
                tx: test_participant_tx_args(),
                epoch: 1,
                proof_epoch: 2,
                at: Some(43),
                reason: "over_credit".to_owned(),
                receipt_json: Some(r#"{"receipt":{"body":{"session_id":"s1"}}}"#.to_owned()),
                receipt_file: None,
                claimed_mu_owed_cum: 2000,
                previous_mu_owed_cum: None,
            }
        })
        .unwrap_err();
        assert!(err.to_string().contains("over_credit"));
    }

    #[test]
    fn fraud_proof_challenger_builds_root_matched_over_credit_candidate() {
        let sig = "aa".repeat(64);
        let receipt = json!({
            "receipt": {
                "body": {
                    "schema_version": SESSION_RECEIPT_SCHEMA_VERSION,
                    "session_id": "s1",
                    "seq": 1,
                    "final": true,
                    "rail": "fiat",
                    "user": "11".repeat(32),
                    "provider": "22".repeat(32),
                    "enclave_id": "33".repeat(32),
                    "model_id": "mayhem/test",
                    "price_ver": 1,
                    "rules_ver": 1,
                    "usage": { "input_token": 1, "output_token": 1 },
                    "mu_owed_cum": 100,
                    "prompt_hash": "44".repeat(32),
                    "ts": 1_000,
                },
                "enclave_sig": sig.clone(),
                "user_sig": sig,
            }
        });
        let envelope = normalized_receipt_envelope(&receipt).unwrap();
        let inflated = receipt_envelope_with_mu_owed_cum(&envelope, 200);
        let committed_use_root = usage_leaf_hash_from_envelope(&inflated).unwrap();
        let commit = json!({
            "type": "epoch_commit",
            "epoch": 1,
            "status": "provisional",
            "provisional_until_epoch": 3,
            "commit_hash": "cc".repeat(32),
            "submitted_by": "55".repeat(32),
            "roots": { "use": committed_use_root },
            "totals": {
                "use_count": 1,
                "use_mu": 200
            }
        });

        let candidates =
            fraud_proof_candidates_from_values(&[commit], &[receipt], Some(2), 42, None).unwrap();

        assert_eq!(candidates.len(), 1);
        let candidate = &candidates[0];
        assert_eq!(candidate.epoch, 1);
        assert_eq!(candidate.proof_epoch, 2);
        assert_eq!(candidate.actual_mu, 100);
        assert_eq!(candidate.claimed_mu, 200);
        assert_eq!(candidate.claimed_mu_owed_cum, 200);
        assert_eq!(candidate.previous_mu_owed_cum, 0);
        assert_eq!(candidate.command["op"], "fraud_proof");
        assert_eq!(candidate.command["receipt"]["body"]["mu_owed_cum"], 100);
        assert!(candidate.command["receipt"]
            .get("enclave_pubkey")
            .is_some_and(Value::is_null));
        assert!(candidate.copy_paste.contains("/tx --command"));
        assert_eq!(candidate.proof_hash.len(), 64);
    }

