    #[test]
    fn admin_epoch_payloads_accept_recomputed_outputs() {
        let roots = json!({
            "dep": "d".repeat(64),
            "use": "u".repeat(64),
            "earn": "e".repeat(64),
            "fee": "f".repeat(64),
        });
        let totals = json!({
            "dep_count": 0,
            "dep_mu": 0,
            "use_count": 1,
            "use_mu": 2_000,
            "provider_count": 1,
            "earn_mu": 1_700,
            "fee_mu": 300,
            "fee_cum_mu": 300,
        });

        let commit = admin_epoch_commit_payload(&AdminEpochCommitArgs {
            tx: test_admin_tx_args(),
            epoch: Some(7),
            at: 25_200,
            recomputed_file: None,
            roots_json: Some(roots.to_string()),
            roots_file: None,
            totals_json: Some(totals.to_string()),
            totals_file: None,
        })
        .unwrap();
        assert_eq!(
            commit,
            json!({
                "op": "epoch_commit",
                "epoch": 7,
                "at": 25_200,
                "roots": roots,
                "totals": totals,
            })
        );

        let apply = admin_epoch_apply_payload(&AdminEpochApplyArgs {
            tx: test_admin_tx_args(),
            epoch: Some(7),
            at: 25_200,
            recomputed_file: None,
            debits_json: Some(r#"[{"user":"user-a","mu":2000}]"#.to_owned()),
            debits_file: None,
            earnings_json: Some(r#"[{"provider":"provider-a","gross_mu":2000}]"#.to_owned()),
            earnings_file: None,
            roots_json: Some(commit["roots"].to_string()),
            roots_file: None,
            totals_json: Some(commit["totals"].to_string()),
            totals_file: None,
        })
        .unwrap();
        assert_eq!(
            apply,
            json!({
                "op": "epoch_apply",
                "epoch": 7,
                "at": 25_200,
                "debits": [{"user": "user-a", "mu": 2000}],
                "earnings": [{"provider": "provider-a", "gross_mu": 2000}],
                "roots": commit["roots"],
                "totals": commit["totals"],
            })
        );
        let apply_key = epoch_apply_feature_key(&apply).unwrap();
        assert!(apply_key.starts_with("epoch/apply/7/"));
        assert_eq!(apply_key.len(), "epoch/apply/7/".len() + 64);
        assert_eq!(
            apply_key,
            epoch_apply_feature_key(&json!({
                "totals": commit["totals"],
                "roots": commit["roots"],
                "earnings": [{"gross_mu": 2000, "provider": "provider-a"}],
                "debits": [{"mu": 2000, "user": "user-a"}],
                "at": 25_200,
                "epoch": 7,
                "op": "epoch_apply",
            }))
            .unwrap()
        );
    }

