    #[test]
    fn evidence_checks_cover_all_epoch_roots_and_totals() {
        let recomputed = json!({
            "roots": {
                "dep": "a".repeat(64),
                "use": "b".repeat(64),
                "earn": "c".repeat(64),
                "fee": "d".repeat(64),
            },
            "totals": {
                "dep_count": 1,
                "dep_mu": 2,
                "use_count": 3,
                "use_mu": 4,
                "provider_count": 5,
                "earn_mu": 6,
                "fee_mu": 7,
                "fee_cum_mu": 8,
            }
        });
        let evidence = EpochEvidenceSnapshot {
            dep: Some(json!({
                "merkle_root": "a".repeat(64),
                "count": 1,
                "mu_total": 2,
            })),
            r#use: Some(json!({
                "merkle_root": "b".repeat(64),
                "sessions": 3,
                "mu_total": 4,
                "providers": 5,
            })),
            earn: Some(json!({
                "merkle_root": "c".repeat(64),
                "provider_count": 5,
                "mu_cum_total": 6,
            })),
            fee: Some(json!({
                "merkle_root": "d".repeat(64),
                "mu_fee_epoch": 7,
                "mu_fee_cum": 8,
            })),
        };

        let checks = verify_epoch_evidence(4, &recomputed, &evidence);
        assert_eq!(checks.len(), 13);
        assert!(checks.iter().all(|check| check.ok));

        let mismatched = EpochEvidenceSnapshot {
            fee: Some(json!({
                "merkle_root": "d".repeat(64),
                "mu_fee_epoch": 7,
                "mu_fee_cum": 9,
            })),
            ..evidence
        };
        let checks = verify_epoch_evidence(4, &recomputed, &mismatched);
        assert!(checks.iter().any(|check| {
            check.key == "ev/fee/4.mu_fee_cum" && !check.ok && check.actual == json!(9)
        }));
    }

