    #[test]
    fn catalog_list_report_filters_launch_and_surfaces_download_sources() {
        let mut catalog = test_catalog(&"aa".repeat(32));
        catalog.models[0]
            .canary
            .fingerprints
            .insert("gguf-q4_k_m".to_owned(), "bb".repeat(32));
        let mut launch = catalog.models[0].clone();
        launch.model_id = "test/launch@4bit".to_owned();
        launch.tier = "launch".to_owned();
        launch.min_app_version = Some(installed_app_version().to_owned());
        catalog.models.push(launch);

        let report = catalog_list_report(
            &catalog,
            PathBuf::from("catalog/models.json"),
            PathBuf::from("catalog/signatures/models.json.sig"),
            "cc".repeat(32),
            "test-key".to_owned(),
            CatalogListTier::Launch,
            None,
        );

        assert!(report.ok);
        assert_eq!(report.tier_filter, "launch");
        assert_eq!(report.model_count, 1);
        assert_eq!(report.artifact_count, 1);
        assert_eq!(report.models[0].model_id, "test/launch@4bit");
        assert_eq!(
            report.models[0].min_app_version.as_deref(),
            Some(installed_app_version())
        );
        assert_eq!(
            report.models[0].canary_verification_method,
            "token_fingerprint"
        );
        assert_eq!(report.models[0].canary_verification_tolerance_bps, None);
        assert_eq!(report.models[0].artifacts[0].source_repo, "test/model");
        assert_eq!(
            report.models[0].artifacts[0].source_url.as_deref(),
            Some("https://huggingface.co/test/model/resolve/1111111111111111111111111111111111111111/model.gguf")
        );
        assert!(report.authority.contains("contract ledger"));
    }

    #[test]
    fn canary_probe_request_uses_normal_chat_completion_shape() {
        let prompt = CanaryPrompt {
            id: "shape".to_owned(),
            messages: vec![json!({ "role": "user", "content": "return ok" })],
            tools: Some(vec![json!({
                "type": "function",
                "function": {
                    "name": "write",
                    "parameters": { "type": "object" }
                }
            })]),
            temperature: Some(0.2),
            max_tokens: Some(16),
        };

        let request = canary_probe_request("admin/model", &prompt);

        assert_eq!(request["model"], "admin/model");
        assert_eq!(
            request["messages"],
            json!([{ "role": "user", "content": "return ok" }])
        );
        assert_eq!(request["tools"], json!(prompt.tools.as_ref().unwrap()));
        assert_eq!(request["temperature"], 0.2);
        assert_eq!(request["max_tokens"], 16);
        assert_eq!(request["stream"], false);
        assert!(request.get("canary").is_none());
    }

    #[test]
    fn canary_text_match_normalizes_whitespace_and_scores_mismatch() {
        let exact = evaluate_text_match("alpha\n beta", "alpha beta", 10_000);
        assert!(exact.pass);
        assert_eq!(exact.match_bps, 10_000);
        assert_eq!(exact.total_positions, 10);

        let mismatch = evaluate_text_match("abcdef", "abcxyz", 9_000);
        assert!(!mismatch.pass);
        assert_eq!(mismatch.matched_positions, 3);
        assert_eq!(mismatch.match_bps, 5_000);
    }

